module vram_display #(parameter XOFFSET = 0, YOFFSET = 0) (reset,clk,hcount,vcount,vr_pixel,
		    vram_addr,vram_read_data);
    input reset, clk;
    input [10:0] hcount;
    input [9:0] 	vcount;
    output reg [29:0] vr_pixel;
    output [18:0] vram_addr;
    input [35:0]  vram_read_data;
    wire[10:0] x;
    wire[9:0] y;
    assign x = hcount - XOFFSET;
    assign y = vcount - YOFFSET;
    //forecast hcount & vcount 2 clock cycles ahead to get data from ZBT
    // for 1024x720 resolution:
    //wire [10:0] hcount_f = (x >= 1048) ? x - 1048 : (x + 2);
    //wire [9:0] vcount_f = (x >= 1048) ? ((y == 805) ? 0 : y + 1) : y;
    // for 800x600 resolution:
    wire [10:0] hcount_f = (x >= 840) ? x - 840 : (x + 2);
    wire [9:0] vcount_f = (x >= 840) ? ((y == 627) ? 0 : y + 1) : y;
    reg [18:0] vram_addr;
    always@(*) begin
      if(hcount_f < 640 && vcount_f < 480) begin
        vram_addr = {vcount_f[8:0], hcount_f[9:0]};
        vr_pixel = vram_read_data[29:0];
      end
      else begin
        vr_pixel = {10'd0,10'd512,10'd512};
      end
    end
endmodule // vram_display

module regfile(fromReg1, fromReg2, toReg, rs2, rs1, rd, RegWrite, clk); 
  localparam bus_size = 32; 
  input[bus_size-1:0] toReg; 
  input[4:0] rs1, rs2, rd; 
  input RegWrite; 
  input clk; 
  output reg[bus_size-1:0] fromReg1, fromReg2; 
  supply0[bus_size-1:0] zero;       // a register hardwired to zero 
  reg[bus_size-1:0] regArray[1:31]; // an array of registers of length 31 
  // hardwiring x0 to 0 and reading regs 
  always @(rs1, rs2) begin 
    if (!rs1) fromReg1 = zero; // if rs1 == 0
    else fromReg1 = regArray[rs1]; 
    if (!rs2) fromReg2 = zero; // if rs2 == 0 
    else fromReg2 = regArray[rs2]; 
  end 
  // if RegWrite is enabled only, update the reg specified by 'rd' with 'toReg' 
  always @(posedge clk) begin 
    if (RegWrite && rd) regArray[rd] <= toReg; 
  end 
endmodule // regfile

//module always assumes 1 bit for sign
module multiplier
#(
  parameter integer DATA_WIDTH	 = 32,
  parameter integer WEIGHT_WIDTH = 32
)
(
  input [DATA_WIDTH-1:0] data,
  input [WEIGHT_WIDTH-1:0] weight,
  output [DATA_WIDTH-1:0] out
);
wire [DATA_WIDTH+WEIGHT_WIDTH-1:0] total;
wire sign;
// assuming always 1 bit for sign, multiply integer+fractional parts
assign total = data[DATA_WIDTH-2:0] * weight[WEIGHT_WIDTH-2:0];
assign sign = data[DATA_WIDTH-1] ^ weight[WEIGHT_WIDTH-1];
assign out = {sign, total[DATA_WIDTH+WEIGHT_WIDTH-1:WEIGHT_WIDTH+1]};
endmodule // multiplier

