module pipelining(rs1,rs2,rd,z,addr,func,clk1,clk2);
input clk1,clk2;
input [3:0] rs1,rs2,rd;
input [1:0] func;
input [7:0] addr;
output [15:0] z;
reg [15:0] L12_A,L12_B,L23_z,L34_z;
reg [3:0] L12_rd,L12_func,L23_rd;
reg [7:0] L12_addr,L23_addr,L34_addr;
reg [15:0] regbank [0:15];
reg [15:0] mem [0:255];
assign z = L34_z;
//stage1
always @(posedge clk1)
begin
L12_A <= #2 regbank[rs1];
L12_B <= #2 regbank[rs2];
L12_rd <= #2 rd;
L12_func <= #2 func;
L12_addr <= #2 addr;
end
//stage2
always @(negedge clk2)
begin
	case(func)
		0: L23_z <= #2 L12_A + L12_B;
		1: L23_z <= #2 L12_A - L12_B;
		2: L23_z <= #2 L12_A & L12_B;
		3: L23_z <= #2 L12_A ^ L12_B;
		default: L23_z <= #2 16'hxxxx;
	endcase
	L23_rd <= #2 L12_rd;
	L23_addr <= #2 L12_addr;
end
//stage3
always @(posedge clk1)
begin
regbank[L23_rd] <= #2 L23_z;
L34_z <= #2 L23_z;
L34_addr <= #2 L23_addr;
end
//stage4
always @(negedge clk2)
begin
mem[L34_addr] <= #2 L34_z;
end 
endmodule

module CTRL_TX   #(parameter DATA_WIDTH = 8)   (
input wire rst,
input wire clk,
input wire Busy,
input wire [2*DATA_WIDTH-1:0] ALU_OUT,
input wire ALU_OUT_VALID,
input wire [DATA_WIDTH-1:0] Rd_DATA,
input wire Rd_DATA_Valid,
output reg [DATA_WIDTH-1:0] TX_P_DATA,
output reg TX_D_VLD
);
localparam IDLE = 3'b000;
localparam ALU0_SEND = 3'b001 ;
localparam ALU1_SEND = 3'b011;
localparam REG_FILE_SEND = 3'b110;
reg [2:0] current_state , next_state;
reg [7:0]TX_P_DATA_2 ;
always @(posedge clk or negedge rst) begin
    if (!rst) begin
      current_state <= IDLE;  
    end
    else
    begin
    current_state <= next_state;
end
end  
always @(*) begin
    case(current_state)
    IDLE: begin
        TX_D_VLD = 1'b0;
        TX_P_DATA = 8'b0;
        if (ALU_OUT_VALID )
        begin
            next_state = ALU0_SEND;
        end
        else if (Rd_DATA_Valid) begin
            next_state = REG_FILE_SEND;
        end
else
begin
    next_state = IDLE;
end
    end
REG_FILE_SEND : begin
    if (!Busy)
    begin
        TX_D_VLD = 1'b1;
        TX_P_DATA = Rd_DATA;
        next_state = IDLE;
    end
    else
    begin
        TX_D_VLD = 1'b0;
        TX_P_DATA = 8'b0;
        next_state = IDLE;  
    end
end
ALU0_SEND : begin
    if (!Busy)
    begin
        TX_D_VLD = 1'b1;
        TX_P_DATA = ALU_OUT[7:0];
         TX_P_DATA_2 = ALU_OUT[15:8];
        next_state = ALU1_SEND;
    end
    else
    begin
        TX_D_VLD = 1'b0;
        TX_P_DATA = 8'b0;
        next_state = IDLE;  
    end
end
ALU1_SEND : begin
    if (!Busy)
    begin
        TX_D_VLD = 1'b1;
        TX_P_DATA = TX_P_DATA_2;
        next_state = IDLE;
    end
    else
    begin
        TX_D_VLD = 1'b0;
        TX_P_DATA = 8'b0;
        next_state = IDLE;  
    end
end
default: begin
      TX_D_VLD = 1'b0;
        TX_P_DATA = 8'b0;
        next_state = IDLE;  
end
endcase
end
endmodule

