module paddle(
	input clk_1ms,reset, 
	input button, button1, button2, button3,
	input [9:0] x, y,
	output paddle1_on,paddle2_on,
	output [11:0] rgb_paddle1, rgb_paddle2,
	output reg [9:0] x_paddle1 = L_position + (paddlewidth/2),
	output reg [9:0] y_paddle1 = V_active/2,
	output reg [9:0] x_paddle2 = H_active-(R_position + (paddlewidth/2)),
	output reg [9:0] y_paddle2 = V_active/2
	);
	localparam H_active = 640;
	localparam V_active = 480;
	localparam paddlewidth = 20;
	localparam paddleheight = 40;
	localparam L_position = 20;
	localparam R_position = 20;
	always @ (posedge clk_1ms)
	begin
		if(!reset)
		begin	
			x_paddle1 <= L_position + (paddlewidth/2);
			y_paddle1 <= V_active/2;
		end
		else if (!button && y_paddle1-(paddleheight/2) > 0)
			y_paddle1 <= y_paddle1-1;
		else if (!button1 && y_paddle1+(paddleheight/2) < V_active)
			y_paddle1 <= y_paddle1+1;
		else y_paddle1 <= y_paddle1;
	end
	assign paddle1_on = (x >= x_paddle1-(paddlewidth/2) && x <= x_paddle1+(paddlewidth/2) && y >= y_paddle1-(paddleheight/2) && y < y_paddle1+(paddleheight/2))?1:0;
	assign rgb_paddle1 = 12'b000011110000; 
	//Second padlle
	always @ (posedge clk_1ms)
	begin
		if(!reset)
		begin	
			x_paddle2 <= H_active-(R_position + (paddlewidth/2));
			y_paddle2 <= V_active/2;
		end
		else if (!button2 && y_paddle2-(paddleheight/2) > 0)
			y_paddle2 <= y_paddle2-1;
		else if (!button3 && y_paddle2+(paddleheight/2) < V_active )
			y_paddle2 <= y_paddle2+1;
		else y_paddle2 <= y_paddle2;
	end
	assign paddle2_on = (x >= x_paddle2-(paddlewidth/2) && x <= x_paddle2+(paddlewidth/2) && y >= y_paddle2-(paddleheight/2) && y < y_paddle2+(paddleheight/2))?1:0;
	assign rgb_paddle2 = 12'b110000001100; //orange =12'bb111101110000
endmodule

module multiply(
                clk,
                multiplier,
                multiplicand,
                result
                );
input clk;
input [15:00] multiplier;
input [15:00] multiplicand;
output[31:00] result;
reg [31:00] result;
reg [15:00] abs_multiplicand;
reg lsb;
integer i,j;
always @( multiplicand or multiplier)
begin
    result = { 16'h0000, multiplier[15] ? -multiplier : multiplier };  
    abs_multiplicand = multiplicand[15] ? -multiplicand : multiplicand;
   for (i=15; i>=0; i = i - 1)
   begin    
       lsb    = result[0];
       result = result >>1;
       if (lsb == 1'b1)
       begin
         result[31:15] = result[30:15] + abs_multiplicand;   
       end
       if ((!i) && (multiplier[15] ^ multiplicand[15]))
       begin
         result = -result;
       end 
   end
end
endmodule

`timescale 1ns/1ps
module jt1943_prom_we(
    input                clk_rom,
    input                clk_rgb,
    input                downloading,
    input      [21:0]    ioctl_addr,
    input      [ 7:0]    ioctl_data,
    input                ioctl_wr,
    output reg [21:0]    prog_addr,
    output reg [ 7:0]    prog_data,
    output reg [ 1:0]    prog_mask, // active low
    output reg           prog_we,
    output reg [12:0]    prom_we
);
localparam SNDADDR=22'h14_000<<1, CHARADDR=22'h18_000*2,
    SCR1ADDR=22'h24_000<<1, ROMEND=22'h6C_000*2, MAP1ADDR=22'h1C_000<<1,
    OBJADDR=22'h4C_000<<1;
// latch signals that come from a different dommain
reg [21:0]    latched_addr;
reg [ 7:0]    latched_data;
reg           latched_wr;
always @(posedge clk_rom) begin
    latched_addr <= ioctl_addr; 
    latched_data <= ioctl_data;
    latched_wr   <= ioctl_wr;
end
wire [21:0] scr_start = latched_addr - SCR1ADDR;
wire [21:0] map_start = latched_addr - MAP1ADDR;
reg set_strobe, set_done;
reg [12:0] prom_we0;
always @(posedge clk_rgb) begin
    prom_we <= 'd0;
    if( set_strobe ) begin
        prom_we <= prom_we0;
        set_done <= 1'b1;
    end else if(set_done) begin
        set_done <= 1'b0;
    end
end
always @(posedge clk_rom) begin
    if( set_done ) set_strobe <= 1'b0;
    if ( latched_wr ) begin
        prog_we   <= 1'b1;
        prog_data <= latched_data;
        if(latched_addr < MAP1ADDR) begin
            if(latched_addr>=SNDADDR && latched_addr<CHARADDR) begin // Sound ROM
                prom_we0   <= 13'h10_00;
                set_strobe <= 1'b1;
                prog_we    <= 1'b0; // Do not write this on the SDRAM
                prog_addr  <= latched_addr - SNDADDR;
                prog_mask <= 2'b11;
            end else begin // Main ROM, CHAR ROM
                prog_addr <= {1'b0, latched_addr[21:1]};
                prog_mask <= {latched_addr[0], ~latched_addr[0]};
            end
        end
        else if(latched_addr < SCR1ADDR) begin // MAP1+MAP2
            // MAP data is reordered so reads hit consequitive addresses
            // this optimizes cache usage.
            prog_addr <= MAP1ADDR[21:1] + {map_start[21:5], map_start[3:1], map_start[4]};
            prog_mask <= {map_start[0], ~map_start[0]};
        end
        else if(latched_addr < OBJADDR) begin // SCR
            prog_addr <= SCR1ADDR[21:1] + {scr_start[21:16], scr_start[14:0]};
            prog_mask <= { scr_start[15], ~scr_start[15]};
        end
        else if(latched_addr < ROMEND) begin // OBJ
            prog_addr <= SCR1ADDR[21:1] + {scr_start[21:16],
                scr_start[14:6], scr_start[4:1], scr_start[5], scr_start[0] }; // bit order swapped to increase cache hits
            prog_mask <= { scr_start[15], ~scr_start[15]};
        end
        else begin // PROMs
            prog_addr <= { 3'h7, latched_addr[18:0] };
            prog_we   <= 1'b0;
            prog_mask <= 2'b11;
            case(latched_addr[11:8])
                4'h0: prom_we0 <= 13'h0_01;    //
                4'h1: prom_we0 <= 13'h0_02;    //
                4'h2: prom_we0 <= 13'h0_04;    //
                4'h3: prom_we0 <= 13'h0_08;    //
                4'h4: prom_we0 <= 13'h0_10;    //
                4'h5: prom_we0 <= 13'h0_20;    //
                4'h6: prom_we0 <= 13'h0_40;    //
                4'h7: prom_we0 <= 13'h0_80;    //
                4'h8: prom_we0 <= 13'h1_00;    //
                4'h9: prom_we0 <= 13'h2_00;    //
                4'ha: prom_we0 <= 13'h4_00;    //
                4'hb: prom_we0 <= 13'h8_00;    //
                default: prom_we0 <= 13'h0;    //
            endcase
            set_strobe <= 1'b1;
        end
    end
    else begin
        prog_we <= 1'b0;
    end
end
endmodule // jt1492_promprog

`timescale 1ns / 1ps
module HighLevelFSM(
    input clock,
    input reset,
    input [14:0] controls,
    output reg [9:0] f_controls =0,
    output reg [9:0] t_controls =0,
	 output reg [9:0] m_controls =0,
	 output reg [11:0] status =0
    );
    	//Inititate state variables
	 reg [1:0] state=0;
	 reg [1:0] f = 0;
	 reg [1:0] t = 1;
	 reg [1:0] m = 2;
	 //Enter acts as a special control signal within HLFSM
	 wire enter;
	 assign enter = controls[12];
	 //Controls sent to individual modules
	 //f=frequency, t=time, m=mixer
	 reg [7:0] n_f_controls = 0;
	 reg [7:0] n_t_controls = 0;
	 reg [7:0] n_m_controls = 0;
	always@(posedge clock) begin
		if (reset) begin
			f_controls<=0;
			t_controls<=0;
			m_controls<=0;
			n_f_controls<=0;
			n_t_controls<=0;
			n_m_controls<=0;
			state<=0;
			status<=0;
		//State controlled by pressing number buttons 3-1
		end else if(controls[11]) begin
			state<=f;
		end else if(controls[10]) begin
			state<=t;
		end else if(controls[9]) begin
			state<=m;
		end else begin
			status[11:10]<=state;
			//Assign controls based on state
			case(state)
				f:
					begin
						n_f_controls[7:0]<=controls[7:0];
						f_controls[9:8]<=controls[14:13];
						status[9:0]<=f_controls[9:0];
//						if(enter) begin
							f_controls[7:0]<=n_f_controls[7:0];
//						end
					end
				t:
					begin
						n_t_controls[7:0]<=controls[7:0];
						t_controls[9:8]<=controls[14:13];
						status[9:0]<=t_controls[9:0];
						if(enter) begin
							t_controls[7:0]<=n_t_controls[7:0];
						end
					end
				m:
					begin
						n_m_controls[7:0]<=controls[7:0];
						m_controls[9:8]<=controls[14:13];
						status[9:0]<=m_controls[9:0];
						if(enter) begin
							m_controls[7:0]<=n_m_controls[7:0];
						end
					end
			endcase
		end
	end	
endmodule

