module reset_tree #(
  parameter DELAY0 = 10,
  parameter DELAY1 = 10,
  parameter DELAY2 = 10)
(
  input clk,
  input rst0,
  input rst1,
  input rst2,
  output reg delay_rst0,
  output reg delay_rst1,
  output reg delay_rst2,
  output [3:0] stage
);
  reg [31:0] rst_cnt = 32'b0;
  reg [3:0]  wd_rst_cnt = 4'b0;
  reg        wd_rst;
  reg [3:0]  rst_stage;
  always @ (posedge clk) begin
    if (&wd_rst_cnt == 0) begin
      wd_rst_cnt <= wd_rst_cnt + 1;
      wd_rst <= 1'b1;
      end
    else
      wd_rst <= 1'b0;
    end
  always @ (posedge clk) begin
  if (wd_rst) begin
    rst_stage <= 4'b0001;
    delay_rst0 <= 1'b1;
    delay_rst1 <= 1'b1;
    delay_rst2 <= 1'b1;
    rst_cnt <= 32'b0;
    end
  else begin
    case (rst_stage)
      4'b0001 : begin
        if (!rst0) begin
          rst_cnt <= rst_cnt + 1;
          delay_rst0 <= 1'b1;
          delay_rst1 <= 1'b1;
          delay_rst2 <= 1'b1;
          if (rst_cnt == DELAY0) begin
            delay_rst0 <= 1'b0;
            rst_cnt <= 32'b0;
            rst_stage <= 4'b0010;
            end
          end
        end
      4'b0010 : begin
        if (!rst1) begin
          rst_cnt <= rst_cnt + 1;
          delay_rst1 <= 1'b1;
          delay_rst2 <= 1'b1;
          if (rst_cnt == DELAY1) begin
            delay_rst1 <= 1'b0;
            rst_cnt <= 32'b0;
            rst_stage <= 4'b0100;
            end
          end
        end
      4'b0100 : begin
        if (!rst2) begin
          rst_cnt <= rst_cnt + 1;
          delay_rst2 <= 1'b1;
          if (rst_cnt == DELAY2) begin
            delay_rst2 <= 1'b0;
            rst_cnt <= 32'b0;
            rst_stage <= 4'b1000;
            end
          end
        end
      4'b1000 : begin
        delay_rst0 <= 1'b0;
        delay_rst1 <= 1'b0;
        delay_rst2 <= 1'b0;
        end
      default : rst_stage <= 4'b0001;
      endcase
    end
  end
  assign stage = rst_stage;
endmodule

