module ALUControl
(
	input [2:0] ALUOp,
	input [5:0] ALUFunction,
	output [3:0] ALUOperation
);
//se agregan todas las operacion que nuestro procesador sera capaz de ejecutar
localparam R_Type_AND    = 9'b111_100100;
localparam R_Type_OR     = 9'b111_100101;
localparam R_Type_NOR    = 9'b111_100111;
localparam R_Type_ADD    = 9'b111_100000;
localparam R_Type_SUB    = 9'b111_100010;
localparam R_Type_SRL    = 9'b111_000010;
localparam R_Type_SLL    = 9'b111_000000;
localparam R_Type_JR     = 9'b111_001000;
localparam I_Type_ADDI   = 9'b100_xxxxxx;
localparam I_Type_ORI    = 9'b101_xxxxxx;
localparam I_Type_LUI    = 9'b011_xxxxxx;
localparam I_Type_BEQ    = 9'b001_xxxxxx;
localparam I_Type_BNE    = 9'b010_xxxxxx;
localparam I_Type_SW     = 9'b110_xxxxxx;
localparam I_Type_LW     = 9'b000_xxxxxx;
reg [3:0] ALUControlValues;
wire [8:0] Selector;
assign Selector = {ALUOp, ALUFunction};
//se le agregan las instrucciones con un valor que debe coincidir con los valores en la ALU
always@(Selector)begin
	casex(Selector)
		R_Type_AND:    ALUControlValues = 4'b0000;
		R_Type_OR: 		ALUControlValues = 4'b0001;
		R_Type_NOR: 	ALUControlValues = 4'b0010;
		R_Type_ADD:		ALUControlValues = 4'b0011;
		R_Type_SUB: 	ALUControlValues = 4'b0100;
		R_Type_SRL:		ALUControlValues = 4'b0101;
		R_Type_SLL:		ALUControlValues = 4'b0110;
		R_Type_JR: 		ALUControlValues = 4'b1110;
		I_Type_LUI: 	ALUControlValues = 4'b0111;
		I_Type_ORI:		ALUControlValues = 4'b0001;
		I_Type_ADDI: 	ALUControlValues = 4'b0011;
		I_Type_BEQ: 	ALUControlValues = 4'b1000;
		I_Type_BNE: 	ALUControlValues = 4'b1001;
		I_Type_SW: 		ALUControlValues = 4'b0011;
		I_Type_LW:		ALUControlValues = 4'b0011;
		default: ALUControlValues = 4'b1111;
	endcase
end
assign ALUOperation = ALUControlValues;
endmodule

module fsm_counter (
    input clock,
    input synchronous_reset,
    input start,
    input write,
    output done
);
    parameter INIT=0, PROCESS1=1, PROCESS2=2, PROCESS3=3;
    reg [2:0] current_state, next_state;
    reg [2:0] counter;
    always@(*)begin
        case(current_state)
            INIT:  next_state = start?PROCESS1:INIT;
            PROCESS1:  next_state = PROCESS2;
            PROCESS2:  next_state = PROCESS3;
            PROCESS3:  next_state = PROCESS1;
        endcase
    end
    always@(posedge clock) begin
        if(synchronous_reset)
            current_state <= INIT;
        else
            current_state <= next_state;
    end
    always@(posedge clock) begin
        case(current_state) 
            INIT:  counter <= 3'b000;
            PROCESS1:  counter <= {2'b00,write};
            PROCESS2:  counter <= {counter[1:0],write};
            PROCESS3:  counter <= {counter[1:0],write};
        endcase
    end
    assign done = (current_state==PROCESS1) & (counter == 3'b011) | (counter == 3'b101) | (counter == 3'b110);
endmodule

