	reg [25:0] cnt;
	assign x_ = x > midx ? x - midx : midx - x;
	assign y_ = y > midy ? y - midy : midy - y;
	always@(*)begin
		if(  ((x_*x_) + (y_*y_) <= 16*16))begin
			gp_valid <= 1;
			if(cnt <= 5000000)begin
				if((x+y > midx+midy) ||(x+midy < y+midx))begin
					rgb <= 3'b110;
					gp_valid <= 1;
				end
				else
