					gp_valid <= 0;
			end
			else if(cnt <= 10000000)begin
				rgb <= 3'b110;
				gp_valid <= 1;
			end
		end
		else 
			gp_valid <= 0;
	end
	always@(posedge clk)begin
		if(cnt >=10000000)
			cnt <= 0;
		else
			cnt <= cnt + 1 ;
	end
//(x+y > midx+midy) || right down
