module led_clk(clk, reset, clk_out);
   //inputs
   input      clk, reset;
   //outputs
   output reg clk_out;
   //counter variable
   reg [15:0] count;
   always @(posedge clk, posedge reset) begin
      //if reset then reset count and clock
      if(reset) begin
         count <= 16'b0;
         clk_out <= 1'b0;
      end else 
      if(count >= 25000) begin
            count <= 16'b0;
            //set output clock to opposite if count is greater than or equal 
				//to 25000
            clk_out <= ~clk_out;
      end else begin
         //increment count
         count <= (count + 1);
      end     
     end
endmodule

