module sequence_detector_counter (
    input clock,
    input synchronous_reset,
    input data_input,
    output [3:0] counter_output,
    output is_counting,
    output is_done,
    input acknowledgement );
    parameter [3:0] STATE_0 = 4'b0000,  // Initial State
                    STATE_1 = 4'b0001,  
                    STATE_2 = 4'b0010,  
                    STATE_3 = 4'b0011,  
                    B_STATE_0 = 4'b0100,  
                    B_STATE_1 = 4'b0101,  
                    B_STATE_2 = 4'b0110,  
                    B_STATE_3 = 4'b0111,  
                    COUNT_STATE = 4'b1000,  
                    WAIT_STATE =  4'b1001;  
    reg [3:0] current_state, next_state;
    always @ (*)
        begin
            case(current_state)
                STATE_0: next_state <= (data_input) ? STATE_1 : STATE_0;
                STATE_1: next_state <= (data_input) ? STATE_2 : STATE_0;
                STATE_2: next_state <= (data_input) ? STATE_2 : STATE_3;
                STATE_3: next_state <= (data_input) ? B_STATE_0 : STATE_0;
                B_STATE_0: next_state <= B_STATE_1;
                B_STATE_1: next_state <= B_STATE_2;
                B_STATE_2: next_state <= B_STATE_3;
                B_STATE_3: next_state <= COUNT_STATE;
                COUNT_STATE: next_state <= (done_counting) ? WAIT_STATE : COUNT_STATE;
                WAIT_STATE: next_state <= (acknowledgement) ? STATE_0 : WAIT_STATE;
                default next_state <= STATE_0;
            endcase
        end
    // Data Path to implement Shift and Decrement
    wire shift_enable = (current_state == B_STATE_0)||(current_state == B_STATE_1)||(current_state == B_STATE_2)||(current_state == B_STATE_3);
    wire count_enable = (counter_output == 10'd999 && current_state == COUNT_STATE); 
    wire done_counting = (q_des == 4'b0 && counter_output == 10'd999);
    reg [9:0] count_register;
    reg [3:0] des_register;
    // count decrementer and shifter
    always @ (posedge clock)
        begin
            if (!shift_enable && !count_enable)
                des_register <= des_register;
            else if (shift_enable && !count_enable)
                des_register <= {des_register[2:0], data_input};
            else if (!shift_enable && count_enable)
                des_register <= des_register - 4'b1;
            else
                des_register <= des_register;
        end
    // 1000-counter
    always @ (posedge clock)
        begin
            if (synchronous_reset)
                count_register <= 10'd0;
            else if ((current_state == COUNT_STATE) && (count_register < 10'd999))
                count_register <= count_register + 10'd1;
            else
                count_register <= 10'd0;
        end
    // State Transition
    always @ (posedge clock)
        begin
            if (synchronous_reset)
                current_state <= STATE_0;
            else
                current_state <= next_state;
        end
    assign is_done = (current_state == WAIT_STATE);
    assign is_counting = (current_state == COUNT_STATE);
    assign counter_output = des_register;
endmodule

