                    begin
                        parities = 2'b00;
                        state = 2'b00;
                    end
                else if(in == 1'b1 && state == 2'b00)
                    begin
                        parities = 2'b11;
                        state = 2'b01;
                    end
                else if(in == 1'b0 && state == 2'b01)
                    begin
                        parities = 2'b10;
                        state = 2'b10;
                    end
                else if(in == 1'b1 && state == 2'b01)
                    begin
                        parities = 2'b01;
                        state = 2'b11;
                    end
                else if(in == 1'b0 && state == 2'b11)
                    begin
                        parities = 2'b01;
                        state = 2'b10;
                    end
                else if(in == 1'b1 && state == 2'b11)
                    begin
                        parities = 2'b10;
                        state = 2'b11;
                    end
                else if(in == 1'b0 && state == 2'b10)
                    begin
                        parities = 2'b11;
                        state = 2'b00;
                    end
                else if(in == 1'b1 && state == 2'b10)
