module keys #(parameter keys = 61) (
    input                  clk_i,
    input  wire            rst_n_i,
    input  wire [keys-1:0] keys_i,
    output reg  [keys-1:0] keys_o
    );
    // each key is represented by a 7-bit register
    reg [7:0] counter   [keys-1:0];
    integer key;
    // Debouncing Counter - Arm after pin change and counter high
    always @(posedge clk_i) begin
        for (key = 0; key < keys; key = key + 1) begin
            if (rst_n_i == 1'b0) begin
                counter[key] <= 1'b0;
                keys_o[key]  <= 1'b1;
            end else if (counter[key] != 8'hFF) begin
                counter[key] <= counter[key] + 1'b1;
            end else if (keys_o[key] != keys_i[key]) begin
                keys_o[key] <= keys_i[key];
                counter[key] <= 8'h00;
            end
        end
    end
endmodule

module IF_ID_FF(instr_ID, pc_ID, instr_IF, pc_IF, stall, rst_n, clk);
	// Inputs
	input wire [15:0] instr_IF, pc_IF;
	input wire stall, rst_n, clk;
	// Outputs
	output reg[15:0] instr_ID, pc_ID;
	// Local wires
	wire [15:0] next_instr, next_pc;
	always@(posedge clk, negedge rst_n)begin
		if(~rst_n)begin
			instr_ID <= 16'h0000;
			pc_ID <= 16'h0000;
		end
		else begin
			instr_ID <= next_instr;
			pc_ID <= next_pc;
		end
	end
	assign next_instr = (stall) ? instr_ID : instr_IF;
	assign next_pc = (stall) ? pc_ID : pc_IF;
endmodule

