module state_machine(
    input clk,
    input data_in,
    input reset,    // Synchronous reset
    output done
); 
    reg [3:0] data_counter;
    parameter RECEIVE=0, DONE=1, READY=3, ERROR=4;
    reg [2:0] current_state, next_state;
    always @(*) begin
        case (current_state)
            READY: next_state <= data_in ? READY : RECEIVE;
            RECEIVE: begin
                if((data_counter==8)&data_in) begin
                    next_state <= DONE;
                end else if((data_counter==8)&(~data_in)) begin
                    next_state <= ERROR;
                end else begin
                    next_state <= RECEIVE;
                end
            end
            DONE: next_state <= data_in ? READY : RECEIVE;
            ERROR: next_state <= data_in ? READY : ERROR;
        endcase
    end
    always @(posedge clk) begin
        if(reset) begin
            current_state <= READY;
            data_counter <= 0;
        end else begin
            if((current_state == RECEIVE)&&(data_counter!=8)) begin
                data_counter <= data_counter + 1;
            end else if(current_state == ERROR) begin
                data_counter <= 0;
            end else if(current_state == DONE) begin
                data_counter <= 0;
            end
            current_state <= next_state;
        end
    end
    assign done = (current_state == DONE);
endmodule

