module ALU_main(
    input [31:0] data1,
    input [31:0] data2,
    input [2:0] ALUctrl,
    output reg [31:0] alu_result,
    output reg zero
    );
	 always@(*)
	 begin
		case(ALUctrl)
			3'b000: alu_result = data1 + data2;
			3'b001: alu_result = data1 - data2;
			3'b010: alu_result = data1 & data2;
			3'b011: alu_result = data1 | data2;
			3'b100: alu_result = data1 << data2;
			3'b101: alu_result = data1 >> data2;
		endcase
		if(alu_result == 0)
			zero = 1'b1;
		else
			zero = 1'b0;
	 end
endmodule

module ALUDecoder(ALUOp,funct,ALUControl);
	input [1:0] ALUOp;
	input [5:0] funct;
	output [2:0] ALUControl;
	reg [2:0] ALUControl;
	always @(ALUOp or funct) begin
		casex ({ALUOp, funct})
			8'b00xxxxxx: ALUControl = 3'b010;
			8'bx1xxxxxx: ALUControl = 3'b110;
			8'b1x100000: ALUControl = 3'b010;
			8'b1x100010: ALUControl = 3'b110;
			8'b1x100100: ALUControl = 3'b000;
			8'b1x100101: ALUControl = 3'b001;
			8'b1x101010: ALUControl = 3'b111;
		endcase
	end
endmodule

module ALU(
	input [32 - 1: 0] in1  ,
	input [32 - 1: 0] in2  ,
	input [5 - 1: 0] ALUCtl,
	input Sign             ,
	output reg [32 - 1: 0] out
);
	wire ss;
	assign ss = {in1[31], in2[31]};
	wire lt_31;
	assign lt_31 = (in1[30:0] < in2[30:0]);
	// lt_signed means whether (in1 < in2)
	wire lt_signed;
	assign lt_signed = (in1[31] ^ in2[31])? 
		((ss == 2'b01)? 0: 1): lt_31;
	// different ALU operations
	always @(*)
		case (ALUCtl)
			5'b00000: out <= in1 & in2;
			5'b00001: out <= in1 | in2;
            5'b00011: out <= in1 | in2;
			5'b00010: out <= in1 + in2;
			5'b00110: out <= in1 - in2;
			5'b00111: out <= {31'h00000000, Sign? lt_signed: (in1 < in2)};
			5'b01100: out <= ~(in1 | in2);
			5'b01101: out <= in1 ^ in2;
			5'b10000: out <= (in2 << in1[4: 0]);
			5'b11000: out <= (in2 >> in1[4: 0]);
			5'b11001: out <= ({{32{in2[31]}}, in2} >> in1[4: 0]);
			default: out <= 32'h00000000;
		endcase
endmodule

