module comparator(gt,lt,eq,in1,in2,comp_enable,reset);
  parameter word_len = 14;
  input comp_enable,reset;
  input [word_len-1:0]in1,in2;
  output reg gt,lt,eq;
  always @(in1,in2,comp_enable,reset)
  begin: comparator_block
