			gt = 1'b1;
			lt = 1'b0;
			eq = 1'b0;
		end
		else if(in1<in2)
		begin
			lt = 1'b1;
			gt = 1'b0;
			eq = 1'b0;
		end
		else
		begin
			eq = 1'b1;
			lt = 1'b0;
			gt = 1'b0;
		end
	end 
	else 
	begin
		gt = 1'b0;
		lt = 1'b0;
		eq = 1'b0;
	end
  end
endmodule

