								RegWrite 	 <= 1'b1;
								Uncondbranch <= 1'b0;
								ALUOp    	 <= 3'b010;
							end
				`OP_OR: begin 
								Reg2Loc  	 <= 1'b0;
								ALUSrc   	 <= 1'b0;
								Branch   	 <= 1'b0;
								MemRead  	 <= 1'b0;
								MemWrite 	 <= 1'b0;
								MemtoReg 	 <= 1'b0;
								RegWrite 	 <= 1'b1;
								Uncondbranch <= 1'b0;
								ALUOp    	 <= 3'b011;
							end
				`OP_STUR: begin 
								Reg2Loc  	 <= 1'b1;
								ALUSrc   	 <= 1'b1;
								Branch   	 <= 1'b0;
								MemRead  	 <= 1'b0;
								MemWrite 	 <= 1'b1;
