								RegWrite 	 <= 1'b1;
								Uncondbranch <= 1'b0;
								ALUOp    	 <= 3'b000;
							 end
				`OP_ADDI: begin 
								Reg2Loc  	 <= 1'b1;
								ALUSrc   	 <= 1'b1;
								Branch   	 <= 1'b0;
								MemRead  	 <= 1'b0;
								MemWrite 	 <= 1'b0;
