								Branch   	 <= 1'b0;
								MemRead  	 <= 1'b0;
								MemWrite 	 <= 1'b0;
								MemtoReg 	 <= 1'b0;
								RegWrite 	 <= 1'b1;
								Uncondbranch <= 1'b0;
								ALUOp    	 <= 3'b001;
							 end
				`OP_CBZ: begin 
								Reg2Loc  	 <= 1'b1;
								ALUSrc   	 <= 1'b0;
								Branch   	 <= 1'b1;
								MemRead  	 <= 1'b0;
