    input [2:0] led5,
    input[1:0] state,
    input warning,
    output reg led1_out, led2_out, led3_out, led4_out, led5_out,
    output reg led6_out,
    output reg led7_out, led8_out
);
reg led;
parameter CNT_MAX = 25'd20000000;
reg[24:0] cnt;
