module fsm(clk, reset, an3, an2, an1, an0, char);
input clk, reset;
output an3, an2, an1, an0;
output [3:0] char;
reg [3:0] counter;
reg an3, an2, an1, an0;
reg [3:0] char;
always @(posedge clk or posedge reset) 
begin
	if(reset) 
	begin
		counter = 4'b0000;
		char = 4'b0010; 
		an3 = 1'b1; 
		an2 = 1'b1;
		an1 = 1'b1;
		an0 = 1'b1;
	end
	else 
	begin
		case(counter)
			4'b1111: 
			begin
				an3 = 1'b1;
				counter = counter - 1;
			end
			4'b1110: 
			begin 
				counter = counter - 1;
				char = 4'b0001;
			end
			4'b1100: 
			begin 
				counter = counter - 1; 
				an2 = 1'b0; 
			end 
			4'b1011: 
			begin 
				counter = counter - 1;
				an2 = 1'b1; 
			end	
			4'b1010: 
			begin 
				counter = counter - 1; 
				char = 4'b0110; 
			end
			4'b1000: 
			begin 
				counter = counter - 1; 
				an1 = 1'b0; 
			end 
			4'b0111: 
			begin
				counter = counter - 1;
				an1 = 1'b1;
			end
			4'b0110: 
			begin
				counter = counter - 1; 
				char = 4'b0001; 
			end
			4'b0100: 
			begin 
				counter = counter - 1; 
				an0 = 1'b0; 
			end 
			4'b0011: 
			begin
				counter = counter - 1;
				an0 = 1'b1;
			end
			4'b0010: 
			begin
				counter = counter - 1; 
				char = 4'b0010; 
			end
			4'b0000: 
			begin 
				counter = counter - 1; 
				an3 = 1'b0; 
			end
			default: counter = counter - 1;
		endcase
	end
end
endmodule

