module seg7 (in,out);
	input wire [3:0] in;
	output reg [7:0] out;
	wire [1:0] wire_part;
	reg [5:0] reg_part;
	assign wire_part[1] = 1;//turns off decimal(i think)
	assign wire_part[0] = (in[3]&in[2]&(~in[1])&(~in[0])) | ((~in[3])&in[2]&in[1]&in[0]) | ((~in[3])&(~in[2])&(~in[1]));
	always @ (in[3:0]) begin
		case ({in[3],in[2],in[1],in[0]})
			4'b0000: begin
				reg_part = 6'b000000;
				out = {wire_part,reg_part};
			end
			4'b0001: begin
				reg_part = 6'b111001;
				out = {wire_part,reg_part};
			end
			4'b0010: begin
				reg_part = 6'b100100;
				out = {wire_part,reg_part};
			end
			4'b0011: begin
				reg_part = 6'b110000;
				out = {wire_part,reg_part};
