module jkff (
    input j, k, clk, rst, output reg q
);
    always@(posedge clk) begin
        if(rst)
        q <= 1'b0;
        else begin
            case ({j, k})
                2'b00 : q <= q;
                2'b01 : q <= 1'b0;
                2'b10 : q <= 1'b1;
                2'b11 : q <= ~q; 
                default: begin
                end
            endcase
        end
    end
endmodule

module half_adder(
						input a,
						input b,
						input c,
						output out,
						output c_out);
	wire w1,w2,w3;
	or  first_or( c_out , w3 , w2 );
	and first_and( w3 , w1 , c );
	and second_and( w2 , a , b );
	xor first_xor( out , w1 , c );
	xor second_xor( w1 , a , b );
endmodule

module full_adder 
  (
   a,
   b,
   carry_in,
   sum,
   carry_out
   );
  input  a;
  input  b;
  input  carry_in;
  output sum;
  output carry_out;
  wire   w_WIRE_1;
  wire   w_WIRE_2;
  wire   w_WIRE_3;
  assign w_WIRE_1 = a ^ b;
  assign w_WIRE_2 = w_WIRE_1 & carry_in;
  assign w_WIRE_3 = a & b;
  assign sum   = w_WIRE_1 ^ carry_in;
  assign carry_out = w_WIRE_2 | w_WIRE_3;
endmodule

