module FSMup(
clk, rst, in, out    );
	 input clk, rst;
	 input	in;
	 output reg [1:0] out;
	 wire w, w2;
	 //wire clk, cclk;
	 //clk50	divider(.clk(nclk),.rst(rst),.clkdivided1hz(clk), .clkdivided2hz(cclk));
	 //shift_reg r1 (clk,rst, in, w);
	 //risingdge edge1 (~clk, rst, w, w2);
	assign w2 = in;
	 reg [1:0] state, nextstate;
	// wire [64:1] dectext;
	 parameter [1:0] s0 = 2'b00, s1 = 2'b01, s2 = 2'b10, s3 = 2'b11;
	 always @ (w2 or state )
		if(w2 == 2'b0) nextstate = state;
		else
		case (state)
			s0:
			begin
				if(w2) begin nextstate = s1; out <= 2'b00; end // seven <= 7'b0000001;end
				//else nextstate = s0;
			end
			s1:
			begin
				if (w2) begin nextstate = s2; out<= 2'b01;end // seven <= 7'b1001111; end
			//else if (!w2[1]) nextstate = s1;
				//else nextstate = s0;
			end
			s2:
			begin
				if (w2) begin nextstate = s3; out<= 2'b10;end //seven <= 7'b0010010; end
			//else if (!w2[2]) nextstate = s2;
				//else nextstate = s0;
			end
			s3:
			begin
				if (w2) begin nextstate = s0; out <= 2'b11;end // seven <= 7'b0000110; end
				//else nextstate = s0;
			end
				default: begin
					nextstate = 2'bx;
				end
		endcase
		always @ (posedge clk or posedge rst)
		begin
			if (rst) begin state <= s0; end
			else state <= nextstate;
		end
endmodule

module fifo_module
    #(parameter DEPTH           = 32,
                WIDTH           = 8
     )(
    // Data
    input [7:0]         data_bus_in,
    output [7:0]    data_bus_out,
    // Instruction
    input               write_ins,
    input               read_ins,
    // State 
    output              full,
    output              empty,
    // Reset 
    input               rst_n
    );
    // Pointer
    localparam POINTER_SIZE = $clog2(DEPTH);
    localparam init_buffer = 8'b00000000;
    localparam init_index_front = 0;
    localparam init_index_rear = 0;
    reg [POINTER_SIZE - 1:0] front_queue;
    reg [POINTER_SIZE - 1:0] rear_queue;
    reg [WIDTH - 1:0] queue [DEPTH - 1:0];
    //Data 
    assign data_bus_out = queue[front_queue - 1];
    // State 
    assign full = (rear_queue == (front_queue - 1));
    assign empty = (rear_queue == front_queue);
    // Write instruction
    always @(posedge write_ins, negedge rst_n) begin
        if(!rst_n) begin
            rear_queue <= init_index_rear;
//            for(i = 0; i < capacity; i = i + 1) begin
//                queue[i] <= init_buffer;
//            end
//            queue[capacity - 1:0] <= 0;
        end
        else begin
            if(!full) begin
                queue[rear_queue] <= data_bus_in;
                rear_queue <= rear_queue + 1;
            end
        end
    end 
    // Read instruction
    always @(posedge read_ins, negedge rst_n) begin
        if(!rst_n) begin
            front_queue <= init_index_front;
        end
        else begin
            if(!empty) begin
                front_queue <= front_queue + 1;
            end
        end
    end
endmodule

module Limit(		//limit in cm 
	input wire clk,
	input wire [11:0] distance1,
	input wire [11:0] distance2,
	input wire [11:0] distance3,
	output reg [9:0] led
);
parameter limitInCm = 100;
always @(posedge clk)
	begin	
		if (distance1 > limitInCm)
			led <= 9'b000000111;
		else if (distance2 > limitInCm)
			led <= 9'b000111000;
		else if (distance3 > limitInCm)
			led <= 9'b111000000;
		else
			led <= 9'b000000000;
	end
endmodule

module write_address_gen #(parameter ADDR_WIDTH =5) (input wr_clk,input Wr_en,input [ADDR_WIDTH:0] sync_read_ptr,input reset, output reg Wr_full,output [ADDR_WIDTH-1:0] wr_address,output reg [ADDR_WIDTH:0] wr_ptr);
reg [ADDR_WIDTH:0] wr_bin_ptr;
wire temp_full;
wire [ADDR_WIDTH:0] wr_gray_ptr_next, wr_bin_ptr_next;
always @(posedge wr_clk,posedge reset)
	if (reset)
		{wr_bin_ptr, wr_ptr} <= 0;
	else
		{wr_bin_ptr, wr_ptr} <= {wr_bin_ptr_next, wr_gray_ptr_next};
assign wr_address = wr_bin_ptr[ADDR_WIDTH-1:0];
assign wr_bin_ptr_next = wr_bin_ptr + (Wr_en & ~Wr_full); // will increment by 1 as long as enable is 1 and full is 0
assign wr_gray_ptr_next = (wr_bin_ptr_next>>1) ^ wr_bin_ptr_next; // binary to gray code
assign temp_full = (wr_gray_ptr_next=={~sync_read_ptr[ADDR_WIDTH:ADDR_WIDTH-1], sync_read_ptr[ADDR_WIDTH-2:0]});
// if read_ptr is at 000000 and write_ptr is at 100000
// grey code is 000000 and 110000
// so 110000 == {~(00),0000} is fifo is full
always @(posedge wr_clk,posedge reset)
    if (reset)
		Wr_full <= 1'b0;
	 else
	    Wr_full <= temp_full;
endmodule

