`timescale 1ns/1ps
module fifo #(
	parameter DEPTH = 16,
	parameter DEPTH_l = 4,
	parameter WIDTH = 8
)(
	input										clock,
	input										reset,
	input										wr,
	input				[WIDTH-1:0]	din,
	input										rd,
	output			[WIDTH-1:0]	dout,
	output									full,
	output									empty
);
reg	[WIDTH-1:0] data [0:DEPTH-1];
reg [DEPTH_l:0] wr_pnt;
reg [DEPTH_l:0] rd_pnt;
integer i;
assign dout = !empty ? data[rd_pnt[DEPTH_l-1:0]] : 0;
assign empty = wr_pnt == rd_pnt;
assign full = (wr_pnt[DEPTH_l] != rd_pnt[DEPTH_l]) & (wr_pnt[DEPTH_l-1:0] == rd_pnt[DEPTH_l-1:0]);
always @(posedge clock)
if (reset)
	rd_pnt <= 0;
else if (rd & !empty)
	rd_pnt <= rd_pnt + 1;
else
	rd_pnt <= rd_pnt;
always @(posedge clock)
if (reset)
	wr_pnt <= 0;
else if (wr & !full)
	wr_pnt <= wr_pnt + 1;
else
	wr_pnt <= wr_pnt;
always @(posedge clock)
if (reset)
	for (i=0; i < DEPTH; i = i+1) begin
		data[i] <= 0;
	end
else if (wr & !full)
	data[wr_pnt] <= din;
else
	for (i=0; i < DEPTH; i = i+1) begin
		data[i] <= data[i];
	end
endmodule

module cafea(
	clk,
	y,
	n,
	fond,
	rst_n,
	cafea,
	cioco,
	zahar,
	lapte,
	msg
);
input clk;
input y;
input n;
input [4:0]fond;
input rst_n;
output reg cafea;
output reg cioco;
output reg zahar;
output reg lapte;
output reg[3:0]msg;
localparam Idle = 4'd0;
localparam Meniu = 4'd1;
localparam Cafea = 4'd2;
localparam Ciocolata = 4'd3;
localparam Lapte_extra = 4'd4;
localparam Zahar_extra = 4'd5;
localparam Bani = 4'd6;
localparam Fond = 4'd7;
localparam Activ = 4'd8;
//stari suplimentare intermediare
localparam Lapte = 4'd9;
localparam Zahar = 4'd10;
reg [3:0]state;
always @(posedge clk,negedge rst_n) begin		
	if(~rst_n)
		state<=Idle;
    else begin
        case(state)
        Idle: begin
            if(y)
				state<=Meniu;
				else
				state<=state;
        end
        Meniu: begin
            if(y)
                state <= Cafea;
            else if(n)
                state <= Ciocolata;
			else
				state <= state;
        end
		Ciocolata: begin
            state<=Lapte_extra;
			end
		Cafea: begin
                state<=Lapte_extra;
			end
		Lapte_extra: begin
                if(y)
				state<=Lapte;
				else if(n)
				state<=Zahar_extra;
				else
				state <= state;
			end
		Zahar_extra: begin
                if(y)
				state<=Zahar;
				else if(n)
				state<=Bani;
				else
				state <= state;				
			end
		Lapte: begin
            state<=Zahar_extra;
			end
		Zahar: begin
                state <= Bani;
			end
		Bani: begin
                if(y && fond>=5)
				state<=Activ;
				else if(y && fond<5)
				state<=Fond;
				else
				state <= state;				
			end	
		Fond: begin
                state <= Bani;		
			end
        default: state<=Idle;
        endcase
    end
end
always @(*) begin
    case(state)
	Idle: msg = 4'd0;
	Meniu: msg = 4'd1;
	Cafea: begin 
		msg = 4'd2;
		cafea=1;
	end
	Ciocolata: begin 
		msg = 4'd3;
		cioco=1;
	end
	Lapte_extra: msg = 4'd4;
	Zahar_extra: msg = 4'd5;
	Bani: msg = 4'd6;
	Fond: msg = 4'd7;
	Activ: msg = 4'd8;
//stari suplimentare intermediare
	Lapte: begin 
		msg = 4'd9;
		lapte=1;
	end
	Zahar: begin 
		msg = 4'd10;
		zahar=1;
	end
    default: msg = 4'd0;
    endcase
end
endmodule

module lut
	(
		input [2:0] block, // 0 is I, 1 is J, 2 is L, 3 is O, 4 is S, 5 is T,6 is Z.
		input [1:0] rotation,
		output reg [7:0] X, // [1:0] x1, [3:2] x2, [5:4] x3, [7:6] x4
		output reg [7:0] Y, // [1:0] y1, [3:2] y2, [5:4] y3, [7:6] y4
		output reg [5:0] colour
	);
	always @(*) begin
		case (block)
			3'b000: begin
				colour = 6'b00_11_11;
				if (rotation == 2'b00 || rotation == 2'b10) begin
					X = 8'b00_01_10_11;
					Y = 8'b00_00_00_00;
				end
				else begin
					X = 8'b00_00_00_00;
					Y = 8'b00_01_10_11;
				end
			end
			3'b001: begin
				colour = 6'b00_00_11;
				if (rotation == 2'b00) begin
					X = 8'b00_00_01_10;
					Y = 8'b00_01_01_01;
				end
				else if (rotation == 2'b01) begin
					X = 8'b00_00_00_01;
					Y = 8'b00_01_10_00;
				end
				else if (rotation == 2'b10) begin
					X = 8'b00_01_10_10;
					Y = 8'b01_01_01_10;
				end
				else begin
					X = 8'b00_01_01_01;
					Y = 8'b10_10_01_00;
				end
			end
			3'b010: begin
				colour = 6'b11_10_00;
				if (rotation == 2'b00) begin
					X = 8'b00_01_10_10;
					Y = 8'b01_01_01_00;
				end
				else if (rotation == 2'b01) begin
					X = 8'b00_00_00_01;
					Y = 8'b00_01_10_10;
				end
				else if (rotation == 2'b10) begin
					X = 8'b00_00_01_10;
					Y = 8'b00_01_00_00; // may be a problem
				end
				else begin
					X = 8'b00_01_01_01;
					Y = 8'b00_00_01_10;
				end
			end
			// The Square
			3'b011: begin
				X = 8'b00_01_00_01;
				Y = 8'b00_00_01_01;
				colour = 6'b11_11_00;
			end
			3'b100: begin
				colour = 6'b00_11_00;
				if (rotation == 2'b00) begin
					X = 8'b00_01_01_10;
					Y = 8'b01_01_00_00;
				end
				else if (rotation == 2'b01) begin
					X = 8'b00_00_01_01;
					Y = 8'b00_01_01_10;
				end
				else if (rotation == 2'b10) begin
					X = 8'b00_01_01_10;
					Y = 8'b10_10_01_01;
				end
				else begin
					X = 8'b00_00_01_01;
					Y = 8'b00_01_01_10;
				end	
			end
			3'b101: begin
				colour = 6'b11_00_11;
				if (rotation == 2'b00) begin
					X = 8'b00_01_01_10;
					Y = 8'b01_01_00_01;
				end
				else if (rotation == 2'b01) begin
					X = 8'b00_00_00_01;
					Y = 8'b00_01_10_01;
				end
				else if (rotation == 2'b10) begin
					X = 8'b00_01_01_10;
					Y = 8'b01_01_10_01;
				end
				else begin
					X = 8'b00_01_01_01;
					Y = 8'b01_00_01_10;
				end
			end
			3'b110: begin
				colour = 6'b11_00_00;
				if (rotation == 2'b00) begin
					X = 8'b00_01_01_10;
					Y = 8'b00_00_01_01;
				end
				else if (rotation == 2'b01) begin
					X = 8'b00_00_01_01;
					Y = 8'b01_10_01_00;
				end
				else if (rotation == 2'b10) begin
					X = 8'b00_01_01_10;
					Y = 8'b01_01_10_10;
				end
				else begin
					X = 8'b00_00_01_01;
					Y = 8'b10_01_01_00;
				end
			end
			default: begin
				colour = 6'b00_11_11;
				X = 8'b00_01_10_11;
				Y = 8'b00_00_00_00;
			end
		endcase
	end
endmodule

