module Counter99(
input wire clk,
input wire reset,
input wire enable,
output wire [3:0] count0,
output wire [3:0] count1
);
// Contador de quatro dígitos decimais com entrada de enable, reset e clock.
reg [3:0] s_count0; reg [3:0] s_count1;
  always @(posedge clk) begin
    if((reset == 1'b1)) begin
      s_count0 <= {4{1'b0}};
      s_count1 <= {4{1'b0}};
    end
    else if((s_count0 == 4'b1001 && s_count1 == 4'b1001)) begin
      s_count0 <= s_count0;
      s_count1 <= s_count1;
    end
    else if((!(s_count0[0] == 1'b0) && !(s_count0[0] == 1'b1))) begin
      s_count0 <= {4{1'b0}};
      s_count1 <= {4{1'b0}};
    end
    else if((enable == 1'b0)) begin
      s_count0 <= s_count0;
      s_count1 <= s_count1;
    end
    else begin
      if((s_count0 == 4'b1001)) begin
        s_count0 <= 4'b0000;
        if((s_count1 == 4'b1001)) begin
          s_count1 <= 4'b0000;
        end
        else begin
          s_count1 <= s_count1 + 1;
        end
      end
      else begin
        s_count0 <= s_count0 + 1;
      end
    end
  end
  assign count0 = s_count0;
  assign count1 = s_count1;
endmodule

module parity_checker_for_LBDR(
input wire [DATA_WIDTH - 1:0] RX,
input wire empty,
output reg faulty
);
parameter [31:0] DATA_WIDTH=32;
reg xor_all;
  always @(empty, RX) begin
    if(empty == 1'b0) begin
      xor_all <= XOR_REDUCE[RX[DATA_WIDTH - 1:1]];
    end
    else begin
      xor_all <= 1'b0;
    end
  end
  always @(RX, xor_all) begin
    faulty <= 1'b0;
    if(xor_all != RX[0]) begin
      faulty <= 1'b1;
    end
  end
endmodule

module Subsys_LCDDriver(
input wire CLK,
input wire RS,
input wire RW,
input wire CLR,
input wire RH,
input wire SC,
input wire [7:0] datai,
output reg Eo,
output reg RSo,
output reg RWo,
output reg [7:0] datao
);
  always @(CLK, RS, RW, CLR, RH, SC, datai) begin : P1
    reg [7:0] data = 1'b0;
    reg RSv, RWv = 1'b0;
    RSv = RS;
    RWv = RW;
    data = datai;
    if((CLR == 1'b1)) begin
      RSv = 1'b0;
      RWv = 1'b0;
      data = 8'b00000001;
    end
    if((RH == 1'b1)) begin
      RSv = 1'b0;
      RWv = 1'b0;
      data = 8'b00000010;
    end
    if((SC == 1'b1)) begin
      RSv = 1'b0;
      RWv = 1'b0;
      data = 8'b00010100;
    end
    Eo <= CLK;
    RSo <= RSv;
    RWo <= RWv;
    datao <= data;
  end
endmodule

module Counter60(
output reg [2:0] h,
output reg [3:0] l,
output reg co,
input wire en,
input wire clk,
input wire rst
);
  always @(posedge clk, posedge rst) begin : P1
    reg [3:0] tlow;
    reg [2:0] thigh;
    if(rst == 1'b1) begin
      tlow = {1{1'b0}};
      thigh = {1{1'b0}};
    end else begin
      co <= 1'b0;
      if(en == 1'b1) begin
        if(tlow < 10) begin
          tlow = tlow + 1;
        end
        if(tlow == 10) begin
          thigh = thigh + 1;
          tlow = {1{1'b0}};
        end
        if(thigh == 6) begin
          thigh = {1{1'b0}};
          co <= 1'b1;
        end
        h <= thigh;
        l <= tlow;
      end
    end
  end
endmodule

