module ICMP_detector(
input wire [7:0] data_in,
input wire enable,
input wire reset,
input wire clk,
output reg ICMP_detected,
output wire [7:0] test
);
reg [10:0] address_counter = 1'b0;
reg saved = 1'b0;
wire [7:0] test_i = 1'b0;
reg [7:0] reset_counter = 1'b0;
  assign test = reset_counter;
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      address_counter <= {11{1'b0}};
    end
    else if(enable == 1'b1) begin
      address_counter <= address_counter + 1;
    end
  end
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      ICMP_detected <= 1'b0;
    end
    else if(enable == 1'b1 && address_counter == 25 && data_in == 8'h01) begin
      ICMP_detected <= 1'b1;
      saved <= 1'b1;
    end
  end
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      reset_counter <= reset_counter + 1;
    end
  end
endmodule

module debounce(
