);
reg [23:0] c;
  always @(posedge clk) begin
    if(i == 1'b1) begin
      if(c == 24'hffffff) begin
        o <= 1'b1;
      end
      else begin
        o <= 1'b0;
      end
      c <= c + 1;
    end
    else begin
      c <= {24{1'b0}};
      o <= 1'b0;
    end
  end
endmodule

