reg [NUM_STAGES - 1:0] cnt;
  always @(posedge clk, posedge rst_n) begin
    if((rst_n == 1'b0)) begin
      cnt <= {((NUM_STAGES - 1)-(0)+1){1'b0}};
    end else begin
      if((clear == 1'b1)) begin
        cnt <= {((NUM_STAGES - 1)-(0)+1){1'b0}};
      end
      else if((enable == 1'b1)) begin
        // count up
        cnt <= (cnt) + 1;
      end
    end
  end
  assign cnt_out = cnt;
endmodule

