      PortBInRegD <= PBIN[7:0];
    end
    else begin
      PortBInRegD <= PortBInRegQ;
    end
  end
  always @(posedge RESET, posedge CLK) begin
    if((RESET == 1'b1)) begin
      PortBInRegQ <= 8'b00000000;
    end else begin
      PortBInRegQ <= PortBInRegD;
