module add_subb(
input wire [size - 1:0] a,
input wire [size - 1:0] b,
input wire add_sub,
output wire cout,
output wire [size - 1:0] sum
);
parameter [31:0] size;
//std_logic_vector defines array of 8 elements with indexed from 0 to 7; can use bit_vector as well
//define architecture for adder-subtractor
wire [size:0] carry;  //for connecting carry-out pins internally among adders
wire [size - 1:0] b_bar;
  assign carry[0] = add_sub;
  assign cout = add_sub ^ carry[size];
  genvar i;
  generate for (i=size - 1; i >= 0; i = i - 1) begin: G0
    //create the complete circuit
    assign b_bar[i] = b[i] ^ carry[0];
    full_adder adder_subtractor_array(
          .a(a[i]),
      .b(b_bar[i]),
      .carry_in(carry[i]),
      .carry_out(carry[i + 1]),
      .sum(sum[i]));
  end
  endgenerate
endmodule

module TBM_T_FSM(
input wire clk_i,
input wire reset_i,
input wire TBM_T_start_i,
input wire serdat_i,
output reg [3:0] payload_o,
output reg [3:0] type_o,
output reg wen_o
);
parameter [3:0]
  waiting = 0,
  tick_X1 = 1,
  tick_EW7 = 2,
  tick_EW6 = 3,
  tick_X2 = 4,
  tick_EW5 = 5,
  tick_EW4 = 6,
  tick_EW3 = 7,
  tick_EW2 = 8,
  tick_X3 = 9,
  tick_EW1 = 10,
  tick_EW0 = 11,
  tick_X4 = 12;
reg [3:0] s_state;
reg [7:0] s_payload;  //unsigned(3 downto 0);
  always @(posedge clk_i, posedge reset_i) begin
      // process p_serin
    if((reset_i == 1'b1)) begin
      // asynchronous reset 
      wen_o <= 1'b0;
      payload_o <= 4'b0000;
      type_o <= 4'b0000;
      s_state <= waiting;
    end else begin
      // rising clock edge
      case(s_state)
            //-----------------------------------------------------------------------
      tick_X1 : begin
        wen_o <= 1'b0;
        s_state <= tick_EW7;
        //-----------------------------------------------------------------------
      end
      tick_EW7 : begin
        s_payload[7] <= serdat_i;
        s_state <= tick_EW6;
        //-----------------------------------------------------------------------
      end
      tick_EW6 : begin
        s_payload[6] <= serdat_i;
        s_state <= tick_X2;
        //-----------------------------------------------------------------------
      end
      tick_X2 : begin
        s_state <= tick_EW5;
        //-----------------------------------------------------------------------
      end
      tick_EW5 : begin
        s_payload[5] <= serdat_i;
        s_state <= tick_EW4;
        //-----------------------------------------------------------------------
      end
      tick_EW4 : begin
        s_payload[4] <= serdat_i;
        s_state <= tick_EW3;
        //-----------------------------------------------------------------------
        //-----------------------------------------------------------------------
      end
      tick_EW3 : begin
        s_payload[3] <= serdat_i;
        s_state <= tick_EW2;
        //-----------------------------------------------------------------------
      end
      tick_EW2 : begin
        s_payload[2] <= serdat_i;
        payload_o[3] <= s_payload[7];
        payload_o[2] <= s_payload[6];
        payload_o[1] <= s_payload[5];
        payload_o[0] <= s_payload[4];
        wen_o <= 1'b1;
        type_o <= 4'b1011;
        s_state <= tick_X3;
        //-----------------------------------------------------------------------
      end
      tick_X3 : begin
        wen_o <= 1'b0;
        s_state <= tick_EW1;
        //-----------------------------------------------------------------------
      end
      tick_EW1 : begin
        s_payload[1] <= serdat_i;
        s_state <= tick_EW0;
        //-----------------------------------------------------------------------
      end
      tick_EW0 : begin
        s_payload[0] <= serdat_i;
        s_state <= tick_X4;
        //-----------------------------------------------------------------------
        //-----------------------------------------------------------------------
      end
      tick_X4 : begin
        payload_o[3] <= s_payload[3];
        payload_o[2] <= s_payload[2];
        payload_o[1] <= s_payload[1];
        payload_o[0] <= s_payload[0];
        wen_o <= 1'b1;
        type_o <= 4'b1100;
        s_state <= waiting;
        //-----------------------------------------------------------------------
      end
      default : begin
        if(TBM_T_start_i == 1'b1) begin
          wen_o <= 1'b0;
          s_state <= tick_X1;
        end
        else begin
          wen_o <= 1'b0;
          s_state <= waiting;
        end
      end
      endcase
    end
  end
endmodule

