module pwm(
input wire clk,
input wire rst,
input wire enable,
input wire [31:0] top,
input wire [31:0] duty_cycle,
output wire output
);
reg [31:0] timer_count;
reg out_signal;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      timer_count <= {32{1'b0}};
      out_signal <= 1'b1;
    end else begin
      if((enable == 1'b1)) begin
        timer_count <= timer_count + 1;
      end
      if((timer_count > (top))) begin
        timer_count <= {32{1'b0}};
      end
      if((timer_count < (duty_cycle))) begin
        out_signal <= 1'b0;
      end
      else begin
        out_signal <= 1'b1;
      end
    end
  end
  assign output = out_signal;
endmodule

