module Memory(
input wire Clk,
input wire rst,
input wire Mux_Selector,
input wire Memory_WriteEnable,
input wire Stack_WriteEnable,
input wire StackPushPop,
input wire [9:0] InputAddress,
input wire [9:0] LoadAdress,
input wire [15:0] DataIn,
output reg [15:0] DataOut,
output reg [15:0] M0,
output reg [15:0] M1,
input wire Flags_Z_In,
input wire Flags_NF_In,
input wire Flags_V_In,
input wire Flags_C_In,
output reg Flags_Z_Out,
output reg Flags_NF_Out,
output reg Flags_V_Out,
output reg Flags_C_Out,
input wire [4:0] BranchOpCode_In,
input wire [15:0] BranchR1_In,
output reg [15:0] Branch_Out
);
//StackPushPop 0: psuh, 1: pop
//FlagEnable : in std_logic;
reg [9:0] Address;
wire [15:0] DO; wire [15:0] DO0; wire [15:0] DO1;
wire [15:0] dontCare1; wire [15:0] dontCare2;
  syncram2 #(
      .n(10))
  Mem(
      Clk,
    rst,
    Memory_WriteEnable,
    Stack_WriteEnable,
    StackPushPop,
    Address,
    datain,
    DO,
    DO0,
    DO1);
  always @(posedge clk, posedge rst) begin
    if(Mux_Selector == 1'b0) begin
      Address <= InputAddress;
    end
    else begin
      Address <= LoadAdress;
    end
    DataOut <= DO;
    M0 <= DO0;
    M1 <= DO1;
    if(BranchOpCode_In == 5'b10100 && Flags_Z_In == 1'b1) begin
      //JZ Rdst
      Branch_Out <= BranchR1_In;
      Flags_Z_Out <= 1'b0;
    end
    else if(BranchOpCode_In == 5'b10101 && Flags_NF_In == 1'b1) begin
      //JN Rdst
      Branch_Out <= BranchR1_In;
      Flags_NF_Out <= 1'b0;
    end
    else if(BranchOpCode_In == 5'b10110 && Flags_C_In == 1'b1) begin
      //JC Rdst
      Branch_Out <= BranchR1_In;
      Flags_C_Out <= 1'b0;
    end
    else if(BranchOpCode_In == 5'b10111) begin
      //JMP Rdst	
      Branch_Out <= BranchR1_In;
    end
    else if(BranchOpCode_In == 5'b11001) begin
      //RET
      Branch_Out <= DO;
    end
    else if(BranchOpCode_In == 5'b11010) begin
      //RTI --FLAGS RESTORED
      Branch_Out <= DO;
      Flags_Z_Out <= 1'b0;
      Flags_NF_Out <= 1'b0;
      Flags_C_Out <= 1'b0;
      Flags_V_Out <= 1'b0;
    end
    else begin
      Flags_Z_Out <= Flags_Z_In;
      Flags_NF_Out <= Flags_NF_In;
      Flags_C_Out <= Flags_C_In;
      Flags_V_Out <= Flags_V_In;
    end
  end
endmodule

