module ALUN(
input wire [N - 1:0] a,
input wire [N - 1:0] b,
input wire [2:0] op,
output wire [N - 1:0] r,
output wire [N - 1:0] m,
output wire [N - 1:0] r2
);
parameter [31:0] N=8;
wire [N - 1:0] s_a; wire [N - 1:0] s_b; reg [N - 1:0] s_r;
wire [(2 * N) - 1:0] s_m;
  assign s_a = a;
  assign s_b = b;
  assign s_m = s_a * s_b;
  always @(*) begin
    case(op)
      3'b000 : s_r <= s_a + s_b;
      3'b001 : s_r <= s_a - s_b;
      3'b010 : s_r <= s_m[N - 1:0];
      3'b011 : s_r <= s_a / s_b;
      3'b100 : s_r <= s_a % s_b;
      3'b101 : s_r <= s_a & s_b;
      3'b110 : s_r <= s_a | s_b;
      3'b111 : s_r <= s_a ^ s_b;
    endcase
  end
  assign r = s_r;
  assign m = (op == 3'b010) ? s_m[(2 * N) - 1:4] : {((N - 1)-(0)+1){1'b0}};
  assign r2 = r;
endmodule

