  always @(*) begin
    case(Shift_Cnt)
      3'b111 : Shift_Temp <= Pipe_Serializer[Bit_Ptr + 7 -: 7 + 1];
      3'b110 : Shift_Temp <= {Pipe_Serializer[Bit_Ptr + 6 -: 6 + 1],Bit_Serializer[7]};
      3'b101 : Shift_Temp <= {Pipe_Serializer[Bit_Ptr + 5 -: 5 + 1],Bit_Serializer[7:6]};
      3'b100 : Shift_Temp <= {Pipe_Serializer[Bit_Ptr + 4 -: 4 + 1],Bit_Serializer[7:5]};
      3'b011 : Shift_Temp <= {Pipe_Serializer[Bit_Ptr + 3 -: 3 + 1],Bit_Serializer[7:4]};
      3'b010 : Shift_Temp <= {Pipe_Serializer[Bit_Ptr + 2 -: 2 + 1],Bit_Serializer[7:3]};
      3'b001 : Shift_Temp <= {Pipe_Serializer[Bit_Ptr + 1 -: 1 + 1],Bit_Serializer[7:2]};
      default : Shift_Temp <= {Pipe_Serializer[Bit_Ptr],Bit_Serializer[7:1]};
    endcase
  end
  // "Bit_Ptr" points to first pipeline bit to shift into output register
  always @(*) begin
    case(Shift_Cnt)
      3'b111 : Bit_Ptr_Temp <= Bit_Ptr + 8;
      3'b110 : Bit_Ptr_Temp <= Bit_Ptr + 7;
      3'b101 : Bit_Ptr_Temp <= Bit_Ptr + 6;
      3'b100 : Bit_Ptr_Temp <= Bit_Ptr + 5;
      3'b011 : Bit_Ptr_Temp <= Bit_Ptr + 4;
      3'b010 : Bit_Ptr_Temp <= Bit_Ptr + 3;
      3'b001 : Bit_Ptr_Temp <= Bit_Ptr + 2;
      default : Bit_Ptr_Temp <= Bit_Ptr + 1;
    endcase
  end
  // process for pipelining data
  always @(posedge clk) begin
    // initialize output register data from FIFO
    if((FSM_Fill_Serializer == 1'b1)) begin
      Bit_Serializer[0] <= FIFO_tdata[7];
      Bit_Serializer[1] <= FIFO_tdata[6];
      Bit_Serializer[2] <= FIFO_tdata[5];
      Bit_Serializer[3] <= FIFO_tdata[4];
      Bit_Serializer[4] <= FIFO_tdata[3];
      Bit_Serializer[5] <= FIFO_tdata[2];
      Bit_Serializer[6] <= FIFO_tdata[1];
      Bit_Serializer[7] <= FIFO_tdata[0];
      // update output register with shifted data
    end
    else if((Shift == 1'b1)) begin
      Bit_Serializer <= Shift_Temp;
    end
    // initialize pipeline register
    if((FSM_Fill_Pipeline_0 == 1'b1)) begin
      Pipe_Serializer[0] <= FIFO_tdata[7];
      Pipe_Serializer[1] <= FIFO_tdata[6];
      Pipe_Serializer[2] <= FIFO_tdata[5];
      Pipe_Serializer[3] <= FIFO_tdata[4];
      Pipe_Serializer[4] <= FIFO_tdata[3];
      Pipe_Serializer[5] <= FIFO_tdata[2];
      Pipe_Serializer[6] <= FIFO_tdata[1];
      Pipe_Serializer[7] <= FIFO_tdata[0];
      Bit_Ptr <= 0;
    end
    else if((FSM_Fill_Pipeline_1 == 1'b1)) begin
      Pipe_Serializer[8] <= FIFO_tdata[7];
      Pipe_Serializer[9] <= FIFO_tdata[6];
      Pipe_Serializer[10] <= FIFO_tdata[5];
      Pipe_Serializer[11] <= FIFO_tdata[4];
      Pipe_Serializer[12] <= FIFO_tdata[3];
      Pipe_Serializer[13] <= FIFO_tdata[2];
      Pipe_Serializer[14] <= FIFO_tdata[1];
      Pipe_Serializer[15] <= FIFO_tdata[0];
    end
    // update pipeline with shifted data
    if((Shift == 1'b1)) begin
      // if bit pointer falls beyond first byte
      if((Bit_Ptr_Temp >= 8)) begin
        Pipe_Serializer[7:0] <= Pipe_Serializer[15:8];
        Bit_Ptr <= Bit_Ptr_Temp - 8;
      end
      else begin
        Bit_Ptr <= Bit_Ptr_Temp;
      end
    end
    // new byte to fill shifted pipeline
    if((FSM_Shift_Pipeline == 1'b1)) begin
      Pipe_Serializer[8] <= FIFO_tdata[7];
      Pipe_Serializer[9] <= FIFO_tdata[6];
      Pipe_Serializer[10] <= FIFO_tdata[5];
      Pipe_Serializer[11] <= FIFO_tdata[4];
      Pipe_Serializer[12] <= FIFO_tdata[3];
      Pipe_Serializer[13] <= FIFO_tdata[2];
      Pipe_Serializer[14] <= FIFO_tdata[1];
      Pipe_Serializer[15] <= FIFO_tdata[0];
    end
  end
  // control FSM
  always @(posedge clk) begin
    if((Rst == 1'b1)) begin
      estado <= WAIT_START;
    end
    else begin
      case(estado)
            // wait for reset to end
      WAIT_START : begin
        estado <= FILL_SERIALIZER;
        // begin read FIFO to fill output register
      end
      FILL_SERIALIZER : begin
        if((FIFO_tvalid == 1'b1)) begin
          estado <= FILL_PIPELINE_0;
        end
        // read ahead next 2 bytes
      end
      FILL_PIPELINE_0 : begin
        if((FIFO_tvalid == 1'b1)) begin
          estado <= FILL_PIPELINE_1;
        end
      end
      FILL_PIPELINE_1 : begin
        if((FIFO_tvalid == 1'b1)) begin
          estado <= CHECK_PIPELINE;
        end
        // when data must be shited, read byte from FIFO
      end
      CHECK_PIPELINE : begin
        if((FSM_Shift_Needed == 1'b1 && FIFO_tvalid == 1'b0)) begin
          estado <= SHIFT_PIPELINE;
        end
        // if FIFO was empty when asked, wait until it has a byte inside
      end
      SHIFT_PIPELINE : begin
        if((FIFO_tvalid == 1'b1)) begin
          estado <= CHECK_PIPELINE;
        end
      end
      endcase
    end
  end
  // when a shift is requested and bit pointer is going to fall beyond output register, pipelined
  // must be shifted too
  assign FSM_Shift_Needed = Shift == 1'b1 && Bit_Ptr_Temp >= 8 ? 1'b1 : 1'b0;
  // read FIFO data
  always @(*) begin
    case(estado)
      FILL_SERIALIZER : FIFO_tready <= 1'b1;
      FILL_PIPELINE_0 : FIFO_tready <= 1'b1;
      FILL_PIPELINE_1 : FIFO_tready <= 1'b1;
      CHECK_PIPELINE : FIFO_tready <= FSM_Shift_Needed;
      SHIFT_PIPELINE : FIFO_tready <= 1'b1;
      default : FIFO_tready <= 1'b0;
    endcase
  end
  // initialize output data
  assign FSM_Fill_Serializer = estado == FILL_SERIALIZER ? FIFO_tvalid : 1'b0;
  // initialize pipeline data
  assign FSM_Fill_Pipeline_0 = estado == FILL_PIPELINE_0 ? FIFO_tvalid : 1'b0;
  assign FSM_Fill_Pipeline_1 = estado == FILL_PIPELINE_1 ? FIFO_tvalid : 1'b0;
  // update pipeline data
  always @(*) begin
    case(estado)
      CHECK_PIPELINE : FSM_Shift_Pipeline <= FIFO_tvalid & FSM_Shift_Needed;
      SHIFT_PIPELINE : FSM_Shift_Pipeline <= FIFO_tvalid;
      default : FSM_Shift_Pipeline <= 1'b0;
    endcase
  end
  // output data ready
  always @(*) begin
    case(estado)
      WAIT_START : Serial_tvalid <= 1'b0;
      FILL_SERIALIZER : Serial_tvalid <= 1'b0;
      FILL_PIPELINE_0 : Serial_tvalid <= 1'b0;
      FILL_PIPELINE_1 : Serial_tvalid <= 1'b0;
      default : Serial_tvalid <= 1'b1;
    endcase
  end
  assign Serial_tdata = Bit_Serializer;
endmodule

module zpuino_timers(
input wire wb_clk_i,
input wire wb_rst_i,
output reg [wordSize - 1:0] wb_dat_o,
input wire [wordSize - 1:0] wb_dat_i,
input wire [maxIObit:minIObit] wb_adr_i,
input wire wb_we_i,
input wire wb_cyc_i,
input wire wb_stb_i,
output wire wb_ack_o,
output wire wb_inta_o,
output wire wb_intb_o,
output wire [A_PWMCOUNT - 1:0] pwm_A_out,
output wire [B_PWMCOUNT - 1:0] pwm_B_out
);
parameter A_TSCENABLED=false;
parameter [31:0] A_PWMCOUNT=2;
parameter [31:0] A_WIDTH=16;
parameter A_PRESCALER_ENABLED=true;
parameter A_BUFFERS=true;
parameter B_TSCENABLED=false;
parameter [31:0] B_PWMCOUNT=2;
parameter [31:0] B_WIDTH=16;
parameter B_PRESCALER_ENABLED=false;
parameter B_BUFFERS=false;
wire [wordSize - 1:0] timer0_read;
wire timer0_stb;
wire timer0_cyc;
wire timer0_we;
wire timer0_interrupt;
wire timer0_ack;
wire [wordSize - 1:0] timer1_read;
wire timer1_stb;
wire timer1_cyc;
wire timer1_we;
wire timer1_interrupt;
wire timer1_ack;
  assign wb_inta_o = timer0_interrupt;
  assign wb_intb_o = timer1_interrupt;
  //comp <= timer0_comp;
  timer #(
      .TSCENABLED(A_TSCENABLED),
    .PWMCOUNT(A_PWMCOUNT),
    .WIDTH(A_WIDTH),
    .PRESCALER_ENABLED(A_PRESCALER_ENABLED),
    .BUFFERS(A_BUFFERS))
  timer0_inst(
      .wb_clk_i(wb_clk_i),
    .wb_rst_i(wb_rst_i),
    .wb_dat_o(timer0_read),
    .wb_dat_i(wb_dat_i),
    .wb_adr_i(wb_adr_i[7:2]),
    .wb_cyc_i(timer0_cyc),
    .wb_stb_i(timer0_stb),
    .wb_we_i(timer0_we),
    .wb_ack_o(timer0_ack),
    .wb_inta_o(timer0_interrupt),
    .pwm_out(pwm_A_out));
  timer #(
      .TSCENABLED(B_TSCENABLED),
    .PWMCOUNT(B_PWMCOUNT),
    .WIDTH(B_WIDTH),
    .PRESCALER_ENABLED(B_PRESCALER_ENABLED),
    .BUFFERS(B_BUFFERS))
  timer1_inst(
      .wb_clk_i(wb_clk_i),
    .wb_rst_i(wb_rst_i),
    .wb_dat_o(timer1_read),
    .wb_dat_i(wb_dat_i),
    .wb_adr_i(wb_adr_i[7:2]),
    .wb_cyc_i(timer1_cyc),
    .wb_stb_i(timer1_stb),
    .wb_we_i(timer1_we),
    .wb_ack_o(timer1_ack),
    .wb_inta_o(timer1_interrupt),
    .pwm_out(pwm_B_out));
  always @(wb_adr_i, timer0_read, timer1_read) begin
    wb_dat_o <= {((wordSize - 1)-(0)+1){1'b0}};
    case(wb_adr_i[8])
    1'b0 : begin
      wb_dat_o <= timer0_read;
    end
    1'b1 : begin
      wb_dat_o <= timer1_read;
    end
    default : begin
      wb_dat_o <= {((wordSize - 1)-(0)+1){DontCareValue}};
    end
    endcase
  end
  assign timer0_cyc = wb_adr_i[8] == 1'b0 ? wb_cyc_i : 1'b0;
  assign timer1_cyc = wb_adr_i[8] == 1'b1 ? wb_cyc_i : 1'b0;
  assign timer0_stb = wb_adr_i[8] == 1'b0 ? wb_stb_i : 1'b0;
  assign timer1_stb = wb_adr_i[8] == 1'b1 ? wb_stb_i : 1'b0;
  assign timer0_we = wb_adr_i[8] == 1'b0 ? wb_we_i : 1'b0;
  assign timer1_we = wb_adr_i[8] == 1'b1 ? wb_we_i : 1'b0;
  assign wb_ack_o = timer0_ack | timer1_ack;
    //spp_data(0) <= timer0_spp_data;
  //spp_data(1) <= timer1_spp_data;
  //spp_en(0) <= timer0_spp_en;
  //spp_en(1) <= timer1_spp_en;
endmodule

module siete_segmentos_4bits_mux(
input wire clk,
input wire reset,
input wire [3:0] D0,
input wire [3:0] D1,
input wire [3:0] D2,
input wire [3:0] D3,
output reg [3:0] salida,
output reg [3:0] MUX
);
//Primer digito.
//Segundo digito.
//Tercer digito.
//Cuarto digito.
//Salida del multiplexor (valor a desplegar).
//Valor que define cual digito se va a mostrar.
parameter [2:0]
  rst = 0,
  v0 = 1,
  v1 = 2,
  v2 = 3,
  v3 = 4;
reg [2:0] estado;
  always @(posedge reset, posedge clk) begin
    if((reset == 1'b1)) begin
      estado <= rst;
      MUX <= 4'hF;
      salida <= 4'b1111;
    end else begin
      case(estado)
      v0 : begin
        salida <= D3;
        MUX <= 4'b1110;
        estado <= v1;
      end
      v1 : begin
        salida <= D2;
        MUX <= 4'b1101;
        estado <= v2;
      end
      v2 : begin
        salida <= D1;
        MUX <= 4'b1011;
        estado <= v3;
      end
      default : begin
        salida <= D0;
        MUX <= 4'b0111;
        estado <= v0;
      end
      endcase
    end
  end
endmodule

module ip_block_ctrl(
input wire rst,
input wire clk_cmd,
input wire in_cmd_val,
input wire [63:0] in_cmd,
output wire out_cmd_val,
output wire [63:0] out_cmd,
output wire cmd_busy,
output wire [31:0] reg0,
output wire [31:0] reg1,
input wire [31:0] reg2,
input wire [31:0] reg3,
input wire [31:0] reg4,
input wire [31:0] reg5,
input wire [31:0] reg6,
input wire [31:0] reg7,
input wire [31:0] reg8,
input wire [31:0] mbx_in_reg,
input wire mbx_in_val
);
parameter [27:0] START_ADDR=28'h0000000;
parameter [27:0] STOP_ADDR=28'h00000FF;
// Command Interface
// out
//out
//in
//in
//in 
//in
//in
//in
//in
//value of the mailbox to send
//pulse to indicate mailbox is valid 
//-----------------------------------------------------------------------------------
// Architecture declaration
//-----------------------------------------------------------------------------------
//--------------------------------------------------------------------------------------------------
// Constants
//--------------------------------------------------------------------------------------------------
parameter ADDR_REG0 = 32'h00000000;
parameter ADDR_REG1 = 32'h00000001;
parameter ADDR_REG2 = 32'h00000002;
parameter ADDR_REG3 = 32'h00000003;
parameter ADDR_REG4 = 32'h00000004;
parameter ADDR_REG5 = 32'h00000005;
parameter ADDR_REG6 = 32'h00000006;
parameter ADDR_REG7 = 32'h00000007;
parameter ADDR_REG8 = 32'h00000008;
parameter ADDR_REG9 = 32'h00000009;
parameter ADDR_REGA = 32'h0000000A;
parameter ADDR_REGB = 32'h0000000B;
parameter ADDR_REGC = 32'h0000000C;
parameter ADDR_REGD = 32'h0000000D;
parameter ADDR_REGE = 32'h0000000E;
parameter ADDR_REGF = 32'h0000000F;  //--------------------------------------------------------------------------------------------------
// Signals
//--------------------------------------------------------------------------------------------------
wire out_reg_val;
wire [27:0] out_reg_addr;
wire [31:0] out_reg;
wire in_reg_req;
wire [27:0] in_reg_addr;
reg in_reg_val;
reg [31:0] in_reg;
reg [31:0] register0;
reg [31:0] register1;
wire [31:0] register2;
wire [31:0] register3;
wire [31:0] register4;
wire [31:0] register5;
wire [31:0] register6;
wire [31:0] register7;
wire [31:0] register8;
wire [31:0] register9;
wire [31:0] registerA;  //*************************************************************************************************
  //*************************************************************************************************
  assign reg0 = register0;
  assign reg1 = register1;
  //--------------------------------------------------------------------------------------------------
  // Stellar Command Interface
  //--------------------------------------------------------------------------------------------------
  stellar_generic_cmd #(
      .START_ADDR(START_ADDR),
    .STOP_ADDR(STOP_ADDR))
  stellar_cmd_inst(
      .reset(rst),
    .clk_cmd(clk_cmd),
    .in_cmd_val(in_cmd_val),
    .in_cmd(in_cmd),
    .out_cmd_val(out_cmd_val),
    .out_cmd(out_cmd),
    .clk_reg(clk_cmd),
    .out_reg_val(out_reg_val),
    .out_reg_addr(out_reg_addr),
    .out_reg(out_reg),
    .in_reg_req(in_reg_req),
    .in_reg_addr(in_reg_addr),
    .in_reg_val(in_reg_val),
    .in_reg(in_reg),
    .mbx_in_val(mbx_in_val),
    .mbx_in_reg(mbx_in_reg));
  assign cmd_busy = 1'b0;
  //--------------------------------------------------------------------------------------------------
  // Registers
  //--------------------------------------------------------------------------------------------------
  always @(posedge rst, posedge clk_cmd) begin
    if((rst == 1'b1)) begin
      in_reg_val <= 1'b0;
      in_reg <= {32{1'b0}};
      register0 <= {32{1'b0}};
      register1 <= {32{1'b0}};
    end else begin
      //----------------------------------------------------------
      // Write
      //----------------------------------------------------------
      if((out_reg_val == 1'b1 && out_reg_addr == ADDR_REG0)) begin
        register0 <= out_reg;
      end
      if((out_reg_val == 1'b1 && out_reg_addr == ADDR_REG1)) begin
        register1 <= out_reg;
      end
      //----------------------------------------------------------
      // Read
      //----------------------------------------------------------
      if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG0)) begin
        in_reg_val <= 1'b1;
        in_reg <= register0;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG1)) begin
        in_reg_val <= 1'b1;
        in_reg <= register1;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG2)) begin
        in_reg_val <= 1'b1;
        in_reg <= reg2;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG3)) begin
        in_reg_val <= 1'b1;
        in_reg <= reg3;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG4)) begin
        in_reg_val <= 1'b1;
        in_reg <= reg4;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG5)) begin
        in_reg_val <= 1'b1;
        in_reg <= reg5;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG6)) begin
        in_reg_val <= 1'b1;
        in_reg <= reg6;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG7)) begin
        in_reg_val <= 1'b1;
        in_reg <= reg7;
      end
      else if((in_reg_req == 1'b1 && in_reg_addr == ADDR_REG8)) begin
        in_reg_val <= 1'b1;
        in_reg <= reg8;
      end
      else begin
        in_reg_val <= 1'b0;
        in_reg <= in_reg;
      end
    end
  end
    //*************************************************************************************************
//*************************************************************************************************
endmodule

