module BLOCK_WORD_COUNTER(
input wire CLK,
input wire RESET,
input wire RESTART,
input wire BW_RDY,
output wire EOB_MARK,
output reg [15:0] BLOCK_HEADER_OUT,
output wire BLOCK_HEADER_OUT_RDY,
output wire BLOCK_COUNT_RDY
);
parameter [31:0] GBTid=0;
parameter [31:0] egroupID=0;
parameter [31:0] epathID=0;
// Block Word Ready Enable
//-----------
// End Of Block flag to send the trailer
//> sending block header
//> sending block header
//-----------
reg [9:0] count_sig = 1'b0;
reg [4:0] seq_num = 1'b0;
wire SOB_MARK; wire SOB_MARK0; wire seqCNTcase; wire seqCNTtrig; wire EOB_MARK_sig;
reg SOB_MARK1 = 1'b0; reg blockCountRdy = 1'b0;
wire [31:0] BLOCK_HEADER;  // two first words are always sent in the beginning of a block transmittion
parameter count_offset = 10'b0000000001;
  always @(posedge CLK) begin
    if(RESET == 1'b1 || RESTART == 1'b1) begin
      blockCountRdy <= 1'b0;
    end
    else if(SOB_MARK1 == 1'b1) begin
      blockCountRdy <= 1'b1;
    end
  end
  //
  assign BLOCK_COUNT_RDY = blockCountRdy;
  //------------------------------------------------------------
  // counting block words, data partition
  //------------------------------------------------------------
  always @(posedge CLK) begin
    if(RESET == 1'b1) begin
      count_sig <= {10{1'b0}};
    end
    else begin
      if(EOB_MARK_sig == 1'b1 || RESTART == 1'b1) begin
        count_sig <= count_offset;
      end
      else if(BW_RDY == 1'b1) begin
        count_sig <= count_sig + 1;
      end
    end
  end
  //------------------------------------------------------------
  // End Of Block trigger out for the 
  // sub-chunk data manager to insert a trailer
  //------------------------------------------------------------
  assign EOB_MARK_sig = (count_sig == BLOCK_WORDn) ? 1'b1 : 1'b0;
  // there is one more space left, for the trailer
  assign EOB_MARK = EOB_MARK_sig;
  // to output
  //------------------------------------------------------------
  // Block Sequence counter, 5 bit
  //------------------------------------------------------------
  assign seqCNTcase = EOB_MARK_sig | RESTART;
  pulse_pdxx_pwxx #(
      .pd(2),
    .pw(1))
  seqCNTtrig_pulse(
      CLK,
    seqCNTcase,
    seqCNTtrig);
  //
  always @(posedge CLK) begin
    if(RESET == 1'b1) begin
      seq_num <= {5{1'b0}};
    end
    else begin
      if(seqCNTtrig == 1'b1) begin
        seq_num <= seq_num + 1;
      end
    end
  end
  //------------------------------------------------------------
  // Start Of Block Mark to insert block header
  //------------------------------------------------------------
  assign SOB_MARK = (count_sig == count_offset) ? 1'b1 : 1'b0;
  //------------------------------------------------------------
  // Start Of Block produces 2 triggers 
  // to send 2 words, as header is 32bit
  //------------------------------------------------------------
  pulse_pdxx_pwxx #(
      .pd(0),
    .pw(1))
  SOB_MARK0_PULSE(
      CLK,
    SOB_MARK,
    SOB_MARK0);
  // FIFO WE to send word0
  always @(posedge CLK) begin
    SOB_MARK1 <= SOB_MARK0;
    // FIFO WE to send word1
  end
  //
  // [0xABCD_16]  [[block_counter_5]  [GBTid_5   egroupID_3   epathID_3]]
  assign BLOCK_HEADER = {16'b1010101111001101,seq_num,GBTid,egroupID,epathID};
  //
  always @(posedge CLK) begin
    if(SOB_MARK0 == 1'b1) begin
      BLOCK_HEADER_OUT <= BLOCK_HEADER[31:16];
    end
    else begin
      BLOCK_HEADER_OUT <= BLOCK_HEADER[15:0];
    end
  end
  //
  assign BLOCK_HEADER_OUT_RDY = SOB_MARK0 | SOB_MARK1;
    //
endmodule

module arbiter_out(
input wire reset,
input wire clk,
input wire X_N_Y,
input wire X_E_Y,
input wire X_W_Y,
input wire X_S_Y,
input wire X_L_Y,
input wire [1:0] credit,
output reg grant_Y_N,
output reg grant_Y_E,
output reg grant_Y_W,
output reg grant_Y_S,
output reg grant_Y_L
);
// From LBDR modules
// Grants given to LBDR requests (encoded as one-hot)
parameter [2:0]
  IDLE = 0,
  North = 1,
  East = 2,
  West = 3,
  South = 4,
  Local = 5;
reg [2:0] state = IDLE; reg [2:0] state_in = IDLE;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b0) begin
      state <= IDLE;
    end else begin
      state <= state_in;
    end
  end
  // anything below here is pure combinational
  always @(state, X_N_Y, X_E_Y, X_W_Y, X_S_Y, X_L_Y, credit) begin
    grant_Y_N <= 1'b0;
    grant_Y_E <= 1'b0;
    grant_Y_W <= 1'b0;
    grant_Y_S <= 1'b0;
    grant_Y_L <= 1'b0;
    case(state)
    IDLE : begin
      if(X_N_Y == 1'b1) begin
        state_in <= North;
      end
      else if(X_E_Y == 1'b1) begin
        state_in <= East;
      end
      else if(X_W_Y == 1'b1) begin
        state_in <= West;
      end
      else if(X_S_Y == 1'b1) begin
        state_in <= South;
      end
      else if(X_L_Y == 1'b1) begin
        state_in <= Local;
      end
      else begin
        state_in <= IDLE;
      end
    end
    North : begin
      if(credit != 2'b00 && X_N_Y == 1'b1) begin
        grant_Y_N <= 1'b1;
      end
      if(X_N_Y == 1'b1) begin
        state_in <= North;
      end
      else if(X_E_Y == 1'b1) begin
        state_in <= East;
      end
      else if(X_W_Y == 1'b1) begin
        state_in <= West;
      end
      else if(X_S_Y == 1'b1) begin
        state_in <= South;
      end
      else if(X_L_Y == 1'b1) begin
        state_in <= Local;
      end
      else begin
        state_in <= IDLE;
      end
    end
    East : begin
      if(credit != 2'b00 && X_E_Y == 1'b1) begin
        grant_Y_E <= 1'b1;
      end
      if(X_E_Y == 1'b1) begin
        state_in <= East;
      end
      else if(X_W_Y == 1'b1) begin
        state_in <= West;
      end
      else if(X_S_Y == 1'b1) begin
        state_in <= South;
      end
      else if(X_L_Y == 1'b1) begin
        state_in <= Local;
      end
      else if(X_N_Y == 1'b1) begin
        state_in <= North;
      end
      else begin
        state_in <= IDLE;
      end
    end
    West : begin
      if(credit != 2'b00 && X_W_Y == 1'b1) begin
        grant_Y_W <= 1'b1;
      end
      if(X_W_Y == 1'b1) begin
        state_in <= West;
      end
      else if(X_S_Y == 1'b1) begin
        state_in <= South;
      end
      else if(X_L_Y == 1'b1) begin
        state_in <= Local;
      end
      else if(X_N_Y == 1'b1) begin
        state_in <= North;
      end
      else if(X_E_Y == 1'b1) begin
        state_in <= East;
      end
      else begin
        state_in <= IDLE;
      end
    end
    South : begin
      if(credit != 2'b00 && X_S_Y == 1'b1) begin
        grant_Y_S <= 1'b1;
      end
      if(X_S_Y == 1'b1) begin
        state_in <= South;
      end
      else if(X_L_Y == 1'b1) begin
        state_in <= Local;
      end
      else if(X_N_Y == 1'b1) begin
        state_in <= North;
      end
      else if(X_E_Y == 1'b1) begin
        state_in <= East;
      end
      else if(X_W_Y == 1'b1) begin
        state_in <= West;
      end
      else begin
        state_in <= IDLE;
      end
    end
    default : begin
      if(credit != 2'b00 && X_L_Y == 1'b1) begin
        grant_Y_L <= 1'b1;
      end
      if(X_L_Y == 1'b1) begin
        state_in <= Local;
      end
      else if(X_N_Y == 1'b1) begin
        state_in <= North;
      end
      else if(X_E_Y == 1'b1) begin
        state_in <= East;
      end
      else if(X_W_Y == 1'b1) begin
        state_in <= West;
      end
      else if(X_S_Y == 1'b1) begin
        state_in <= South;
      end
      else begin
        state_in <= IDLE;
      end
    end
    endcase
  end
endmodule

module example_core_lite_v1_0_S00_AXI(
output wire [31:0] SLV_REG00_OUT,
output wire [31:0] SLV_REG01_OUT,
output wire [31:0] SLV_REG02_OUT,
output wire [31:0] SLV_REG03_OUT,
input wire [31:0] SLV_REG04_IN,
input wire [31:0] SLV_REG05_IN,
input wire [31:0] SLV_REG06_IN,
input wire [31:0] SLV_REG07_IN,
input wire [31:0] SLV_REG08_IN,
input wire [31:0] SLV_REG09_IN,
input wire [31:0] SLV_REG10_IN,
input wire [31:0] SLV_REG11_IN,
input wire S_AXI_ACLK,
input wire S_AXI_ARESETN,
input wire [C_S_AXI_ADDR_WIDTH - 1:0] S_AXI_AWADDR,
input wire [2:0] S_AXI_AWPROT,
input wire S_AXI_AWVALID,
output wire S_AXI_AWREADY,
input wire [C_S_AXI_DATA_WIDTH - 1:0] S_AXI_WDATA,
input wire [(C_S_AXI_DATA_WIDTH / 8) - 1:0] S_AXI_WSTRB,
input wire S_AXI_WVALID,
output wire S_AXI_WREADY,
output wire [1:0] S_AXI_BRESP,
output wire S_AXI_BVALID,
input wire S_AXI_BREADY,
input wire [C_S_AXI_ADDR_WIDTH - 1:0] S_AXI_ARADDR,
input wire [2:0] S_AXI_ARPROT,
input wire S_AXI_ARVALID,
output wire S_AXI_ARREADY,
output wire [C_S_AXI_DATA_WIDTH - 1:0] S_AXI_RDATA,
output wire [1:0] S_AXI_RRESP,
output wire S_AXI_RVALID,
input wire S_AXI_RREADY
);
// Users to add parameters here
// User parameters ends
// Do not modify the parameters beyond this line
// Width of S_AXI data bus
parameter [31:0] C_S_AXI_DATA_WIDTH=32;
parameter [31:0] C_S_AXI_ADDR_WIDTH=6;
// Users to add ports here
// Output register from ARM (i.e. Send commands and Data)
// Input register to ARM (i.e. Receive status and Data)
// User ports ends
// Do not modify the ports beyond this line
// Global Clock Signal
// Global Reset Signal. This Signal is Active LOW
// Write address (issued by master, acceped by Slave)
// Write channel Protection type. This signal indicates the
// privilege and security level of the transaction, and whether
// the transaction is a data access or an instruction access.
// Write address valid. This signal indicates that the master signaling
// valid write address and control information.
// Write address ready. This signal indicates that the slave is ready
// to accept an address and associated control signals.
// Write data (issued by master, acceped by Slave) 
// Write strobes. This signal indicates which byte lanes hold
// valid data. There is one write strobe bit for each eight
// bits of the write data bus.    
// Write valid. This signal indicates that valid write
// data and strobes are available.
// Write ready. This signal indicates that the slave
// can accept the write data.
// Write response. This signal indicates the status
// of the write transaction.
// Write response valid. This signal indicates that the channel
// is signaling a valid write response.
// Response ready. This signal indicates that the master
// can accept a write response.
// Read address (issued by master, acceped by Slave)
// Protection type. This signal indicates the privilege
// and security level of the transaction, and whether the
// transaction is a data access or an instruction access.
// Read address valid. This signal indicates that the channel
// is signaling valid read address and control information.
// Read address ready. This signal indicates that the slave is
// ready to accept an address and associated control signals.
// Read data (issued by slave)
// Read response. This signal indicates the status of the
// read transfer.
// Read valid. This signal indicates that the channel is
// signaling the required read data.
// Read ready. This signal indicates that the master can
// accept the read data and response information.
// AXI4LITE signals
reg [C_S_AXI_ADDR_WIDTH - 1:0] axi_awaddr;
reg axi_awready;
reg axi_wready;
reg [1:0] axi_bresp;
reg axi_bvalid;
reg [C_S_AXI_ADDR_WIDTH - 1:0] axi_araddr;
reg axi_arready;
reg [C_S_AXI_DATA_WIDTH - 1:0] axi_rdata;
reg [1:0] axi_rresp;
reg axi_rvalid;  // Example-specific design signals
// local parameter for addressing 32 bit / 64 bit C_S_AXI_DATA_WIDTH
// ADDR_LSB is used for addressing 32/64 bit registers/memories
// ADDR_LSB = 2 for 32 bits (n downto 2)
// ADDR_LSB = 3 for 64 bits (n downto 3)
parameter ADDR_LSB = (C_S_AXI_DATA_WIDTH / 32) + 1;
parameter OPT_MEM_ADDR_BITS = 3;  //----------------------------------------------
//-- Signals for user logic register space example
//------------------------------------------------
//-- Number of Slave Registers 12
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg0;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg1;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg2;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg3;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg4;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg5;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg6;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg7;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg8;
reg [C_S_AXI_DATA_WIDTH - 1:0] slv_reg9;
wire [C_S_AXI_DATA_WIDTH - 1:0] slv_reg10;
wire [C_S_AXI_DATA_WIDTH - 1:0] slv_reg11;
wire slv_reg_rden;
wire slv_reg_wren;
reg [C_S_AXI_DATA_WIDTH - 1:0] reg_data_out;
wire [31:0] byte_index;
  // I/O Connections assignments
  assign S_AXI_AWREADY = axi_awready;
  assign S_AXI_WREADY = axi_wready;
  assign S_AXI_BRESP = axi_bresp;
  assign S_AXI_BVALID = axi_bvalid;
  assign S_AXI_ARREADY = axi_arready;
  assign S_AXI_RDATA = axi_rdata;
  assign S_AXI_RRESP = axi_rresp;
  assign S_AXI_RVALID = axi_rvalid;
  // Implement axi_awready generation
  // axi_awready is asserted for one S_AXI_ACLK clock cycle when both
  // S_AXI_AWVALID and S_AXI_WVALID are asserted. axi_awready is
  // de-asserted when reset is low.
  always @(posedge S_AXI_ACLK) begin
    if(S_AXI_ARESETN == 1'b0) begin
      axi_awready <= 1'b0;
    end
    else begin
      if((axi_awready == 1'b0 && S_AXI_AWVALID == 1'b1 && S_AXI_WVALID == 1'b1)) begin
        // slave is ready to accept write address when
        // there is a valid write address and write data
        // on the write address and data bus. This design 
        // expects no outstanding transactions. 
        axi_awready <= 1'b1;
      end
      else begin
        axi_awready <= 1'b0;
      end
    end
  end
  // Implement axi_awaddr latching
  // This process is used to latch the address when both 
  // S_AXI_AWVALID and S_AXI_WVALID are valid. 
  always @(posedge S_AXI_ACLK) begin
    if(S_AXI_ARESETN == 1'b0) begin
      axi_awaddr <= {((C_S_AXI_ADDR_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      if((axi_awready == 1'b0 && S_AXI_AWVALID == 1'b1 && S_AXI_WVALID == 1'b1)) begin
        // Write Address latching
        axi_awaddr <= S_AXI_AWADDR;
      end
    end
  end
  // Implement axi_wready generation
  // axi_wready is asserted for one S_AXI_ACLK clock cycle when both
  // S_AXI_AWVALID and S_AXI_WVALID are asserted. axi_wready is 
  // de-asserted when reset is low. 
  always @(posedge S_AXI_ACLK) begin
    if(S_AXI_ARESETN == 1'b0) begin
      axi_wready <= 1'b0;
    end
    else begin
      if((axi_wready == 1'b0 && S_AXI_WVALID == 1'b1 && S_AXI_AWVALID == 1'b1)) begin
        // slave is ready to accept write data when 
        // there is a valid write address and write data
        // on the write address and data bus. This design 
        // expects no outstanding transactions.           
        axi_wready <= 1'b1;
      end
      else begin
        axi_wready <= 1'b0;
      end
    end
  end
  // Implement memory mapped register select and write logic generation
  // The write data is accepted and written to memory mapped registers when
  // axi_awready, S_AXI_WVALID, axi_wready and S_AXI_WVALID are asserted. Write strobes are used to
  // select byte enables of slave registers while writing.
  // These registers are cleared when reset (active low) is applied.
  // Slave register write enable is asserted when valid address and data are available
  // and the slave is ready to accept the write address and write data.
  assign slv_reg_wren = axi_wready & S_AXI_WVALID & axi_awready & S_AXI_AWVALID;
  always @(posedge S_AXI_ACLK) begin : P2
    reg [OPT_MEM_ADDR_BITS:0] loc_addr;
    if(S_AXI_ARESETN == 1'b0) begin
      slv_reg0 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg1 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg2 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg3 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg4 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg5 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg6 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg7 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg8 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
      slv_reg9 <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      loc_addr = axi_awaddr[ADDR_LSB + OPT_MEM_ADDR_BITS -: OPT_MEM_ADDR_BITS + 1];
      if((slv_reg_wren == 1'b1)) begin
        case(loc_addr)
        4'b0000 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 0
              slv_reg0[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b0001 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 1
              slv_reg1[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b0010 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 2
              slv_reg2[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b0011 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 3
              slv_reg3[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b0100 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 4
              slv_reg4[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b0101 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 5
              slv_reg5[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b0110 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 6
              slv_reg6[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b0111 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 7
              slv_reg7[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b1000 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 8
              slv_reg8[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        4'b1001 : begin
          for (byte_index=0; byte_index <= C_S_AXI_DATA_WIDTH / 8 - 1; byte_index = byte_index + 1) begin
            if((S_AXI_WSTRB[byte_index] == 1'b1)) begin
              // Respective byte enables are asserted as per write strobes                   
              // slave registor 9
              slv_reg9[byte_index * 8 + 7 -: 7 + 1] <= S_AXI_WDATA[byte_index * 8 + 7 -: 7 + 1];
            end
          end
        end
        default : begin
          slv_reg0 <= slv_reg0;
          slv_reg1 <= slv_reg1;
          slv_reg2 <= slv_reg2;
          slv_reg3 <= slv_reg3;
          slv_reg4 <= slv_reg4;
          slv_reg5 <= slv_reg5;
          slv_reg6 <= slv_reg6;
          slv_reg7 <= slv_reg7;
          slv_reg8 <= slv_reg8;
          slv_reg9 <= slv_reg9;
        end
        endcase
      end
    end
  end
  // Implement write response logic generation
  // The write response and response valid signals are asserted by the slave 
  // when axi_wready, S_AXI_WVALID, axi_wready and S_AXI_WVALID are asserted.  
  // This marks the acceptance of address and indicates the status of 
  // write transaction.
  always @(posedge S_AXI_ACLK) begin
    if(S_AXI_ARESETN == 1'b0) begin
      axi_bvalid <= 1'b0;
      axi_bresp <= 2'b00;
      //need to work more on the responses
    end
    else begin
      if((axi_awready == 1'b1 && S_AXI_AWVALID == 1'b1 && axi_wready == 1'b1 && S_AXI_WVALID == 1'b1 && axi_bvalid == 1'b0)) begin
        axi_bvalid <= 1'b1;
        axi_bresp <= 2'b00;
      end
      else if((S_AXI_BREADY == 1'b1 && axi_bvalid == 1'b1)) begin
        //check if bready is asserted while bvalid is high)
        axi_bvalid <= 1'b0;
        // (there is a possibility that bready is always asserted high)
      end
    end
  end
  // Implement axi_arready generation
  // axi_arready is asserted for one S_AXI_ACLK clock cycle when
  // S_AXI_ARVALID is asserted. axi_awready is 
  // de-asserted when reset (active low) is asserted. 
  // The read address is also latched when S_AXI_ARVALID is 
  // asserted. axi_araddr is reset to zero on reset assertion.
  always @(posedge S_AXI_ACLK) begin
    if(S_AXI_ARESETN == 1'b0) begin
      axi_arready <= 1'b0;
      axi_araddr <= {((C_S_AXI_ADDR_WIDTH - 1)-(0)+1){1'b1}};
    end
    else begin
      if((axi_arready == 1'b0 && S_AXI_ARVALID == 1'b1)) begin
        // indicates that the slave has acceped the valid read address
        axi_arready <= 1'b1;
        // Read Address latching 
        axi_araddr <= S_AXI_ARADDR;
      end
      else begin
        axi_arready <= 1'b0;
      end
    end
  end
  // Implement axi_arvalid generation
  // axi_rvalid is asserted for one S_AXI_ACLK clock cycle when both 
  // S_AXI_ARVALID and axi_arready are asserted. The slave registers 
  // data are available on the axi_rdata bus at this instance. The 
  // assertion of axi_rvalid marks the validity of read data on the 
  // bus and axi_rresp indicates the status of read transaction.axi_rvalid 
  // is deasserted on reset (active low). axi_rresp and axi_rdata are 
  // cleared to zero on reset (active low).  
  always @(posedge S_AXI_ACLK) begin
    if(S_AXI_ARESETN == 1'b0) begin
      axi_rvalid <= 1'b0;
      axi_rresp <= 2'b00;
    end
    else begin
      if((axi_arready == 1'b1 && S_AXI_ARVALID == 1'b1 && axi_rvalid == 1'b0)) begin
        // Valid read data is available at the read data bus
        axi_rvalid <= 1'b1;
        axi_rresp <= 2'b00;
        // 'OKAY' response
      end
      else if((axi_rvalid == 1'b1 && S_AXI_RREADY == 1'b1)) begin
        // Read data is accepted by the master
        axi_rvalid <= 1'b0;
      end
    end
  end
  // Implement memory mapped register select and read logic generation
  // Slave register read enable is asserted when valid address is available
  // and the slave is ready to accept the read address.
  assign slv_reg_rden = axi_arready & S_AXI_ARVALID & ( ~axi_rvalid);
  always @(slv_reg0, slv_reg1, slv_reg2, slv_reg3, slv_reg4, slv_reg5, slv_reg6, slv_reg7, slv_reg8, slv_reg9, axi_araddr, S_AXI_ARESETN, slv_reg_rden) begin : P1
    reg [OPT_MEM_ADDR_BITS:0] loc_addr;
    // Address decoding for reading registers
    loc_addr = axi_araddr[ADDR_LSB + OPT_MEM_ADDR_BITS -: OPT_MEM_ADDR_BITS + 1];
    case(loc_addr)
    4'b0000 : begin
      reg_data_out <= slv_reg0;
    end
    4'b0001 : begin
      reg_data_out <= slv_reg1;
    end
    4'b0010 : begin
      reg_data_out <= slv_reg2;
    end
    4'b0011 : begin
      reg_data_out <= slv_reg3;
    end
    4'b0100 : begin
      reg_data_out <= SLV_REG04_IN;
    end
    4'b0101 : begin
      reg_data_out <= SLV_REG05_IN;
    end
    4'b0110 : begin
      reg_data_out <= SLV_REG06_IN;
    end
    4'b0111 : begin
      reg_data_out <= SLV_REG07_IN;
    end
    4'b1000 : begin
      reg_data_out <= SLV_REG08_IN;
    end
    4'b1001 : begin
      reg_data_out <= SLV_REG09_IN;
    end
    4'b1010 : begin
      reg_data_out <= SLV_REG10_IN;
    end
    4'b1011 : begin
      reg_data_out <= SLV_REG11_IN;
    end
    default : begin
      reg_data_out <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
    end
    endcase
  end
  // Output register or memory read data
  always @(posedge S_AXI_ACLK) begin
    if((S_AXI_ARESETN == 1'b0)) begin
      axi_rdata <= {((C_S_AXI_DATA_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      if((slv_reg_rden == 1'b1)) begin
        // When there is a valid read address (S_AXI_ARVALID) with 
        // acceptance of read address by the slave (axi_arready), 
        // output the read dada 
        // Read address mux
        axi_rdata <= reg_data_out;
        // register read data
      end
    end
  end
  // Add user logic here
  assign SLV_REG00_OUT = slv_reg0;
  assign SLV_REG01_OUT = slv_reg1;
  assign SLV_REG02_OUT = slv_reg2;
  assign SLV_REG03_OUT = slv_reg3;
    // User logic ends
endmodule

