module edid_decode(
input wire clk,
input wire edid_de,
input wire [7:0] edid_data,
input wire [7:0] edid_addr,
input wire invalidate,
output reg valid,
output wire support_RGB444,
output wire support_YCC444,
output wire support_YCC422,
output reg [15:0] pixel_clock_x10k,
output reg [11:0] h_visible_len,
output reg [11:0] h_blank_len,
output reg [11:0] h_front_len,
output reg [11:0] h_sync_len,
output reg [11:0] v_visible_len,
output reg [11:0] v_blank_len,
output reg [11:0] v_front_len,
output reg [11:0] v_sync_len,
output wire interlaced
);
reg [7:0] checksum;
wire [7:0] checksum_next;
  assign checksum_next = checksum + (edid_data);
  always @(posedge clk) begin
    if(edid_de == 1'b1) begin
      checksum <= checksum_next;
      valid <= 1'b0;
      case(edid_addr)
      8'h00 : begin
        // reset the checksum
        checksum <= edid_data;
      end
      8'h18 : begin
        // Colour modes supported
        support_rgb444 <= 1'b1;
        support_ycc444 <= edid_data[3];
        support_ycc422 <= edid_data[4];
        // Timing 0 - 1	
      end
      8'h36 : begin
        pixel_clock_x10k[7:0] <= edid_data;
      end
      8'h37 : begin
        pixel_clock_x10k[15:8] <= edid_data;
        // Timing 2 - 4	
      end
      8'h38 : begin
        h_visible_len[7:0] <= edid_data;
      end
      8'h39 : begin
        h_blank_len[7:0] <= edid_data;
      end
      8'h3A : begin
        h_visible_len[11:8] <= edid_data[7:4];
        h_blank_len[11:8] <= edid_data[3:0];
        // Timing 5 - 7	
      end
      8'h3B : begin
        v_visible_len[7:0] <= edid_data;
      end
      8'h3C : begin
        v_blank_len[7:0] <= edid_data;
      end
      8'h3D : begin
        v_visible_len[11:8] <= edid_data[7:4];
        v_blank_len[11:8] <= edid_data[3:0];
        // Timing 8 - 11
      end
      8'h3E : begin
        h_front_len[7:0] <= edid_data;
      end
      8'h3F : begin
        h_sync_len[7:0] <= edid_data;
      end
      8'h40 : begin
        v_front_len[3:0] <= edid_data[7:4];
        v_sync_len[3:0] <= edid_data[3:0];
      end
      8'h41 : begin
        h_front_len[9:8] <= edid_data[7:6];
        h_sync_len[9:8] <= edid_data[5:4];
        v_front_len[5:4] <= edid_data[3:2];
        v_sync_len[5:4] <= edid_data[1:0];
        // Timing 11-16 not used - that is the physical 
        // size and boarder.
      end
      8'h7F : begin
        if(checksum_next == 8'h00) begin
          valid <= 1'b1;
        end
      end
      default : begin
      end
      endcase
      //----------------------------------------------
      // Allow for an external event to invalidate the 
      // outputs (e.g. hot plug)
      //----------------------------------------------
      if(invalidate == 1'b1) begin
        valid <= 1'b0;
      end
    end
  end
endmodule

module DEBOUNCER(
input wire CLK,
input wire RST,
input wire DIN,
output wire DOUT
);
// Clock
// High active asynchronous reset
// Data input
// Debounced data output
reg [3:0] data_shreg;
reg data_deb_reg;
  assign DOUT = data_deb_reg;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data_shreg <= {4{1'b0}};
      data_deb_reg <= 1'b0;
    end else begin
      data_shreg <= {data_shreg[2:0],DIN};
      data_deb_reg <= data_shreg[0] & data_shreg[1] & data_shreg[2] & data_shreg[3];
    end
  end
endmodule

module tcp_engine_session_filter(
input wire clk,
input wire [15:0] listen_port,
input wire drop_connection,
output wire connected,
input wire in_data_valid,
input wire [7:0] in_data,
input wire in_hdr_valid,
input wire [31:0] in_src_ip,
input wire [15:0] in_src_port,
input wire [15:0] in_dst_port,
input wire [31:0] in_seq_num,
input wire [31:0] in_ack_num,
input wire [15:0] in_window,
input wire in_flag_urg,
input wire in_flag_ack,
input wire in_flag_psh,
input wire in_flag_rst,
input wire in_flag_syn,
input wire in_flag_fin,
input wire [15:0] in_urgent_ptr,
output reg out_data_valid,
output reg [7:0] out_data,
output reg out_hdr_valid,
output wire [31:0] out_from_ip,
output wire [15:0] out_from_port,
output reg [31:0] out_seq_num,
output reg [31:0] out_ack_num,
output reg [15:0] out_window,
output reg out_flag_urg,
output reg out_flag_ack,
output reg out_flag_psh,
output reg out_flag_rst,
output reg out_flag_syn,
output reg out_flag_fin,
output reg [15:0] out_urgent_ptr
);
// data received over TCP/IP
reg i_connected = 1'b0;
reg do_drop = 1'b0;
reg [15:0] session_src_port = 1'b0;
reg [31:0] session_src_ip = 1'b0;
  assign connected = i_connected;
  assign out_from_ip = session_src_ip;
  assign out_from_port = session_src_port;
  always @(posedge clk) begin
    if(i_connected == 1'b1) begin
      if(do_drop == 1'b1 && in_data_valid == 1'b0 && in_hdr_valid == 1'b0) begin
        // Drop the connection
        i_connected <= 1'b0;
        out_data_valid <= 1'b0;
        out_hdr_valid <= 1'b0;
        do_drop <= 1'b0;
      end
      else begin
        if(in_dst_port == listen_port && in_src_ip == session_src_ip && in_src_port == session_src_port) begin
          out_data_valid <= in_data_valid;
          out_hdr_valid <= in_hdr_valid;
        end
        else begin
          out_data_valid <= 1'b0;
          out_hdr_valid <= 1'b0;
        end
      end
    end
    else begin
      if(in_hdr_valid == 1'b1) begin
        if(in_dst_port == listen_port && in_flag_syn == 1'b1) begin
          i_connected <= 1'b1;
          session_src_port <= in_src_port;
          session_src_ip <= in_src_ip;
          out_data_valid <= in_data_valid;
          out_hdr_valid <= in_hdr_valid;
        end
      end
    end
    // Copy non-key data over anyway (just don't assert the valid siganls!
    out_data <= in_data;
    out_seq_num <= in_seq_num;
    out_ack_num <= in_ack_num;
    out_window <= in_window;
    out_flag_urg <= in_flag_urg;
    out_flag_ack <= in_flag_ack;
    out_flag_psh <= in_flag_psh;
    out_flag_rst <= in_flag_rst;
    out_flag_syn <= in_flag_syn;
    out_flag_fin <= in_flag_fin;
    out_urgent_ptr <= in_urgent_ptr;
    // Remember if we are asked to drop the connection
    if(do_drop == 1'b0) begin
      do_drop <= drop_connection;
    end
  end
endmodule

