`timescale 1 ns / 1 ns
module fifo_mem_synth(
input wire CLK_IN,
input wire CLKB_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
reg [0:0] WEA_R = 1'b0;
wire [10:0] ADDRA = 1'b0;
reg [10:0] ADDRA_R = 1'b0;
wire [7:0] DINA = 1'b0;
reg [7:0] DINA_R = 1'b0;
wire CLKB = 1'b0;
wire RSTB = 1'b0;
wire [10:0] ADDRB = 1'b0;
reg [10:0] ADDRB_R = 1'b0;
wire [7:0] DOUTB;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire clkb_in_i;
reg RESETB_SYNC_R1 = 1'b1;
reg RESETB_SYNC_R2 = 1'b1;
reg RESETB_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  //  clkb_buf: bufg
  //    PORT map(
  //      i => CLKB_IN,
  //      o => clkb_in_i
  //    );
  assign clkb_in_i = CLKB_IN;
  assign CLKB = clkb_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  assign RSTB = # 50 RESETB_SYNC_R3;
  always @(posedge clkb_in_i) begin
    RESETB_SYNC_R1 <= RESET_IN;
    RESETB_SYNC_R2 <= RESETB_SYNC_R1;
    RESETB_SYNC_R3 <= RESETB_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(8),
    .READ_WIDTH(8))
  BMG_DATA_CHECKER_INST(
      .CLK(clkb_in_i),
    .RST(RSTB),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTB),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge clkb_in_i) begin
    if((RSTB == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLKA(clk_in_i),
    .CLKB(clkb_in_i),
    .TB_RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .ADDRB(ADDRB),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {1{1'b0}};
      DINA_R <= # 50 {8{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {11{1'b0}};
      ADDRB_R <= # 50 {11{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
      ADDRB_R <= # 50 ADDRB;
    end
  end
  fifo_mem_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .CLKA(CLKA),
    //Port B
    .ADDRB(ADDRB_R),
    .DOUTB(DOUTB),
    .CLKB(CLKB));
endmodule

