wire [7:0] rx_d;
wire in_busy;
reg in_busy_1;
wire out_busy;
reg tx_read;
wire tx_empty;
parameter [0:0]
  IDLE = 0,
  READ = 1;
reg out_state;
  always @(posedge clk) begin
    in_busy_1 <= in_busy;
  end
  assign en_out = ena & wea;
  assign en_in = ena &  ~wea;
  assign busy = en_in == 1'b1 && in_busy == 1'b1 && in_busy_1 == 1'b1 ? 1'b1 : en_in == 1'b1 && in_busy_1 == 1'b1 ? 1'b1 : en_out == 1'b1 ? out_busy : 1'b0;
  fifo fifo_in(
      .rst(rst),
    .clk(clk),
    .dia(rx_d),
    .ena(rx_valid),
    .full(/* open */),
    .dob(doa),
    .enb(en_in),
    .empty(in_busy));
  fifo fifo_out(
      .rst(rst),
    .clk(clk),
    .dia(dia),
    .ena(en_out),
    .full(out_busy),
    .dob(tx_d),
    .enb(tx_read),
    .empty(tx_empty));
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      out_state <= IDLE;
      tx_read <= 1'b0;
      tx_start <= 1'b0;
    end
    else begin
      case(out_state)
      IDLE : begin
        tx_start <= 1'b0;
        if(tx_empty == 1'b0) begin
          out_state <= READ;
          tx_read <= 1'b1;
        end
      end
      READ : begin
        tx_read <= 1'b0;
        if(tx_busy == 1'b0) begin
          tx_start <= 1'b1;
          out_state <= IDLE;
        end
      end
      endcase
    end
  end
  rs232 rs232_i(
      .rst(rst),
    .clk(clk),
    .rx(rx),
    .tx(tx),
    .tx_start(tx_start),
    .tx_d(tx_d),
    .tx_busy(tx_busy),
    .rx_valid(rx_valid),
    .rx_d(rx_d));
endmodule

