module UARTTransmitter(
input wire clk,
input wire rst,
input wire tick,
input wire [7:0] d_in,
input wire tx_start,
output reg tx_done,
output wire tx
);
parameter [1:0]
  idle = 0,
  start = 1,
  data = 2,
  stop = 3;
reg [1:0] next_state; reg [1:0] current_state;
reg [3:0] tick_counter; reg [3:0] tick_counter_next;
reg [2:0] bit_counter; reg [2:0] bit_counter_next;
reg [7:0] reg; reg [7:0] reg_next;
reg tx_reg; reg tx_reg_next;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      current_state <= idle;
      tick_counter <= {4{1'b0}};
      bit_counter <= {3{1'b0}};
      reg <= {8{1'b0}};
      tx_reg <= 1'b1;
    end else begin
      current_state <= next_state;
      tick_counter <= tick_counter_next;
      bit_counter <= bit_counter_next;
      reg <= reg_next;
      tx_reg <= tx_reg_next;
    end
  end
  always @(current_state, tick_counter, bit_counter, reg, tick, tx_reg, tx_start, d_in) begin
    next_state <= current_state;
    tick_counter_next <= tick_counter;
    bit_counter_next <= bit_counter;
    reg_next <= reg;
    tx_reg_next <= tx_reg;
    tx_done <= 1'b0;
    case(current_state)
    idle : begin
      tx_reg_next <= 1'b1;
      if((tx_start == 1'b1)) begin
        next_state <= start;
        tick_counter_next <= 4'b0000;
        reg_next <= d_in;
      end
    end
    start : begin
      tx_reg_next <= 1'b0;
      if((tick == 1'b1)) begin
        if((tick_counter < 15)) begin
          tick_counter_next <= tick_counter + 1;
        end
        else begin
          tick_counter_next <= 4'b0000;
          bit_counter_next <= 3'b000;
          next_state <= data;
        end
      end
    end
    data : begin
      tx_reg_next <= reg[0];
      if((tick == 1'b1)) begin
        if((tick_counter < 15)) begin
          tick_counter_next <= tick_counter + 1;
        end
        else begin
          tick_counter_next <= 4'b0000;
          reg_next <= {1'b0,reg[7:1]};
          if((bit_counter == 7)) begin
            next_state <= stop;
          end
          else begin
            bit_counter_next <= bit_counter + 1;
          end
        end
      end
    end
    stop : begin
      tx_reg_next <= 1'b1;
      if((tick == 1'b1)) begin
        if((tick_counter < 15)) begin
          tick_counter_next <= tick_counter + 1;
        end
        else begin
          next_state <= idle;
          tx_done <= 1'b1;
        end
      end
    end
    endcase
  end
  assign tx = tx_reg;
endmodule

