    end
    else if(Sel == 3'o2) begin
      Temp <= D[2];
    end
    else if(Sel == 3'o3) begin
      Temp <= D[3];
    end
    else if(Sel == 3'o4) begin
      Temp <= D[4];
    end
    else if(Sel == 3'o5) begin
      Temp <= D[5];
    end
    else if(Sel == 3'o6) begin
      Temp <= D[6];
    end
    else begin
      Temp <= D[7];
    end
  end
  always @(Strobe, Temp) begin
    if(Strobe == 1'b1) begin
      Y <= 1'b1;
      W <= 1'b0;
    end
    else begin
      Y <= Temp;
      W <=  ~Temp;
    end
  end
endmodule

module stage(
input wire [31:0] input,
input wire inputReady,
input wire [31:0] data,
input wire clock,
input wire reset,
input wire wrMask,
input wire wrValue,
input wire wrConfig,
input wire arm,
input wire [1:0] level,
input wire demuxed,
output reg run,
output reg match
);
parameter [1:0]
  OFF = 0,
  ARMED = 1,
  MATCHED = 2;
reg [31:0] maskRegister; reg [31:0] valueRegister; reg [31:0] configRegister;
reg [31:0] intermediateRegister; reg [31:0] shiftRegister;
wire [31:0] testValue;
wire cfgStart; wire cfgSerial;
wire [4:0] cfgChannel;
wire [1:0] cfgLevel;
reg [15:0] counter; wire [15:0] cfgDelay;
wire matchL16; wire matchH16; reg match32Register;
reg [1:0] state;
reg serialChannelL16; reg serialChannelH16;
  // assign configuration bits to more meaningful signal names
  assign cfgStart = configRegister[27];
  assign cfgSerial = configRegister[26];
  assign cfgChannel = configRegister[24:20];
  assign cfgLevel = configRegister[17:16];
  assign cfgDelay = configRegister[15:0];
  // use shift register or input depending on configuration
  assign testValue = cfgSerial == 1'b1 ? shiftRegister : input;
  // apply mask and value and create a additional pipeline step
  always @(posedge clock) begin
    intermediateRegister <= (testValue ^ valueRegister) & maskRegister;
  end
  // match upper and lower word separately
  assign matchL16 = intermediateRegister[15:0] == 16'b0000000000000000 ? 1'b1 : 1'b0;
  assign matchH16 = intermediateRegister[31:16] == 16'b0000000000000000 ? 1'b1 : 1'b0;
  // in demux mode only one half must match, in normal mode both words must match
  always @(posedge clock) begin
    if(demuxed == 1'b1) begin
      match32Register <= matchL16 | matchH16;
    end
    else begin
      match32Register <= matchL16 & matchH16;
    end
  end
  // select serial channel based on cfgChannel
  always @(input, cfgChannel) begin
    for (i=0; i <= 15; i = i + 1) begin
      if((cfgChannel[3:0]) == i) begin
        serialChannelL16 <= input[i];
        serialChannelH16 <= input[i + 16];
      end
    end
  end
  // shift in bit from selected channel whenever input is ready
  always @(posedge clock) begin
    if(inputReady == 1'b1) begin
      if(demuxed == 1'b1) begin
        // in demux mode two bits come in per sample
        shiftRegister <= {shiftRegister[29:0],serialChannelH16,serialChannelL16};
      end
      else if(cfgChannel[4] == 1'b1) begin
        shiftRegister <= {shiftRegister[30:0],serialChannelH16};
      end
      else begin
        shiftRegister <= {shiftRegister[30:0],serialChannelL16};
      end
    end
  end
  // trigger state machine
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b1) begin
      state <= OFF;
    end else begin
      run <= 1'b0;
      match <= 1'b0;
      case(state)
      OFF : begin
        if(arm == 1'b1) begin
          state <= ARMED;
        end
      end
      ARMED : begin
        if(match32Register == 1'b1 && level >= cfgLevel) begin
          counter <= cfgDelay;
          state <= MATCHED;
        end
      end
      MATCHED : begin
        if(inputReady == 1'b1) begin
          if(counter == 16'b0000000000000000) begin
            run <= cfgStart;
            match <=  ~cfgStart;
            state <= OFF;
          end
          else begin
            counter <= counter - 1;
          end
        end
      end
      endcase
    end
  end
  // handle mask, value & config register write requests
  always @(posedge clock) begin
    if(wrMask == 1'b1) begin
      maskRegister <= data;
    end
    if(wrValue == 1'b1) begin
      valueRegister <= data;
    end
    if(wrConfig == 1'b1) begin
      configRegister <= data;
    end
  end
endmodule

