module ULA_MODULO(
input wire [3:0] A,
input wire [3:0] B,
input wire [2:0] Controle,
output reg [7:0] Z
);
// Entrada1
// Entrada2
// Vetor de Controle(S2S1S0)
// Saída
wire [3:0] SaidaAux;
wire [3:0] SaidaAux1;
wire [3:0] SaidaAux2;
wire [3:0] SaidaAux3;
wire [3:0] SaidaAux4;
wire [3:0] SaidaAux5;
wire [7:0] SaidaAux6;
wire [3:0] SaidaAux7;
wire FlagCarrySoma; wire FlagOvSoma;
wire FlagCarrySub; wire FlagOvSub;
  AND_BitABit Operacao1(
      A,
    B,
    SaidaAux);
  OR_BitABit Operacao2(
      A,
    B,
    SaidaAux1);
  Inversor Operacao3(
      A,
    SaidaAux2);
  XOR_BitABit Operacao4(
      A,
    B,
    SaidaAux3);
  Somador4bits Operacao5(
      A,
    B,
    .Cin(1'b0),
    .Cout(FlagCarrySoma),
    .Ov(FlagOvSoma),
    .Z(SaidaAux4));
  // Z(4): Flag Cout / Z(5): Flag Overflow
  Subtrator Operacao6(
      A,
    B,
    .O(SaidaAux5),
    .Ov(FlagOvSub),
    .Cout(FlagCarrySub));
  // Z(4): Flag Borrow / Z(5): Flag Overflow
  Multiplicador Operacao7(
      A,
    B,
    SaidaAux6);
  Incrementador Operacao8(
      A,
    SaidaAux7);
  always @(Controle, SaidaAux, SaidaAux1, SaidaAux2, SaidaAux3, SaidaAux4, SaidaAux5, SaidaAux6, SaidaAux7, FlagCarrySoma, FlagOvSoma, FlagCarrySub, FlagOvSub) begin
    case(Controle)
    3'b000 : begin
      Z[7:4] <= 4'b0000;
      // 000 - And
      Z[3:0] <= SaidaAux;
    end
    3'b001 : begin
      Z[7:4] <= 4'b0000;
      // 001 - Or
      Z[3:0] <= SaidaAux1;
    end
    3'b010 : begin
      Z[7:4] <= 4'b0000;
      // 010 - Not
      Z[3:0] <= SaidaAux2;
    end
    3'b011 : begin
      Z[7:4] <= 4'b0000;
      // 011 - Xor
      Z[3:0] <= SaidaAux3;
    end
    3'b100 : begin
      Z[3:0] <= SaidaAux4;
      // 100 - Soma
      Z[5:4] <= 2'b00;
      Z[7] <= FlagCarrySoma;
      Z[6] <= FlagOvSoma;
    end
    3'b101 : begin
      Z[3:0] <= SaidaAux5;
      // 101 - Subtração
      Z[5:4] <= 2'b00;
      Z[7] <=  ~(FlagCarrySub);
      Z[6] <= FlagOvSub;
    end
    3'b110 : begin
      Z <= SaidaAux6;
      // 110 - Multiplicação		
    end
    3'b111 : begin
      Z[7:4] <= 4'b0000;
      // 111 - Incrementação
      Z[3:0] <= SaidaAux7;
    end
    default : begin
      Z <= 8'b00000000;
    end
    endcase
  end
endmodule

module BoothPartProdGen(
input wire [2:0] bin3,
input wire [15:0] a,
output reg [16:0] product
);
parameter ONE17 = 17'b00000000000000001;
  always @(bin3, a) begin
    if(bin3 == 3'b001 || bin3 == 3'b010) begin
      // * 1
      product <= {1'b0,a};
    end
    else if(bin3 == 3'b011) begin
      // * 2
      product <= {a,1'b0};
    end
    else if(bin3 == 3'b101 || bin3 == 3'b110) begin
      // * -1
      product <= ( ~({1'b0,a})) + (ONE17);
    end
    else if(bin3 == 3'b100) begin
      // * -2
      product <= ( ~({a,1'b0})) + (ONE17);
    end
    else begin
      product <= 17'b00000000000000000;
    end
  end
endmodule

