module debouncer(
input wire clock,
input wire input,
output reg output
);
parameter [31:0] CLOCK_RATE_HZ=50000000;
parameter [31:0] SETTLING_TIME_MS=10;
parameter max = (CLOCK_RATE_HZ * SETTLING_TIME_MS) / 1000;
reg [31:0] cnt = 0;
reg last;
  always @(posedge clock) begin
    last <= input;
    if(input == last) begin
      if(cnt == max) begin
        output <= input;
      end
      else begin
        cnt <= cnt + 1;
      end
    end
    else begin
      cnt <= 0;
    end
  end
endmodule

