module sevenSegment4(
output reg [27:0] sevenSegmentVector4,
input wire [15:0] numberDesired4,
input wire clock,
input wire reset
);
  always @(posedge clock, posedge numberDesired4) begin
    case(numberDesired4[3:0])
    4'b0000 : begin
      sevenSegmentVector4[6:0] <= 7'b0000001;
      //0
    end
    4'b0001 : begin
      sevenSegmentVector4[6:0] <= 7'b1001111;
      //1
    end
    4'b0010 : begin
      sevenSegmentVector4[6:0] <= 7'b0010010;
      //2
    end
    4'b0011 : begin
      sevenSegmentVector4[6:0] <= 7'b0000110;
      //3
    end
    4'b0100 : begin
      sevenSegmentVector4[6:0] <= 7'b1001100;
      //4
    end
    4'b0101 : begin
      sevenSegmentVector4[6:0] <= 7'b0100100;
      //5
    end
    4'b0110 : begin
      sevenSegmentVector4[6:0] <= 7'b0100000;
      //6
    end
    4'b0111 : begin
      sevenSegmentVector4[6:0] <= 7'b0001111;
      //7
    end
    4'b1000 : begin
      sevenSegmentVector4[6:0] <= 7'b0000000;
      //8
    end
    4'b1001 : begin
      sevenSegmentVector4[6:0] <= 7'b0000100;
      //9
    end
    4'b1010 : begin
      sevenSegmentVector4[6:0] <= 7'b0001000;
      //A
    end
    4'b1011 : begin
      sevenSegmentVector4[6:0] <= 7'b1100000;
      //b
    end
    4'b1100 : begin
      sevenSegmentVector4[6:0] <= 7'b0110001;
      //C
    end
    4'b1101 : begin
      sevenSegmentVector4[6:0] <= 7'b1000010;
      //d
    end
    4'b1110 : begin
      sevenSegmentVector4[6:0] <= 7'b0110000;
      //E
    end
    4'b1111 : begin
      sevenSegmentVector4[6:0] <= 7'b0111000;
      //F
    end
    default : begin
      sevenSegmentVector4[6:0] <= 7'b1111111;
      //' ' 
    end
    endcase
    case(numberDesired4[7:4])
    4'b0000 : begin
      sevenSegmentVector4[13:7] <= 7'b0000001;
      //0
