module ToolsColorManagment(
input wire clk,
input wire reset_n,
input wire [nb_bits_Tool - 1:0] CurrentTool,
input wire [nb_bits_Color - 1:0] CurrentColor,
output reg [nb_bits_Color - 1:0] Color
);
parameter [31:0] nb_bits_Color=12;
parameter [31:0] nb_bits_Tool=4;
parameter [31:0] nb_bits_SaveParamEn=3;
  // Process
  always @(posedge Clk) begin
    if(reset_n == 1'b0) begin
      // initialization     : on active synchronous reset
      Color <= {((nb_bits_Color - 1)-(0)+1){1'b0}};
      // couleur par defaut : noir
    end
    else begin
      if(CurrentTool == 4'b0100) begin
        // Dans le cas de la gomme, on "efface" avec du blanc
        Color <= {((nb_bits_Color - 1)-(0)+1){1'b1}};
        // blanc
      end
      else begin
        Color <= CurrentColor;
      end
    end
  end
endmodule

module add_178(
output wire [19:0] result,
input wire [19:0] in_a,
input wire [19:0] in_b
);
wire [21:0] carry_inA;
wire [21:0] carry_inB;
wire [21:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign result = carry_res[20:1];
endmodule

module complemento4(
input wire [3:0] entrada,
input wire sel,
output wire [3:0] saida
);
reg [3:0] aux;
  always @(entrada, sel, aux) begin
    if((sel == 1'b1)) begin
      aux <= entrada ^ 4'b1111;
    end
    else begin
      aux <= entrada;
    end
  end
  assign saida = aux;
endmodule

module MUX(
input wire [N - 1:0] A,
input wire [N - 1:0] B,
input wire SEL,
output wire [N - 1:0] Y
);
parameter [31:0] N=NSUMG;
// Number of bits
// Architectures
wire [N - 1:0] A_NAND;  // Output of first nand A_NAND
wire [N - 1:0] B_NAND;  // Output of first nand B_NAND
wire SEL_NOT;
  INVERTER INV_GEN(
      SEL,
    SEL_NOT);
  // Generates 3*N nand ports from the NAND1 compoment:
  // N nands are used to evaluate A_NAND(i) = NOT( A(i) * SEL )
  // N nands are used to evaluate B_NAND(i) = NOT( B(i) * SEL_NOT )
  // Then these outputs are fed to other N nands to evaluate
  // NOT( NOT( A(i) * SEL ) * NOT( B(i) * SEL_NOT ) ) = A * SEL + B * SEL_NOT
  // which is the classic n-bit mux behavior
  genvar i;
  generate for (i=0; i <= N - 1; i = i + 1) begin: NAND_GEN
      NAND1 NAND_A(
          A[i],
      SEL,
      A_NAND[i]);
    NAND1 NAND_B(
          B[i],
      SEL_NOT,
      B_NAND[i]);
    NAND1 Y_GEN(
          A_NAND[i],
      B_NAND[i],
      Y[i]);
  end
  endgenerate
endmodule

module spi(
input wire clk,
input wire [31:0] data,
output reg ready,
input wire valid,
output reg clatch,
output wire cclk,
output reg cdata
);
parameter [0:0]
  idle = 0,
  deliver = 1;
  //type of state machine.
reg state;
reg [31:0] payload;
reg [31:0] index = 0;
wire cclkb;
  clk_div #(
      .div(2000))
  clk_div1(
      .input(clk),
    .output(cclkb));
  assign cclk = cclkb;
  always @(negedge cclkb) begin
    case(state)
    idle : begin
      clatch <= 1'b1;
      ready <= 1'b1;
      if((valid == 1'b1)) begin
        state <= deliver;
        payload <= data;
        index <= 0;
      end
    end
    deliver : begin
      clatch <= 1'b0;
      ready <= 1'b0;
      cdata <= payload[31 - index];
      index <= index + 1;
      if((index == 31)) begin
        state <= idle;
      end
    end
    endcase
  end
endmodule

module cmp_132(
output wire eq,
input wire [2:0] in0,
input wire [2:0] in1
);
wire tmp;
  // Compute the result
  assign tmp = in0 != in1 ? 1'b0 : 1'b1;
  // Set the outputs
  assign eq = tmp;
endmodule

module mul_547(
output wire [30:0] result,
input wire [30:0] in_a,
input wire [14:0] in_b
);
wire [45:0] tmp_res;
  // The actual multiplication
  assign tmp_res = (in_a) * (in_b);
  // Set the output
  assign result = tmp_res[30:0];
endmodule

