    endcase
  end
  assign L_XYZS = L_BASE + L_POST;
  assign L_ADR = L_BASE + L_PRE;
  assign L_WE_A = (L_ADR[15:5] == 11'b00000000000) ? I_WE_M : 1'b0;
  assign L_WE_SR = (L_ADR == 16'h005F) ? I_WE_M : 1'b0;
  assign L_WE_SP_AMOD = (I_AMOD[2:0] == AS_SP) ? I_WE_XYZS : 1'b0;
  assign L_WE_SP[1] = (L_ADR == 16'h005E) ? I_WE_M : L_WE_SP_AMOD;
  assign L_WE_SP[0] = (L_ADR == 16'h005D) ? I_WE_M : L_WE_SP_AMOD;
  assign L_DX = (L_WE_MISC[26] == 1'b1) ? L_XYZS : I_DIN;
  assign L_DY = (L_WE_MISC[28] == 1'b1) ? L_XYZS : I_DIN;
  assign L_DZ = (L_WE_MISC[30] == 1'b1) ? L_XYZS : I_DIN;
  assign L_DSP = (I_AMOD[3:0] == AM_WS) ? L_XYZS : I_DIN;
  // the WE signals for the differen registers.
  //
  // case 1: write to an 8-bit register addressed by DDDDD.
  //
  // I_WE_D(0) = '1' and I_DDDDD matches,
  //
  assign L_WE_D[0] = (I_DDDDD == 5'b00000) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[1] = (I_DDDDD == 5'b00001) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[2] = (I_DDDDD == 5'b00010) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[3] = (I_DDDDD == 5'b00011) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[4] = (I_DDDDD == 5'b00100) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[5] = (I_DDDDD == 5'b00101) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[6] = (I_DDDDD == 5'b00110) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[7] = (I_DDDDD == 5'b00111) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[8] = (I_DDDDD == 5'b01000) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[9] = (I_DDDDD == 5'b01001) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[10] = (I_DDDDD == 5'b01010) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[11] = (I_DDDDD == 5'b01011) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[12] = (I_DDDDD == 5'b01100) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[13] = (I_DDDDD == 5'b01101) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[14] = (I_DDDDD == 5'b01110) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[15] = (I_DDDDD == 5'b01111) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[16] = (I_DDDDD == 5'b10000) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[17] = (I_DDDDD == 5'b10001) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[18] = (I_DDDDD == 5'b10010) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[19] = (I_DDDDD == 5'b10011) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[20] = (I_DDDDD == 5'b10100) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[21] = (I_DDDDD == 5'b10101) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[22] = (I_DDDDD == 5'b10110) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[23] = (I_DDDDD == 5'b10111) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[24] = (I_DDDDD == 5'b11000) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[25] = (I_DDDDD == 5'b11001) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[26] = (I_DDDDD == 5'b11010) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[27] = (I_DDDDD == 5'b11011) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[28] = (I_DDDDD == 5'b11100) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[29] = (I_DDDDD == 5'b11101) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[30] = (I_DDDDD == 5'b11110) ? I_WE_D[0] : 1'b0;
  assign L_WE_D[31] = (I_DDDDD == 5'b11111) ? I_WE_D[0] : 1'b0;
  //
  // case 2: write to a 16-bit register pair addressed by DDDD.
  //
  // I_WE_DD(1) = '1' and L_DDDD matches,
  //
  assign L_DDDD = I_DDDDD[4:1];
  assign L_WE_D2 = {I_WE_D[1],I_WE_D[1]};
  assign L_WE_DD[1:0] = (L_DDDD == 4'b0000) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[3:2] = (L_DDDD == 4'b0001) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[5:4] = (L_DDDD == 4'b0010) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[7:6] = (L_DDDD == 4'b0011) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[9:8] = (L_DDDD == 4'b0100) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[11:10] = (L_DDDD == 4'b0101) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[13:12] = (L_DDDD == 4'b0110) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[15:14] = (L_DDDD == 4'b0111) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[17:16] = (L_DDDD == 4'b1000) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[19:18] = (L_DDDD == 4'b1001) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[21:20] = (L_DDDD == 4'b1010) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[23:22] = (L_DDDD == 4'b1011) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[25:24] = (L_DDDD == 4'b1100) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[27:26] = (L_DDDD == 4'b1101) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[29:28] = (L_DDDD == 4'b1110) ? L_WE_D2 : 2'b00;
  assign L_WE_DD[31:30] = (L_DDDD == 4'b1111) ? L_WE_D2 : 2'b00;
  //
  // case 3: write to an 8-bit register pair addressed by an I/O address.
  //
  // L_WE_A = '1' and L_ADR(4 downto 0) matches
  //
  assign L_WE_IO[0] = (L_ADR[4:0] == 5'b00000) ? L_WE_A : 1'b0;
  assign L_WE_IO[1] = (L_ADR[4:0] == 5'b00001) ? L_WE_A : 1'b0;
  assign L_WE_IO[2] = (L_ADR[4:0] == 5'b00010) ? L_WE_A : 1'b0;
  assign L_WE_IO[3] = (L_ADR[4:0] == 5'b00011) ? L_WE_A : 1'b0;
  assign L_WE_IO[4] = (L_ADR[4:0] == 5'b00100) ? L_WE_A : 1'b0;
  assign L_WE_IO[5] = (L_ADR[4:0] == 5'b00101) ? L_WE_A : 1'b0;
  assign L_WE_IO[6] = (L_ADR[4:0] == 5'b00110) ? L_WE_A : 1'b0;
  assign L_WE_IO[7] = (L_ADR[4:0] == 5'b00111) ? L_WE_A : 1'b0;
  assign L_WE_IO[8] = (L_ADR[4:0] == 5'b01000) ? L_WE_A : 1'b0;
  assign L_WE_IO[9] = (L_ADR[4:0] == 5'b01001) ? L_WE_A : 1'b0;
  assign L_WE_IO[10] = (L_ADR[4:0] == 5'b01010) ? L_WE_A : 1'b0;
  assign L_WE_IO[11] = (L_ADR[4:0] == 5'b01011) ? L_WE_A : 1'b0;
  assign L_WE_IO[12] = (L_ADR[4:0] == 5'b01100) ? L_WE_A : 1'b0;
  assign L_WE_IO[13] = (L_ADR[4:0] == 5'b01101) ? L_WE_A : 1'b0;
  assign L_WE_IO[14] = (L_ADR[4:0] == 5'b01110) ? L_WE_A : 1'b0;
  assign L_WE_IO[15] = (L_ADR[4:0] == 5'b01111) ? L_WE_A : 1'b0;
  assign L_WE_IO[16] = (L_ADR[4:0] == 5'b10000) ? L_WE_A : 1'b0;
  assign L_WE_IO[17] = (L_ADR[4:0] == 5'b10001) ? L_WE_A : 1'b0;
  assign L_WE_IO[18] = (L_ADR[4:0] == 5'b10010) ? L_WE_A : 1'b0;
  assign L_WE_IO[19] = (L_ADR[4:0] == 5'b10011) ? L_WE_A : 1'b0;
  assign L_WE_IO[20] = (L_ADR[4:0] == 5'b10100) ? L_WE_A : 1'b0;
  assign L_WE_IO[21] = (L_ADR[4:0] == 5'b10101) ? L_WE_A : 1'b0;
  assign L_WE_IO[22] = (L_ADR[4:0] == 5'b10110) ? L_WE_A : 1'b0;
  assign L_WE_IO[23] = (L_ADR[4:0] == 5'b10111) ? L_WE_A : 1'b0;
  assign L_WE_IO[24] = (L_ADR[4:0] == 5'b11000) ? L_WE_A : 1'b0;
  assign L_WE_IO[25] = (L_ADR[4:0] == 5'b11001) ? L_WE_A : 1'b0;
  assign L_WE_IO[26] = (L_ADR[4:0] == 5'b11010) ? L_WE_A : 1'b0;
  assign L_WE_IO[27] = (L_ADR[4:0] == 5'b11011) ? L_WE_A : 1'b0;
  assign L_WE_IO[28] = (L_ADR[4:0] == 5'b11100) ? L_WE_A : 1'b0;
  assign L_WE_IO[29] = (L_ADR[4:0] == 5'b11101) ? L_WE_A : 1'b0;
  assign L_WE_IO[30] = (L_ADR[4:0] == 5'b11110) ? L_WE_A : 1'b0;
  assign L_WE_IO[31] = (L_ADR[4:0] == 5'b11111) ? L_WE_A : 1'b0;
  // case 4 special cases.
  // 4a. WE_01 for register pair 0/1 (multiplication opcode).
  // 4b. I_WE_XYZS for X (register pairs 26/27) and I_AMOD matches
  // 4c. I_WE_XYZS for Y (register pairs 28/29) and I_AMOD matches
  // 4d. I_WE_XYZS for Z (register pairs 30/31) and I_AMOD matches
  //
  assign L_WE_X = (I_AMOD[3:0] == AM_WX) ? I_WE_XYZS : 1'b0;
  assign L_WE_Y = (I_AMOD[3:0] == AM_WY) ? I_WE_XYZS : 1'b0;
  assign L_WE_Z = (I_AMOD[3:0] == AM_WZ) ? I_WE_XYZS : 1'b0;
  assign L_WE_MISC = {L_WE_Z,L_WE_Z,L_WE_Y,L_WE_Y,L_WE_X,L_WE_X,24'h000000,I_WE_01,I_WE_01};
  // multiplication result    r00
  assign L_WE = L_WE_D | L_WE_DD | L_WE_IO | L_WE_MISC;
  assign Q_S = (L_ADR[0] == 1'b0) ? L_S[7:0] : L_S[15:8];
  assign Q_FLAGS = S_FLAGS;
  assign Q_Z = R_R30;
  assign Q_ADR = L_ADR;
endmodule

