module fp_lsft78(
input wire [78:1] inbus,
input wire [6:1] shift,
output wire [78:1] outbus
);
wire [78:1] levzip; wire [78:1] levone; wire [78:1] levtwo;
wire [78:1] levthr; wire [78:1] levfor; wire [78:1] levfiv;
wire [78:1] levsix;
  assign levzip = inbus;
  assign levone[1] = levzip[1] &  ~(shift[1]);
  genvar k;
  generate for (k=2; k <= 78; k = k + 1) begin: gaa
      assign levone[k] = (levzip[k] &  ~(shift[1])) | (levzip[k - 1] & shift[1]);
  end
  endgenerate
  assign levtwo[1] = levone[1] &  ~(shift[2]);
  assign levtwo[2] = levone[2] &  ~(shift[2]);
  genvar k;
  generate for (k=3; k <= 78; k = k + 1) begin: gba
      assign levtwo[k] = (levone[k] &  ~(shift[2])) | (levone[k - 2] & shift[2]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 4; k = k + 1) begin: gca
      assign levthr[k] = levtwo[k] &  ~(shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=5; k <= 78; k = k + 1) begin: gcb
      assign levthr[k] = (levtwo[k] &  ~(shift[3])) | (levtwo[k - 4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 8; k = k + 1) begin: gda
      assign levfor[k] = levthr[k] &  ~(shift[4]);
  end
  endgenerate
  genvar k;
  generate for (k=9; k <= 78; k = k + 1) begin: gdb
      assign levfor[k] = (levthr[k] &  ~(shift[4])) | (levthr[k - 8] & shift[4]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 16; k = k + 1) begin: gea
      assign levfiv[k] = levfor[k] &  ~(shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=17; k <= 78; k = k + 1) begin: geb
      assign levfiv[k] = (levfor[k] &  ~(shift[5])) | (levfor[k - 16] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 32; k = k + 1) begin: gfa
      assign levsix[k] = levfiv[k] &  ~(shift[6]);
  end
  endgenerate
  genvar k;
  generate for (k=33; k <= 78; k = k + 1) begin: gfb
      assign levsix[k] = (levfiv[k] &  ~(shift[6])) | (levfiv[k - 32] & shift[6]);
  end
  endgenerate
  assign outbus = levsix;
endmodule

module neo430_cfu(
input wire clk_i,
input wire rden_i,
input wire wren_i,
input wire [15:0] addr_i,
input wire [15:0] data_i,
output reg [15:0] data_o,
output wire clkgen_en_o,
input wire [7:0] clkgen_i
);
// host access --
// global clock line
// read enable
// write enable
// address
// data in
// data out
// clock generator --
// enable clock generator
// custom IOs --
//  ...
// IO space: module base address --
parameter hi_abb_c = index_size_f[io_size_c] - 1;  // high address boundary bit
parameter lo_abb_c = index_size_f[cfu_size_c];  // low address boundary bit
// access control --
wire acc_en;  // module access enable
wire [15:0] addr;  // access address
wire wren;  // full word write enable
wire rden;  // read enable
// accessible regs (8x16-bit) --
reg [15:0] cfu_ctrl_reg;
reg [15:0] user_reg1;
reg [15:0] user_reg2;
reg [15:0] user_reg3;
reg [15:0] user_reg4;
reg [15:0] user_reg5;
reg [15:0] user_reg6;
reg [15:0] user_reg7;
  // Access Control -----------------------------------------------------------
  // -----------------------------------------------------------------------------
  // These assignments are required to check if this unit is accessed at all.
  // Do NOT modify this for your custom application (unless you really know what you are doing)!
  assign acc_en = (addr_i[hi_abb_c:lo_abb_c] == cfu_base_c[hi_abb_c:lo_abb_c]) ? 1'b1 : 1'b0;
  assign addr = {cfu_base_c[15:lo_abb_c],addr_i[lo_abb_c - 1:1],1'b0};
  // word aligned
  assign wren = acc_en & wren_i;
  assign rden = acc_en & rden_i;
  // Clock System -------------------------------------------------------------
  // -----------------------------------------------------------------------------
  // The top unit implements a clock generator providing 8 "derived clocks"
  // Actually, these signals must not be used as direct clock signals, but as clock enable signals.
  // If wou want to drive a system at MAIN_CLK/8 use the following construct:
  // if rising_edge(clk_i) then -- Always use the main clock for all clock processes!
  //   if (clkgen_i(clk_div8_c) = '1') then -- the div8 "clock" is actually a clock enable
  //     ...
  //   end if;
  // end if;
  // The following clock divider rates are available:
  // clkgen_i(clk_div2_c)    -> MAIN_CLK/2
  // clkgen_i(clk_div4_c)    -> MAIN_CLK/4
  // clkgen_i(clk_div8_c)    -> MAIN_CLK/8
  // clkgen_i(clk_div64_c)   -> MAIN_CLK/64
  // clkgen_i(clk_div128_c)  -> MAIN_CLK/128
  // clkgen_i(clk_div1024_c) -> MAIN_CLK/1024
  // clkgen_i(clk_div2048_c) -> MAIN_CLK/2048
  // clkgen_i(clk_div4096_c) -> MAIN_CLK/4096
  // this signal enabled the generator driving the clkgen_i
  // set this signal to '0' when you do not need the clkgen_i signal or when your CFU is disabled
  // to reduce dynamic power consumption
  assign clkgen_en_o = 1'b0;
  // Write access -------------------------------------------------------------
  // -----------------------------------------------------------------------------
  // Here we are writing to the interface registers of the module. This unit can only be accessed
  // in full 16-bit word mode!
  // Please note, that all register of every unit are cleared during the processor boot sequence.
  // Make cfu_reg0_addr_c the CFU's control register. This register is cleared first during booting.
  // If the control register is cleared no actions should be taken when writing to other CFU registers.
  always @(posedge clk_i) begin
    // write access to user registers --
    if((wren == 1'b1)) begin
      // valid write access
      // use full-parallel IFs instead of a CASE to prevent some EDA tools from complaining (GHDL)
      if((addr == cfu_reg0_addr_c)) begin
        cfu_ctrl_reg <= data_i;
      end
      if((addr == cfu_reg1_addr_c)) begin
        user_reg1 <= data_i;
      end
      if((addr == cfu_reg2_addr_c)) begin
        user_reg2 <= data_i;
      end
      if((addr == cfu_reg3_addr_c)) begin
        user_reg3 <= data_i;
      end
      if((addr == cfu_reg4_addr_c)) begin
        user_reg4 <= data_i;
      end
      if((addr == cfu_reg5_addr_c)) begin
        user_reg5 <= data_i;
      end
      if((addr == cfu_reg6_addr_c)) begin
        user_reg6 <= data_i;
      end
      if((addr == cfu_reg7_addr_c)) begin
        user_reg7 <= data_i;
      end
    end
  end
  // >>> UNIT HARDWARE RESET <<< --
  // The IO devices DO NOT feature a dedicated reset signal, so make sure your CFU does not require a defined initial state.
  // If you really require a defined initial state, implement a software reset by implementing a control register with an
  // enable bit, which resets all internal states when cleared.
  // Read access --------------------------------------------------------------
  // -----------------------------------------------------------------------------
  // This is the read access process. Data must be asserted synchronously to the output data bus
  // and thus, with exactly 1 cycle delay. The units always output a full 16-bit word, no matter if we want to
  // read 8- or 16-bit. For actual 8-bit read accesses the corresponding byte is selected in the
  // hardware of the CPU core.
  always @(posedge clk_i) begin
    data_o <= {16{1'b0}};
    // this is crucial for the final OR-ing of all IO device's outputs
    if((rden == 1'b1)) begin
      // valid read access
      // use IFs instead of a CASE to prevent some EDA tools from complaining (GHDL)
      if((addr == cfu_reg0_addr_c)) begin
        data_o <= cfu_ctrl_reg;
      end
      else if((addr == cfu_reg1_addr_c)) begin
        data_o <= user_reg1;
      end
      else if((addr == cfu_reg2_addr_c)) begin
        data_o <= user_reg2;
      end
      else if((addr == cfu_reg3_addr_c)) begin
        data_o <= user_reg3;
      end
      else if((addr == cfu_reg4_addr_c)) begin
        data_o <= user_reg4;
      end
      else if((addr == cfu_reg5_addr_c)) begin
        data_o <= user_reg5;
      end
      else if((addr == cfu_reg6_addr_c)) begin
        data_o <= user_reg6;
      end
      else if((addr == cfu_reg7_addr_c)) begin
        data_o <= user_reg7;
      end
      else begin
        data_o <= {16{1'b0}};
      end
    end
  end
endmodule

module ALU_Control(
input wire [1:0] ALU_OP,
input wire [5:0] ALU_Funct_In,
output wire [3:0] ALU_Control_out
);
//! Opcode from controller
//! funt_in from instruction (first 6 bits)
//! alu_control output
//! @brief This is the ALU control that generates the 4 control bits for the ALU
//! @details opcode 00: load/store functions (add for calculating adress)
//! @details opcode 01: branch on equal (substract for comparing inputs)
//! @details opcode 10: R-type instruction (depends on ALU_Funct_In)
//! @details ALU_Funct_In 100000: add
//! @details ALU_Funct_In 100000: substract
//! @details ALU_Funct_In 100000: AND
//! @details ALU_Funct_In 100000: OR
//! @details ALU_Funct_In 100000: set less then
  always @(ALU_OP, ALU_Funct_In) begin
    if((ALU_OP == 2'b00)) begin
      // load/store functions
      ALU_Control_Out <= 4'b0010;
      // set to add to calculate adress
    end
    else if((ALU_OP == 2'b01)) begin
      // branch on equal
      ALU_Control_Out <= 4'b0110;
      // set to substract
    end
    else if((ALU_OP == 2'b10)) begin
      // R-type instruction
      case(ALU_Funct_In)
      6'b100000 : begin
        ALU_Control_Out <= 4'b0010;
        //add
      end
      6'b100010 : begin
        ALU_Control_Out <= 4'b0110;
        //substract
      end
      6'b100100 : begin
        ALU_Control_Out <= 4'b0000;
        //AND
      end
      6'b100101 : begin
        ALU_Control_Out <= 4'b0001;
        //OR
      end
      6'b101010 : begin
        ALU_Control_Out <= 4'b0111;
        //slt
      end
      6'b100111 : begin
        ALU_Control_Out <= 4'b1100;
        //NOR
      end
      6'b011000 : begin
        ALU_Control_Out <= 4'b1101;
        //mult(values chosen at will)
      end
      6'b010000 : begin
        ALU_Control_Out <= 4'b1111;
        //output Hi (chosen at will)
      end
      6'b010010 : begin
        ALU_Control_Out <= 4'b1110;
        //output Lo (chosen at will)
      end
      default : begin
        ALU_Control_Out <= 4'b0100;
        //error value
      end
      endcase
    end
    else begin
      ALU_Control_Out <= 4'b1111;
      //error value
    end
  end
