module idex_reg(
input wire [(CW_SIZE + ALUOP_SIZE) - 2:0] cw_to_ex_dec,
input wire [31:0] jump_address_dec,
input wire [31:0] pc_4_dec,
input wire [31:0] read_data_1_dec,
input wire [31:0] read_data_2_dec,
input wire [31:0] immediate_ext_dec,
input wire [15:0] immediate_dec,
input wire [4:0] rt_dec,
input wire [4:0] rd_dec,
input wire [4:0] rs_dec,
input wire clk,
input wire rst,
output reg [(CW_SIZE + ALUOP_SIZE) - 2:0] cw_to_ex,
output reg [31:0] jump_address,
output reg [31:0] pc_4,
output reg [31:0] read_data_1,
output reg [31:0] read_data_2,
output reg [31:0] immediate_ext,
output reg [15:0] immediate,
output reg [4:0] rt,
output reg [4:0] rd,
output reg [4:0] rs
);
// INPUTS
// control word directed to the ex stage (note -2 since unsigned control signal is alredy used in decode thus no need to propagate)
// jump address extended
// PC incremented by 4 from decode
// reg 1 read from decode
// reg 2 read from decode
// immediate sign extended from decode
// immediate for lui instrucion from decode
// rt address from decode
// rs address from decode
// rd address from decode
// global clock signal
// global reset signal
// OUTPUTS
// control word for ex stage
// jump address to ex stage
//--------------------------------------------------------------------------
//--------------------------------------------------------------------------
  //----------------------
  // Reg Proc
  // Type: Sequiential
  // Purpose: Implement
  // the behavior of the
  // pipeline register
  // Reset is synchronous
  //----------------------
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      cw_to_ex <= {(((CW_SIZE + ALUOP_SIZE) - 2)-(0)+1){1'b0}};
      jump_address <= {32{1'b0}};
      pc_4 <= {32{1'b0}};
      read_data_1 <= {32{1'b0}};
      read_data_2 <= {32{1'b0}};
      immediate_ext <= {32{1'b0}};
      immediate <= {16{1'b0}};
      rt <= {5{1'b0}};
      rd <= {5{1'b0}};
      rs <= {5{1'b0}};
    end
    else begin
      cw_to_ex <= cw_to_ex_dec;
      jump_address <= jump_address_dec;
      pc_4 <= pc_4_dec;
      read_data_1 <= read_data_1_dec;
      read_data_2 <= read_data_2_dec;
      immediate_ext <= immediate_ext_dec;
      immediate <= immediate_dec;
      rt <= rt_dec;
      rd <= rd_dec;
      rs <= rs_dec;
    end
  end
endmodule

