module bcd_adder(
input wire [3:0] b_in,
input wire [3:0] a_in,
input wire c_in,
output wire c_out,
output wire [3:0] s_out
);
wire cin;
wire co1; wire co2; wire co3; wire co4; wire co5; wire co6;
wire s0; wire s1; wire s2; wire s3; wire s4; wire s5; wire s6;
wire a1; wire a2;
wire cout;
wire hold_low;
  adder FA3(
      .b(b_in[3]),
    .a(a_in[3]),
    .ci(co3),
    .co(co4),
    .s(s3));
  adder FA2(
      .b(b_in[2]),
    .a(a_in[2]),
    .ci(co2),
    .co(co3),
    .s(s2));
  adder FA1(
      .b(b_in[1]),
    .a(a_in[1]),
    .ci(co1),
    .co(co2),
    .s(s1));
  adder FA0(
      .b(b_in[0]),
    .a(a_in[0]),
    .ci(cin),
    .co(co1),
    .s(s0));
  assign hold_low = 1'b0;
  assign cout = co4 | a1 | a2;
  assign s6 = co6 ^ s3;
  assign a1 = s3 & s2;
  assign a2 = s3 & s1;
  adder FA5(
      .b(s2),
    .a(cout),
    .ci(co5),
    .co(co6),
    .s(s5));
  adder FA4(
      .b(s1),
    .a(cout),
    .ci(hold_low),
    .co(co5),
    .s(s4));
  assign s_out[0] = s0;
  assign s_out[1] = s4;
  assign s_out[2] = s5;
  assign s_out[3] = s6;
  assign c_out = cout;
endmodule

