module vga_sync(
input wire clk_in,
input wire reset_in,
output wire hSync_out,
output wire vSync_out,
output wire [COORD_WIDTH - 1:0] pixX_out,
output wire [COORD_WIDTH - 1:0] pixY_out
);
// Horizontal parameters (numbers are pixel clock counts)
parameter [31:0] HORIZ_DISP=640;
parameter [31:0] HORIZ_FP=16;
parameter [31:0] HORIZ_RT=96;
parameter [31:0] HORIZ_BP=48;
parameter [31:0] VERT_DISP=480;
parameter [31:0] VERT_FP=10;
parameter [31:0] VERT_RT=2;
parameter [31:0] VERT_BP=29;
parameter [31:0] COORD_WIDTH=10;
// Line & pixel counters
reg [COORD_WIDTH - 1:0] vCount = 1'b0;
wire [COORD_WIDTH - 1:0] vCount_next;
reg [COORD_WIDTH - 1:0] hCount = 1'b0;
wire [COORD_WIDTH - 1:0] hCount_next;  // Registered horizontal & vertical sync signals
reg vSync = 1'b1;
wire vSync_next;
reg hSync = 1'b1;
wire hSync_next;  // End-of-line/screen flags
wire hEnd;
wire vEnd;
  // Registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      vCount <= {((COORD_WIDTH - 1)-(0)+1){1'b0}};
      hCount <= {((COORD_WIDTH - 1)-(0)+1){1'b0}};
      vSync <= 1'b1;
      hSync <= 1'b1;
    end
    else begin
      vCount <= vCount_next;
      hCount <= hCount_next;
      vSync <= vSync_next;
      hSync <= hSync_next;
    end
  end
  // End-of-line flag
  assign hEnd = hCount == (HORIZ_DISP + HORIZ_FP + HORIZ_BP + HORIZ_RT - 1) ? 1'b1 : 1'b0;
  // End-of-frame flag
  assign vEnd = vCount == (VERT_DISP + VERT_FP + VERT_BP + VERT_RT - 1) ? 1'b1 : 1'b0;
  // Current pixel within the current line, 0-639 for 640x480@60Hz
  assign hCount_next = hEnd == 1'b0 ? hCount + 1 : {((COORD_WIDTH - 1)-(0)+1){1'b0}};
  // Current line within the current frame, 0-524 for 640x480@60Hz
  assign vCount_next = hEnd == 1'b1 && vEnd == 1'b1 ? {((COORD_WIDTH - 1)-(0)+1){1'b0}} : hEnd == 1'b1 && vEnd == 1'b0 ? vCount + 1 : vCount;
  // Registered horizontal and vertical syncs
  assign hSync_next = hCount >= (HORIZ_DISP + HORIZ_FP - 1) && hCount < (HORIZ_DISP + HORIZ_FP + HORIZ_RT - 1) ? 1'b0 : 1'b1;
  assign vSync_next = vCount == (VERT_DISP + VERT_FP - 1) && hEnd == 1'b1 ? 1'b0 : vCount == (VERT_DISP + VERT_FP + VERT_RT - 1) && hEnd == 1'b1 ? 1'b1 : vSync;
  // Drive output signals
  assign hSync_out = hSync;
  assign vSync_out = vSync;
  assign pixX_out = hCount;
  assign pixY_out = vCount;
endmodule

module vga_laplacian_fusion(
input wire clk_25,
input wire [23:0] rgb_blur_0,
input wire [23:0] rgb_pass_0,
input wire [23:0] rgb_blur_1,
input wire [23:0] rgb_pass_1,
output reg [23:0] rgb_out
);
  always @(posedge clk_25) begin : P1
    reg [31:0] r_0, g_0, b_0, r_1, g_1, b_1;
    reg [31:0] r_diff_0, g_diff_0, b_diff_0, r_diff_1, g_diff_1, b_diff_1;
    r_0 = rgb_pass_0[23:16];
    g_0 = rgb_pass_0[15:8];
    b_0 = rgb_pass_0[7:0];
    r_1 = rgb_pass_1[23:16];
    g_1 = rgb_pass_1[15:8];
    b_1 = rgb_pass_1[7:0];
    r_diff_0 = r_0 - (rgb_blur_0[23:16]);
    g_diff_0 = g_0 - (rgb_blur_0[15:8]);
    b_diff_0 = b_0 - (rgb_blur_0[7:0]);
    r_diff_1 = r_1 - (rgb_blur_1[23:16]);
    g_diff_1 = g_1 - (rgb_blur_1[15:8]);
    b_diff_1 = b_1 - (rgb_blur_1[7:0]);
    rgb_out[23:16] <= r_0 * (r_diff_0 / (r_diff_0 + r_diff_1)) + r_1 * (r_diff_1 / (r_diff_0 + r_diff_1));
    rgb_out[15:8] <= g_0 * (g_diff_0 / (g_diff_0 + g_diff_1)) + g_1 * (g_diff_1 / (g_diff_0 + g_diff_1));
    rgb_out[7:0] <= b_0 * (b_diff_0 / (b_diff_0 + b_diff_1)) + b_1 * (b_diff_1 / (b_diff_0 + b_diff_1));
  end
endmodule

