module alu(
input wire [3:0] a,
input wire [3:0] b,
input wire [2:0] alucode,
output reg [3:0] result,
output reg z,
output reg o
);
  always @(alucode, a, b) begin : P1
    reg [4:0] im;
    case(alucode)
        // ADD
    3'b000 : begin
      im = ({1'b0,a}) + ({1'b0,b});
      result <= im[3:0];
      z <= im[4];
      // SUB
    end
    3'b001 : begin
      im = ({1'b0,a}) - ({1'b0,b});
      result <= im[3:0];
      z <= im[4];
      // AND
    end
    3'b010 : begin
      im[3:0] = {a[0] & b[0],a[1] & b[1],a[2] & b[2],a[3] & b[3]};
      if(im[3:0] == 3'b111) begin
        z <= 1'b1;
      end
      else begin
        z <= 1'b0;
      end
      result <= im[3:0];
      // CMP
    end
    3'b011 : begin
      if(a < b) begin
        result <= a;
        z <= 1'b0;
      end
      else if(a == b) begin
        result <= a;
        z <= 1'b1;
      end
      else begin
        result <= b;
        z <= 1'b0;
      end
      // RT
    end
    3'b100 : begin
      result <= {1'b0,a[2:0]};
      z <= a[3];
      // RR
    end
    3'b101 : begin
      result <= {a[3:1],1'b0};
      z <= a[0];
      // Parity
    end
    3'b110 : begin
      result <= a;
      z <= a[0] ^ a[1] ^ a[2] ^ a[3];
    end
    default : begin
      result <= {4{1'b0}};
      z <= 1'b0;
      o <= 1'b0;
    end
    endcase
  end
endmodule

