module Frecuencimetro(
input wire reloj,
input wire senialGenerador,
output wire [6:0] decenasDisplay,
output wire [6:0] unidadesDisplay
);
// Reloj interno de la placa
// Senial introducida por el generador
// Valor de las decenas a mostrar en el display
// Valor de las unidades a mostrar en el display
// Definimos la arquitectura
reg [31:0] salida;  // En esta senial guardaremos el valor del numero de pulsos de la senial para mostrar dicho resultado
reg [31:0] unidades;  // Valor de las unidades
reg [31:0] decenas;  // Valor de las decenas
reg [31:0] pulsosReloj;  // Contamos los pulsos de nuestra senial de reloj
reg [31:0] pulsosSenial;  // Contamos los pulsos de la senial introducida
reg flag = 1'b0;  // Marca utilizada para reiniciar los pulso de la senial
// Instanciamos el codificador de 7 segmentos para la representacion mediante display
  // Proceso que cuenta el numero de pulsos que da el reloj. Cuando llegue a 25175 (ya que la frecuencia es de
  // 25'175 MHz = 25175000 pulsos por segundo) es que ha pasado un segundo. Por tanto mostramos los pulsos que ha dado
  // nuestra senial hasta entonces (en KHz)
  always @(posedge reloj) begin
    pulsosReloj <= pulsosReloj + 1;
    flag <= 1'b0;
    if((pulsosReloj >= 25175)) begin
      flag <= 1'b1;
      salida <= pulsosSenial;
      pulsosReloj <= 0;
    end
  end
  // Proceso que cuenta el numero de pulsos que da la senial del generador en un segundo. Obtenemos asi su frecuencia
  always @(posedge flag, posedge senialGenerador) begin
    if(flag == 1'b1) begin
      pulsosSenial <= 0;
    end else begin
      pulsosSenial <= pulsosSenial + 1;
    end
  end
  // Proceso para obtener el valor de la frecuencia de la senial a partir del numero de pulsos obtenidos de esta
  // Como sabemos que se movera el valor entre los 1-90 KHz, en el primer display mostraremos las unidades en KHz y en el segundo las decenas en KHz
  always @(salida) begin
    decenas <= salida / 10;
    // Obtenemos las decenas
    unidades <= salida - decenas * 10;
    // Obtenemos las unidades
  end
  // Codificamos para mostrar por el display de 7 segmentos las unidades
  codificador7Segmentos mostrarUnidadesDisplay(
      .entrada(unidades),
    .salida(unidadesDisplay));
  // Codificamos para mostrar por el display de 7 segmenos las decenas
  codificador7Segmentos mostrarDecenasDisplay(
      .entrada(decenas),
    .salida(decenasDisplay));
endmodule

