module csi_rx_clock_det(
input wire ref_clock,
input wire ext_clock,
input wire enable,
input wire reset_in,
output wire reset_out
);
//reference clock in; must not be synchronised to ext_clock
//external byte clock input for detection
//active high enable
//active high asynchronous reset in
//active high reset out to ISERDESs
reg [3:0] count_value;
wire clk_fail;
reg ext_clk_lat;
reg last_ext_clk;
reg [7:0] clk_fail_count;
  always @(posedge ext_clock, posedge reset_in, posedge clk_fail) begin
    if(reset_in == 1'b1 || clk_fail == 1'b1) begin
      count_value <= 4'h0;
    end else begin
      if(enable == 1'b1) begin
        if(count_value < 3) begin
          count_value <= count_value + 1;
        end
      end
    end
  end
  //Reset in between frames, by detecting the loss of the high speed clock
  always @(posedge ref_clock) begin
    ext_clk_lat <= ext_clock;
    last_ext_clk <= ext_clk_lat;
    if(last_ext_clk != ext_clk_lat) begin
      clk_fail_count <= {8{1'b0}};
    end
    else begin
      if(clk_fail_count < 250) begin
        clk_fail_count <= clk_fail_count + 1;
      end
    end
  end
  assign clk_fail = clk_fail_count >= 200 ? 1'b1 : 1'b0;
  assign reset_out = count_value >= 2 ? 1'b0 : 1'b1;
endmodule

