module UART(
input wire CS,
input wire WE,
input wire [1:0] REG_SEL,
input wire [15:0] WR_DATA,
output reg [7:0] RD_DATA,
output reg RX_IRQ,
output reg TX_IRQ,
input wire RXD,
output wire TXD,
input wire RESET,
input wire RDV,
input wire FCLK
);
// chip select
// write enable
// register select
// write data
// read  data
// RX interrupt request
// TX interrupt request
// RX serial data
// TX serial data
// system reset
// read data valid
// fast clock
//=================================================================
// Signal definitions
//=================================================================
wire [1:0] PARITY_MODE;
reg FRAMING_ERR;
reg PARITY_ERR;
reg OVERRUN_ERR;
reg STATUS_CLR;  // clear status register
reg [3:0] TX_STATE;  // TX state
reg [3:0] TX_NSTATE;  // TX next state
reg [7:0] TX_SHIFT_REG;  // TX shift reg
reg [3:0] TX_COUNT;  // TX shift counter
wire [7:0] TX_FIFO_DATA;  // TX FIFO out
wire TX_FIFO_OVFL;  // TX FIFO overflow flag
wire TX_FIFO_FULL;  // TX FIFO full flag
wire TX_FIFO_EMPTY;  // TX FIFO empty flag
reg TX_FIFO_OP;  // TX FIFO 1==push 0== pop
reg TX_FIFO_CKEN;  // TX FIFO clock enable
reg TX_SHIFT_LD;  // TX shift reg load
wire TX_EN;  // TX enabled
reg TX_CLK_EN;  // TX clock enable
reg TX_PARITY;  // TX parity
reg TX_SHIFT_EN;  // TX shift reg enable
reg TX_SHIFT_EN1;  // TX shift reg enable delayed
reg TX_BCLK;  // TX baud clock
reg TX_BCLK_DLY;  // TX baud clock delayed
reg [3:0] RX_STATE;  // RX state
reg [3:0] RX_NSTATE;  // RX next state
reg [2:0] RX_COUNT;  // RX shift counter
reg [7:0] RX_SHIFT_REG;  // RX shift register
wire [7:0] RX_FIFO_DATA;  // RX FIFO data
wire RX_FIFO_OVFL;  // RX FIFO overflow flag
reg RX_FIFO_STOP;  // RX FIFO stop flag
wire RX_FIFO_FULL;  // RX FIFO full flag
wire RX_FIFO_EMPTY;  // RX FIFO empty flag
reg RX_FIFO_OP;  // RX FIFO 1==push 0== pop
reg RX_FIFO_CKEN;  // RX FIFO clock enable
wire RX_EN;  // RX enable
reg RX_ACCEPT;  // receiver has accepted frame
reg RXD_SYNC;  // synchronize received data
reg RXD_SYNC1;  // synchronize received data
reg RX_CLK_EN;  // receiver clock enable
reg RX_SHIFT_EN;  // receiver shift enable
reg RX_PARITY;  // calculated receiver parity
reg RX_START;  // testing start bit
reg RX_BCLK;  // receiver baud clock
reg RX_BCLK_DLY;  // receiver baud clock delayed
wire RXDI;  // receive  data
reg TXDI;  // transmit data
wire [15:0] PRELOAD;  // baud rate preload
reg [15:0] RX_BAUD;  // RX baud counter
reg [15:0] TX_BAUD;  // TX baud counter
// Registers
reg [3:0] CNTL_REG;  // control
reg [15:0] BRSR_REG;  // baud rate select
reg [7:0] STAT_REG;  // status
reg [1:0] MASK_REG;  // interrupt mask
// Register addresses
parameter CNTL_ADDR = 2'b00;  // control
parameter STAT_ADDR = 2'b00;  // status
parameter BRSR_ADDR = 2'b01;  // baud rate
parameter MASK_ADDR = 2'b10;  // irq mask
parameter HOLD_ADDR = 2'b11;  // hold reg
// parity modes
parameter NONE = 2'b00;
parameter EVEN = 2'b01;
parameter ODD = 2'b10;  // State Constants
parameter IDLE = 4'b1000;
parameter LOAD = 4'b0010;
parameter D7 = 4'b0010;
parameter SHIFT = 4'b0100;
parameter PRTY = 4'b0000;
parameter STOP = 4'b0001;  // Misc
parameter CKDIV_TC = 10'b0000000000;
parameter TX_INIT = 4'b0011;
parameter TX_TC = 4'b0000;
parameter RX_INIT = 3'b000;
parameter RX_TC = 3'b100;  //================================================================
// component definitions
//================================================================
//================================================================
// End of types, component, and signal definition section
//================================================================
  //=============================================
  // Register Writes
  //=============================================
  always @(negedge FCLK) begin
    STATUS_CLR <= 1'b0;
    if(((CS == 1'b1) && (WE == 1'b1))) begin
      case(REG_SEL)
      CNTL_ADDR : begin
        if((WR_DATA[4] == 1'b1)) begin
          STATUS_CLR <= 1'b1;
        end
        else begin
          CNTL_REG <= WR_DATA[3:0];
        end
      end
      BRSR_ADDR : begin
        BRSR_REG <= WR_DATA;
      end
      MASK_ADDR : begin
        MASK_REG <= WR_DATA[1:0];
      end
      default : begin
      end
      endcase
    end
    // reset state
    if((RESET == 1'b1)) begin
      CNTL_REG <= {4{1'b0}};
      BRSR_REG <= {16{1'b0}};
      MASK_REG <= {2{1'b0}};
      STATUS_CLR <= 1'b1;
    end
  end
  //=============================================
  // TX FIFO Control
  //=============================================
  always @(CS, WE, REG_SEL, TX_EN, TX_SHIFT_LD) begin
    TX_FIFO_CKEN <= 1'b0;
    TX_FIFO_OP <= 1'b0;
    // push tx FIFO
    if(((CS == 1'b1) && (WE == 1'b1) && (REG_SEL == HOLD_ADDR))) begin
      if((TX_EN == 1'b1)) begin
        TX_FIFO_OP <= 1'b1;
        TX_FIFO_CKEN <= 1'b1;
      end
    end
    // pop TX FIFO
    if((TX_SHIFT_LD == 1'b1)) begin
      TX_FIFO_CKEN <= 1'b1;
    end
  end
  //=============================================
  // Status Register
  //=============================================
  always @(FRAMING_ERR, PARITY_ERR, OVERRUN_ERR, TX_FIFO_FULL, TX_FIFO_EMPTY, RX_FIFO_FULL, RX_FIFO_EMPTY) begin
    STAT_REG[7] <= 1'b0;
    STAT_REG[6] <= FRAMING_ERR;
    STAT_REG[5] <= PARITY_ERR;
    STAT_REG[4] <= OVERRUN_ERR;
    STAT_REG[3] <= TX_FIFO_EMPTY;
    // TX FIFO is empty
    STAT_REG[2] <=  ~TX_FIFO_FULL;
    // TX FIFO is not full
    STAT_REG[1] <= RX_FIFO_FULL;
    // RX FIFO is full
    STAT_REG[0] <=  ~RX_FIFO_EMPTY;
    // RX FIFO is not empty
  end
  //=============================================
  // Control Register Outputs
  //=============================================
  assign PRELOAD = BRSR_REG;
  // baud rate select constant
  assign PARITY_MODE = CNTL_REG[3:2];
  // parity mode (even/odd/none)
  assign RX_EN = CNTL_REG[1];
  // receiver enable
  assign TX_EN = CNTL_REG[0];
  // transmit enable
  //=============================================
  // Register Reads
  //=============================================
  always @(CS, REG_SEL, RX_FIFO_DATA, STAT_REG) begin
    RD_DATA <= RX_FIFO_DATA;
    if((CS == 1'b1)) begin
      case(REG_SEL)
      STAT_ADDR : begin
        // status register
        RD_DATA <= STAT_REG;
      end
      default : begin
      end
      endcase
    end
  end
  //=========================================================================
  // RX Interrupt Generation Logic
  //
  //  Generated RX_IRQ if: Data is ready in the receiver reg
  //  and the RX IRQ is not masked.
  //=========================================================================
  always @(RX_FIFO_FULL, MASK_REG) begin
    RX_IRQ <= 1'b0;
    if(((RX_FIFO_FULL == 1'b1) && (MASK_REG[0] == 1'b1))) begin
      RX_IRQ <= 1'b1;
    end
  end
  //=========================================================================
  // TX Interrupt Generation Logic
  //
  //  Generated TX_IRQ if: The transmitter is empty and the TX IRQ
  //  is not masked and the transmitter is enabled
  //  Note: The transmit interrupt can only be cleared by writing new data
  //  to the transmit hold register or by disabling the transmitter.
  //=========================================================================
  always @(TX_FIFO_EMPTY, MASK_REG, TX_EN) begin
    TX_IRQ <= 1'b0;
    if(((TX_FIFO_EMPTY == 1'b1) && (MASK_REG[1] == 1'b1) && (TX_EN == 1'b1))) begin
      TX_IRQ <= 1'b1;
    end
  end
  assign TXD = TXDI;
  // transmit data from tx shift reg
  assign RXDI = RXD;
  // receive  data from pin
  //================================================
  // Transmit state machine
  //================================================
  always @(negedge FCLK) begin
    if((TX_CLK_EN == 1'b1)) begin
      TX_STATE <= TX_NSTATE;
    end
    // reset state
    if((RESET == 1'b1)) begin
      TX_STATE <= IDLE;
    end
  end
  //================================================
  // Transmit shift counter
  //
  //  0) 0011    3) 1011    6) 1100
  //  1) 0110    4) 0111    7) 1000
  //  2) 1101    5) 1110    8) 0000   <- TC
  //
  //================================================
  always @(negedge FCLK) begin
    if(((TX_STATE == SHIFT) && (TX_CLK_EN == 1'b1))) begin
      TX_COUNT <= {TX_COUNT[2:0], ~(TX_COUNT[0] ^ TX_COUNT[3])};
    end
    if((TX_STATE == IDLE)) begin
      TX_COUNT <= TX_INIT;
    end
  end
  //================================================
  // Transmit state machine next state logic
  //================================================
  always @(TX_STATE, TX_SHIFT_EN, TX_CLK_EN, TX_COUNT, PARITY_MODE) begin
    case(TX_STATE)
    IDLE : begin
      // detect the leading edge of the transmit shift enable
      if((TX_SHIFT_EN == 1'b1)) begin
        TX_NSTATE <= LOAD;
      end
      else begin
        TX_NSTATE <= IDLE;
      end
    end
    LOAD : begin
      // detect the first transmit clock enable
      if((TX_CLK_EN == 1'b1)) begin
        TX_NSTATE <= SHIFT;
      end
      else begin
        TX_NSTATE <= LOAD;
      end
    end
    SHIFT : begin
      if(((TX_CLK_EN == 1'b1) && (TX_COUNT == TX_TC))) begin
        if((PARITY_MODE == NONE)) begin
          TX_NSTATE <= STOP;
        end
        else begin
          TX_NSTATE <= PRTY;
        end
      end
      else begin
        TX_NSTATE <= SHIFT;
      end
    end
    PRTY : begin
      if((TX_CLK_EN == 1'b1)) begin
        TX_NSTATE <= STOP;
      end
      else begin
        TX_NSTATE <= PRTY;
      end
    end
    STOP : begin
      if((TX_CLK_EN == 1'b1)) begin
        TX_NSTATE <= IDLE;
      end
      else begin
        TX_NSTATE <= STOP;
      end
    end
    default : begin
      TX_NSTATE <= IDLE;
    end
    endcase
  end
  //================================================
  // Transmit Shift Enable
  //================================================
  always @(negedge FCLK) begin
    // TX_SHIFT_EN is active if:
    //   the previous shift has finished (TX_STATE=IDLE) and
    //   the FIFO has data (TX_FIFO_EMPTY=0) and
    //   the transmitter is enabled (TX_EN=1)
    if(((TX_STATE == IDLE) && (TX_FIFO_EMPTY == 1'b0) && (TX_EN == 1'b1))) begin
      TX_SHIFT_EN <= 1'b1;
    end
    else if(((TX_STATE == STOP) && (TX_CLK_EN == 1'b1))) begin
      TX_SHIFT_EN <= 1'b0;
    end
    // delay for edge detection
    TX_SHIFT_EN1 <= TX_SHIFT_EN;
    // reset state
    if(((RESET == 1'b1) || (TX_EN == 1'b0))) begin
      TX_SHIFT_EN <= 1'b0;
      TX_SHIFT_EN1 <= 1'b0;
    end
  end
  //=============================================
  // Transmit baud-rate clock divider
  //=============================================
  always @(negedge FCLK) begin
    // delayed baud clock for edge detection
    TX_BCLK_DLY <= TX_BCLK;
    if((TX_SHIFT_EN == 1'b1)) begin
      // count
      TX_BAUD <= {TX_BAUD[14:0], ~(TX_BAUD[2] ^ TX_BAUD[15])};
      // reload at terminal count
      if((TX_BAUD == CKDIV_TC)) begin
        TX_BAUD <= PRELOAD;
        TX_BCLK <=  ~TX_BCLK;
      end
    end
    // load the initial count on reset or
    // when we start to send a new frame
    if(((RESET == 1'b1) || ((TX_SHIFT_EN == 1'b1) && (TX_SHIFT_EN1 == 1'b0)))) begin
      TX_BAUD <= PRELOAD;
      TX_BCLK <= 1'b0;
    end
  end
  //==========================================
  // Transmit Clock Enable
  //==========================================
  always @(TX_BCLK, TX_BCLK_DLY) begin
    if(((TX_BCLK == 1'b0) && (TX_BCLK_DLY == 1'b1))) begin
      // center TX clock in the middle of the data
      // at the falling edge of TX_BCLK
      TX_CLK_EN <= 1'b1;
    end
    else begin
      TX_CLK_EN <= 1'b0;
    end
  end
  //==========================================
  // Transmit Parity Generation
  //==========================================
  always @(negedge FCLK) begin
    if((TX_STATE == IDLE)) begin
      // for odd  parity init TX_PARITY to 1
      // for even parity init TX_PARITY to 0
      TX_PARITY <= PARITY_MODE[0];
    end
    if(((TX_CLK_EN == 1'b1) && (TX_STATE == SHIFT))) begin
      // calculate parity during shift
      TX_PARITY <= TX_PARITY ^ TX_SHIFT_REG[0];
    end
  end
  //==========================================
  // Transmit Shift Register
  //==========================================
  always @(negedge FCLK) begin
    TX_SHIFT_LD <= 1'b0;
    // load from the hold register
    if((TX_SHIFT_EN == 1'b1 && TX_SHIFT_EN1 == 1'b0)) begin
      TX_SHIFT_REG <= TX_FIFO_DATA;
      TX_SHIFT_LD <= 1'b1;
    end
    // shift
    if(((TX_CLK_EN == 1'b1) && (TX_STATE == SHIFT))) begin
      TX_SHIFT_REG <= {1'b1,TX_SHIFT_REG[7:1]};
    end
    // reset state
    if((RESET == 1'b1)) begin
      TX_SHIFT_REG <= {8{1'b0}};
    end
  end
  //==========================================
  // Transmit Data
  //==========================================
  always @(negedge FCLK) begin
    if((TX_CLK_EN == 1'b1)) begin
      TXDI <= 1'b1;
      // mark bit
      if((TX_STATE == LOAD)) begin
        TXDI <= 1'b0;
        // start bit
      end
      if((TX_STATE == SHIFT)) begin
        TXDI <= TX_SHIFT_REG[0];
        // data bit
      end
      if((TX_NSTATE == PRTY)) begin
        TXDI <= TX_PARITY;
        // parity bit
      end
    end
    // reset state
    if((RESET == 1'b1)) begin
      TXDI <= 1'b1;
    end
  end
  //================================================
  // Receiver shift enable
  //================================================
  always @(negedge FCLK) begin
    // RX_SHIFT_EN is active if the start bit is OK
    // and the shift register is not full.
    // It is only hi during data bits
    if(((RX_STATE == IDLE) && (RX_START == 1'b1) && (RX_FIFO_STOP == 1'b0))) begin
      RX_SHIFT_EN <= 1'b1;
    end
    // clear the RX shift enable
    if(((RX_CLK_EN == 1'b1) && (RX_STATE == D7))) begin
      RX_SHIFT_EN <= 1'b0;
    end
    // reset state
    if(((RESET == 1'b1) || (RX_EN == 1'b0))) begin
      RX_SHIFT_EN <= 1'b0;
    end
  end
  //=============================================
  // Receiver baud-rate clock divider
  //=============================================
  always @(negedge FCLK) begin
    // delayed baud clock for edge detection
    RX_BCLK_DLY <= RX_BCLK;
    if(((RX_SHIFT_EN == 1'b1) || (RX_STATE != IDLE))) begin
      // count
      RX_BAUD <= {RX_BAUD[14:0], ~(RX_BAUD[2] ^ RX_BAUD[15])};
      // reload at terminal count
      if((RX_BAUD == CKDIV_TC)) begin
        RX_BAUD <= PRELOAD;
        RX_BCLK <=  ~RX_BCLK;
      end
    end
    // load the initial count on Reset or
    // when we start to receive a new frame
    if(((RESET == 1'b1) || (RX_START == 1'b1))) begin
      RX_BAUD <= PRELOAD;
      RX_BCLK <= 1'b0;
    end
  end
  //==========================================
  // Receiver Clock Enable
  //==========================================
  always @(negedge FCLK) begin
    if(((RX_BCLK_DLY == 1'b0) && (RX_BCLK == 1'b1))) begin
      // center RX clock in the middle of the data
      // at the rising edge of RX_BCLK
      RX_CLK_EN <= 1'b1;
    end
    else begin
      RX_CLK_EN <= 1'b0;
    end
  end
  //==========================================
  // Receive start of frame
  //==========================================
  always @(negedge FCLK) begin
    // find the falling edge of the start bit
    if(((RX_STATE == IDLE) && ((RXD_SYNC1 == 1'b0) && (RXD_SYNC == 1'b1)))) begin
      RX_START <= 1'b1;
    end
    else begin
      RX_START <= 1'b0;
    end
    // reset state
    if((RESET == 1'b1)) begin
      RX_START <= 1'b0;
    end
  end
  //================================================
  // Receiver shift counter
  //
  // 0) 000     3) 101     6) 100   <- TC
  // 1) 001     4) 011
  // 2) 010     5) 110
  //
  //================================================
  always @(negedge FCLK) begin
    if(((RX_STATE == SHIFT) && (RX_CLK_EN == 1'b1))) begin
      RX_COUNT <= {RX_COUNT[1:0], ~(RX_COUNT[0] ^ RX_COUNT[2])};
    end
    if((RX_STATE == IDLE)) begin
      RX_COUNT <= RX_INIT;
    end
  end
  //================================================
  // Receiver state machine
  //================================================
  always @(negedge FCLK) begin
    if((RX_CLK_EN == 1'b1)) begin
      RX_STATE <= RX_NSTATE;
    end
    // reset state
    if((RESET == 1'b1)) begin
      RX_STATE <= IDLE;
    end
  end
  //=============================================================
  // Receiver state machine next state logic
  //=============================================================
  always @(RX_STATE, RX_ACCEPT, RX_COUNT, PARITY_MODE) begin
    case(RX_STATE)
    IDLE : begin
      if((RX_ACCEPT == 1'b1)) begin
        RX_NSTATE <= SHIFT;
        // accept data
      end
      else begin
        RX_NSTATE <= IDLE;
        // wait
      end
    end
    SHIFT : begin
      if((RX_COUNT == RX_TC)) begin
        RX_NSTATE <= D7;
      end
      else begin
        RX_NSTATE <= SHIFT;
      end
    end
    D7 : begin
      if((PARITY_MODE == NONE)) begin
        RX_NSTATE <= STOP;
        // skip parity
      end
      else begin
        RX_NSTATE <= PRTY;
        // get  parity
      end
    end
    PRTY : begin
      RX_NSTATE <= STOP;
    end
    STOP : begin
      RX_NSTATE <= IDLE;
    end
    default : begin
      RX_NSTATE <= IDLE;
    end
    endcase
  end
  //================================================
  // Receiver shift register accept data
  //================================================
  always @(negedge FCLK) begin
    // RX_ACCEPT goes hi if start bit is OK & there's room
    // It stays hi until the data has been received
    if(((RX_STATE == IDLE) && (RX_START == 1'b1) && (RX_FIFO_STOP == 1'b0))) begin
      RX_ACCEPT <= 1'b1;
    end
    if((RX_STATE == D7)) begin
      RX_ACCEPT <= 1'b0;
    end
    // reset state
    if(((RESET == 1'b1) || (RX_EN == 1'b0))) begin
      RX_ACCEPT <= 1'b0;
    end
  end
  //================================================
  // Receiver shift register
  //================================================
  always @(negedge FCLK) begin
    // synchronize the received data
    RXD_SYNC1 <= RXDI;
    RXD_SYNC <= RXD_SYNC1;
    // shift in the data
    if(((RX_CLK_EN == 1'b1) && (RX_SHIFT_EN == 1'b1))) begin
      RX_SHIFT_REG <= {RXD_SYNC,RX_SHIFT_REG[7:1]};
    end
  end
  //================================================
  // RX FIFO control
  //================================================
  always @(negedge FCLK) begin
    RX_FIFO_OP <= 1'b0;
    RX_FIFO_CKEN <= 1'b0;
    // push the RX FIFO when data received
    if(((RX_CLK_EN == 1'b1) && (RX_STATE == STOP))) begin
      RX_FIFO_OP <= 1'b1;
      RX_FIFO_CKEN <= 1'b1;
    end
    // RX FIFO on a uP read
    if((RDV == 1'b1)) begin
      if(((CS == 1'b1) && (REG_SEL == HOLD_ADDR))) begin
        RX_FIFO_OP <= 1'b0;
        RX_FIFO_CKEN <= 1'b1;
      end
    end
  end
  //================================================
  // Receiver parity generation
  //================================================
  always @(negedge FCLK) begin
    if(((RX_STATE == IDLE) && (RX_ACCEPT == 1'b0))) begin
      // for odd  parity init RX_PARITY to 1
      // for even parity init RX_PARITY to 0
      RX_PARITY <= PARITY_MODE[0];
    end
    else begin
      if((RX_CLK_EN == 1'b1)) begin
        // calculate parity during shift
        RX_PARITY <= RX_PARITY ^ RXD_SYNC;
      end
    end
  end
  //================================================
  // Receiver error flags
  //================================================
  always @(negedge FCLK) begin
      // PARITY_ERR is set when the calculated parity doesn't match
    // the received parity. It stays set until a character
    // without a parity error is received.
    // FRAMING_ERR is set if the stop bit=0. It stays set until
    // a character without a frame error is received.
    // OVERRUN_ERR set if a new start bit is seen but there's no room
    // for more data. It stays set until explicitly cleared.
    if((RX_CLK_EN == 1'b1)) begin
      // check for framing sync
      if((RX_STATE == STOP)) begin
        FRAMING_ERR <=  ~RXD_SYNC;
      end
      // check parity
      if(((RX_STATE == STOP) && (PARITY_MODE != NONE))) begin
        PARITY_ERR <= RX_PARITY;
      end
    end
    // check for FIFO overrun
    if(((RX_FIFO_STOP == 1'b1) && (RX_STATE == IDLE) && (RX_START == 1'b1))) begin
      OVERRUN_ERR <= 1'b1;
    end
    // Clear framing error
    if(((RX_EN == 1'b0) || (STATUS_CLR == 1'b1))) begin
      FRAMING_ERR <= 1'b0;
    end
    // Clear parity error
    if(((RX_EN == 1'b0) || (PARITY_MODE == NONE) || (STATUS_CLR == 1'b1))) begin
      PARITY_ERR <= 1'b0;
    end
    // Clear overrun error
    if(((RX_EN == 1'b0) || (STATUS_CLR == 1'b1))) begin
      OVERRUN_ERR <= 1'b0;
    end
  end
  //================================================
  // RX FIFO flags
  //================================================
  always @(negedge FCLK) begin
    // set overflow
    if((RX_FIFO_OVFL == 1'b1)) begin
      RX_FIFO_STOP <= 1'b1;
    end
    // reset state
    if(((RESET == 1'b1) || (STATUS_CLR == 1'b1))) begin
      RX_FIFO_STOP <= 1'b0;
    end
  end
  //============================================
  // Instantiate the RX FIFO
  //============================================
  FIFO RX_FIFO(
      .FIFO_OUT(RX_FIFO_DATA),
    .FIFO_IN(RX_SHIFT_REG),
    .OVFL(RX_FIFO_OVFL),
    .LAST(RX_FIFO_FULL),
    .EMPTY(RX_FIFO_EMPTY),
    .FIFO_OP(RX_FIFO_OP),
    .CKEN(RX_FIFO_CKEN),
    .CLK(FCLK),
    .RESET(RESET));
  //============================================
  // Instantiate the TX FIFO
  //============================================
  FIFO TX_FIFO(
      .FIFO_OUT(TX_FIFO_DATA),
    .FIFO_IN(WR_DATA[7:0]),
    .OVFL(TX_FIFO_OVFL),
    .LAST(TX_FIFO_FULL),
    .EMPTY(TX_FIFO_EMPTY),
    .FIFO_OP(TX_FIFO_OP),
    .CKEN(TX_FIFO_CKEN),
    .CLK(FCLK),
    .RESET(RESET));
endmodule

module contador_up_down_0_499(
input wire clk,
input wire reset,
input wire cnt_up,
input wire cnt_down,
output wire [8:0] contador
);
reg [8:0] temporal = 9'b000111011;
  always @(posedge clk, posedge reset, posedge cnt_up, posedge cnt_down) begin
    if((reset == 1'b1)) begin
      temporal <= 9'b000111011;
    end else begin
      if((cnt_up == 1'b1 && temporal < 499)) begin
        temporal <= temporal + 1;
      end
      else if((cnt_down == 1'b1 && temporal > 0)) begin
        temporal <= temporal - 1;
      end
    end
  end
  assign contador = temporal;
endmodule

module ssd(
input wire clk,
input wire reset,
input wire [15:0] input,
output wire [3:0] an_sel,
output reg [6:0] output
);
reg [3:0] cur;
reg [3:0] an_sel_s = 4'b1110;
  always @(cur) begin
    case(cur)
    4'h0 : begin
      output <= 7'b1000000;
    end
    4'h1 : begin
      output <= 7'b1111001;
    end
    4'h2 : begin
      output <= 7'b0100100;
    end
    4'h3 : begin
      output <= 7'b0110000;
    end
    4'h4 : begin
      output <= 7'b0011001;
    end
    4'h5 : begin
      output <= 7'b0010010;
    end
    4'h6 : begin
      output <= 7'b0000010;
    end
    4'h7 : begin
      output <= 7'b1111000;
    end
    4'h8 : begin
      output <= 7'b0000000;
    end
    4'h9 : begin
      output <= 7'b0010000;
    end
    4'hA : begin
      output <= 7'b0001000;
    end
    4'hB : begin
      output <= 7'b0000011;
    end
    4'hC : begin
      output <= 7'b1000110;
    end
    4'hD : begin
      output <= 7'b0100001;
    end
    4'hE : begin
      output <= 7'b0000110;
    end
    default : begin
      output <= 7'b0001110;
    end
    endcase
  end
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      an_sel_s <= 4'b1110;
    end else begin
      case(an_sel_s)
      4'b1110 : begin
        an_sel_s <= 4'b1101;
        cur <= input[7:4];
      end
      4'b1101 : begin
        an_sel_s <= 4'b1011;
        cur <= input[11:8];
      end
      4'b1011 : begin
        an_sel_s <= 4'b0111;
        cur <= input[15:12];
      end
      4'b0111 : begin
        an_sel_s <= 4'b1110;
        cur <= input[3:0];
      end
      default : begin
        an_sel_s <= 4'b1110;
        cur <= input[3:0];
      end
      endcase
    end
  end
  assign an_sel = reset == 1'b1 ? 4'b1111 : an_sel_s;
endmodule

module Gate_Xor(
input wire A,
input wire B,
output wire Q
);
  assign Q = A ^ B;
endmodule

module trigger(
input wire [31:0] la_input,
input wire la_inputReady,
input wire [31:0] data,
input wire clock,
input wire reset,
input wire [3:0] wrMask,
input wire [3:0] wrValue,
input wire [3:0] wrConfig,
input wire arm,
input wire demuxed,
output reg run,
input wire ExtTriggerIn
);
wire [3:0] stageMatch;
wire [4:0] stageRun;
reg [1:0] levelReg;
  //Connect ExtTriggerIn to the last stageRun
  //stageRun(4) <= ExtTriggerIn;	--Disable external trigger
  // create stages
  genvar i;
  generate for (i=0; i <= 3; i = i + 1) begin: stages
      stage Inst_stage(
          .la_input(la_input),
      .la_inputReady(la_inputReady),
      .data(data),
      .clock(clock),
      .reset(reset),
      .wrMask(wrMask[i]),
      .wrValue(wrValue[i]),
      .wrConfig(wrConfig[i]),
      .arm(arm),
      .level(levelReg),
      .demuxed(demuxed),
      .run(stageRun[i]),
      .match(stageMatch[i]));
  end
  endgenerate
  // increase level on match
  always @(posedge clock, posedge arm) begin : P2
    reg tmp;
    if(arm == 1'b1) begin
      levelReg <= 2'b00;
    end else begin
      tmp = stageMatch[0];
      for (i=1; i <= 3; i = i + 1) begin
        tmp = tmp | stageMatch[i];
      end
      if(tmp == 1'b1) begin
        levelReg <= levelReg + 1;
      end
    end
  end
  // if any of the stages set run, capturing starts
  always @(stageRun) begin : P1
    reg tmp;
    tmp = stageRun[0];
    for (i=1; i <= 4; i = i + 1) begin
      tmp = tmp | stageRun[i];
    end
    run <= tmp;
  end
endmodule

`timescale 1 ns / 1 ns
module ram_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
reg [0:0] WEA_R = 1'b0;
wire [9:0] ADDRA = 1'b0;
reg [9:0] ADDRA_R = 1'b0;
wire [7:0] DINA = 1'b0;
reg [7:0] DINA_R = 1'b0;
wire [7:0] DOUTA;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(8),
    .READ_WIDTH(8))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
