module dp_rsft64x64(
input wire [116:1] inbus,
input wire [6:1] shift,
output wire [116:1] outbus
);
wire [116:1] levzip; wire [116:1] levone; wire [116:1] levtwo; wire [116:1] levthr;
  assign levzip = inbus;
  // unsigned input
  genvar k;
  generate for (k=1; k <= 113; k = k + 1) begin: gla
      assign levone[k] = (levzip[k] &  ~(shift[2]) &  ~(shift[1])) | (levzip[k + 1] &  ~(shift[2]) & shift[1]) | (levzip[k + 2] & shift[2] &  ~(shift[1])) | (levzip[k + 3] & shift[2] & shift[1]);
  end
  endgenerate
  // 29/07/65 always shift 116, else will fill with zeros
  // fixed here and other lines
  assign levone[114] = (levzip[114] &  ~(shift[2]) &  ~(shift[1])) | (levzip[115] &  ~(shift[2]) & shift[1]) | (levzip[116] & shift[2] &  ~(shift[1])) | (levzip[116] & shift[2] & shift[1]);
  assign levone[115] = (levzip[115] &  ~(shift[2]) &  ~(shift[1])) | (levzip[116] &  ~(shift[2]) & shift[1]) | (levzip[116] & shift[2] &  ~(shift[1])) | (levzip[116] & shift[2] & shift[1]);
  assign levone[116] = levzip[116];
  genvar k;
  generate for (k=1; k <= 104; k = k + 1) begin: glba
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k + 4] &  ~(shift[4]) & shift[3]) | (levone[k + 8] & shift[4] &  ~(shift[3])) | (levone[k + 12] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=105; k <= 108; k = k + 1) begin: glbb
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k + 4] &  ~(shift[4]) & shift[3]) | (levone[k + 8] & shift[4] &  ~(shift[3])) | (levone[116] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=109; k <= 112; k = k + 1) begin: glbc
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k + 4] &  ~(shift[4]) & shift[3]) | (levone[116] & shift[4] &  ~(shift[3])) | (levone[116] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=113; k <= 116; k = k + 1) begin: glbd
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[116] & (shift[4] | shift[3]));
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 66; k = k + 1) begin: glca
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k + 16] &  ~(shift[6]) & shift[5]) | (levtwo[k + 32] & shift[6] &  ~(shift[5])) | (levtwo[k + 48] & shift[6] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=67; k <= 84; k = k + 1) begin: glcb
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k + 16] &  ~(shift[6]) & shift[5]) | (levtwo[k + 32] & shift[6] &  ~(shift[5])) | (levtwo[116] & shift[6] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=85; k <= 100; k = k + 1) begin: glcc
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k + 16] &  ~(shift[6]) & shift[5]) | (levtwo[116] & shift[6] &  ~(shift[5])) | (levtwo[116] & shift[6] & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=101; k <= 116; k = k + 1) begin: glcd
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[116] & (shift[6] | shift[5]));
  end
  endgenerate
  assign outbus = levthr;
endmodule

module CTRL(
input wire [5:0] OPCode,
output reg RegDst,
output reg Jump,
output reg Branch,
output reg MemRead,
output reg MemtoReg,
output reg [1:0] ALUOp,
output reg MemWrite,
output reg ALUSrc,
output reg RegWrite
);
  always @(OPCode) begin
    case(OPCode)
        //TYPE R
    6'b000000 : begin
      RegDst <= 1'b1;
      Jump <= 1'b0;
      ALUSrc <= 1'b0;
      MemtoReg <= 1'b0;
      RegWrite <= 1'b1;
      MemRead <= 1'b0;
      MemWrite <= 1'b0;
      Branch <= 1'b0;
      ALUOp[1] <= 1'b1;
      ALUOp[0] <= 1'b0;
      //TYPE LW						
    end
    6'b100011 : begin
      RegDst <= 1'b0;
      Jump <= 1'b0;
      ALUSrc <= 1'b1;
      MemtoReg <= 1'b1;
      RegWrite <= 1'b1;
      MemRead <= 1'b1;
      MemWrite <= 1'b0;
      Branch <= 1'b0;
      ALUOp[1] <= 1'b0;
      ALUOp[0] <= 1'b0;
      //TYPE SW					
    end
    6'b101011 : begin
      RegDst <= 1'b0;
      //X
      Jump <= 1'b0;
      ALUSrc <= 1'b1;
      MemtoReg <= 1'b0;
      //X
      RegWrite <= 1'b0;
      MemRead <= 1'b0;
      MemWrite <= 1'b1;
      Branch <= 1'b0;
      ALUOp[1] <= 1'b0;
      ALUOp[0] <= 1'b0;
      //TYPE JUMP
    end
    6'b000010 : begin
      RegDst <= 1'b0;
      //X
      Jump <= 1'b1;
      ALUSrc <= 1'b0;
      MemtoReg <= 1'b0;
      //X
      RegWrite <= 1'b0;
      MemRead <= 1'b0;
      MemWrite <= 1'b0;
      Branch <= 1'b0;
      ALUOp[1] <= 1'b1;
      ALUOp[0] <= 1'b0;
      //TYPE BEQ
      //TYPE BEQ
    end
    default : begin
      RegDst <= 1'b0;
      //X
      Jump <= 1'b0;
      ALUSrc <= 1'b0;
      MemtoReg <= 1'b0;
      //X
      RegWrite <= 1'b0;
      MemRead <= 1'b0;
      MemWrite <= 1'b0;
      Branch <= 1'b1;
      ALUOp[1] <= 1'b0;
      ALUOp[0] <= 1'b1;
    end
    endcase
  end
endmodule

