module Segment7Decoder(
input wire [3:0] bcd,
output reg [6:0] segment7
);
//BCD input
// 7 bit decoded output.
//'a' corresponds to MSB of segment7 and g corresponds to LSB of segment7.
  always @(bcd) begin
    case(bcd)
    4'b0000 : begin
      segment7 <= 7'b1000000;
      // '0'
    end
    4'b0001 : begin
      segment7 <= 7'b1111001;
      // '1'
    end
    4'b0010 : begin
      segment7 <= 7'b0100100;
      // '2'
    end
    4'b0011 : begin
      segment7 <= 7'b0110000;
      // '3'
    end
    4'b0100 : begin
      segment7 <= 7'b0011001;
      // '4' 
    end
    4'b0101 : begin
      segment7 <= 7'b0010010;
      // '5'
    end
    4'b0110 : begin
      segment7 <= 7'b0000010;
      // '6'
    end
    4'b0111 : begin
      segment7 <= 7'b1111000;
      // '7'
    end
    4'b1000 : begin
      segment7 <= 7'b0000000;
      // '8'
    end
    4'b1001 : begin
      segment7 <= 7'b0010000;
      // '9'
    end
    4'b1010 : begin
      segment7 <= 7'b0001000;
      //'A'
    end
    4'b1011 : begin
      segment7 <= 7'b0000011;
      //'b'
    end
    4'b1100 : begin
      segment7 <= 7'b0100111;
      //'c'
    end
    4'b1101 : begin
      segment7 <= 7'b0100001;
      //'d'
    end
    4'b1110 : begin
      segment7 <= 7'b0000110;
      //'E'
    end
    4'b1111 : begin
      segment7 <= 7'b0001110;
      //'f'
      //nothing is displayed when a number more than 9 is given as input. 
    end
    default : begin
      segment7 <= 7'b1111111;
    end
    endcase
  end
endmodule

module conv_8to16(
input wire clk_in,
input wire reset_in,
input wire [7:0] data8_in,
input wire valid8_in,
output reg ready8_out,
output reg [15:0] data16_out,
output reg valid16_out,
input wire ready16_in
);
// System clock
// 8-bit data coming in
// 16-bit data going out
parameter [0:0]
  S_WAIT_MSB = 0,
  S_WAIT_LSB = 1;
reg state = S_WAIT_MSB;
reg state_next;
reg [7:0] msb = 1'b0;
reg [7:0] msb_next;
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      state <= S_WAIT_MSB;
      msb <= {8{1'b0}};
    end
    else begin
      state <= state_next;
      msb <= msb_next;
    end
  end
  // Next state logic
  //process(state, msb, data8_in, valid8_in)
  always @(state, msb, data8_in, valid8_in, ready16_in) begin
    state_next <= state;
    msb_next <= msb;
    valid16_out <= 1'b0;
    case(state)
        // Wait for the LSB to arrive:
    S_WAIT_LSB : begin
      ready8_out <= ready16_in;
      // ready for data from 8-bit side
      data16_out <= {msb,data8_in};
      if((valid8_in == 1'b1 && ready16_in == 1'b1)) begin
        valid16_out <= 1'b1;
        state_next <= S_WAIT_MSB;
      end
      // Wait for the MSB to arrive:
    end
    default : begin
      ready8_out <= 1'b1;
      // ready for data from 8-bit side
      data16_out <= {16{1'bX}};
      if((valid8_in == 1'b1)) begin
        msb_next <= data8_in;
        state_next <= S_WAIT_LSB;
      end
    end
    endcase
  end
endmodule

