module u64test_remote(
input wire arst,
input wire [2:0] BUTTON,
input wire PHI2,
input wire DOTCLK,
input wire IO1n,
input wire IO2n,
input wire ROMLn,
input wire ROMHn,
input wire BA,
input wire RWn,
output wire GAMEn,
output wire EXROMn,
output wire DMAn,
inout wire IRQn,
inout wire NMIn,
input wire RESETn,
inout reg [7:0] D,
inout reg [15:0] A,
output wire LED_MOTORn,
output wire LED_DISKn,
output wire LED_CARTn,
output wire LED_SDACTn,
inout wire IEC_SRQ,
inout wire IEC_RST,
inout wire IEC_CLK,
inout wire IEC_DATA,
inout wire IEC_ATN,
input wire CAS_READ,
input wire CAS_WRITE,
input wire CAS_MOTOR,
input wire CAS_SENSE
);
wire clock;
reg addr_en;
reg [7:0] ram_address;
wire ram_en;
wire ram_we;
reg [7:0] ram_wdata;
wire [7:0] ram_rdata;
reg [4:0] iec_out;
reg [15:0] addr_out;
reg [7:0] cart_out;
reg [7:0] reg_out;
reg [3:0] led_out;
wire [7:0] cart_in = 8'h00;
wire [7:0] iec_in = 8'h00;
wire [7:0] cas_in = 8'h00;
reg phi2_d = 1'b1;
reg io2n_d = 1'b1;
reg rwn_d = 1'b1;
  assign clock =  ~PHI2;
  always @(posedge clock, posedge arst) begin : P1
    reg [2:0] v_addr;
    if(arst == 1'b1) begin
      addr_en <= 1'b0;
      iec_out <= {5{1'b0}};
      addr_out <= {16{1'b0}};
      cart_out <= {8{1'b0}};
      led_out <= {4{1'b0}};
    end else begin
      if(RWn == 1'b0 && IO1n == 1'b0) begin
        v_addr = A[2:0];
        case(v_addr)
        3'b000 : begin
          cart_out <= D[7:0];
        end
        3'b010 : begin
          addr_out[15:8] <= D;
        end
        3'b011 : begin
          addr_out[7:0] <= D;
        end
        3'b100 : begin
          iec_out <= D[4:0];
        end
        3'b110 : begin
          if(D == 8'hB9) begin
            addr_en <= 1'b1;
          end
        end
        3'b111 : begin
          led_out <= D[3:0];
        end
        default : begin
        end
        endcase
      end
    end
  end
  spram #(
      .g_width_bits(8),
    .g_depth_bits(8))
  i_ram(
      .clock(DOTCLK),
    .address(ram_address),
    .rdata(ram_rdata),
    .wdata(ram_wdata),
    .en(ram_en),
    .we(ram_we));
  assign ram_en = 1'b1;
  always @(posedge DOTCLK) begin
    ram_address <= A[7:0];
    phi2_d <= PHI2;
    io2n_d <= IO2n;
    rwn_d <= RWn;
    ram_wdata <= D;
  end
  assign ram_we = phi2_d == 1'b1 && PHI2 == 1'b0 && io2n_d == 1'b0 && rwn_d == 1'b0 ? 1'b1 : 1'b0;
  always @(*) begin
    case(A[2:0])
      3'b000 : reg_out <= cart_out;
      3'b001 : reg_out <= cart_in;
      3'b010 : reg_out <= A[15:8];
      3'b011 : reg_out <= A[7:0];
  // lower 3 bits will always read as "011"
      3'b100 : reg_out <= iec_in;
      3'b101 : reg_out <= cas_in;
      default : reg_out <= 8'h99;
    endcase
  end
  always @(IO1n, IO2n, RWn, reg_out, ram_rdata) begin
    D <= {8{1'bZ}};
    if(RWn == 1'b1) begin
      // read cycle
      if(IO1n == 1'b0) begin
        D <= reg_out;
      end
      else if(IO2n == 1'b0) begin
        D <= ram_rdata;
      end
    end
  end
  always @(addr_en, BA, addr_out) begin
    A <= {16{1'bZ}};
    if(addr_en == 1'b1 && BA == 1'b1) begin
      A <= addr_out;
    end
  end
  // IEC pins
  assign IEC_ATN = iec_out[0] == 1'b1 ? 1'b0 : 1'bZ;
  assign IEC_CLK = iec_out[1] == 1'b1 ? 1'b0 : 1'bZ;
  assign IEC_DATA = iec_out[2] == 1'b1 ? 1'b0 : 1'bZ;
  assign IEC_SRQ = iec_out[3] == 1'b1 ? 1'b0 : 1'bZ;
  assign IEC_RST = iec_out[4] == 1'b1 ? 1'b0 : 1'bZ;
  assign iec_in = {3'b000,IEC_RST,IEC_SRQ,IEC_DATA,IEC_CLK,IEC_ATN};
  // CAS pins
  assign cas_in = {4'b0000,CAS_SENSE,CAS_WRITE,CAS_READ,CAS_MOTOR};
  // CART pins
  assign cart_in[0] = IRQn;
  assign cart_in[1] = NMIn;
  assign cart_in[2] = ROMLn;
  assign cart_in[3] = ROMHn;
  assign cart_in[4] = DOTCLK;
  assign cart_in[5] = RESETn;
  assign cart_in[6] = BA;
  assign IRQn = cart_out[0] == 1'b1 || button[2] == 1'b0 ? 1'b0 : 1'bZ;
  assign NMIn = cart_out[1] == 1'b1 || button[1] == 1'b0 ? 1'b0 : 1'bZ;
  assign GAMEn = cart_out[2] == 1'b1 ? 1'b0 : 1'bZ;
  assign EXROMn = cart_out[3] == 1'b1 ? 1'b0 : 1'bZ;
  assign DMAn = cart_out[4] == 1'b1 ? 1'b0 : 1'bZ;
  // RESETn     <= '0' when cart_out(5) <= '1' else 'Z';
  assign LED_MOTORn =  ~led_out[0];
  assign LED_DISKn =  ~led_out[1];
  assign LED_CARTn =  ~led_out[2];
  assign LED_SDACTn =  ~led_out[3];
endmodule

module alu8bit(
input wire [31:0] a,
input wire [31:0] b,
input wire [1:0] op,
output reg zero,
output reg bigthan,
output wire [31:0] result
);
wire [31:0] temp;
  assign temp = op == 2'b00 ? a & b : op == 2'b01 ? a | b : op == 2'b10 ? a + b : op == 2'b11 ? a - b : {32{1'b0}};
  assign result = temp;
  always @(op, temp) begin
    if((op == 2'b11 && temp == 0)) begin
      zero <= 1'b1;
      bigthan <= 1'b0;
    end
    else if((op == 2'b11 && temp > 0)) begin
      zero <= 1'b0;
      bigthan <= 1'b1;
    end
    else begin
      zero <= 1'b0;
      bigthan <= 1'b0;
    end
  end
endmodule

module convertidor_piso_actual(
