module re_control(
input wire c_clk,
input wire c_rst,
input wire cpu_rd,
input wire cpu_sc,
input wire cpu_pa,
output reg ready,
output reg rd_enable,
output reg [2:0] mux_enable,
output reg rd_strobe
);
parameter [3:0]
  idle = 0,
  hold = 1,
  hold1 = 2,
  read0 = 3,
  read1 = 4,
  read2 = 5,
  read3 = 6,
  read4 = 7,
  finish = 8;
reg [3:0] nState; reg [3:0] cState;
  always @(posedge c_clk, posedge c_rst) begin
    if((c_rst == 1'b1)) begin
      cState <= idle;
    end else begin
      cState <= nState;
    end
  end
  always @(cState, cpu_pa, cpu_sc, cpu_rd) begin : P1
  //, parity, c_cpu_sc
    case(cState)
    idle : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      if(((cpu_sc == 1'b1) && (cpu_pa == 1'b1))) begin
        nState <= hold;
      end
      else begin
        nState <= idle;
      end
    end
    hold : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      if((cpu_rd == 1'b1)) begin
        nState <= hold1;
      end
      else begin
        nState <= idle;
      end
    end
    hold1 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b0;
      ready <= 1'b1;
      mux_enable <= 3'b000;
      nState <= read0;
    end
    read0 : begin
      rd_enable <= 1'b1;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b000;
      nState <= read1;
    end
    read1 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b001;
      nState <= read2;
    end
    read2 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b010;
      nState <= read3;
    end
    read3 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b011;
      nState <= read4;
    end
    read4 : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b1;
      mux_enable <= 3'b100;
      nState <= finish;
    end
    finish : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      nState <= idle;
    end
    default : begin
      rd_enable <= 1'b0;
      rd_strobe <= 1'b1;
      ready <= 1'b0;
      mux_enable <= 3'b000;
      nState <= idle;
    end
    endcase
  end
endmodule

