module rotary(
input wire clk,
input wire rot_a,
input wire rot_b,
output reg up,
output reg down
);
reg rotary_a_in;
reg rotary_b_in;
reg [1:0] rotary_in;
reg rotary_q1;
reg rotary_q2;
reg delay_rotary_q1;
reg rotary_event;
reg rotary_left;
wire qa0; wire qa1; wire qa2; wire qb0; wire qb1; wire qb2;
  always @(posedge clk) begin
    rotary_a_in <= rot_a;
    rotary_b_in <= rot_b;
    rotary_in <= {rotary_b_in,rotary_a_in};
    case(rotary_in)
    2'b00 : begin
      rotary_q1 <= 1'b0;
      rotary_q2 <= rotary_q2;
    end
    2'b01 : begin
      rotary_q1 <= rotary_q1;
      rotary_q2 <= 1'b0;
    end
    2'b10 : begin
      rotary_q1 <= rotary_q1;
      rotary_q2 <= 1'b1;
    end
    2'b11 : begin
      rotary_q1 <= 1'b1;
      rotary_q2 <= rotary_q2;
    end
    default : begin
      rotary_q1 <= rotary_q1;
      rotary_q2 <= rotary_q2;
    end
    endcase
  end
  always @(posedge clk) begin
    delay_rotary_q1 <= rotary_q1;
    if(rotary_q1 == 1'b1 && delay_rotary_q1 == 1'b0) begin
      rotary_event <= 1'b1;
      rotary_left <= rotary_q2;
    end
    else begin
      rotary_event <= 1'b0;
      rotary_left <= rotary_left;
    end
  end
  always @(posedge clk) begin
    if(rotary_event == 1'b1 && rotary_left == 1'b1) begin
      up <= 1'b0;
      down <= 1'b1;
    end
    else if(rotary_event == 1'b1 && rotary_left == 1'b0) begin
      up <= 1'b1;
      down <= 1'b0;
    end
    else begin
      up <= 1'b0;
      down <= 1'b0;
    end
  end
endmodule

