module roadWarrior(
input wire clk,
input wire avance,
input wire reset,
output reg [6:0] memoria,
output reg registro
);
reg [2:0] contadorRegistro = 1'b0;
reg [6:0] contadorCuadros = 1'b0;
reg [6:0] contadorMemoria = 1'b0;
  // Proceso memoria
  always @(posedge clk, posedge avance, posedge reset, posedge contadorRegistro, posedge contadorCuadros, posedge contadorMemoria) begin
    if(reset == 1'b1) begin
      contadorCuadros <= 7'b0000000;
      contadorMemoria <= 7'b0000000;
      contadorRegistro <= 3'b000;
      memoria <= 7'b0000000;
      registro <= 1'b0;
    end else begin
      // Proceso para el registro y la memoria
      case(contadorRegistro)
      3'b000 : begin
        registro <= 1'b1;
        contadorMemoria <= contadorCuadros;
      end
      default : begin
        registro <= 1'b0;
        contadorMemoria <= contadorMemoria + 1;
      end
      endcase
      contadorRegistro <= contadorRegistro + 1;
      memoria <= contadorMemoria;
      // Proceso para el avance del escenario
      if(avance == 1'b1) begin
        contadorCuadros <= contadorCuadros + 1;
      end
    end
  end
endmodule

module dsp(
