input wire reverb_delayed_valid,
input wire [15:0] reverb_delayed_data,
input wire loopBuffer_out_valid,
input wire [15:0] loopBuffer_out,
output wire [31:0] tuner_readdata
);
//select signals
//left channel audio
//--left channel audio in (valid signal)
// right channel audio
// right channel audio in (valid signal)
//left channel audio out
//left channel audio out (valid signal)
//right channel audio out
//right channel audio out (valid signal)
// Valid signal for sdram input. Used for reverb
// sdram input. Used for reverb.
//Valid signal  for sdram output. Used for reverb. 
//output from sdram. Used for reverb
//Valid signal for  delayed audio from sdram. Used for reverb
//delayed audio from sdram. Used for reverb
//loopBuffer_in_valid	: out  std_logic;
//loopBuffer_in		: out  std_logic_vector(15 downto 0);
//guitar tuner data
wire [1:0] dist_completed;
wire dist_en;
wire reverb_en;
wire tuner_en;
wire out_valid;
wire [15:0] distortion; wire [15:0] reverb; wire [15:0] outgoing; wire [15:0] placeholder; wire [15:0] current; wire [15:0] prev; wire [15:0] audio_loop;
wire [17:0] mult_result;
parameter multiplier = 2'b11;
wire [15:0] decayed_signal;
wire [15:0] reverb_int;
  assign out_valid = dist_completed[0] | (reverb_source_valid & reverb_delayed_valid) | loopBuffer_out_valid;
  //Reverb start
  assign mult_result = (multiplier) * (reverb_delayed_data);
  // 18 bits
  assign decayed_signal = mult_result[15:0];
  assign reverb_int = (reverb_source_data) + ({decayed_signal[15],decayed_signal[15:2]});
  assign reverb = reverb_int;
  assign reverb_sink_data = (reverb_int) + (incoming_data_left);
  assign reverb_sink_valid = incoming_valid_left;
  //Reverb end
