  //std_logic_vector(signed(loopBuffer_out)+signed(incoming_data_left));
  //Loop Back End
  //Output signals
  assign outgoing_data_left = outgoing;
  assign outgoing_valid_left = out_valid;
  assign outgoing_valid_right = incoming_valid_right;
  assign outgoing_data_right = incoming_data_right;
  MUX5X1 MUX(
      .clk(clk),
    .distortion(distortion),
    .reverb(reverb),
    .AUDIO_IN(incoming_data_left[15:0]),
    .audio_loop(audio_loop),
    .OUTPUT(outgoing),
    .SEL(enable[4:0]));
  distort d1(
      .clk(clk),
    .reset(reset_n),
    .dist_en(enable[0]),
    .ready(incoming_valid_left),
    .done(dist_completed[0]),
    .data_in(incoming_data_left[15:0]),
    .clipping_write(clipping_write),
    .clipping_read(clipping_read),
    .clipping_value(clipping_value),
    .clipping_readdata(clipping_readdata),
    .data_out(distortion[15:0]));
  tuner t0(
      .clk(clk),
    .reset(reset_n),
    .tuner_en(enable[2]),
    .tuner_in(outgoing[15]),
    .tuner_data(outgoing),
    .tuner_data_available(out_valid),
    .tuner_out(tuner_readdata));
