module booth4(
input wire [15:0] a,
input wire [2:0] d,
output reg [16:0] m
);
// Signals for two's complement
wire [15:0] ai;
wire [15:0] an;
  // Two's complement of a,
  // assuming that of course compiler takes care of 
  // getting rid of duplicate two's complement circuits
  assign ai =  ~a;
  cla #(
      .N(16))
  cla_stage(
      .a(ai),
    .b(16'b0000000000000001),
    .ci(1'b0),
    .s(an));
  // Dummy lookup table
  always @(*) begin
    case(d)
      3'b001 : m <= {a[15],a};
  // Sign expanded addition
      3'b010 : m <= {a[15],a};
  // Same as previous
      3'b011 : m <= {a,1'b0};
  // Add double
      3'b100 : m <= {an,1'b0};
  // Subtract double
      3'b101 : m <= {an[15],an};
  // Sign expanded subtraction
      3'b110 : m <= {an[15],an};
      default : m <= 17'b00000000000000000;
    endcase
  end
endmodule

module uartrx(
input wire reset,
input wire clk,
input wire rx,
output wire [N - 1:0] data,
output reg rdy,
output reg err
);
parameter [31:0] N=8;
// Reset the UART.
// Baud clock.
// Serial data input.
// Parallel data output.
// New data ready.
// Error occurred.
// Shift register for loading new data from the serial line.
reg [N - 1:0] shftrx;  // Buffer for outputting the received data.
reg [N - 1:0] outbuf;  // Counter for indicating the number of bits received. There is 1 start bit,
// N data bits, and 1 stop bit for a total of N+2 bits.
reg [31:0] state;
  // Always output the buffered data.
  assign data = outbuf;
  //
  // LoadNextBit
  //
  // On each clock edge, this process will shift a new bit into the shift
  // register. Once the character is full, it will pulse the 'rdy' signal low
  // and output the data. It will then wait for the next start bit to begin
  // receiving again.
  //
  // If the stop bit is found to be '0' instead of '1', then the 'err' signal
  // will be pulsed low instead of 'rdy'.
  //
  always @(posedge clk) begin
    // By default, data is not ready and no error has occurred.
    rdy <= 1'b1;
    err <= 1'b1;
    // By default, latch the output buffer and shift register.
    outbuf <= outbuf;
    shftrx <= shftrx;
    // First, check for reset conditions.
    if((reset == 1'b0)) begin
      // When resetting, we set the counter back to zero to wait for
      // the next start bit.
      state <= 0;
      // If no bits loaded, wait for start bit.
    end
    else if((state == 0)) begin
      if((rx == 1'b0)) begin
        // Start bit received, begin shifting in data.
        state <= 1;
      end
      else begin
        // Otherwise, continue waiting.
        state <= 0;
      end
      // All data has been received.
    end
    else if((state == (N + 1))) begin
      // Reset counter regardless of data validity.
      state <= 0;
      // Always output the shifted data, even if it is found to be
      // invalid.
      outbuf <= shftrx;
      // Check for a valid stop bit.
      if((rx == 1'b1)) begin
        // Stop bit is valid; indicate data is ready.
        rdy <= 1'b0;
      end
      else begin
        // Stop bit invalid; indicate an error occurred.
        err <= 1'b0;
      end
      // Still just shifting in the data.
    end
    else begin
      // Shift the new data bit into the LSB of the shift register.
      shftrx <= {shftrx[N - 2:0],rx};
      // Go to next state.
      state <= state + 1;
    end
  end
endmodule

module mod_7segments(
input wire clk_8KHz,
input wire reset,
input wire [3:0] dig0,
input wire [3:0] dig1,
input wire [3:0] dig2,
input wire [3:0] dig3,
input wire [3:0] dig4,
input wire [3:0] dig5,
input wire [3:0] dig6,
input wire [3:0] dig7,
input wire [7:0] g,
output reg [7:0] an,
output reg [6:0] segments
);
// Entrada clk 8 KHZ, reset
// Entrada digitos binario
// Entrada habilitar 7 segmentos
// Salida seleccion 7 segmentos
// Salida 7 segmentos
wire [6:0] seg0; wire [6:0] seg1; wire [6:0] seg2; wire [6:0] seg3; wire [6:0] seg4; wire [6:0] seg5; wire [6:0] seg6; wire [6:0] seg7;
reg [2:0] estado; reg [2:0] estado_sig;
  mod_bcd bcd0(
      .bcd(dig0),
    .g(g[0]),
    .segment7(seg0));
  mod_bcd bcd1(
      .bcd(dig1),
    .g(g[1]),
    .segment7(seg1));
  mod_bcd bcd2(
      .bcd(dig2),
    .g(g[2]),
    .segment7(seg2));
  mod_bcd bcd3(
      .bcd(dig3),
    .g(g[3]),
    .segment7(seg3));
  mod_bcd bcd4(
      .bcd(dig4),
    .g(g[4]),
    .segment7(seg4));
  mod_bcd bcd5(
      .bcd(dig5),
    .g(g[5]),
    .segment7(seg5));
  mod_bcd bcd6(
      .bcd(dig6),
    .g(g[6]),
    .segment7(seg6));
  mod_bcd bcd7(
      .bcd(dig7),
    .g(g[7]),
    .segment7(seg7));
  always @(posedge clk, posedge reset, posedge seg1, posedge seg2, posedge seg3, posedge seg4) begin
    if(reset == 1'b0) begin
      segments <= 7'b0111111;
      an <= 8'b00000000;
      estado <= 3'b000;
      estado_sig <= 3'b000;
    end else begin
      estado <= estado_sig;
      case(estado)
      3'b000 : begin
        estado_sig <= 3'b001;
        an <= 8'b11111110;
        segments <= seg0;
      end
      3'b001 : begin
        estado_sig <= 3'b010;
        an <= 8'b11111101;
        segments <= seg1;
      end
      3'b010 : begin
        estado_sig <= 3'b011;
        an <= 8'b11111011;
        segments <= seg2;
      end
      3'b011 : begin
        estado_sig <= 3'b100;
        an <= 8'b11110111;
        segments <= seg3;
      end
      3'b100 : begin
        estado_sig <= 3'b101;
        an <= 8'b11101111;
        segments <= seg4;
      end
      3'b101 : begin
        estado_sig <= 3'b110;
        an <= 8'b11011111;
        segments <= seg5;
      end
      3'b110 : begin
        estado_sig <= 3'b111;
        an <= 8'b10111111;
        segments <= seg6;
      end
      3'b111 : begin
        estado_sig <= 3'b000;
        an <= 8'b01111111;
        segments <= seg7;
      end
      default : begin
        estado_sig <= 3'b000;
        an <= 8'b00000000;
        segments <= 7'b0111111;
      end
      endcase
    end
  end
endmodule

