module zpuino_serialreset(
input wire clk,
input wire rx,
input wire rstin,
output wire rstout
);
parameter [31:0] SYSTEM_CLOCK_MHZ=100;
parameter rstcount_val = ((SYSTEM_CLOCK_MHZ * 1000000) / 300) * 8;
reg [31:0] rstcount;
reg rstcount_zero_q;
  assign rstout = rstin == 1'b1 || rstcount_zero_q == 1'b1 ? 1'b1 : 1'b0;
  always @(posedge clk) begin
    if(rstin == 1'b1) begin
      rstcount <= rstcount_val;
      rstcount_zero_q <= 1'b0;
    end
    else begin
      if(rx == 1'b1) begin
        rstcount <= rstcount_val;
      end
      else begin
        if(rstcount != 0) begin
          rstcount <= rstcount - 1;
          rstcount_zero_q <= 1'b0;
        end
        else begin
          rstcount_zero_q <= 1'b1;
        end
      end
    end
  end
endmodule

module dp_fabs(
input wire sysclk,
input wire reset,
input wire enable,
input wire signin,
input wire [11:1] exponentin,
input wire [52:1] mantissain,
output wire signout,
output wire [11:1] exponentout,
output wire [52:1] mantissaout,
output wire satout,
output wire zeroout,
output wire nanout
);
reg signff;
reg [11:1] exponentff;
reg [52:1] mantissaff;
wire [11:1] expnode;
wire [11:1] expzerochk; wire [11:1] expmaxchk;
wire expzero; wire expmax;
wire [52:1] manzerochk;
wire manzero; wire mannonzero;
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      signff <= 1'b0;
      for (k=1; k <= 11; k = k + 1) begin
        exponentff[k] <= 1'b0;
      end
      for (k=1; k <= 52; k = k + 1) begin
        mantissaff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        signff <= 1'b0;
        exponentff <= exponentin;
        mantissaff <= mantissain;
      end
    end
  end
  assign expzerochk[1] = exponentff[1];
  assign expmaxchk[1] = exponentff[1];
  genvar k;
  generate for (k=2; k <= 11; k = k + 1) begin: gxa
      assign expzerochk[k] = expzerochk[k - 1] | exponentff[k];
    assign expmaxchk[k] = expmaxchk[k - 1] & exponentff[k];
  end
  endgenerate
  assign expzero =  ~(expzerochk[11]);
  assign expmax = expmaxchk[11];
  assign manzerochk[1] = mantissaff[1];
  genvar k;
  generate for (k=2; k <= 52; k = k + 1) begin: gma
      assign manzerochk[k] = manzerochk[k - 1] | mantissaff[k];
  end
  endgenerate
  assign manzero =  ~(manzerochk[52]);
  assign mannonzero = manzerochk[52];
  assign signout = signff;
  assign exponentout = exponentff;
  assign mantissaout = mantissaff;
  assign satout = expmax & manzero;
  assign zeroout = expzero;
  assign nanout = expmax & mannonzero;
endmodule

module deserializer(
input wire rclr_n,
input wire rclk,
input wire srclr_n,
input wire srclk,
input wire ser,
output wire [7:0] q,
output wire qh
);
//-------------------------------------------------------------------------
//-------------------------------------------------------------------------
wire [7:0] qint_n;
wire [7:0] qint;
wire srclr;
wire rclr;
  assign srclr =  ~srclr_n;
  assign rclr =  ~rclr_n;
  // bascule d
  bascule_d bascule_d_connect(
      .d(ser),
    .clk(srclk),
    .r(srclr),
    .q(qint[0]),
    .q_n(qint_n[0]));
  // generate bascule rs input
  genvar j;
  generate for (j=1; j <= 7; j = j + 1) begin: d_g
      bascule_rs rs_p2(
          .r1(qint_n[j - 1]),
      .r2(srclr),
      .clk(srclk),
      .s(qint[j - 1]),
      .q(qint[j]),
      .q_n(qint_n[j]));
  end
  endgenerate
  // generate bascule rs output
  genvar i;
  generate for (i=0; i <= 7; i = i + 1) begin: rs_out
      bascule_rs rs_p(
          .r1(rclr),
      .r2(qint_n[i]),
      .clk(rclk),
      .s(qint[i]),
      .q(q[i]),
      .q_n(/* open */));
  end
  endgenerate
endmodule

module part1(
input wire [3:0] SW,
output wire [6:0] LEDSEG,
output wire ENABLE
);
// (3)=A, (2)=B, (1)=C, (0)=D
// segments of our displays
  assign ENABLE = 1'b0;
  // SEG A : F0 = A B C D' + B' C D + A' C'  + A' B' ;
  assign LEDSEG[0] = (SW[3] & SW[2] & SW[1] &  ~SW[0]) | ( ~SW[2] & SW[1] & SW[0]) | ( ~SW[3] &  ~SW[1]) | ( ~SW[3] &  ~SW[2]);
  // SEG B : F1 = B' C D' + A' C'  + B' C' D + A' B' ;
  assign LEDSEG[1] = ( ~SW[2] & SW[1] &  ~SW[0]) | ( ~SW[3] &  ~SW[1]) | ( ~SW[2] &  ~SW[1] & SW[0]) | ( ~SW[3] &  ~SW[2]);
  // SEG C : F2 = B C' D + A' B'  + A' C' ;
  assign LEDSEG[2] = (SW[2] &  ~SW[1] & SW[0]) | ( ~SW[3] &  ~SW[2]) | ( ~SW[3] &  ~SW[1]);
  // SEG D : F3 = A' D' + B C D' + B' C D + B' C' D' + A' C' ;
  assign LEDSEG[3] = ( ~SW[3] &  ~SW[0]) | (SW[2] & SW[1] &  ~SW[0]) | ( ~SW[2] & SW[1] & SW[0]) | ( ~SW[2] &  ~SW[1] &  ~SW[0]) | ( ~SW[3] &  ~SW[1]);
  // SEG E : F4 = A' C'  + B' C  + D';
  assign LEDSEG[4] = ( ~SW[3] &  ~SW[1]) | ( ~SW[2] & SW[1]) | ( ~SW[0]);
  // SEG F : F5 = A B D' + A' B'  + B C'  + C' D';
  assign LEDSEG[5] = (SW[3] & SW[2] &  ~SW[0]) | ( ~SW[3] &  ~SW[2]) | (SW[2] &  ~SW[1]) | ( ~SW[1] &  ~SW[0]);
  // SED G : A B C  + B' C' D' + A' C'  + A' B' ;
  assign LEDSEG[6] = (SW[3] & SW[2] & SW[1]) | ( ~SW[2] &  ~SW[1] &  ~SW[0]) | ( ~SW[3] &  ~SW[1]) | ( ~SW[3] &  ~SW[2]);
endmodule

