module gh_fifo_async16_sr(
input wire clk_WR,
input wire clk_RD,
input wire rst,
input wire srst,
input wire WR,
input wire RD,
input wire [data_width - 1:0] D,
output wire [data_width - 1:0] Q,
output wire empty,
output wire full
);
parameter [31:0] data_width=8;
// size of data bus
// write clock
// read clock
// resets counters
// resets counters (sync with clk_WR)
// write control 
// read control
reg [data_width - 1:0] ram_mem[15:0];
wire iempty;
wire ifull;
wire add_WR_CE;
reg [4:0] add_WR;  // 4 bits are used to address MEM
reg [4:0] add_WR_GC;  // 5 bits are used to compare
wire [4:0] n_add_WR;  //   for empty, full flags
reg [4:0] add_WR_RS;  // synced to read clk
wire add_RD_CE;
reg [4:0] add_RD;
reg [4:0] add_RD_GC;
reg [4:0] add_RD_GCwc;
wire [4:0] n_add_RD;
reg [4:0] add_RD_WS;  // synced to write clk
reg srst_w;
reg isrst_w;
reg srst_r;
reg isrst_r;
  //------------------------------------------
  //----- memory -----------------------------
  //------------------------------------------
  always @(posedge clk_WR) begin
    if(((WR == 1'b1) && (ifull == 1'b0))) begin
      ram_mem[add_WR[3:0]] <= D;
    end
  end
  assign Q = ram_mem[add_RD[3:0]];
  //---------------------------------------
  //--- Write address counter -------------
  //---------------------------------------
  assign add_WR_CE = (ifull == 1'b1) ? 1'b0 : (WR == 1'b0) ? 1'b0 : 1'b1;
  assign n_add_WR = add_WR + 4'h1;
  always @(posedge clk_WR, posedge rst) begin
    if((rst == 1'b1)) begin
      add_WR <= {5{1'b0}};
      add_RD_WS <= 5'b11000;
      add_WR_GC <= {5{1'b0}};
    end else begin
      add_RD_WS <= add_RD_GCwc;
      if((srst_w == 1'b1)) begin
        add_WR <= {5{1'b0}};
        add_WR_GC <= {5{1'b0}};
      end
      else if((add_WR_CE == 1'b1)) begin
        add_WR <= n_add_WR;
        add_WR_GC[0] <= n_add_WR[0] ^ n_add_WR[1];
        add_WR_GC[1] <= n_add_WR[1] ^ n_add_WR[2];
        add_WR_GC[2] <= n_add_WR[2] ^ n_add_WR[3];
        add_WR_GC[3] <= n_add_WR[3] ^ n_add_WR[4];
        add_WR_GC[4] <= n_add_WR[4];
      end
      else begin
        add_WR <= add_WR;
        add_WR_GC <= add_WR_GC;
      end
    end
  end
  assign full = ifull;
  assign ifull = (iempty == 1'b1) ? 1'b0 : (add_RD_WS != add_WR_GC) ? 1'b0 : 1'b1;
  //---------------------------------------
  //--- Read address counter --------------
  //---------------------------------------
  assign add_RD_CE = (iempty == 1'b1) ? 1'b0 : (RD == 1'b0) ? 1'b0 : 1'b1;
  assign n_add_RD = add_RD + 4'h1;
  always @(posedge clk_RD, posedge rst) begin
    if((rst == 1'b1)) begin
      add_RD <= {5{1'b0}};
      add_WR_RS <= {5{1'b0}};
      add_RD_GC <= {5{1'b0}};
      add_RD_GCwc <= 5'b11000;
    end else begin
      add_WR_RS <= add_WR_GC;
      if((srst_r == 1'b1)) begin
        add_RD <= {5{1'b0}};
        add_RD_GC <= {5{1'b0}};
        add_RD_GCwc <= 5'b11000;
      end
      else if((add_RD_CE == 1'b1)) begin
        add_RD <= n_add_RD;
        add_RD_GC[0] <= n_add_RD[0] ^ n_add_RD[1];
        add_RD_GC[1] <= n_add_RD[1] ^ n_add_RD[2];
        add_RD_GC[2] <= n_add_RD[2] ^ n_add_RD[3];
        add_RD_GC[3] <= n_add_RD[3] ^ n_add_RD[4];
        add_RD_GC[4] <= n_add_RD[4];
        add_RD_GCwc[0] <= n_add_RD[0] ^ n_add_RD[1];
        add_RD_GCwc[1] <= n_add_RD[1] ^ n_add_RD[2];
        add_RD_GCwc[2] <= n_add_RD[2] ^ n_add_RD[3];
        add_RD_GCwc[3] <= n_add_RD[3] ^ ( ~n_add_RD[4]);
        add_RD_GCwc[4] <=  ~n_add_RD[4];
      end
      else begin
        add_RD <= add_RD;
        add_RD_GC <= add_RD_GC;
        add_RD_GCwc <= add_RD_GCwc;
      end
    end
  end
  assign empty = iempty;
  assign iempty = (add_WR_RS == add_RD_GC) ? 1'b1 : 1'b0;
  //--------------------------------
  //-	sync rest stuff --------------
  //- srst is sync with clk_WR -----
  //- srst_r is sync with clk_RD ---
  //--------------------------------
  always @(posedge clk_WR, posedge rst) begin
    if((rst == 1'b1)) begin
      srst_w <= 1'b0;
      isrst_r <= 1'b0;
    end else begin
      isrst_r <= srst_r;
      if((srst == 1'b1)) begin
        srst_w <= 1'b1;
      end
      else if((isrst_r == 1'b1)) begin
        srst_w <= 1'b0;
      end
    end
  end
  always @(posedge clk_RD, posedge rst) begin
    if((rst == 1'b1)) begin
      srst_r <= 1'b0;
      isrst_w <= 1'b0;
    end else begin
      isrst_w <= srst_w;
      if((isrst_w == 1'b1)) begin
        srst_r <= 1'b1;
      end
      else begin
        srst_r <= 1'b0;
      end
    end
  end
endmodule

module REGISTER_FDE(
input wire [N - 1:0] DIN,
input wire ENABLE,
input wire CLK,
input wire RESET,
output wire [N - 1:0] DOUT
);
parameter [31:0] N=1;
// Data in
// Enable
// Clock
// Reset
// Data out
// Architectures
wire [N - 1:0] INT_OUT;
  genvar i;
  generate for (i=0; i <= N - 1; i = i + 1) begin: REG_GEN_A
      FLIPFLOP ASYNC_REG(
          DIN[i],
      ENABLE,
      CLK,
      RESET,
      INT_OUT[i]);
  end
  endgenerate
  assign DOUT = INT_OUT;
endmodule

module top(
input wire clk,
input wire rst,
input wire [W - 1:0] i_data_a,
input wire [W - 1:0] i_data_b,
input wire i_data_carry,
input wire [3:0] i_ctrl,
output reg [W - 1:0] o_data_c,
output reg o_data_carry,
output reg [1:0] o_data_comp,
output wire o_valid
);
parameter [31:0] W=4;
// Width of data
// active high sync to clock
// input data A
// input data B
// carry in or borrow in
// control signals
// output data C
// carry out or borrow out
// output comparison
// valid output
// 1: FETCH
reg [3:0] reg_i_instr_1 = 1'b0;
reg [W - 1:0] reg_i_data_a_1 = 1'b0;
reg [W - 1:0] reg_i_data_b_1 = 1'b0;
reg reg_i_data_carry_1 = 1'b0;  // 2: DECODE
reg [3:0] reg_i_instr_2 = 1'b0;
reg [W - 1:0] reg_i_data_a_2 = 1'b0;
reg [W - 1:0] reg_i_data_b_2 = 1'b0;
reg reg_i_data_carry_2 = 1'b0;  // 3: Execute
reg [3:0] reg_i_instr_3 = 1'b0;
reg [W - 1:0] reg_i_data_a_3 = 1'b0;
reg [W - 1:0] reg_i_data_b_3 = 1'b0;
reg reg_i_data_carry_3 = 1'b0;  // Output signals of ALU
wire [W - 1:0] sig_data_c = 1'b0;
wire sig_data_carry = 1'b0;
wire [1:0] sig_data_comp = 1'b0;
wire sig_valid = 1'b0;
reg reg_valid = 1'b0;  // Declare component ALU
  // Instruction pipeline (1: FETCH, 2: DECODE, 3: EXECUTE)
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      // 1: FETCH
      reg_i_instr_1 <= {4{1'b0}};
      // NOP
      // 2: DECODE
      reg_i_instr_2 <= {4{1'b0}};
      // NOP
      // 2: DECODE
      reg_i_instr_3 <= {4{1'b0}};
      // NOP
    end
    else begin
      // 1: FETCH
      reg_i_instr_1 <= i_ctrl;
      // 2: DECODE
      reg_i_instr_2 <= reg_i_instr_1;
      // 3: Execute
      reg_i_instr_3 <= reg_i_instr_2;
    end
  end
  // Operand pipeline (1: FETCH, 2: DECODE, 3: EXECUTE)
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      // 1: FETCH
      reg_i_data_a_1 <= {((W - 1)-(0)+1){1'b0}};
      reg_i_data_b_1 <= {((W - 1)-(0)+1){1'b0}};
      reg_i_data_carry_1 <= 1'b0;
      // 2: DECODE
      reg_i_data_a_2 <= {((W - 1)-(0)+1){1'b0}};
      reg_i_data_b_2 <= {((W - 1)-(0)+1){1'b0}};
      reg_i_data_carry_2 <= 1'b0;
      // 2: Execute
      reg_i_data_a_3 <= {((W - 1)-(0)+1){1'b0}};
      reg_i_data_b_3 <= {((W - 1)-(0)+1){1'b0}};
      reg_i_data_carry_3 <= 1'b0;
    end
    else begin
      // 1: FETCH
      reg_i_data_a_1 <= i_data_a;
      reg_i_data_b_1 <= i_data_b;
      reg_i_data_carry_1 <= i_data_carry;
      // 2: DECODE
      reg_i_data_a_2 <= reg_i_data_a_1;
      reg_i_data_b_2 <= reg_i_data_b_1;
      reg_i_data_carry_2 <= reg_i_data_carry_1;
      // 2: EXECUTE
      reg_i_data_a_3 <= reg_i_data_a_2;
      reg_i_data_b_3 <= reg_i_data_b_2;
      reg_i_data_carry_3 <= reg_i_data_carry_2;
    end
  end
  // 2: DECODE
  // Check if fetched instruction is a valid instruction
  assign sig_valid = reg_i_instr_2 == 4'b0001 || reg_i_instr_2 == 4'b0010 || reg_i_instr_2 == 4'b0011 || reg_i_instr_2 == 4'b0100 || reg_i_instr_2 == 4'b0101 || reg_i_instr_2 == 4'b0110 || reg_i_instr_2 == 4'b0111 ? 1'b1 : 1'b0;
  // 2: DECODE
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      reg_valid <= 1'b0;
    end
    else begin
      reg_valid <= sig_valid;
    end
  end
  // 2: DECODE
  assign o_valid = reg_valid;
  // 3: EXECUTE
  alu #(
      .W(W))
  alu_inst(
      .i_data_a(reg_i_data_a_3),
    .i_data_b(reg_i_data_b_3),
    .i_data_carry(reg_i_data_carry_3),
    .i_ctrl(reg_i_instr_3),
    .o_data_c(sig_data_c),
    .o_data_carry(sig_data_carry),
    .o_data_comp(sig_data_comp));
  // 3: EXECUTE
  always @(posedge clk) begin
    if((rst == 1'b1)) begin
      o_data_c <= {((W - 1)-(0)+1){1'b0}};
      o_data_carry <= 1'b0;
      o_data_comp <= {2{1'b0}};
    end
    else begin
      if((reg_valid == 1'b1)) begin
        o_data_c <= sig_data_c;
        o_data_carry <= sig_data_carry;
        o_data_comp <= sig_data_comp;
      end
      else begin
        o_data_c <= {((W - 1)-(0)+1){1'b0}};
        o_data_carry <= 1'b0;
        o_data_comp <= {2{1'b0}};
      end
    end
  end
endmodule

module alu(
input wire clk,
input wire rst,
input wire [15:0] opcode,
input wire a,
input wire b,
output reg y
);
reg ci;
reg co;
reg [7:0] mux1; reg [7:0] mux2;
  always @(a, b, ci, mux1, mux2) begin : P1
    reg [2:0] sel;
    sel = {a,b,ci};
    y <= mux1[sel];
    co <= mux2[sel];
  end
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b0)) begin
      ci <= 1'b0;
      mux1 <= {8{1'b0}};
      mux2 <= {8{1'b0}};
    end else begin
      ci <= co;
      mux1 <= opcode[15:8];
      mux2 <= opcode[7:0];
    end
  end
endmodule

module dac_mkid_interface(
input wire dac_clk_p,
input wire dac_clk_n,
output wire dac_smpl_clk_i_p,
output wire dac_smpl_clk_i_n,
output wire dac_smpl_clk_q_p,
output wire dac_smpl_clk_q_n,
output wire dac_sync_i_p,
output wire dac_sync_i_n,
output wire dac_sync_q_p,
output wire dac_sync_q_n,
output wire [15:0] dac_data_i_p,
output wire [15:0] dac_data_i_n,
output wire [15:0] dac_data_q_p,
output wire [15:0] dac_data_q_n,
output wire dac_not_sdenb_i,
output wire dac_not_sdenb_q,
output wire dac_sclk,
output wire dac_sdi,
output wire dac_not_reset,
input wire dac_smpl_clk,
input wire [15:0] dac_data_i0,
input wire [15:0] dac_data_i1,
input wire [15:0] dac_data_q0,
input wire [15:0] dac_data_q1,
input wire dac_sync_i,
input wire dac_sync_q,
input wire not_sdenb_i,
input wire not_sdenb_q,
input wire sclk,
input wire sdi,
input wire not_reset,
output wire dac_clk_out,
output wire dac_clk90_out,
output wire dac_clk180_out,
output wire dac_clk270_out,
output wire dac_dcm_locked
);
parameter [31:0] OUTPUT_CLK=0;
parameter [31:0] CTRL_CLK_PHASE=0;
//------------------------------------
// differential signals from/to DAC
//------------------------------------
// clock from DAC
// clock to DAC
// enable analog output for DAC
// data written to DAC
// configuration ports of DAC      
// dac_phase			: in	STD_LOGIC;
//------------------------------------
// signals from/to design
//------------------------------------
// defined in xps_dac_mkid.m  
// defined in dac_mkid yellow block and dac_mkid_mask.m
// serial ports
// phase				: out	STD_LOGIC
// clock to FPGA
// dcm lock
//------------------------------------------------------------------------------
// Architecture section
//------------------------------------------------------------------------------
wire [15:0] data_i;
wire [15:0] data_q;
wire smpl_clk;
wire dac_clk_in;
wire dac_clk;
wire dcm_clk;
wire dcm_clk90;
wire dcm_clk180;
wire dcm_clk270;
wire clk;
wire clk90;
wire clk180;
wire clk270;
  //---------------------------------------------------------------------
  // Serial input (DAC configuration)
  //---------------------------------------------------------------------
  OBUF #(
      .IOSTANDARD(7'bDEFAULT))
  OBUF_inst_not_sdenb_i(
      .O(dac_not_sdenb_i),
    .I(not_sdenb_i));
  OBUF #(
      .IOSTANDARD(7'bDEFAULT))
  OBUF_inst_not_sdenb_q(
      .O(dac_not_sdenb_q),
    .I(not_sdenb_q));
  OBUF #(
      .IOSTANDARD(7'bDEFAULT))
  OBUF_inst_sclk(
      .O(dac_sclk),
    .I(sclk));
  OBUF #(
      .IOSTANDARD(7'bDEFAULT))
  OBUF_inst_sdi(
      .O(dac_sdi),
    .I(sdi));
  OBUF #(
      .IOSTANDARD(7'bDEFAULT))
  OBUF_inst_not_reset(
      .O(dac_not_reset),
    .I(not_reset));
  //-----------------------------------------------------------------
  // Sample clock in to DAC.  "dac_smpl_clk_i_p/n" is a DDR clock. --
  //-----------------------------------------------------------------
  BUFG BUFG_inst(
      .O(smpl_clk),
    .I(dac_smpl_clk));
  OBUFDS #(
      .IOSTANDARD(7'bLVDS_25))
  OBUFDS_inst_smpl_clk_i(
      .O(dac_smpl_clk_i_p),
    .OB(dac_smpl_clk_i_n),
    .I(smpl_clk));
  OBUFDS #(
      .IOSTANDARD(7'bLVDS_25))
  OBUFDS_inst_smpl_clk_q(
      .O(dac_smpl_clk_q_p),
    .OB(dac_smpl_clk_q_n),
    .I(smpl_clk));
  //--------------------------------
  // Enable analog output for DAC --
  //--------------------------------
  OBUFDS #(
      .IOSTANDARD(7'bLVDS_25))
  OBUFDS_inst_dac_sync_i(
      .O(dac_sync_i_p),
    .OB(dac_sync_i_n),
    .I(dac_sync_i));
  OBUFDS #(
      .IOSTANDARD(7'bLVDS_25))
  OBUFDS_inst_dac_sync_q(
      .O(dac_sync_q_p),
    .OB(dac_sync_q_n),
    .I(dac_sync_q));
  //---------------------------------------------------------------------
  //  DAC data outputs
  //      Requires an ODDR to double the data rate, and an 
  //	OBUFDS to convert to differential signal.
  //---------------------------------------------------------------------
  // DAC output I --
  genvar j;
  generate for (j=0; j <= 15; j = j + 1) begin: ODDR_inst_generate_data_i
      ODDR #(
          .DDR_CLK_EDGE(9'bSAME_EDGE),
      .INIT(1'b0),
      .SRTYPE(4'bSYNC))
    ODDR_inst_data_i(
          .Q(data_i[j]),
      .C(smpl_clk),
      .CE(1'b1),
      .D1(dac_data_i0[j]),
      .D2(dac_data_i1[j]),
      .R(1'b0),
      .S(1'b0));
  end
  endgenerate
  genvar j;
  generate for (j=0; j <= 15; j = j + 1) begin: OBUFDS_inst_generate_data_i
      OBUFDS #(
          .IOSTANDARD(7'bLVDS_25))
    OBUFDS_inst_data1_i(
          .O(dac_data_i_p[j]),
      .OB(dac_data_i_n[j]),
      .I(data_i[j]));
