module fifo_out(
input wire CLOCK,
input wire RESET,
input wire [31:0] L_DIN,
input wire L_VIN,
output reg L_RIN,
input wire [15:0] L_SZ,
input wire L_DIR,
input wire [31:0] N_DIN,
input wire N_VIN,
output reg N_RIN,
input wire [15:0] N_SZ,
input wire N_DIR,
input wire [31:0] S_DIN,
input wire S_VIN,
output reg S_RIN,
input wire [15:0] S_SZ,
input wire S_DIR,
input wire [31:0] E_DIN,
input wire E_VIN,
output reg E_RIN,
input wire [15:0] E_SZ,
input wire E_DIR,
input wire [31:0] W_DIN,
input wire W_VIN,
output reg W_RIN,
input wire [15:0] W_SZ,
input wire W_DIR,
output wire [31:0] DOUT,
output wire VOUT,
input wire ROUT
);
// local
// north
// south
// east
// west
// output
parameter RAW = false;
wire reset_n;
parameter [0:0]
  RR = 0,
  TRACK = 1;
reg state; reg state_next;
reg [15:0] count; reg [15:0] count_next;  // track packet size
reg [31:0] index; reg [31:0] index_next;  // index input fifo
reg [31:0] fifo_din;
reg fifo_vin;
wire fifo_rin;
  // fifo
  generate if (RAW == true) begin: fifo_raw
      fifo #(
          .FIFO_WIDTH(10),
      .DATA_WIDTH(32))
    fifo_i(
          // clock and reset
      .CLOCK(CLOCK),
      .RESET(RESET),
      // fifo input interface
      .DAT_I(fifo_din),
      .VAL_I(fifo_vin),
      .RDY_I(fifo_rin),
      .FULL(/* open */),
      // fifo output interface
      .DAT_O(DOUT),
      .VAL_O(VOUT),
      .RDY_O(ROUT),
      .EMPTY(/* open */),
      .OCC_SIZE(/* open */),
      .VAC_SIZE(/* open */));
  end
  endgenerate
  generate if (RAW == false) begin: fifo_xil
      FIFO_32x1Kr fifo_i(
          .s_aclk(CLOCK),
      .s_aresetn(reset_n),
      .s_axis_tdata(fifo_din),
      .s_axis_tvalid(fifo_vin),
      .s_axis_tready(fifo_rin),
      .m_axis_tdata(DOUT),
      .m_axis_tvalid(VOUT),
      .m_axis_tready(ROUT));
  end
  endgenerate
  assign reset_n =  ~RESET;
  always @(posedge CLOCK) begin
    if(RESET == 1'b1) begin
      state <= RR;
      index <= 0;
    end
    else begin
      state <= state_next;
      count <= count_next;
      index <= index_next;
    end
  end
  always @(state, count, index, fifo_rin, L_DIR, L_SZ, L_DIN, L_VIN, N_DIR, N_SZ, N_DIN, N_VIN, S_DIR, S_SZ, S_DIN, S_VIN, E_DIR, E_SZ, E_DIN, E_VIN, W_DIR, W_SZ, W_DIN, W_VIN) begin
    state_next <= state;
    count_next <= count;
    index_next <= index;
    fifo_din <= {32{1'b0}};
    fifo_vin <= 1'b0;
    L_RIN <= 1'b0;
    N_RIN <= 1'b0;
    S_RIN <= 1'b0;
    E_RIN <= 1'b0;
    W_RIN <= 1'b0;
    case(state)
    RR : begin
      if(index == 0 && L_DIR == 1'b1) begin
        state_next <= TRACK;
        count_next <= L_SZ;
      end
      else if(index == 1 && N_DIR == 1'b1) begin
        state_next <= TRACK;
        count_next <= N_SZ;
      end
      else if(index == 2 && S_DIR == 1'b1) begin
        state_next <= TRACK;
        count_next <= S_SZ;
      end
      else if(index == 3 && E_DIR == 1'b1) begin
        state_next <= TRACK;
        count_next <= E_SZ;
      end
      else if(index == 4 && W_DIR == 1'b1) begin
        state_next <= TRACK;
        count_next <= W_SZ;
      end
      else begin
        if(index == 4) begin
          index_next <= 0;
        end
        else begin
          index_next <= index + 1;
        end
      end
    end
    TRACK : begin
      if(index == 0) begin
        L_RIN <= fifo_rin;
        fifo_din <= L_DIN;
        fifo_vin <= L_VIN;
        if(fifo_rin == 1'b1 && L_VIN == 1'b1) begin
          count_next <= count - 1;
          if(count == 1) begin
            // last word is transfering
            state_next <= RR;
          end
        end
      end
      else if(index == 1) begin
        N_RIN <= fifo_rin;
        fifo_din <= N_DIN;
        fifo_vin <= N_VIN;
        if(fifo_rin == 1'b1 && N_VIN == 1'b1) begin
          count_next <= count - 1;
          if(count == 1) begin
            // last word is transfering
            state_next <= RR;
          end
        end
      end
      else if(index == 2) begin
        S_RIN <= fifo_rin;
        fifo_din <= S_DIN;
        fifo_vin <= S_VIN;
        if(fifo_rin == 1'b1 && S_VIN == 1'b1) begin
          count_next <= count - 1;
          if(count == 1) begin
            // last word is transfering
            state_next <= RR;
          end
        end
      end
      else if(index == 3) begin
        E_RIN <= fifo_rin;
        fifo_din <= E_DIN;
        fifo_vin <= E_VIN;
        if(fifo_rin == 1'b1 && E_VIN == 1'b1) begin
          count_next <= count - 1;
          if(count == 1) begin
            // last word is transfering
            state_next <= RR;
          end
        end
      end
      else if(index == 4) begin
        W_RIN <= fifo_rin;
        fifo_din <= W_DIN;
        fifo_vin <= W_VIN;
        if(fifo_rin == 1'b1 && W_VIN == 1'b1) begin
          count_next <= count - 1;
          if(count == 1) begin
            // last word is transfering
            state_next <= RR;
          end
        end
      end
    end
    endcase
  end
endmodule

module customblock(
input wire C,
input wire D,
output reg Q
);
reg [31:0] count = 1;  //counts number of CLOCK cycles
wire [31:0] period = 10;  //PWM signal period is 10 times of clock period
wire [31:0] boost = 9;  //number of clock pulses during T_ON
wire [31:0] buck = 1;  //number of clock pulses during T_OFF
  always @(posedge C, posedge D) begin
    count <= count + 1;
    if((count == period)) begin
      // resets count for period
      count <= 1;
    end
    if((D == 1'b1)) begin
      //boost duty cycle when compartor output is high--
      if((count <= boost)) begin
        Q <= 1'b1;
      end
      else if((count > boost)) begin
        Q <= 1'b0;
      end
    end
    if((D == 1'b0)) begin
      //buck duty cycle when compartor output is low--
      if((count <= buck)) begin
        //
        Q <= 1'b1;
      end
      else if((count > buck)) begin
        Q <= 1'b0;
      end
    end
  end
endmodule

