module SIMPLE_FIFO(
input wire CLK,
input wire RESET,
input wire [DATA_WIDTH - 1:0] DATA_IN,
input wire WRITE_EN,
output reg [DATA_WIDTH - 1:0] DATA_OUT,
input wire READ_EN,
output wire STATE_FULL,
output wire STATE_EMPTY
);
parameter [31:0] DATA_WIDTH=64;
parameter [31:0] DEPTH=512;
// global FPGA clock
// global synchronous reset
// Write interface
// Read interface
// Control
// -----------------------------------------------------------------
// Signals
// -----------------------------------------------------------------
reg [DATA_WIDTH - 1:0] fifo[0:DEPTH - 1];
reg [31:0] read_ptr;
reg [31:0] write_ptr;
reg [31:0] depth_cur;
  // -----------------------------------------------------------------
  // Logic
  // -----------------------------------------------------------------
  // FIFO read and write
  always @(posedge CLK) begin
    if((RESET == 1'b1)) begin
      write_ptr <= 0;
      read_ptr <= 0;
      DATA_OUT <= {((DATA_WIDTH - 1)-(0)+1){1'b0}};
    end
    else begin
      // Read in the FIFO
      if((read_en == 1'b1)) begin
        data_out <= fifo[read_ptr];
        // Increment the pointer
        if((read_ptr < (DEPTH - 1))) begin
          read_ptr <= read_ptr + 1;
        end
        else begin
          read_ptr <= 0;
        end
      end
      // Write in the FIFO
      if((write_en == 1'b1)) begin
        fifo[write_ptr] <= data_in;
        // Increment the pointer
        if((write_ptr < (DEPTH - 1))) begin
          write_ptr <= write_ptr + 1;
        end
        else begin
          write_ptr <= 0;
        end
      end
    end
  end
  // FIFO depth management
  always @(posedge CLK) begin
    if((RESET == 1'b1)) begin
      depth_cur <= 0;
    end
    else begin
      if((write_en == 1'b1 && read_en == 1'b0)) begin
        depth_cur <= depth_cur + 1;
      end
      else if((write_en == 1'b0 && read_en == 1'b1)) begin
        depth_cur <= depth_cur - 1;
      end
    end
  end
  // FIFO full/empty
  assign STATE_FULL = (depth_cur >= DEPTH) ? 1'b1 : 1'b0;
  assign STATE_EMPTY = (depth_cur <= 0) ? 1'b1 : 1'b0;
endmodule

module sr_latch(
