  assign q_n =  ~(s & q);
endmodule

module my_alu(
input wire [NUMBITS - 1:0] A,
input wire [NUMBITS - 1:0] B,
input wire [2:0] opcode,
output reg [NUMBITS - 1:0] result,
output reg carryout,
output reg overflow,
output reg zero
);
parameter [31:0] NUMBITS=8;
reg [NUMBITS:0] stuff;
  always @(A, B, opcode, stuff) begin
    //UNSIGNED ADD
    if(opcode == 3'b000) begin
      stuff <= ({1'b0,A}) + ({1'b0,B});
      result <= stuff[NUMBITS - 1:0];
      //carryout <= '1';
      carryout <= stuff[NUMBITS];
      overflow <= stuff[NUMBITS];
      if(stuff[NUMBITS:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
      //SIGNED ADD	
    end
    else if(opcode == 3'b001) begin
      stuff <= ({1'b0,A}) + ({1'b0,B});
      result <= stuff[NUMBITS - 1:0];
      if((A[NUMBITS - 1] == 1'b0) && (B[NUMBITS - 1] == 1'b0) && (stuff[NUMBITS - 1] == 1'b1)) begin
        overflow <= 1'b1;
      end
      else if((A[NUMBITS - 1] == 1'b1) && (B[NUMBITS - 1] == 1'b1) && (stuff[NUMBITS - 1] == 1'b0)) begin
        overflow <= 1'b1;
      end
      else begin
        overflow <= 1'b0;
      end
      carryout <= stuff[NUMBITS];
      if(stuff[NUMBITS - 1:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
      //UNSIGNED SUB
    end
    else if(opcode == 3'b010) begin
      stuff <= ({1'b0,A}) + ({1'b0,( ~(B)) + 1});
      result <= stuff[NUMBITS - 1:0];
      overflow <= stuff[NUMBITS - 1];
      if(stuff[NUMBITS - 1] == 1'b0) begin
        carryout <= 1'b1;
      end
      else begin
        carryout <= 1'b0;
      end
      if(stuff[NUMBITS - 1:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
      //SIGNED SUB
    end
    else if(opcode == 3'b011) begin
      stuff <= ({1'b0,A}) + ({1'b0,( ~(B)) + 1});
      result <= stuff[NUMBITS - 1:0];
      if((A[NUMBITS - 1] == 1'b0) && (B[NUMBITS - 1] == 1'b1) && (stuff[NUMBITS - 2] == 1'b1)) begin
        overflow <= 1'b1;
      end
      else if((A[NUMBITS - 1] == 1'b1) && (B[NUMBITS - 1] == 1'b0) && (stuff[NUMBITS - 2] == 1'b0)) begin
        overflow <= 1'b1;
      end
      else begin
        overflow <= 1'b0;
      end
      carryout <= stuff[NUMBITS];
      if(stuff[NUMBITS - 1:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
      //BITWISE AND
    end
    else if(opcode == 3'b100) begin
      stuff <= ({1'b0,A}) & ({1'b0,B});
      result <= stuff[NUMBITS - 1:0];
      overflow <= 1'b0;
      carryout <= 1'b0;
      if(stuff[NUMBITS:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
      //BITWISE OR
    end
    else if(opcode == 3'b101) begin
      stuff <= ({1'b0,A}) | ({1'b0,B});
      result <= stuff[NUMBITS - 1:0];
      overflow <= 1'b0;
      carryout <= 1'b0;
      if(stuff[NUMBITS:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
      //BITWUS XOR
    end
    else if(opcode == 3'b110) begin
      stuff <= ({1'b0,A}) ^ ({1'b0,B});
      result <= stuff[NUMBITS - 1:0];
      overflow <= 1'b0;
      carryout <= 1'b0;
      if(stuff[NUMBITS:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
    end
    else begin
      //Divide A by 2
      stuff <= ({1'b0,A}) / 2;
      result <= stuff[NUMBITS - 1:0];
      overflow <= 1'b0;
      carryout <= 1'b0;
      if(stuff[NUMBITS:0] == 0) begin
        zero <= 1'b1;
      end
      else begin
        zero <= 1'b0;
      end
    end
  end
endmodule

