module sub_145(
output wire [3:0] result,
input wire [3:0] in_a,
input wire [3:0] in_b
);
wire [5:0] carry_inA;
wire [5:0] carry_inB;
wire [5:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[4:1];
endmodule

