module fifoRead(
input wire iClk,
input wire iRst,
input wire iRead,
input wire [gAddrWidth:0] iWrPointer,
output wire oEmpty,
output wire oFull,
output wire [gAddrWidth:0] oPointer,
output wire [gAddrWidth - 1:0] oAddress,
output wire [gAddrWidth - 1:0] oUsedWord
);
parameter [31:0] gAddrWidth=4;
reg [gAddrWidth:0] r_ptr_reg;
wire [gAddrWidth:0] r_ptr_next;
wire [gAddrWidth:0] gray1;
wire [gAddrWidth:0] bin;
wire [gAddrWidth:0] bin1;
wire [gAddrWidth - 1:0] raddr_all;
wire raddr_msb;
wire waddr_msb;
wire empty_flag;
wire full_flag;
wire [gAddrWidth:0] r_elements_wr;
wire [gAddrWidth:0] r_elements_rd;
wire [gAddrWidth:0] r_elements_diff;
reg [gAddrWidth - 1:0] r_elements_reg;
wire [gAddrWidth - 1:0] r_elements_next;
  //! Clock process for registers.
  always @(posedge iRst, posedge iClk) begin
    if(iRst == cActivated) begin
      r_ptr_reg <= {((gAddrWidth)-(0)+1){cInactivated}};
      r_elements_reg <= {((gAddrWidth - 1)-(0)+1){cInactivated}};
    end else begin
      r_ptr_reg <= r_ptr_next;
      r_elements_reg <= r_elements_next;
    end
  end
  // (gAddrWidth+1)-bit Gray counter
  assign bin = r_ptr_reg ^ ({cInactivated,bin[gAddrWidth:1]});
  assign bin1 = (bin) + 1;
  assign gray1 = bin1 ^ ({cInactivated,bin1[gAddrWidth:1]});
  // update read pointer
  assign r_ptr_next = iRead == cActivated && empty_flag == cInactivated ? gray1 : r_ptr_reg;
  // gAddrWidth-bit Gray counter
  assign raddr_msb = r_ptr_reg[gAddrWidth] ^ r_ptr_reg[gAddrWidth - 1];
  assign raddr_all = {raddr_msb,r_ptr_reg[gAddrWidth - 2:0]};
  assign waddr_msb = iWrPointer[gAddrWidth] ^ iWrPointer[gAddrWidth - 1];
  // check for FIFO read empty
  assign empty_flag = iWrPointer[gAddrWidth] == r_ptr_reg[gAddrWidth] && iWrPointer[gAddrWidth - 2:0] == r_ptr_reg[gAddrWidth - 2:0] && raddr_msb == waddr_msb ? cActivated : cInactivated;
  // check for FIFO read full
  assign full_flag = iWrPointer[gAddrWidth] != r_ptr_reg[gAddrWidth] && iWrPointer[gAddrWidth - 2:0] == r_ptr_reg[gAddrWidth - 2:0] && raddr_msb == waddr_msb ? cActivated : cInactivated;
  // convert gray value to bin and obtain difference
  assign r_elements_wr = bin;
  assign r_elements_rd = iWrPointer ^ ({cInactivated,r_elements_rd[gAddrWidth:1]});
  assign r_elements_diff = (r_elements_rd) - (r_elements_wr);
  assign r_elements_next = r_elements_diff[gAddrWidth - 1:0];
  // output
  assign oAddress = raddr_all;
  assign oPointer = r_ptr_reg;
  assign oUsedWord = r_elements_reg;
  assign oEmpty = empty_flag;
  assign oFull = full_flag;
endmodule

module clk0_125Hz(
input wire clk,
input wire reset,
output wire clk_out
);
// Reloj de entrada de 50000000Hz.
// Reloj de salida de 0.125Hz.
reg temporal;
reg [31:0] contador = 0;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      temporal <= 1'b0;
      contador <= 0;
    end else begin
      if((contador == 199999999)) begin
        temporal <=  ~(temporal);
        contador <= 0;
      end
      else begin
        contador <= contador + 1;
      end
    end
  end
  assign clk_out = temporal;
endmodule

