// al -> Low Data Output (mapped) (4 std_logic)
// Architecture of the Component
  // Mapping Process
  assign ah[3] = a[5] ^ a[7];
  assign ah[2] = a[5] ^ a[7] ^ a[2] ^ a[3];
  assign ah[1] = a[1] ^ a[7] ^ a[4] ^ a[6];
  assign ah[0] = a[4] ^ a[6] ^ a[5];
  assign al[3] = a[2] ^ a[4];
  assign al[2] = a[1] ^ a[7];
  assign al[1] = a[1] ^ a[2];
  assign al[0] = a[4] ^ a[6] ^ a[5] ^ a[0];
endmodule

