module vga(
input wire clk,
input wire not_reset,
output wire hsync,
output wire vsync,
output wire video_on,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y
);
// VGA 640x480 sync parameters
parameter HD = 640;  // horizontal display area
parameter HF = 16;  // h. front porch
parameter HB = 48;  // h. back porch
parameter HR = 96;  // h. retrace
parameter VD = 480;  // vertical display area
parameter VF = 11;  // v. front porch
parameter VB = 31;  // v. back porch
parameter VR = 2;  // v. retrace
// mod-2 counter
reg mod2; wire mod2_next;  // sync counters
reg [9:0] v_count; reg [9:0] v_count_next;
reg [9:0] h_count; reg [9:0] h_count_next;  // output buffer
reg v_sync; reg h_sync;
wire v_sync_next; wire h_sync_next;  // status signal
wire h_end; wire v_end; wire pixel_tick;
  always @(negedge clk, negedge not_reset) begin
    if(not_reset == 1'b0) begin
      mod2 <= 1'b0;
      v_count <= {10{1'b0}};
      h_count <= {10{1'b0}};
      v_sync <= 1'b0;
      h_sync <= 1'b0;
    end else begin
      mod2 <= mod2_next;
      v_count <= v_count_next;
      h_count <= h_count_next;
      v_sync <= v_sync_next;
      h_sync <= h_sync_next;
    end
  end
  // mod-2 circuit to generate 25 MHz enable tick
  assign mod2_next =  ~mod2;
  // 25 MHz pixel tick
  assign pixel_tick = mod2 == 1'b1 ? 1'b1 : 1'b0;
  // end of counters (799 and 524 pixels)
  assign h_end = h_count == (HD + HF + HB + HR - 1) ? 1'b1 : 1'b0;
  assign v_end = v_count == (VD + VF + VB + VR - 1) ? 1'b1 : 1'b0;
  // mod-800 horizontal sync counter
  always @(h_count, h_end, pixel_tick) begin
    if(pixel_tick == 1'b1) begin
      if(h_end == 1'b1) begin
        h_count_next <= {10{1'b0}};
      end
      else begin
        h_count_next <= h_count + 1;
      end
    end
    else begin
      h_count_next <= h_count;
    end
  end
  // mod-524 vertical sync counter
  always @(v_count, h_end, v_end, pixel_tick) begin
    if(pixel_tick == 1'b1 && h_end == 1'b1) begin
      if(v_end == 1'b1) begin
        v_count_next <= {10{1'b0}};
      end
      else begin
        v_count_next <= v_count + 1;
      end
    end
    else begin
      v_count_next <= v_count;
    end
  end
  // horizontal and vertical sync, buffered to avoid glitch
  assign h_sync_next = (h_count >= (HD + HF)) && (h_count <= (HD + HF + HR - 1)) ? 1'b1 : 1'b0;
  assign v_sync_next = (v_count >= (VD + VF)) && (v_count <= (VD + VF + VR - 1)) ? 1'b1 : 1'b0;
  // video on/off
  assign video_on = (h_count < HD) && (v_count < VD) ? 1'b1 : 1'b0;
  // output signal
  assign hsync = h_sync;
  assign vsync = v_sync;
  assign pixel_x = h_count;
  assign pixel_y = v_count;
endmodule

module lpb_mpc5200b_to_avalon(
input wire clk,
input wire reset_n,
input wire waitrequest,
output reg [31:0] address,
output reg read,
input wire [31:0] readdata,
output reg write,
output reg [31:0] writedata,
output reg [3:0] byteenable,
inout reg [LPBDATAWIDTH - 1:0] lpb_ad,
input wire [LPBCSWIDTH - 1:0] lpb_cs_n,
input wire lpb_oe_n,
output wire lpb_ack_n,
input wire lpb_ale_n,
input wire lpb_rdwr_n,
input wire lpb_ts_n
);
parameter [31:0] LPBADDRWIDTH=32;
parameter [31:0] LPBDATAWIDTH=32;
parameter [31:0] LPBTSIZEWIDTH=3;
parameter [31:0] LPBCSWIDTH=2;
parameter [31:0] LPBBANKWIDTH=2;
// Avalon Fundametal Signals
// Avalon Address/Data Interface
// Avalon SIGNAL (OTHERS)
// MPC5200 address/data interface
// LocalPlus Bus Chip Selects AND other signals
//-------------------------------------------------------
// reset SIGNAL einbauen
//-------------------------------------------------------
reg [LPBADDRWIDTH - 1:0] lpb_adr_q;
reg [LPBDATAWIDTH - 1:0] lpb_data_q;
reg [LPBTSIZEWIDTH - 1:0] lpb_tsize_q;
reg lpb_data_en;
reg lpb_start;
wire lpb_rd;
wire lpb_wr;
reg lpb_ack_i;
reg lpb_start_en;
reg [31:0] lpb_ad_o;
reg lpb_ad_en;
parameter [1:0]
  init = 0,
  act = 1,
  rst = 2;
reg [1:0] avalonstate;
  //activation of FPGA with only one chip select SIGNAL
  assign lpb_rd =  ~lpb_cs_n[0] &  ~lpb_oe_n;
  assign lpb_wr =  ~lpb_cs_n[0] &  ~lpb_rdwr_n;
  // external ack SIGNAL gets internal value
  assign lpb_ack_n =  ~lpb_ack_i;
  // ############################# MPC interface functions ##############################
  // tristate buffer generation
  always @(lpb_ad_o, lpb_ad_en, reset_n) begin
    if(reset_n == 1'b0) begin
      lpb_ad <= {((LPBDATAWIDTH - 1)-(0)+1){1'bZ}};
    end
    else if(lpb_ad_en == 1'b1) begin
      lpb_ad <= lpb_ad_o;
    end
    else begin
      lpb_ad <= {((LPBDATAWIDTH - 1)-(0)+1){1'bZ}};
    end
  end
  // mpc_address_latching : necessary because of multiplexed bus system
  // latching of addresses at falling edge of clk
  always @(posedge clk, posedge reset_n) begin
    if(reset_n == 1'b0) begin
      lpb_adr_q <= {((LPBADDRWIDTH - 1)-(0)+1){1'b0}};
      lpb_tsize_q <= {((LPBTSIZEWIDTH - 1)-(0)+1){1'b0}};
    end else begin
      if(lpb_ale_n == 1'b0) begin
        lpb_adr_q <= lpb_ad[LPBADDRWIDTH - 1:0];
        lpb_tsize_q <= lpb_ad[LPBDATAWIDTH - 2:LPBDATAWIDTH - 4];
      end
    end
  end
  // lpb_write_data_latching
  // latching of data of the lpb bus at write cycle
  always @(posedge clk, posedge reset_n) begin
    if(reset_n == 1'b0) begin
      lpb_data_q <= {((LPBDATAWIDTH - 1)-(0)+1){1'b0}};
      lpb_data_en <= 1'b0;
      lpb_start <= 1'b0;
    end else begin
      if(lpb_ts_n == 1'b0 && lpb_start == 1'b0) begin
        //lpb_start <= '1';		-- for 66MHz we can start here
        lpb_start_en <= 1'b1;
      end
      else begin
        //lpb_start <= '0';
        lpb_start_en <= 1'b0;
      end
      // needable for 33MHz support, for 66MHz we can start erlier
      if(lpb_start_en == 1'b1) begin
        lpb_start <= 1'b1;
      end
      else begin
        lpb_start <= 1'b0;
      end
      if(lpb_ts_n == 1'b0 && lpb_rdwr_n == 1'b0) begin
        lpb_data_en <= 1'b1;
        // wait 1 clock cycle for data ready
      end
      if(lpb_data_en == 1'b1) begin
        lpb_data_q <= lpb_ad;
        lpb_data_en <= 1'b0;
      end
    end
  end
  // lpb_read_data_switching
  // reading of data of avalon register AND applying at the LPB bus
  always @(posedge clk, posedge reset_n) begin
    if(reset_n == 1'b0) begin
      lpb_ad_o <= {32{1'b0}};
      lpb_ad_en <= 1'b0;
    end else begin
      if(lpb_rd == 1'b1 && lpb_ack_i == 1'b0) begin
        case(lpb_tsize_q)
        3'b001 : begin
          lpb_ad_o <= {readdata[7:0],readdata[15:8],readdata[23:16],readdata[31:24]};
        end
        3'b010 : begin
          lpb_ad_o <= {readdata[15:0],readdata[31:16]};
        end
        default : begin
          lpb_ad_o <= readdata;
        end
        endcase
        lpb_ad_en <= 1'b1;
      end
      else begin
        lpb_ad_en <= 1'b0;
      end
    end
  end
  // mpc_ack_generation : necessary to shorten the controller cycle of the mpc
  // genaration of ack SIGNAL at falling edge of local plus bus clock
  always @(posedge clk, posedge reset_n) begin
    if(reset_n == 1'b0) begin
      lpb_ack_i <= 1'b0;
    end else begin
      if(avalonstate == act) begin
        lpb_ack_i <=  ~waitrequest &  ~lpb_ack_i;
      end
      else begin
        lpb_ack_i <= 1'b0;
      end
    end
  end
  // ############################ wishbone read/write state machine ######################
  // state machine for reading/writing avalon bus
  always @(posedge reset_n, posedge clk) begin
    if(reset_n == 1'b0) begin
      avalonstate <= init;
    end else begin
      case(avalonstate)
      init : begin
        if(lpb_start == 1'b1) begin
          // start avalon master statemachine
          avalonstate <= act;
        end
      end
      act : begin
        if(waitrequest == 1'b0) begin
          // wait for no waitrequest 
          avalonstate <= rst;
        end
      end
      rst : begin
        avalonstate <= init;
      end
      default : begin
        avalonstate <= init;
      end
      endcase
    end
  end
  always @(posedge reset_n, posedge clk) begin
    if(reset_n == 1'b0) begin
    end else begin
      if(avalonstate == init && lpb_start == 1'b1) begin
        address <= lpb_adr_q;
        write <= lpb_wr;
        // avalon SIGNAL generation we				
        read <= lpb_rd;
        case(lpb_tsize_q)
                // swap bytes for little endian access
        3'b100 : begin
          byteenable <= 4'b1111;
          writedata <= lpb_data_q;
        end
        3'b010 : begin
          case(lpb_adr_q[1:0])
          2'b00 : begin
            byteenable <= 4'b0011;
            writedata[15:0] <= lpb_data_q[31:16];
          end
          2'b10 : begin
            byteenable <= 4'b1100;
            writedata <= lpb_data_q;
          end
          default : begin
            byteenable <= 4'b1111;
            writedata <= lpb_data_q;
          end
          endcase
        end
        3'b001 : begin
          case(lpb_adr_q[1:0])
          2'b00 : begin
            byteenable <= 4'b0001;
            writedata[7:0] <= lpb_data_q[31:24];
          end
          2'b01 : begin
            byteenable <= 4'b0010;
            writedata[15:8] <= lpb_data_q[31:24];
          end
          2'b10 : begin
            byteenable <= 4'b0100;
            writedata[23:16] <= lpb_data_q[31:24];
          end
          2'b11 : begin
            byteenable <= 4'b1000;
            writedata <= lpb_data_q;
          end
          endcase
        end
        default : begin
          byteenable <= 4'b1111;
          writedata <= lpb_data_q;
        end
        endcase
      end
      if(avalonstate == act) begin
        //readdata_q <= readdata;
        if(waitrequest == 1'b0) begin
          read <= 1'b0;
          write <= 1'b0;
          address <= {32{1'b0}};
          writedata <= {32{1'b0}};
        end
      end
    end
  end
endmodule

module vga800x600(
input wire clk,
output reg [3:0] red,
output reg [3:0] green,
output reg [3:0] blue,
output reg hsync,
output reg vsync,
input wire SW
);
// 40 MHz
reg [10:0] hcount = 1'b0;
reg [9:0] vcount = 1'b0;
  always @(posedge clk) begin
    // Counters
    if(hcount == 1055) begin
      hcount <= {11{1'b0}};
      if(vcount == 627) begin
        vcount <= {10{1'b0}};
      end
      else begin
        vcount <= vcount + 1;
      end
    end
    else begin
      hcount <= hcount + 1;
    end
    // Hsync
    if(hcount >= (800 + 40) && hcount < (800 + 40 + 128)) begin
      hsync <= 1'b0;
    end
    else begin
      hsync <= 1'b1;
    end
    // Vsync
    if(vcount >= (600 + 1) && vcount < (600 + 1 + 4)) begin
      vsync <= 1'b0;
    end
    else begin
      vsync <= 1'b1;
    end
    // Colors
    if(hcount < 800 && vcount < 600) begin
      if(SW == 1'b1) begin
        red <= hcount[3:0];
        green <= 4'b0000;
        blue <= vcount[3:0];
      end
      else begin
        if((hcount[0] ^ vcount[0]) == 1'b1) begin
          red <= 4'b1111;
          green <= 4'b1111;
          blue <= 4'b1111;
        end
        else begin
          red <= 4'b0000;
          green <= 4'b0000;
          blue <= 4'b0000;
        end
      end
    end
    else begin
      red <= 4'b0000;
      green <= 4'b0000;
      blue <= 4'b0000;
    end
  end
endmodule

