module delayLineBRAM_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
reg [0:0] WEA_R = 1'b0;
wire [9:0] ADDRA = 1'b0;
reg [9:0] ADDRA_R = 1'b0;
wire [16:0] DINA = 1'b0;
reg [16:0] DINA_R = 1'b0;
wire [16:0] DOUTA;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(17),
    .READ_WIDTH(17))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {1{1'b0}};
      DINA_R <= # 50 {17{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {10{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  delayLineBRAM_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

module AND2(
input wire a,
input wire b,
output wire z
);
  assign Z = a & b;
endmodule

module psr(
input wire clk,
input wire rst,
input wire [3:0] nzvc,
input wire [4:0] ncwp,
output wire [4:0] cwp,
output wire c
);
reg [31:0] regispsr = 32'b00000000000000000000000000000000;
  always @(posedge clk, posedge rst, posedge nzvc) begin
    if((rst == 1'b1)) begin
      regispsr <= 32'b00000000000000000000000000000000;
    end else begin
      regispsr[26:23] <= nzvc;
      regispsr[4:0] <= ncwp;
    end
  end
  assign c = regispsr[23];
  assign cwp = regispsr[4:0];
endmodule

module intr_sgls_generator(
input wire clk,
input wire reset,
input wire [flags_amount - 1:0] exc_bus,
output wire exception
);
wire exception_detected;
  assign exception_detected = exc_bus[flags_amount - 1] | exc_bus[0];
  data_ff SYNCHRONIZING_FF(
      .clk(clk),
    .reset(reset),
    .d(exception_detected),
    .q(exception));
endmodule

module control_unit(
input wire CLK,
input wire C,
input wire Z,
input wire INT,
input wire RST,
input wire [4:0] OPCODE_HI_5,
input wire [1:0] OPCODE_LO_2,
output reg PC_LD,
output reg [1:0] PC_MUX_SEL,
output reg PC_OE,
output reg SP_LD,
output reg [1:0] INC_DEC,
output reg RESET,
output reg RF_WR,
output reg [1:0] RF_WR_SEL,
output reg RF_OE,
output reg ALU_MUX_SEL,
output reg [3:0] ALU_SEL,
output reg SCR_WR,
output reg SCR_OE,
output reg [1:0] SCR_ADDR_SEL,
output reg C_FLAG_RESTORE,
output reg C_FLAG_SAVE,
output reg C_FLAG_LD,
output reg C_FLAG_SET,
output reg C_FLAG_CLR,
output reg Z_FLAG_RESTORE,
output reg Z_FLAG_SAVE,
output reg Z_FLAG_LD,
output reg Z_FLAG_SET,
output reg Z_FLAG_CLR,
output reg I_FLAG_SET,
output reg I_FLAG_CLR,
output reg IO_OE
);
//From the instruction register:
//Program counter
//Load program counter
//Program counter mux
//Program counter output enable
//Stack Pointer 
//stack pointer load
//SP input mux
//Reset to program counter and stack pointer
//Reset program counter and stack pointer
//Register File
//Reg File Write Enable
//Reg File Mux
//Register File Tristate Ooutput
//ALU
//Scratchpad RAM
//scratchpad write enable
//sp output enable
//sp mux sel
//C Flag
//Z Flag
//Load Z
//Set Z
//Clear Z
//Interrupt Flag 
//Set Interrupt
//Clear Interrupt
//I/O Output Enable
parameter [1:0]
  ST_init = 0,
  ST_fet = 1,
  ST_exec = 2,
  ST_int = 3;
reg [1:0] PS; reg [1:0] NS;
reg int_ast_i = 1'b0;
reg int_set_i = 1'b0;
reg int_clr_i = 1'b0;
  //synchronous process of statemachine
  //intializes present state to ST_init
  //on clock edge, PS updates to NS
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      PS <= ST_init;
    end else begin
      PS <= NS;
      if((int_set_i == 1'b1)) begin
        int_ast_i <= 1'b1;
      end
      else if((int_clr_i == 1'b1)) begin
        int_ast_i <= 1'b0;
      end
    end
  end
  // asynchronous process to determine NS and set all output signals
  always @(opcode_hi_5, opcode_lo_2, PS, NS, z, c, int, int_set_i, int_clr_i, int_ast_i) begin
    int_set_i <= 1'b0;
    int_clr_i <= 1'b0;
    case(PS)
        // STATE: the init cycle ------------------------------------
    // Initialize all control outputs to non-active states and reset the PC and SP to all zeros.
    ST_init : begin
      NS <= ST_fet;
      int_clr_i <= 1'b1;
      RESET <= 1'b1;
      PC_LD <= 1'b0;
      PC_MUX_SEL <= 2'b00;
      PC_OE <= 1'b0;
      SP_LD <= 1'b0;
      INC_DEC <= 2'b00;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      RF_OE <= 1'b0;
      ALU_MUX_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_OE <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      C_FLAG_SAVE <= 1'b0;
      C_FLAG_RESTORE <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b1;
      Z_FLAG_RESTORE <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b1;
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b1;
      Z_FLAG_SAVE <= 1'b0;
      IO_OE <= 1'b0;
      // STATE: the fetch cycle -----------------------------------
      // Set all control outputs to the values needed for fetch
    end
    ST_fet : begin
      NS <= ST_exec;
      if((INT == 1'b1)) begin
        int_set_i <= 1'b1;
      end
      RESET <= 1'b0;
      PC_LD <= 1'b1;
      PC_MUX_SEL <= 2'b00;
      PC_OE <= 1'b0;
      SP_LD <= 1'b0;
      INC_DEC <= 2'b00;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      RF_OE <= 1'b0;
      ALU_MUX_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_OE <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      C_FLAG_SAVE <= 1'b0;
      C_FLAG_RESTORE <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      Z_FLAG_RESTORE <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b0;
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b0;
      Z_FLAG_SAVE <= 1'b0;
      IO_OE <= 1'b0;
      // STATE: the execute cycle ---------------------------------
    end
    ST_exec : begin
      if((INT == 1'b1 || int_ast_i == 1'b1)) begin
        NS <= ST_int;
        int_clr_i <= 1'b1;
      end
      else begin
        NS <= ST_fet;
      end
      // Repeat the init block for all variables here, noting that any output values desired to be different
      // from init values shown below will be assigned in the following case statements for each opcode.
      RESET <= 1'b0;
      PC_LD <= 1'b0;
      PC_MUX_SEL <= 2'b00;
      PC_OE <= 1'b0;
      SP_LD <= 1'b0;
      INC_DEC <= 2'b00;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      RF_OE <= 1'b0;
      ALU_MUX_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_OE <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      C_FLAG_SAVE <= 1'b0;
      C_FLAG_RESTORE <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      Z_FLAG_RESTORE <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b0;
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b0;
      Z_FLAG_SAVE <= 1'b0;
      IO_OE <= 1'b0;
      case(OPCODE_HI_5)
            // Could be AND, OR, EXOR, or TEST
      5'b00000 : begin
        // AND (reg/reg)
        if((OPCODE_LO_2 == 2'b00)) begin
          ALU_SEL <= 4'h5;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // OR (reg/reg)
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          ALU_SEL <= 4'ha;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // EXOR (reg/reg)
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          ALU_SEL <= 4'h7;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // TEST (reg/reg)
        end
        else begin
          ALU_SEL <= 4'hd;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
        end
        // Could be ADD, ADDC, SUB, or SUBC
      end
      5'b00001 : begin
        // ADD (reg/reg)
        if((OPCODE_LO_2 == 2'b00)) begin
          ALU_SEL <= 4'h0;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          C_FLAG_LD <= 1'b1;
          // ADDC (reg/reg)
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          ALU_SEL <= 4'h1;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          C_FLAG_LD <= 1'b1;
          // SUB (reg/reg)
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          ALU_SEL <= 4'h3;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          C_FLAG_LD <= 1'b1;
          // SUBC (reg/reg)
        end
        else begin
          ALU_SEL <= 4'h4;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          C_FLAG_LD <= 1'b1;
        end
        // Could be CMP, MOV, LD, or ST (all reg/reg)
      end
      5'b00010 : begin
        // CMP (reg/reg)
        if((OPCODE_LO_2 == 2'b00)) begin
          ALU_SEL <= 4'h2;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_OE <= 1'b1;
          //RF_WR <= '1'; --do NOT write back to REG!!!!!!
          C_FLAG_LD <= 1'b1;
          // MOV (reg/reg)
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          ALU_SEL <= 4'he;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // LD (reg/reg)
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          SCR_ADDR_SEL <= 2'b11;
          SCR_OE <= 1'b1;
          RF_WR <= 1'b1;
          RF_WR_SEL <= 2'b01;
          // ST (reg/reg)
        end
        else begin
          SCR_ADDR_SEL <= 2'b11;
          SCR_WR <= 1'b1;
          RF_OE <= 1'b1;
        end
        // Could be BRN, CALL, BREQ, or BRNE 
      end
      5'b00100 : begin
        // BRN (no other form)
        // Unditional branch. Add only the signals that will change FROM THE INIT BLOCK
        if((OPCODE_LO_2 == 2'b00)) begin
          PC_MUX_SEL <= 2'b01;
          PC_LD <= 1'b1;
          // CALL (no other form)
          // Call a function
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          PC_MUX_SEL <= 2'b01;
          PC_OE <= 1'b1;
          SCR_WR <= 1'b1;
          SCR_ADDR_SEL <= 2'b10;
          INC_DEC <= 2'b01;
          PC_LD <= 1'b1;
          // BREQ (no other form)
          // Branch if zero set
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          if((z == 1'b1)) begin
            PC_MUX_SEL <= 2'b01;
            PC_LD <= 1'b1;
          end
          // BRNE (no other form)
          // Branch if zero cleared
        end
        else begin
          if((z == 1'b0)) begin
            PC_MUX_SEL <= 2'b01;
            PC_LD <= 1'b1;
          end
        end
        // Could be BRCS or BRCC
      end
      5'b00101 : begin
        // BRCS (no other form)
        // Branch if carry set
        if((OPCODE_LO_2 == 2'b00)) begin
          if((c == 1'b1)) begin
            PC_MUX_SEL <= 2'b01;
            PC_LD <= 1'b1;
          end
          // BRCC (no other form)
          // Branch if carry cleared
        end
        else begin
          if((c == 1'b0)) begin
            PC_MUX_SEL <= 2'b01;
            PC_LD <= 1'b1;
          end
        end
        // Could be LSL, LSR, ROL, or ROR
      end
      5'b01000 : begin
        // LSL (no other form)
        if((OPCODE_LO_2 == 2'b00)) begin
          ALU_SEL <= 4'h8;
          C_FLAG_LD <= 1'b1;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // LSR (no other form)
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          ALU_SEL <= 4'h9;
          C_FLAG_LD <= 1'b1;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // ROL (no other form)
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          ALU_SEL <= 4'hb;
          C_FLAG_LD <= 1'b1;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // ROR (no other form)
        end
        else begin
          ALU_SEL <= 4'hc;
          C_FLAG_LD <= 1'b1;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
        end
        // Could be ASR, PUSH, or POP
      end
      5'b01001 : begin
        // ASR (no other form)
        // Arithmetic shift right
        if((OPCODE_LO_2 == 2'b00)) begin
          ALU_SEL <= 4'h6;
          C_FLAG_LD <= 1'b1;
          Z_FLAG_LD <= 1'b1;
          RF_WR_SEL <= 2'b10;
          RF_WR <= 1'b1;
          RF_OE <= 1'b1;
          // PUSH (no other form)
          // Push a value onto the stack
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          RF_OE <= 1'b1;
          SCR_ADDR_SEL <= 2'b10;
          SCR_WR <= 1'b1;
          INC_DEC <= 2'b01;
          // POP (no other form)
          // Pop a value from the stack
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          SCR_OE <= 1'b1;
          RF_WR <= 1'b1;
          RF_WR_SEL <= 2'b01;
          INC_DEC <= 2'b10;
          SCR_ADDR_SEL <= 2'b01;
        end
        // Could be CLC, SEC, RET, or RETI
      end
      5'b01100 : begin
        // CLC (no other form)
        // Clear the carry flag
        if((OPCODE_LO_2 == 2'b00)) begin
          C_FLAG_CLR <= 1'b1;
          // SEC (no other form)
          // Set the carry flag
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          C_FLAG_SET <= 1'b1;
          // RET (no other form)
          // Return from a function
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          SCR_OE <= 1'b1;
          PC_MUX_SEL <= 2'b10;
          PC_LD <= 1'b1;
          INC_DEC <= 2'b10;
          SCR_ADDR_SEL <= 2'b01;
          // RETI (no other form)
        end
        else begin
          // unclear if this is actually a command being used
        end
        // Could be SEI, CLI, RETID, or RETIE
      end
      5'b01101 : begin
        // SEI (no other form)
        // Set the interrupt flag
        if((OPCODE_LO_2 == 2'b00)) begin
          I_FLAG_SET <= 1'b1;
          // CLI (no other form)
          // Clear the interrupt clag
        end
        else if((OPCODE_LO_2 == 2'b01)) begin
          I_FLAG_CLR <= 1'b1;
          // RETID (no other form)
          // Return with interrupts disabled
        end
        else if((OPCODE_LO_2 == 2'b10)) begin
          SCR_OE <= 1'b1;
          PC_MUX_SEL <= 2'b10;
          PC_LD <= 1'b1;
          INC_DEC <= 2'b10;
          SCR_ADDR_SEL <= 2'b01;
          I_FLAG_CLR <= 1'b1;
          C_FLAG_RESTORE <= 1'b1;
          Z_FLAG_RESTORE <= 1'b1;
          // RETIE (no other form)
          // Return with interrupts enabled
        end
        else begin
          SCR_OE <= 1'b1;
          PC_MUX_SEL <= 2'b10;
          PC_LD <= 1'b1;
          INC_DEC <= 2'b10;
          SCR_ADDR_SEL <= 2'b01;
          I_FLAG_SET <= 1'b1;
          C_FLAG_RESTORE <= 1'b1;
          Z_FLAG_RESTORE <= 1'b1;
        end
        // AND (reg/immed)
      end
      5'b10000 : begin
        ALU_SEL <= 4'h5;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        // OR (reg/immed)
      end
      5'b10001 : begin
        ALU_SEL <= 4'ha;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        // EXOR (reg/immed)
      end
      5'b10010 : begin
        ALU_SEL <= 4'h7;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        // TEST (reg/immed)
      end
      5'b10011 : begin
        ALU_SEL <= 4'hd;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        // ADD (reg/immed)
      end
      5'b10100 : begin
        ALU_SEL <= 4'h0;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        C_FLAG_LD <= 1'b1;
        // ADDC (reg/immed)
      end
      5'b10101 : begin
        ALU_SEL <= 4'h1;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        C_FLAG_LD <= 1'b1;
        // SUB (reg/immed)
      end
      5'b10110 : begin
        ALU_SEL <= 4'h3;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        C_FLAG_LD <= 1'b1;
        // SUBC (reg/immed)
      end
      5'b10111 : begin
        ALU_SEL <= 4'h4;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_WR <= 1'b1;
        RF_OE <= 1'b1;
        C_FLAG_LD <= 1'b1;
        // CMP (reg/immed)
      end
      5'b11000 : begin
        ALU_SEL <= 4'h2;
        ALU_MUX_SEL <= 1'b1;
        Z_FLAG_LD <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_OE <= 1'b1;
        // RF_WR<= '1'; DO NOT WRITE BACK TO REG!!!
        C_FLAG_LD <= 1'b1;
        // IN (no other form)
      end
      5'b11001 : begin
        RF_WR <= 1'b1;
        // OUT (no other form)
      end
      5'b11010 : begin
        RF_OE <= 1'b1;
        IO_OE <= 1'b1;
        // MOV (reg/immed)
      end
      5'b11011 : begin
        RF_WR <= 1'b1;
        RF_WR_SEL <= 2'b10;
        RF_OE <= 1'b1;
        ALU_MUX_SEL <= 1'b1;
        ALU_SEL <= 4'he;
        // LD (reg/immed)
      end
      5'b11100 : begin
        SCR_ADDR_SEL <= 2'b00;
        SCR_OE <= 1'b1;
        RF_WR <= 1'b1;
        RF_WR_SEL <= 2'b01;
        // ST (reg/immed)
      end
      5'b11101 : begin
        SCR_ADDR_SEL <= 2'b00;
        SCR_WR <= 1'b1;
        RF_OE <= 1'b1;
        // WSP (no other form)
      end
      5'b01010 : begin
        RF_OE <= 1'b1;
        SP_LD <= 1'b1;
      end
      default : begin
        // repeat the init block here to avoid incompletely specified outputs and hence avoid
        // the problem of inadvertently created latches within the synthesized system.						
        RESET <= 1'b0;
        PC_LD <= 1'b0;
        PC_MUX_SEL <= 2'b00;
        PC_OE <= 1'b0;
        SP_LD <= 1'b0;
        INC_DEC <= 2'b00;
        RF_WR <= 1'b0;
        RF_WR_SEL <= 2'b00;
        RF_OE <= 1'b0;
        ALU_MUX_SEL <= 1'b0;
        ALU_SEL <= 4'b0000;
        SCR_WR <= 1'b0;
        SCR_OE <= 1'b0;
        SCR_ADDR_SEL <= 2'b00;
        C_FLAG_SAVE <= 1'b0;
        C_FLAG_RESTORE <= 1'b0;
        C_FLAG_LD <= 1'b0;
        C_FLAG_SET <= 1'b0;
        C_FLAG_CLR <= 1'b0;
        Z_FLAG_RESTORE <= 1'b0;
        Z_FLAG_LD <= 1'b0;
        Z_FLAG_SET <= 1'b0;
        Z_FLAG_CLR <= 1'b0;
        I_FLAG_SET <= 1'b0;
        I_FLAG_CLR <= 1'b0;
        Z_FLAG_SAVE <= 1'b0;
        IO_OE <= 1'b0;
      end
      endcase
      // STATE: the interrupt cycle -----------------------------------
      // Do interrupt shit here @ the 3FF, yo
    end
    ST_int : begin
      NS <= ST_fet;
      RESET <= 1'b0;
      PC_LD <= 1'b1;
      PC_MUX_SEL <= 2'b11;
      PC_OE <= 1'b1;
      // ok				
      SP_LD <= 1'b0;
      INC_DEC <= 2'b01;
      // ok
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      RF_OE <= 1'b0;
      // ok
      ALU_MUX_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      // ok
      SCR_WR <= 1'b1;
      SCR_OE <= 1'b0;
      SCR_ADDR_SEL <= 2'b10;
      C_FLAG_SAVE <= 1'b1;
      // ok				
      C_FLAG_RESTORE <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      // ok
      Z_FLAG_RESTORE <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b0;
      // ok  
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b0;
      Z_FLAG_SAVE <= 1'b1;
      IO_OE <= 1'b0;
      // ok
    end
    default : begin
      NS <= ST_fet;
      // repeat the init block here to avoid incompletely specified outputs and hence avoid
      // the problem of inadvertently created latches within the synthesized system.
      RESET <= 1'b0;
      PC_LD <= 1'b0;
      PC_MUX_SEL <= 2'b00;
      PC_OE <= 1'b0;
      SP_LD <= 1'b0;
      INC_DEC <= 2'b00;
      RF_WR <= 1'b0;
      RF_WR_SEL <= 2'b00;
      RF_OE <= 1'b0;
      ALU_MUX_SEL <= 1'b0;
      ALU_SEL <= 4'b0000;
      SCR_WR <= 1'b0;
      SCR_OE <= 1'b0;
      SCR_ADDR_SEL <= 2'b00;
      C_FLAG_SAVE <= 1'b0;
      C_FLAG_RESTORE <= 1'b0;
      C_FLAG_LD <= 1'b0;
      C_FLAG_SET <= 1'b0;
      C_FLAG_CLR <= 1'b0;
      Z_FLAG_RESTORE <= 1'b0;
      Z_FLAG_LD <= 1'b0;
      Z_FLAG_SET <= 1'b0;
      Z_FLAG_CLR <= 1'b0;
      I_FLAG_SET <= 1'b0;
      I_FLAG_CLR <= 1'b0;
      Z_FLAG_SAVE <= 1'b0;
      IO_OE <= 1'b0;
    end
    endcase
  end
endmodule

