module reg8bits(
input wire rst,
input wire ck,
input wire ce,
input wire [7:0] di,
output reg [7:0] do
);
// This is a behaviorial description of a register. However, all
// the synthesis tools will be able to infer a flip-flop with synchronous reset
// and clock enable
  always @(posedge ck) begin
    if(rst == 1'b1) begin
      do <= 8'h00;
    end
    else begin
      if(ce == 1'b1) begin
        do <= di;
      end
    end
  end
endmodule

module generic_and(
input wire [N - 1:0] x,
output wire y
);
parameter [31:0] N=5;
//------------------------------------
wire temp[0:N - 1];
  assign temp[0] = x[0];
  genvar i;
  generate for (i=1; i <= N - 1; i = i + 1) begin: gen
      assign temp[i] = temp[i - 1] & x[i];
  end
  endgenerate
  assign y =  ~temp[N - 1];
//------------------------------------
endmodule

module hcc_mulfp1x(
input wire sysclk,
input wire reset,
input wire enable,
input wire [mantissa + 10:1] aa,
input wire aasat,
input wire aazip,
input wire [mantissa + 10:1] bb,
input wire bbsat,
input wire bbzip,
output wire [mantissa + 10:1] cc,
output wire ccsat,
output wire cczip
);
parameter [31:0] mantissa=32;
parameter [31:0] outputscale=1;
parameter [31:0] synthesize=1;
wire [mantissa + 10:1] mulinaa; wire [mantissa + 10:1] mulinbb;
wire mulinaasat; wire mulinaazip; wire mulinbbsat; wire mulinbbzip;
wire [mantissa + 10:1] ccnode;
wire [10:1] aaexp; wire [10:1] bbexp; wire [10:1] ccexp;
wire [mantissa:1] aaman; wire [mantissa:1] bbman; wire [mantissa:1] ccman;
  //**************************************************
  //***                                            ***
  //*** Input Section                              *** 
  //***                                            ***
  //**************************************************
  //********************************************************
  //*** ieee754 input when multiplier input is from cast ***
  //*** cast now creates different                       ***
  //*** formats for multiplier, divider, and alu         ***
  //*** multiplier format [S][1][mantissa....]           ***
  //********************************************************
  assign mulinaa = aa;
  assign mulinbb = bb;
  assign mulinaasat = aasat;
  assign mulinaazip = aazip;
  assign mulinbbsat = bbsat;
  assign mulinbbzip = bbzip;
  //**************************
  //*** Multiplier Section *** 
  //**************************
  // multiplier input in this form
  // [S ][1 ][M...M][U..U]
  // [32][31][30..8][7..1]
  generate if ((outputscale == 0)) begin: gma
      hcc_mulfp3236 #(
          .mantissa(mantissa),
      .synthesize(synthesize))
    mulone(
          .sysclk(sysclk),
      .reset(reset),
      .enable(enable),
      .aa(mulinaa),
      .aasat(mulinaasat),
      .aazip(mulinaazip),
      .bb(mulinbb),
      .bbsat(mulinbbsat),
      .bbzip(mulinbbzip),
      .cc(ccnode),
      .ccsat(ccsat),
      .cczip(cczip));
  end
  endgenerate
  generate if ((outputscale == 1)) begin: gmb
      hcc_mulfppn3236 #(
          .mantissa(mantissa),
      .synthesize(synthesize))
    multwo(
          .sysclk(sysclk),
      .reset(reset),
      .enable(enable),
      .aa(mulinaa),
      .aasat(mulinaasat),
      .aazip(mulinaazip),
      .bb(mulinbb),
      .bbsat(mulinbbsat),
      .bbzip(mulinbbzip),
      .cc(ccnode),
      .ccsat(ccsat),
      .cczip(cczip));
  end
  endgenerate
  //*** OUTPUTS ***
  assign cc = ccnode;
  //*** DEBUG SECTION ***
  assign aaexp = aa[10:1];
  assign bbexp = bb[10:1];
  assign ccexp = ccnode[10:1];
  assign aaman = aa[mantissa + 10:11];
  assign bbman = bb[mantissa + 10:11];
  assign ccman = ccnode[mantissa + 10:11];
endmodule

module baudGen(
input wire clr,
input wire clk,
input wire [11:0] baudFreq,
input wire [15:0] baudLimit,
output reg ce16
);
// global reset input
// global clock input
// baudFreq = 16 * baudRate / gcd(clkFreq, 16 * baudRate)
// baud rate setting registers - see header description
// baudLimit = clkFreq / gcd(clkFreq, 16 * baudRate) - baudFreq
// baud rate setting registers - see header description
// baud rate multiplyed by 16
reg [15:0] counter;
  // baud divider counter
  // clock divider output
  always @(posedge clr, posedge clk) begin
    if((clr == 1'b1)) begin
      counter <= {16{1'b0}};
      ce16 <= 1'b0;
    end else begin
      if((counter >= baudLimit)) begin
        counter <= counter - baudLimit;
        ce16 <= 1'b1;
      end
      else begin
        counter <= counter + baudFreq;
        ce16 <= 1'b0;
      end
    end
  end
endmodule

