module alu(
input wire [3:0] alu_ctrl,
input wire [31:0] alu_src1,
input wire [31:0] alu_src2,
output reg alu_zero,
output reg [31:0] alu_result,
output wire alu_carry
);
  always @(alu_src1, alu_src2, alu_ctrl) begin : P1
    reg [31:0] src1, src2, result;
    reg zero;
    //
    src1 = alu_src1;
    src2 = alu_src2;
    result = {1{1'b0}};
    zero = 1'b0;
    //
    case(alu_ctrl)
        //AND
    4'b0000 : begin
      result = src1 & src2;
      //OR
    end
    4'b0001 : begin
      result = src1 | src2;
      //ADD
    end
    4'b0010 : begin
      result = src1 + src2;
      //SUB
    end
    4'b0110 : begin
      result = src1 - src2;
      //SLT
    end
    4'b0111 : begin
      if(src1 < src2) begin
        result[0] = 1'b1;
      end
      else begin
        result[0] = 1'b0;
      end
      //NOR
    end
    4'b1100 : begin
      result =  ~(src1 | src2);
      //error
    end
    default : begin
      result = {1{1'b0}};
    end
    endcase
    if((result) == 0) begin
      zero = 1'b1;
    end
    else begin
      zero = 1'b0;
    end
    alu_result <= result;
    alu_zero <= zero;
  end
endmodule

module sub_517(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

