module ws2811Driver(
input wire clk,
input wire load,
input wire [23:0] datain,
output reg busy,
output reg dataout
);
reg [4:0] bitcount;
reg [4:0] subbitcount;  //signal count       : std_logic_vector(9 downto 0) := "1011111000";
wire countEnable;
reg [23:0] shiftData;
wire shiftEnable;
wire shiftOutput;
wire nextOutput;
  always @(posedge clk) begin
    if((load == 1'b1)) begin
      bitcount <= {5{1'b0}};
      subbitcount <= {5{1'b0}};
    end
    else if((countEnable == 1'b1)) begin
      subbitcount <= (subbitcount) + 1;
      if((subbitcount == 5'b10011)) begin
        bitcount <= (bitcount) + 1;
        subbitcount <= {5{1'b0}};
      end
    end
  end
  //process(clk)
  //begin
  //	if(rising_edge(clk)) then
  //		if(load = '1') then
  //			count <= (others => '0');
  //		elsif(countEnable = '1') then
  //			count <= std_logic_vector(unsigned(count) + 1);
  //		end if;
  //	end if;
  //end process;
  always @(posedge clk) begin
    if((load == 1'b1)) begin
      shiftData <= datain;
    end
    else if((shiftEnable == 1'b1)) begin
      shiftData <= {shiftData[22:0],1'b0};
    end
  end
  always @(posedge clk) begin
    dataout <= nextOutput;
  end
  always @(posedge clk) begin
    if((load == 1'b1)) begin
      busy <= 1'b1;
    end
    else if((bitcount == 5'b10111 && subbitcount == 5'b10001)) begin
      busy <= 1'b0;
    end
  end
  // freeze counter when it reaches 24 bytes (24*4 clocks)
  assign countEnable = bitcount == 5'b10111 && subbitcount == 5'b10011 ? 1'b0 : 1'b1;
  // enable shift every 4 clocks
  assign shiftEnable = subbitcount == 5'b10011 ? 1'b1 : 1'b0;
  assign shiftOutput = shiftData[23];
  // over a 4 clock period:
  //     for a 1 output 1 1 1 0
  //     for a 0 output 1 0 0 0
  assign nextOutput = subbitcount[4:2] == 3'b000 ? 1'b1 : subbitcount[4:2] == 3'b100 ? 1'b0 : shiftOutput;
endmodule

module genericregister(
input wire CLK,
input wire EN,
input wire RESET,
input wire [NUMBITS - 1:0] DATA_IN,
output wire [NUMBITS - 1:0] DATA_OUT
);
parameter [31:0] NUMBITS=16;
reg [NUMBITS - 1:0] reg = 1'b0;
  always @(posedge clk, posedge reset) begin
    if((RESET == 1'b1)) begin
      reg <= {((NUMBITS - 1)-(0)+1){1'b0}};
    end else begin
      if(EN == 1'b1) begin
        reg <= DATA_IN;
      end
    end
  end
  assign DATA_OUT = reg;
endmodule

module MUX(
output reg [7:0] TO_ALU,
input wire [7:0] FROM_Y,
input wire [7:0] FROM_IR,
input wire SEL
);
  always @(*) begin
    case(SEL)
      1'b0 : TO_ALU <= FROM_Y;
      1'b1 : TO_ALU <= FROM_IR;
      default : TO_ALU <= 8'b00000000;
    endcase
  end
endmodule

module spi_master_slave(
input wire clk_i,
input wire rst_i,
input wire [BYTE_SIZE - 1:0] data_i,
output wire [BYTE_SIZE - 1:0] data_o,
output reg data_valid_o,
input wire wren_i,
input wire [8:0] clk_div_i,
input wire spi_ssn_i,
input wire spi_clk_i,
output reg spi_clk_o,
output reg spi_do_o,
input wire spi_di_i
);
parameter [31:0] BYTE_SIZE=8;
// core interface
// parallel data in (clocked on rising spi_clk after last bit)
// parallel data output (clocked on rising spi_clk after last bit)
// data valid (read / write finished)
// data write enable, starts transmission when interface is idle
// SPI clock divider
// SPI interface
// spi slave select negated input
// spi slave clock input
// spi master clock output
// spi mosi (master mode) or miso (slave mode)
// spi miso (master mode) or mosi (slave mode)
parameter [2:0]
  idle = 0,
  data1 = 1,
  clock1 = 2,
  data2 = 3,
  clock2 = 4,
  sdata1 = 5,
  sdata2 = 6,
  done = 7;
reg [2:0] state;
reg [BYTE_SIZE - 1:0] data_reg;
reg [8:0] clk_cnt;
reg [8:0] counter;
wire fsm_trigger;
  always @(posedge clk_i, posedge rst_i) begin
    if(rst_i == 1'b1) begin
      clk_cnt <= {9{1'b0}};
    end else begin
      if((clk_cnt < clk_div_i)) begin
        clk_cnt <= clk_cnt + 1;
      end
      else begin
        clk_cnt <= {9{1'b0}};
      end
    end
  end
  assign fsm_trigger = clk_cnt == 9'b000000000 || spi_ssn_i == 1'b0 ? 1'b1 : 1'b0;
  always @(posedge clk_i, posedge rst_i, posedge spi_clk_i, posedge fsm_trigger) begin
    if(rst_i == 1'b1) begin
      data_reg <= {((BYTE_SIZE - 1)-(0)+1){1'b0}};
      counter <= {9{1'b0}};
      data_valid_o <= 1'b0;
      spi_clk_o <= 1'b0;
      spi_do_o <= 1'b0;
    end else begin
      if((fsm_trigger == 1'b1)) begin
        case(state)
        idle : begin
          counter <= {9{1'b0}};
          spi_clk_o <= 1'b0;
          spi_do_o <= 1'b0;
          data_valid_o <= 1'b0;
          data_reg <= data_i;
        end
        data1 : begin
          data_valid_o <= 1'b0;
          spi_do_o <= data_reg[BYTE_SIZE - 1];
        end
        clock1 : begin
          spi_clk_o <= 1'b1;
        end
        data2 : begin
          data_reg <= {data_reg[BYTE_SIZE - 2:0],spi_di_i};
        end
        clock2 : begin
          spi_clk_o <= 1'b0;
          counter <= counter + 1;
        end
        sdata1 : begin
          data_valid_o <= 1'b0;
          spi_do_o <= data_reg[BYTE_SIZE - 1];
        end
        sdata2 : begin
          if((spi_clk_i == 1'b0)) begin
            data_reg <= {data_reg[BYTE_SIZE - 2:0],spi_di_i};
            spi_do_o <= data_reg[BYTE_SIZE - 1];
            counter <= counter + 1;
          end
        end
        done : begin
          counter <= {9{1'b0}};
          data_valid_o <= 1'b1;
          spi_do_o <= 1'b0;
        end
        default : begin
        end
        endcase
      end
    end
  end
  assign data_o = data_reg;
  always @(posedge clk_i, posedge rst_i, posedge state, posedge counter, posedge wren_i, posedge spi_ssn_i, posedge spi_clk_i, posedge fsm_trigger) begin
    if(rst_i == 1'b1) begin
      state <= idle;
    end else begin
      if((fsm_trigger == 1'b1)) begin
        case(state)
        idle : begin
          if((spi_ssn_i == 1'b1)) begin
            if((wren_i == 1'b1)) begin
              state <= data1;
            end
          end
          else begin
            state <= sdata1;
          end
        end
        data1 : begin
          state <= clock1;
        end
        clock1 : begin
          state <= data2;
        end
        data2 : begin
          state <= clock2;
        end
        clock2 : begin
          if((counter < (BYTE_SIZE - 1))) begin
            state <= data1;
          end
          else begin
            state <= done;
          end
        end
        sdata1 : begin
          if((spi_clk_i == 1'b1)) begin
            state <= sdata2;
          end
        end
        sdata2 : begin
          if((spi_clk_i == 1'b0)) begin
            if((counter < (BYTE_SIZE - 1))) begin
              state <= sdata1;
            end
            else begin
              state <= done;
            end
          end
        end
        done : begin
          if((spi_ssn_i == 1'b1)) begin
            if((wren_i == 1'b0)) begin
              state <= idle;
            end
          end
          else begin
            if((spi_clk_i == 1'b1)) begin
              state <= sdata1;
            end
          end
        end
        default : begin
        end
        endcase
      end
    end
  end
endmodule

