module boothDecoder(
input wire [31:0] md,
input wire [2:0] decMr,
output wire [32:0] out1
);
wire [31:0] notMD;
wire [32:0] multMD;
wire [32:0] multNotMD;
  assign notMD = ( ~md) + 1'b1;
  assign multMD = {md,1'b0};
  assign multnotMD = {notMD,1'b0};
  assign out1 = decMr == 3'b000 || decMr == 3'b111 ? {33{1'b0}} : ((decMr == 3'b001 || decMr == 3'b010) && md[31] == 1'b1) ? {1'b1,md} : ((decMr == 3'b001 || decMr == 3'b010) && md[31] == 1'b0) ? {1'b0,md} : decMr == 3'b011 ? multMD : decMr == 3'b100 ? multnotMD : ((decMr == 3'b101 || decMr == 3'b110) && notMD[31] == 1'b1) ? {1'b1,notMD} : ((decMr == 3'b101 || decMr == 3'b110) && notMD[31] == 1'b0) ? {1'b0,notMD} : {33{1'b0}};
endmodule

module lms_pcore_cop(
input wire clk,
input wire reset,
input wire in_strobe,
input wire cop_enable,
output reg out_ready,
output reg dut_enable,
output reg reg_strobe
);
// ufix1
// ufix1
// ufix1
// ufix1
// ufix1
// Signals
wire enb;
reg [7:0] cp_controller_cpstate;  // uint8
reg cp_controller_clkcnt;  // ufix1
reg [7:0] cp_controller_cpstate_next;  // uint8
reg cp_controller_clkcnt_next;  // ufix1
  assign enb = cop_enable;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      cp_controller_cpstate <= 'H00;
      cp_controller_clkcnt <= 1'b0;
    end else begin
      if(enb == 1'b1) begin
        cp_controller_cpstate <= cp_controller_cpstate_next;
        cp_controller_clkcnt <= cp_controller_clkcnt_next;
      end
    end
  end
  always @(cp_controller_cpstate, cp_controller_clkcnt, in_strobe) begin : P1
    reg clkcnt_temp;
    reg [1:0] add_cast;
    reg [1:0] add_temp;
    cp_controller_cpstate_next <= cp_controller_cpstate;
    case(cp_controller_cpstate)
    8'b00000000 : begin
      out_ready <= 1'b1;
      dut_enable <= 1'b0;
      reg_strobe <= 1'b0;
      clkcnt_temp = 1'b0;
      if(in_strobe != 1'b0) begin
        cp_controller_cpstate_next <= 'H01;
      end
      else begin
        cp_controller_cpstate_next <= 'H00;
      end
    end
    8'b00000001 : begin
      out_ready <= 1'b0;
      dut_enable <= 1'b1;
      reg_strobe <= 1'b0;
      add_cast = {1'b0,cp_controller_clkcnt};
      add_temp = add_cast + ('H1);
      clkcnt_temp = add_temp[0];
      if(clkcnt_temp == 1'b1) begin
        cp_controller_cpstate_next <= 'H02;
      end
      else begin
        cp_controller_cpstate_next <= 'H01;
      end
    end
    8'b00000010 : begin
      out_ready <= 1'b0;
      dut_enable <= 1'b0;
      reg_strobe <= 1'b1;
      clkcnt_temp = 1'b0;
      cp_controller_cpstate_next <= 'H00;
    end
    default : begin
      out_ready <= 1'b0;
      dut_enable <= 1'b0;
      reg_strobe <= 1'b0;
      clkcnt_temp = 1'b0;
      cp_controller_cpstate_next <= 'H00;
    end
    endcase
    cp_controller_clkcnt_next <= clkcnt_temp;
  end
endmodule

