module Extender(
input wire [N - 1:0] A,
output reg [(2 * N) - 1:0] Y
);
parameter [31:0] N=8;
  always @(A) begin
    if((A[N - 1] == 1'b0)) begin
      Y[N - 1:0] <= A;
      Y[(2 * N) - 1:N] <= {(((2 * N) - 1)-(N)+1){1'b0}};
    end
    else begin
      Y[N - 1:0] <= A;
      Y[(2 * N) - 1:N] <= {(((2 * N) - 1)-(N)+1){1'b1}};
    end
  end
endmodule

module counter_BCD(
input wire clock_enable,
input wire clock,
input wire reset,
output wire [0:3] output
);
reg [0:3] temp;
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b1) begin
      temp <= 4'b0000;
    end else begin
      if((clock_enable == 1'b0)) begin
        if(temp == 4'b1010) begin
          temp <= 4'b0000;
        end
        else begin
          temp <= temp + 1;
        end
      end
    end
  end
  assign output = temp;
endmodule

