module controller(
input wire clk,
input wire reset,
output reg fitness_reset,
output reg fitness_clk,
input wire fitness_done,
output reg memory_rwbar,
output reg memory_en,
output reg memory_reset
);
parameter [2:0]
  rst = 0,
  fitness_process = 1,
  memory_read = 2,
  increase = 3,
  memory_write = 4;
reg [2:0] next_state; reg [2:0] current_state;
  // next
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      current_state <= rst;
    end
    else begin
      current_state <= next_state;
    end
  end
  // outputs
  always @(current_state) begin
    if(current_state == rst) begin
      fitness_reset <= 1'b1;
      fitness_clk <= 1'b0;
      memory_reset <= 1'b1;
      memory_en <= 1'b0;
    end
    else if(current_state == fitness_process) begin
      if(fitness_done == 1'b0) begin
        fitness_clk <= 1'b1;
      end
      memory_reset <= 1'b0;
      memory_en <= 1'b0;
    end
    else if(current_state == memory_read) begin
      memory_rwbar <= 1'b1;
      memory_en <= 1'b1;
      fitness_clk <= 1'b0;
    end
    else if(current_state == memory_write) begin
      memory_rwbar <= 1'b0;
    end
  end
  // next_state
  always @(current_state) begin
    if(current_state == rst) begin
      next_state <= fitness_process;
    end
    else if(current_state == fitness_process) begin
      if(fitness_done == 1'b0) begin
        next_state <= memory_read;
      end
      else begin
        next_state <= rst;
      end
    end
    else if(current_state == memory_read) begin
      next_state <= increase;
    end
    else if(current_state == increase) begin
      next_state <= memory_write;
    end
    else if(current_state == memory_write) begin
      next_state <= fitness_process;
    end
  end
endmodule

