module pwm10bit(
input wire clk,
input wire adc_samplingrate,
input wire [2:0] adc_channel,
input wire adc_miso,
output wire adc_mosi,
output wire adc_cs,
output wire adc_clk,
output wire [15:0] adc_value,
output wire adc_valid,
output reg pwm_out
);
// ADC SPI MISO
// ADC SPI MOSI
// ADC SPI CHIP SELECT
// ADC SPI CLOCK
// From http://www.micro-nova.com/resources/
reg [31:0] threshold = 0;
reg [31:0] counter = 0;
wire [9:0] adc_out;
wire adc_pulse;
  // map to output and extend to 16 bits
  assign adc_value = {6'b000000,adc_out};
  assign adc_valid = adc_pulse;
  MercuryADC adc(
      // command input
    .clock(clk),
    // from onboard oscillator
    .trigger(adc_samplingrate),
    // assert to sample ADC
    .diffn(1'b1),
    // single/differential inputs
    .channel(adc_channel),
    // channel to sample (3 == light sensor)
    // data output
    .Dout(adc_out),
    // data from ADC
    .OutVal(adc_pulse),
    // pulsed when data sampled
    // ADC connection
    .adc_miso(adc_miso),
    // ADC SPI MISO
    .adc_mosi(adc_mosi),
    // ADC SPI MOSI
    .adc_cs(adc_cs),
    // ADC SPI CHIP SELECT
    .adc_clk(adc_clk));
  always @(adc_pulse) begin
    if((adc_pulse == 1'b1)) begin
      threshold <= adc_out;
    end
  end
  always @(posedge clk) begin
    counter <= counter + 1;
    // just let it wrap around
    if((counter > threshold)) begin
      pwm_out <= 1'b0;
    end
    else begin
      pwm_out <= 1'b1;
    end
  end
endmodule

