module ClockManager(
input wire clk,
output wire clk_50mhz,
output wire clk_100mhz
);
// The system clock.
// The 50 MHz clock.
// The 100 MHz clock.
wire clk50_unbuf; wire clk50_buf;
wire clk100_unbuf; wire clk100_buf;
  //------------------------------------------------------------------------------
  // Connections to and from internal signals.
  //------------------------------------------------------------------------------
  assign clk_50mhz = clk;
  assign clk_100mhz = clk100_buf;
  //------------------------------------------------------------------------------
  // Instantiate components.
  //------------------------------------------------------------------------------
  DCM #(
      .CLKIN_PERIOD(20.0),
    // DLL attributes
    .CLK_FEEDBACK(2'b1X),
    .DLL_FREQUENCY_MODE(3'bLOW),
    .CLKIN_DIVIDE_BY_2(FALSE),
    .CLKDV_DIVIDE(2.0),
    .DUTY_CYCLE_CORRECTION(TRUE),
    // DFS attributes
    .DFS_FREQUENCY_MODE(3'bLOW),
    .CLKFX_MULTIPLY(2),
    .CLKFX_DIVIDE(1))
  dcm_instance(
      .RST(1'b0),
    .CLKIN(clk),
    .CLKFB(clk50_buf),
    .PSEN(1'b0),
    .PSCLK(1'b0),
    .PSINCDEC(1'b0),
    .CLK0(clk50_unbuf),
    .CLK90(/* open */),
    .CLK180(/* open */),
    .CLK270(/* open */),
    .CLK2X(/* open */),
    .CLK2X180(/* open */),
    .CLKDV(/* open */),
    .CLKFX(clk100_unbuf),
    .CLKFX180(/* open */),
    .LOCKED(/* open */),
    .STATUS(/* open */),
    .PSDONE(/* open */));
  BUFG clk50_bufg(
      .I(clk50_unbuf),
    .O(clk50_buf));
  BUFG clk100_bufg(
      .I(clk100_unbuf),
    .O(clk100_buf));
endmodule

module mult_n(
input wire [Nb - 1:0] in_a,
input wire [Nb - 1:0] in_b,
output wire [2 * Nb - 1:0] mult_out
);
parameter [31:0] Nb=9;
reg [(2 * Nb) - 1:0] mult_signed;
  always @(in_a, in_b) begin
    mult_signed <= (in_a) * (in_b);
  end
  assign mult_out = mult_signed;
endmodule

module mask(
input wire [15:0] input,
output reg [15:0] output
);
  always @(input) begin : P1
    reg [15:0] tmp;
    output <= tmp;
    //this shouln't really change anything
    tmp = input;
    tmp = tmp & 16'b1010101010101010;
    output <= tmp;
  end
endmodule

