module debounce(
input wire clk,
input wire signal_in,
output reg signal_out
);
reg [23:0] c;
  always @(posedge clk) begin
    if(signal_in == 1'b1) begin
      if(c == 24'hFFFFFF) begin
        signal_out <= 1'b1;
      end
      else begin
        signal_out <= 1'b0;
      end
      c <= c + 1;
    end
    else begin
      c <= {24{1'b0}};
      signal_out <= 1'b0;
    end
  end
endmodule

