module uart_transmit(
input wire rst_i,
input wire clk_i,
input wire TopTX,
input wire [7:0] Din_i,
output wire Tx_o,
output reg TxBusy_o,
input wire LD_i
);
parameter [1:0]
  idle = 0,
  load_tx = 1,
  shift_tx = 2,
  stop_tx = 3;
reg [9:0] Tx_Reg;
reg [7:0] RegDin;
reg [31:0] TxBitCnt;
reg [1:0] TxFSM;
  // --------------------------
  // Transmit State Machine
  // --------------------------
  assign TX_o = Tx_Reg[0];
  always @(posedge rst_i, posedge clk_i) begin
    if(rst_i == 1'b1) begin
      Tx_Reg <= {10{1'b1}};
      TxBitCnt <= 0;
      TxFSM <= idle;
      TxBusy_o <= 1'b0;
      RegDin <= {8{1'b0}};
    end else begin
      case(TxFSM)
      Idle : begin
        if(Ld_i == 1'b1) begin
          TxFSM <= Load_tx;
          RegDin <= Din_i;
          TxBusy_o <= 1'b1;
        end
      end
      Load_Tx : begin
        if(TopTX == 1'b1) begin
          TxFSM <= Shift_tx;
          TxBitCnt <= 10;
          Tx_Reg <= {1'b1,RegDin,1'b0};
        end
      end
      Shift_Tx : begin
        if(TopTX == 1'b1) begin
          if(TXBitCnt == 1) begin
            TxFSM <= Stop_tx;
          end
          TxBitCnt <= TxBitCnt - 1;
          Tx_Reg <= {1'b1,Tx_Reg[9:1]};
        end
      end
      Stop_Tx : begin
        if(TopTX == 1'b1) begin
          TxFSM <= Idle;
          TxBusy_o <= 1'b0;
        end
      end
      default : begin
        TxFSM <= Idle;
      end
      endcase
    end
  end
endmodule

