module adder(
input wire [N - 1:0] A,
input wire [N - 1:0] B,
input wire Cin,
output wire [N - 1:0] S,
output wire Cout,
output wire overflow
);
parameter [31:0] N=4;
wire [0:N] C;
  assign C[0] = Cin;
  assign Cout = C[N];
  assign overflow = C[N - 1] ^ C[N];
  genvar I;
  generate for (I=0; I <= N - 1; I = I + 1) begin: gen_adders
      full_adder gen_fa(
          .A(A[I]),
      .B(B[I]),
      .Cin(C[I]),
      .S(S[I]),
      .Cout(C[I + 1]));
  end
  endgenerate
endmodule

module up_down_counter(
input wire clk,
input wire resetn,
input wire sraz,
input wire en,
input wire load,
input wire up_downn,
input wire [NBIT - 1:0] E,
output wire [NBIT - 1:0] Q
);
parameter [31:0] NBIT=4;
reg [NBIT - 1:0] Qp;
  always @(posedge clk, posedge resetn) begin
    if(resetn == 1'b0) begin
      Qp <= {((NBIT - 1)-(0)+1){1'b0}};
    end else begin
      if(sraz == 1'b1) begin
        Qp <= {((NBIT - 1)-(0)+1){1'b0}};
      end
      else if(load == 1'b1) begin
        Qp <= E;
      end
      else if(en == 1'b1) begin
        if(up_downn == 1'b1) begin
          Qp <= Qp + 1;
        end
        else begin
          Qp <= Qp - 1;
        end
      end
    end
  end
  // concurrent assignment statement
  assign Q = Qp;
endmodule

