module clk0_5Hz(
input wire clk,
input wire reset,
output wire clk_out
);
// Reloj de entrada de 50000000Hz.
// Reloj de salida de 0.5Hz.
reg temporal;
reg [31:0] contador = 0;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      temporal <= 1'b0;
      contador <= 0;
    end else begin
      if((contador == 49999999)) begin
        temporal <=  ~(temporal);
        contador <= 0;
      end
      else begin
        contador <= contador + 1;
      end
    end
  end
  assign clk_out = temporal;
endmodule

