module logic(
input wire [2:0] Control,
input wire [31:0] Operand1,
input wire [31:0] Operand2,
output reg [31:0] Result1,
output reg [31:0] Result2,
output reg [27:0] Debug
);
  always @(Control, Operand1, Operand2) begin : P1
    reg [31:0] temp;
    case(Control)
    3'b000 : begin
      // NOP
      Result1 <= Operand1;
      Result2 <= Operand2;
      Debug <= 28'h0000000;
    end
    3'b001 : begin
      // AND
      Result1 <= Operand1 & Operand2;
      Result2 <= 32'h00000000;
      Debug <= 28'h0000000;
    end
    3'b010 : begin
      // OR
      Result1 <= Operand1 | Operand2;
      Result2 <= 32'h00000000;
      Debug <= 28'h0000000;
    end
    3'b011 : begin
      // XOR
      Result1 <= Operand1 ^ Operand2;
      Result2 <= 32'h00000000;
      Debug <= 28'h0000000;
    end
    3'b100 : begin
      // NOR
      Result1 <=  ~(Operand1 | Operand2);
      Result2 <= 32'h00000000;
      Debug <= 28'h0000000;
    end
    default : begin
      Result1 <= 32'hFFFFFFFF;
      Result2 <= 32'hFFFFFFFF;
      Debug <= 28'hFFFFFFF;
    end
    endcase
  end
endmodule

