module solenoid_controller(
input wire clock,
output reg [7:0] status,
input wire [7:0] control,
input wire chip_select,
input wire write_enable,
input wire btn_shift_up_in,
input wire btn_shift_down_in,
output reg sol_shift_up_out,
output reg sol_shift_down_out,
output reg irq_btn_out,
input wire reset
);
// clock
// read
// write
// cs
// write enable
// conduit_end.export
// conduit_end.export
// conduit_end.export
// conduit_end.export
// conduit_end.export
// reset
reg handling_btn = 1'b0;
reg handling_control = 1'b0;
reg [7:0] tmp_control = 8'b00000000;
  always @(posedge clock, posedge reset) begin
    if((reset == 1'b1)) begin
      irq_btn_out <= 1'b0;
      status <= 8'b00000000;
      sol_shift_up_out <= 1'b0;
      sol_shift_down_out <= 1'b0;
      handling_btn <= 1'b0;
      handling_control <= 1'b0;
    end else begin
      if((btn_shift_up_in == 1'b1 && handling_btn == 1'b0)) begin
        handling_btn <= 1'b1;
        status <= 8'b00000001;
        irq_btn_out <= 1'b1;
      end
      else if((btn_shift_down_in == 1'b1 && handling_btn == 1'b0)) begin
        handling_btn <= 1'b1;
        status <= 8'b00000010;
        irq_btn_out <= 1'b1;
      end
      else if((btn_shift_up_in == 1'b0 && btn_shift_down_in == 1'b0)) begin
        handling_btn <= 1'b0;
        status <= 8'b00000000;
      end
      if((write_enable == 1'b1 && chip_select == 1'b1)) begin
        tmp_control <= control;
      end
      if((tmp_control == 8'b00000000)) begin
        sol_shift_up_out <= 1'b0;
        sol_shift_down_out <= 1'b0;
      end
      else if(((tmp_control & 8'b10000000) == 128)) begin
        irq_btn_out <= 1'b0;
        status <= 8'b00000000;
      end
      else if(((tmp_control & 8'b00000001) == 1)) begin
        sol_shift_up_out <= 1'b1;
        sol_shift_down_out <= 1'b0;
      end
      else if(((tmp_control & 8'b00000010) == 2)) begin
        sol_shift_up_out <= 1'b0;
        sol_shift_down_out <= 1'b1;
      end
    end
  end
// of solenoid_controller
endmodule

