module ip_pwm_out(
input wire reset_n,
input wire clk,
input wire [7:0] pwm_hz,
input wire pwm_dir,
input wire [7:0] pwm_duty,
output wire pwm_pin_duty,
output wire pwm_pin_dir
);
reg [7:0] pwm_cnt_div;
reg pwm_cnt_div_p;
reg pwm_cnt_div_pp;
reg [7:0] pwm_cnt;
reg pwm_cnt_p;
reg pwm_pin_duty_p;
  assign pwm_pin_duty = pwm_pin_duty_p;
  assign pwm_pin_dir = pwm_dir;
  // PWM 분주 타이머 
  //
  always @(posedge clk) begin
    if(reset_n == 1'b0) begin
      pwm_cnt_div <= {8{1'b0}};
    end
    else begin
      pwm_cnt_div <= pwm_cnt_div + 1;
    end
  end
  always @(posedge clk) begin
    case(pwm_hz)
    8'h00 : begin
      pwm_cnt_div_p <= pwm_cnt_div[0];
    end
    8'h01 : begin
      pwm_cnt_div_p <= pwm_cnt_div[1];
    end
    8'h02 : begin
      pwm_cnt_div_p <= pwm_cnt_div[2];
    end
    8'h03 : begin
      pwm_cnt_div_p <= pwm_cnt_div[3];
    end
    8'h04 : begin
      pwm_cnt_div_p <= pwm_cnt_div[4];
    end
    8'h05 : begin
      pwm_cnt_div_p <= pwm_cnt_div[5];
    end
    8'h06 : begin
      pwm_cnt_div_p <= pwm_cnt_div[6];
    end
    8'h07 : begin
      pwm_cnt_div_p <= pwm_cnt_div[7];
    end
    default : begin
      pwm_cnt_div_p <= pwm_cnt_div[0];
    end
    endcase
    pwm_cnt_div_pp <= pwm_cnt_div_p;
    if(pwm_cnt_div_pp == 1'b0 && pwm_cnt_div_p == 1'b1) begin
      pwm_cnt_p <= 1'b1;
    end
    else begin
      pwm_cnt_p <= 1'b0;
    end
  end
  // PWM 기본 타이머 
  //
  always @(posedge clk) begin
    if(reset_n == 1'b0) begin
      pwm_cnt <= {8{1'b0}};
    end
    else begin
      if(pwm_cnt_p == 1'b1) begin
        pwm_cnt <= pwm_cnt + 1;
      end
    end
  end
  // PWM 출력 
  //
  always @(posedge clk) begin
    if(reset_n == 1'b0) begin
      pwm_pin_duty_p <= 1'b0;
    end
    else begin
      if(pwm_cnt < pwm_duty) begin
        if(pwm_duty == 8'h00) begin
          pwm_pin_duty_p <= 1'b0;
        end
        else begin
          pwm_pin_duty_p <= 1'b1;
        end
      end
      else begin
        if(pwm_duty == 8'hFF) begin
          pwm_pin_duty_p <= 1'b1;
        end
        else begin
          pwm_pin_duty_p <= 1'b0;
        end
      end
    end
  end
endmodule

module fifo(
input wire clk_i,
input wire rst_i,
input wire push_i,
input wire pop_i,
output wire full_o,
output wire empty_o,
input wire [bit_width - 1:0] d_i,
output wire [bit_width - 1:0] q_o
);
parameter [31:0] depth;
parameter [31:0] bit_width;
// calculate the number of words from 
//   the depth (which is like the address width)
parameter number_of_words = 2 ** depth;  // define data type of the storage array
  // define the storage array          
reg [bit_width - 1:0] fifo_data[0:number_of_words - 1];  // read and write index pointers
//  give them one bit more then needed to quickly check for overflow
//  by looking at the most significant bit (tip from Matthias Kreider)
reg [depth:0] w_idx;
reg [depth:0] r_idx;
  always @(posedge clk_i) begin
    if(rst_i == 1'b1) begin
      // reset is active high
      // force reset state
      w_idx <= {((depth)-(0)+1){1'b0}};
      r_idx <= {((depth)-(0)+1){1'b0}};
    end
    else begin
      // normal operation:
      //  writing
      if(push_i == 1'b1) begin
        fifo_data[w_idx[depth - 1:0]] <= d_i;
        w_idx <= w_idx + 1;
      end
      //  reading
      if(pop_i == 1'b1) begin
        r_idx <= r_idx + 1;
      end
    end
  end
  assign q_o = fifo_data[r_idx[depth - 1:0]];
  assign full_o = (r_idx[depth - 1:0] == w_idx[depth - 1:0]) ? r_idx[depth] ^ w_idx[depth] : 1'b0;
  assign empty_o = (r_idx[depth - 1:0] == w_idx[depth - 1:0]) ?  ~(r_idx[depth] ^ w_idx[depth]) : 1'b0;
endmodule

