module vga_control(
input wire pixel_clock,
output reg h_sync,
output reg v_sync,
output wire n_blank,
output wire n_sync,
output reg [31:0] row,
output reg [31:0] col
);
// constants
parameter [31:0] h_pixels=640;
parameter [31:0] h_fp=16;
parameter [31:0] h_pulse=96;
parameter [31:0] h_bp=48;
parameter [31:0] v_pixels=480;
parameter [31:0] v_fp=11;
parameter [31:0] v_pulse=2;
parameter [31:0] v_bp=33;
parameter h_period = h_pulse + h_bp + h_pixels + h_fp;
parameter v_period = v_pulse + v_bp + v_pixels + v_fp;
reg power_on = 1'b0;
  assign n_blank = 1'b1;
  assign n_sync = 1'b0;
  always @(posedge pixel_clock) begin : P1
    reg [31:0] h_count = 0;
    reg [31:0] v_count = 0;
    if((power_on == 1'b0)) begin
      h_count = 0;
      v_count = 0;
      h_sync <= 1'b1;
      v_sync <= 1'b1;
      col <= 0;
      row <= 0;
      power_on <= 1'b1;
    end else begin
      // counters
      if((h_count < (h_period - 1))) begin
        h_count = h_count + 1;
      end
      else begin
        h_count = 0;
        if((v_count < (v_period - 1))) begin
          v_count = v_count + 1;
        end
        else begin
          v_count = 0;
        end
      end
      // horizontal sync signal
      if((h_count < (h_pixels + h_fp) || h_count > (h_pixels + h_fp + h_pulse))) begin
        h_sync <= 1'b1;
      end
      else begin
        h_sync <= 1'b0;
      end
      // vertical sync signal
      if((v_count < (v_pixels + v_fp) || v_count > (v_pixels + v_fp + v_pulse))) begin
        v_sync <= 1'b1;
      end
      else begin
        v_sync <= 1'b0;
      end
      // set pixel coordinates
      if((h_count < h_pixels)) begin
        col <= h_count;
      end
      if((v_count < v_pixels)) begin
        row <= v_count;
      end
    end
  end
endmodule

