  assign valid = active;
  assign output = x;
  always @(posedge clk_100MHz) begin
    last <= input;
    //if(timer > time_val)then
    if((x < vga_width)) begin
      x <= x + 1;
      active <= 1'b1;
    end
    //	timer <= (others=>'0');
    //end if;
    //timer <= timer + 1;
    if((x >= vga_width && (((input) >= (value) && (last) <= (value))))) begin
      x <= {((log2[vga_width] - 1)-(0)+1){1'b0}};
      active <= 1'b0;
    end
  end
endmodule

module MX_3(
