);
  assign OUT_A = IN_C == 1'b0 ? IN_A : IN_B;
endmodule

module T80(
input wire RESET_n,
input wire CLK_n,
input wire CEN,
input wire WAIT_n,
input wire INT_n,
input wire NMI_n,
input wire BUSRQ_n,
output reg M1_n,
output wire IORQ,
output wire NoRead,
output wire Write,
output reg RFSH_n,
output wire HALT_n,
output wire BUSAK_n,
output reg [15:0] A,
input wire [7:0] DInst,
input wire [7:0] DI,
output reg [7:0] DO,
output wire [2:0] MC,
output wire [2:0] TS,
output wire IntCycle_n,
output wire NMICycle_n,
output wire IntE,
output wire Stop,
input wire out0,
output wire [211:0] REG,
input wire DIRSet,
input wire [211:0] DIR
);
parameter [31:0] Mode=0;
parameter [31:0] IOWait=0;
parameter [31:0] Flag_C=0;
parameter [31:0] Flag_N=1;
parameter [31:0] Flag_P=2;
parameter [31:0] Flag_X=3;
parameter [31:0] Flag_H=4;
parameter [31:0] Flag_Y=5;
parameter [31:0] Flag_Z=6;
parameter [31:0] Flag_S=7;
// 0 => OUT(C),0, 1 => OUT(C),255
// IFF2, IFF1, IM, IY, HL', DE', BC', IX, HL, DE, BC, PC, SP, R, I, F', A', F, A
// IFF2, IFF1, IM, IY, HL', DE', BC', IX, HL, DE, BC, PC, SP, R, I, F', A', F, A
parameter aNone = 3'b111;
parameter aBC = 3'b000;
parameter aDE = 3'b001;
parameter aXY = 3'b010;
parameter aIOA = 3'b100;
parameter aSP = 3'b101;
parameter aZI = 3'b110;  // Registers
reg [7:0] ACC; reg [7:0] F;
reg [7:0] Ap; reg [7:0] Fp;
reg [7:0] I;
reg [7:0] R;
reg [15:0] SP; reg [15:0] PC;
reg [7:0] RegDIH;
reg [7:0] RegDIL;
wire [15:0] RegBusA;
wire [15:0] RegBusB;
wire [15:0] RegBusC;
reg [2:0] RegAddrA_r;
wire [2:0] RegAddrA;
reg [2:0] RegAddrB_r;
wire [2:0] RegAddrB;
reg [2:0] RegAddrC;
reg RegWEH;
reg RegWEL;
reg Alternate;  // Help Registers
reg [15:0] WZ;  // MEMPTR register
reg [7:0] IR;  // Instruction register
reg [1:0] ISet;  // Instruction set selector
reg [15:0] RegBusA_r;
wire [15:0] ID16;
wire [7:0] Save_Mux;
reg [2:0] TState;
reg [2:0] MCycle;
reg IntE_FF1;
reg IntE_FF2;
reg Halt_FF;
reg BusReq_s;
reg BusAck;
wire ClkEn;
reg NMI_s;
reg [1:0] IStatus;
wire [7:0] DI_Reg;
wire T_Res;
reg [1:0] XY_State;
reg [2:0] Pre_XY_F_M;
wire NextIs_XY_Fetch;
reg XY_Ind;
reg No_BTR;
reg BTR_r;
wire Auto_Wait;
reg Auto_Wait_t1;
reg Auto_Wait_t2;
reg IncDecZ;  // ALU signals
reg [7:0] BusB;
reg [7:0] BusA;
wire [7:0] ALU_Q;
wire [7:0] F_Out;  // Registered micro code outputs
reg [4:0] Read_To_Reg_r;
reg Arith16_r;
reg Z16_r;
reg [3:0] ALU_Op_r;
reg Save_ALU_r;
reg PreserveC_r;
reg [2:0] MCycles;  // Micro code outputs
wire [2:0] MCycles_d;
wire [2:0] TStates;
reg IntCycle;
reg NMICycle;
wire Inc_PC;
wire Inc_WZ;
wire [3:0] IncDec_16;
wire [1:0] Prefix;
wire Read_To_Acc;
wire Read_To_Reg;
wire [3:0] Set_BusB_To;
wire [3:0] Set_BusA_To;
wire [3:0] ALU_Op;
wire Save_ALU;
wire PreserveC;
wire Arith16;
wire [2:0] Set_Addr_To;
wire Jump;
wire JumpE;
wire JumpXY;
wire Call;
wire RstP;
wire LDZ;
wire LDW;
wire LDSPHL;
wire IORQ_i;
wire [2:0] Special_LD;
wire ExchangeDH;
wire ExchangeRp;
wire ExchangeAF;
wire ExchangeRS;
wire I_DJNZ;
wire I_CPL;
wire I_CCF;
wire I_SCF;
wire I_RETN;
wire I_BT;
wire I_BC;
wire I_BTR;
wire I_RLD;
wire I_RRD;
reg I_RXDD;
wire I_INRC;
wire [1:0] SetWZ;
wire SetDI;
wire SetEI;
wire [1:0] IMode;
wire Halt;
wire XYbit_undoc;
wire [127:0] DOR;
  assign REG = Alternate == 1'b0 ? {IntE_FF2,IntE_FF1,IStatus,DOR,PC,SP,R,I,Fp,Ap,F,ACC} : {IntE_FF2,IntE_FF1,IStatus,DOR[127:112],DOR[47:0],DOR[63:48],DOR[111:64],PC,SP,R,I,Fp,Ap,F,ACC};
  T80_MCode #(
      .Mode(Mode),
    .Flag_C(Flag_C),
    .Flag_N(Flag_N),
    .Flag_P(Flag_P),
    .Flag_X(Flag_X),
    .Flag_H(Flag_H),
    .Flag_Y(Flag_Y),
    .Flag_Z(Flag_Z),
    .Flag_S(Flag_S))
  mcode(
      .IR(IR),
    .ISet(ISet),
    .MCycle(MCycle),
    .F(F),
    .NMICycle(NMICycle),
    .IntCycle(IntCycle),
    .XY_State(XY_State),
    .MCycles(MCycles_d),
    .TStates(TStates),
    .Prefix(Prefix),
    .Inc_PC(Inc_PC),
    .Inc_WZ(Inc_WZ),
    .IncDec_16(IncDec_16),
    .Read_To_Acc(Read_To_Acc),
    .Read_To_Reg(Read_To_Reg),
    .Set_BusB_To(Set_BusB_To),
    .Set_BusA_To(Set_BusA_To),
    .ALU_Op(ALU_Op),
    .Save_ALU(Save_ALU),
    .PreserveC(PreserveC),
    .Arith16(Arith16),
    .Set_Addr_To(Set_Addr_To),
    .IORQ(IORQ_i),
    .Jump(Jump),
    .JumpE(JumpE),
    .JumpXY(JumpXY),
    .Call(Call),
    .RstP(RstP),
    .LDZ(LDZ),
    .LDW(LDW),
    .LDSPHL(LDSPHL),
    .Special_LD(Special_LD),
    .ExchangeDH(ExchangeDH),
    .ExchangeRp(ExchangeRp),
    .ExchangeAF(ExchangeAF),
    .ExchangeRS(ExchangeRS),
    .I_DJNZ(I_DJNZ),
    .I_CPL(I_CPL),
    .I_CCF(I_CCF),
    .I_SCF(I_SCF),
    .I_RETN(I_RETN),
    .I_BT(I_BT),
    .I_BC(I_BC),
    .I_BTR(I_BTR),
    .I_RLD(I_RLD),
    .I_RRD(I_RRD),
    .I_INRC(I_INRC),
    .SetWZ(SetWZ),
    .SetDI(SetDI),
    .SetEI(SetEI),
    .IMode(IMode),
    .Halt(Halt),
    .NoRead(NoRead),
    .Write(Write),
    .XYbit_undoc(XYbit_undoc));
  T80_ALU #(
      .Mode(Mode),
    .Flag_C(Flag_C),
    .Flag_N(Flag_N),
    .Flag_P(Flag_P),
    .Flag_X(Flag_X),
    .Flag_H(Flag_H),
    .Flag_Y(Flag_Y),
    .Flag_Z(Flag_Z),
    .Flag_S(Flag_S))
  alu(
      .Arith16(Arith16_r),
    .Z16(Z16_r),
    .WZ(WZ),
    .XY_State(XY_State),
    .ALU_Op(ALU_Op_r),
    .IR(IR[5:0]),
    .ISet(ISet),
    .BusA(BusA),
    .BusB(BusB),
    .F_In(F),
    .Q(ALU_Q),
    .F_Out(F_Out));
  assign ClkEn = CEN &  ~BusAck;
  assign T_Res = TState == (TStates) ? 1'b1 : 1'b0;
  assign NextIs_XY_Fetch = XY_State != 2'b00 && XY_Ind == 1'b0 && ((Set_Addr_To == aXY) || (MCycle == 3'b001 && IR == 8'b11001011) || (MCycle == 3'b001 && IR == 8'b00110110)) ? 1'b1 : 1'b0;
  assign Save_Mux = ExchangeRp == 1'b1 ? BusB : Save_ALU_r == 1'b0 ? DI_Reg : ALU_Q;
  always @(posedge RESET_n, posedge CLK_n) begin : P2
    reg [7:0] n;
    reg [8:0] ioq;
    if(RESET_n == 1'b0) begin
      PC <= {16{1'b0}};
      // Program Counter
      A <= {16{1'b0}};
      WZ <= {16{1'b0}};
      IR <= 8'b00000000;
      ISet <= 2'b00;
      XY_State <= 2'b00;
      IStatus <= 2'b00;
      MCycles <= 3'b000;
      DO <= 8'b00000000;
      ACC <= {8{1'b1}};
      F <= {8{1'b1}};
      Ap <= {8{1'b1}};
      Fp <= {8{1'b1}};
      I <= {8{1'b0}};
      R <= {8{1'b0}};
      SP <= {16{1'b1}};
      Alternate <= 1'b0;
      Read_To_Reg_r <= 5'b00000;
      Arith16_r <= 1'b0;
      BTR_r <= 1'b0;
      Z16_r <= 1'b0;
      ALU_Op_r <= 4'b0000;
      Save_ALU_r <= 1'b0;
      PreserveC_r <= 1'b0;
      XY_Ind <= 1'b0;
      I_RXDD <= 1'b0;
    end else begin
      if(DIRSet == 1'b1) begin
        ACC <= DIR[7:0];
        F <= DIR[15:8];
        Ap <= DIR[23:16];
        Fp <= DIR[31:24];
        I <= DIR[39:32];
        R <= DIR[47:40];
        SP <= DIR[63:48];
        PC <= DIR[79:64];
        A <= DIR[79:64];
        IStatus <= DIR[209:208];
      end
      else if(ClkEn == 1'b1) begin
        ALU_Op_r <= 4'b0000;
        Save_ALU_r <= 1'b0;
        Read_To_Reg_r <= 5'b00000;
        MCycles <= MCycles_d;
        if(IMode != 2'b11) begin
          IStatus <= IMode;
        end
        Arith16_r <= Arith16;
        PreserveC_r <= PreserveC;
        if(ISet == 2'b10 && ALU_OP[2] == 1'b0 && ALU_OP[0] == 1'b1 && MCycle == 3'b011) begin
          Z16_r <= 1'b1;
        end
        else begin
          Z16_r <= 1'b0;
        end
        if(MCycle == 3'b001 && TState[2] == 1'b0) begin
          // MCycle = 1 and TState = 1, 2, or 3
          if(TState == 2 && Wait_n == 1'b1) begin
            if(Mode < 2) begin
              A[7:0] <= R;
              A[15:8] <= I;
              R[6:0] <= R[6:0] + 1;
            end
            if(Jump == 1'b0 && Call == 1'b0 && NMICycle == 1'b0 && IntCycle == 1'b0 && !(Halt_FF == 1'b1 || Halt == 1'b1)) begin
              PC <= PC + 1;
            end
            if(IntCycle == 1'b1 && IStatus == 2'b01) begin
              IR <= 8'b11111111;
            end
            else if(Halt_FF == 1'b1 || (IntCycle == 1'b1 && IStatus == 2'b10) || NMICycle == 1'b1) begin
              IR <= 8'b00000000;
            end
            else begin
              IR <= DInst;
            end
            ISet <= 2'b00;
            if(Prefix != 2'b00) begin
              if(Prefix == 2'b11) begin
                if(IR[5] == 1'b1) begin
                  XY_State <= 2'b10;
                end
                else begin
                  XY_State <= 2'b01;
                end
              end
              else begin
                if(Prefix == 2'b10) begin
                  XY_State <= 2'b00;
                  XY_Ind <= 1'b0;
                end
                ISet <= Prefix;
              end
            end
            else begin
              XY_State <= 2'b00;
              XY_Ind <= 1'b0;
            end
          end
        end
        else begin
          // either (MCycle > 1) OR (MCycle = 1 AND TState > 3)
          if(MCycle == 3'b110) begin
            XY_Ind <= 1'b1;
            if(Prefix == 2'b01) begin
              ISet <= 2'b01;
            end
          end
          if(T_Res == 1'b1) begin
            BTR_r <= (I_BT | I_BC | I_BTR) &  ~No_BTR;
            if(Jump == 1'b1) begin
              A[15:8] <= DI_Reg;
              A[7:0] <= WZ[7:0];
              PC[15:8] <= DI_Reg;
              PC[7:0] <= WZ[7:0];
            end
            else if(JumpXY == 1'b1) begin
              A <= RegBusC;
              PC <= RegBusC;
            end
            else if(Call == 1'b1 || RstP == 1'b1) begin
              A <= WZ;
              PC <= WZ;
            end
            else if(MCycle == MCycles && NMICycle == 1'b1) begin
              A <= 16'b0000000001100110;
              PC <= 16'b0000000001100110;
            end
            else if(MCycle == 3'b011 && IntCycle == 1'b1 && IStatus == 2'b10) begin
              A[15:8] <= I;
              A[7:0] <= WZ[7:0];
              PC[15:8] <= I;
              PC[7:0] <= WZ[7:0];
            end
            else begin
              case(Set_Addr_To)
              aXY : begin
                if(XY_State == 2'b00) begin
                  A <= RegBusC;
                end
                else begin
                  if(NextIs_XY_Fetch == 1'b1) begin
                    A <= PC;
                  end
                  else begin
                    A <= WZ;
                  end
                end
              end
              aIOA : begin
                if(Mode == 3) begin
                  // Memory map I/O on GBZ80
                  A[15:8] <= {8{1'b1}};
                end
                else if(Mode == 2) begin
                  // Duplicate I/O address on 8080
                  A[15:8] <= DI_Reg;
                end
                else begin
                  A[15:8] <= ACC;
                end
                A[7:0] <= DI_Reg;
                WZ <= ({ACC,DI_Reg}) + 1'b1;
              end
              aSP : begin
                A <= SP;
              end
              aBC : begin
                if(Mode == 3 && IORQ_i == 1'b1) begin
                  // Memory map I/O on GBZ80
                  A[15:8] <= {8{1'b1}};
                  A[7:0] <= RegBusC[7:0];
                end
                else begin
                  A <= RegBusC;
                  if(SetWZ == 2'b01) begin
                    WZ <= RegBusC + 1'b1;
                  end
                  if(SetWZ == 2'b10) begin
                    WZ[7:0] <= RegBusC[7:0] + 1'b1;
                    WZ[15:8] <= ACC;
                  end
                end
              end
              aDE : begin
                A <= RegBusC;
                if(SetWZ == 2'b10) begin
                  WZ[7:0] <= RegBusC[7:0] + 1'b1;
                  WZ[15:8] <= ACC;
                end
              end
              aZI : begin
                if(Inc_WZ == 1'b1) begin
                  A <= (WZ) + 1;
                end
                else begin
                  A[15:8] <= DI_Reg;
                  A[7:0] <= WZ[7:0];
                  if(SetWZ == 2'b10) begin
                    WZ[7:0] <= WZ[7:0] + 1'b1;
                    WZ[15:8] <= ACC;
                  end
                end
              end
              default : begin
                A <= PC;
              end
              endcase
            end
            if(SetWZ == 2'b11) begin
              WZ <= ID16;
            end
            Save_ALU_r <= Save_ALU;
            ALU_Op_r <= ALU_Op;
            if(I_CPL == 1'b1) begin
              // CPL
              ACC <=  ~ACC;
              F[Flag_Y] <=  ~ACC[5];
              F[Flag_H] <= 1'b1;
              F[Flag_X] <=  ~ACC[3];
              F[Flag_N] <= 1'b1;
            end
            if(I_CCF == 1'b1) begin
              // CCF
              F[Flag_C] <=  ~F[Flag_C];
              F[Flag_Y] <= ACC[5];
              F[Flag_H] <= F[Flag_C];
              F[Flag_X] <= ACC[3];
              F[Flag_N] <= 1'b0;
            end
            if(I_SCF == 1'b1) begin
              // SCF
              F[Flag_C] <= 1'b1;
              F[Flag_Y] <= ACC[5];
              F[Flag_H] <= 1'b0;
              F[Flag_X] <= ACC[3];
              F[Flag_N] <= 1'b0;
            end
          end
          if((TState == 2 && I_BTR == 1'b1 && IR[0] == 1'b1) || (TState == 1 && I_BTR == 1'b1 && IR[0] == 1'b0)) begin
            ioq = ({1'b0,DI_Reg}) + ({1'b0,ID16[7:0]});
            F[Flag_N] <= DI_Reg[7];
            F[Flag_C] <= ioq[8];
            F[Flag_H] <= ioq[8];
            ioq = (ioq & ({1'b0,8'h07})) ^ ({1'b0,BusA});
            F[Flag_P] <=  ~(ioq[0] ^ ioq[1] ^ ioq[2] ^ ioq[3] ^ ioq[4] ^ ioq[5] ^ ioq[6] ^ ioq[7]);
          end
          if(TState == 2 && Wait_n == 1'b1) begin
            if(ISet == 2'b01 && MCycle == 3'b111) begin
              IR <= DInst;
            end
            if(JumpE == 1'b1) begin
              PC <= (PC) + (DI_Reg);
              WZ <= (PC) + (DI_Reg);
            end
            else if(Inc_PC == 1'b1) begin
              PC <= PC + 1;
            end
            if(BTR_r == 1'b1) begin
              PC <= PC - 2;
            end
            if(RstP == 1'b1) begin
              WZ <= {16{1'b0}};
              WZ[5:3] <= IR[5:3];
            end
          end
          if(TState == 3 && MCycle == 3'b110) begin
            WZ <= (RegBusC) + (DI_Reg);
          end
          if(MCycle == 3'b011 && TState == 4 && No_BTR == 1'b0) begin
            if(I_BT == 1'b1 || I_BC == 1'b1) begin
              WZ <= (PC) - 1'b1;
            end
          end
          if((TState == 2 && Wait_n == 1'b1) || (TState == 4 && MCycle == 3'b001)) begin
            if(IncDec_16[2:0] == 3'b111) begin
              if(IncDec_16[3] == 1'b1) begin
                SP <= SP - 1;
              end
              else begin
                SP <= SP + 1;
              end
            end
          end
          if(LDSPHL == 1'b1) begin
            SP <= RegBusC;
          end
          if(ExchangeAF == 1'b1) begin
            Ap <= ACC;
            ACC <= Ap;
            Fp <= F;
            F <= Fp;
          end
          if(ExchangeRS == 1'b1) begin
            Alternate <=  ~Alternate;
          end
        end
        if(TState == 3) begin
          if(LDZ == 1'b1) begin
            WZ[7:0] <= DI_Reg;
          end
          if(LDW == 1'b1) begin
            WZ[15:8] <= DI_Reg;
          end
          if(Special_LD[2] == 1'b1) begin
            case(Special_LD[1:0])
            2'b00 : begin
              ACC <= I;
              F[Flag_P] <= IntE_FF2;
              F[Flag_S] <= I[7];
              if(I == 8'h00) begin
                F[Flag_Z] <= 1'b1;
              end
              else begin
                F[Flag_Z] <= 1'b0;
              end
              F[Flag_Y] <= I[5];
              F[Flag_H] <= 1'b0;
              F[Flag_X] <= I[3];
              F[Flag_N] <= 1'b0;
            end
            2'b01 : begin
              ACC <= R;
              F[Flag_P] <= IntE_FF2;
              F[Flag_S] <= R[7];
              if(R == 8'h00) begin
                F[Flag_Z] <= 1'b1;
              end
              else begin
                F[Flag_Z] <= 1'b0;
              end
              F[Flag_Y] <= R[5];
              F[Flag_H] <= 1'b0;
              F[Flag_X] <= R[3];
              F[Flag_N] <= 1'b0;
            end
            2'b10 : begin
              I <= ACC;
            end
            default : begin
              R <= ACC;
            end
            endcase
          end
        end
        if((I_DJNZ == 1'b0 && Save_ALU_r == 1'b1) || ALU_Op_r == 4'b1001) begin
          if(Mode == 3) begin
            F[6] <= F_Out[6];
            F[5] <= F_Out[5];
            F[7] <= F_Out[7];
            if(PreserveC_r == 1'b0) begin
              F[4] <= F_Out[4];
            end
          end
          else begin
            F[7:1] <= F_Out[7:1];
            if(PreserveC_r == 1'b0) begin
              F[Flag_C] <= F_Out[0];
            end
          end
        end
        if(T_Res == 1'b1 && I_INRC == 1'b1) begin
          F[Flag_H] <= 1'b0;
          F[Flag_N] <= 1'b0;
          F[Flag_X] <= DI_Reg[3];
          F[Flag_Y] <= DI_Reg[5];
          if(DI_Reg[7:0] == 8'b00000000) begin
            F[Flag_Z] <= 1'b1;
          end
          else begin
            F[Flag_Z] <= 1'b0;
          end
          F[Flag_S] <= DI_Reg[7];
          F[Flag_P] <=  ~(DI_Reg[0] ^ DI_Reg[1] ^ DI_Reg[2] ^ DI_Reg[3] ^ DI_Reg[4] ^ DI_Reg[5] ^ DI_Reg[6] ^ DI_Reg[7]);
        end
        if(TState == 1 && Auto_Wait_t1 == 1'b0) begin
          // Keep D0 from M3 for RLD/RRD (Sorgelig)
          I_RXDD <= I_RLD | I_RRD;
          if(I_RXDD == 1'b0) begin
            DO <= BusB;
          end
          if(I_RLD == 1'b1) begin
            DO[3:0] <= BusA[3:0];
            DO[7:4] <= BusB[3:0];
          end
          if(I_RRD == 1'b1) begin
            DO[3:0] <= BusB[7:4];
            DO[7:4] <= BusA[3:0];
          end
        end
        if(T_Res == 1'b1) begin
          Read_To_Reg_r[3:0] <= Set_BusA_To;
          Read_To_Reg_r[4] <= Read_To_Reg;
          if(Read_To_Acc == 1'b1) begin
            Read_To_Reg_r[3:0] <= 4'b0111;
            Read_To_Reg_r[4] <= 1'b1;
          end
        end
        if(TState == 1 && I_BT == 1'b1) begin
          F[Flag_X] <= ALU_Q[3];
          F[Flag_Y] <= ALU_Q[1];
          F[Flag_H] <= 1'b0;
          F[Flag_N] <= 1'b0;
        end
        if(TState == 1 && I_BC == 1'b1) begin
          n = ALU_Q - ({7'b0000000,F_Out[Flag_H]});
          F[Flag_X] <= n[3];
          F[Flag_Y] <= n[1];
        end
        if(I_BC == 1'b1 || I_BT == 1'b1) begin
          F[Flag_P] <= IncDecZ;
        end
        if((TState == 1 && Save_ALU_r == 1'b0 && Auto_Wait_t1 == 1'b0) || (Save_ALU_r == 1'b1 && ALU_OP_r != 4'b0111)) begin
          case(Read_To_Reg_r)
          5'b10111 : begin
            ACC <= Save_Mux;
          end
          5'b10110 : begin
            DO <= Save_Mux;
          end
          5'b11000 : begin
            SP[7:0] <= Save_Mux;
          end
          5'b11001 : begin
            SP[15:8] <= Save_Mux;
          end
          5'b11011 : begin
            F <= Save_Mux;
          end
          default : begin
          end
          endcase
          if(XYbit_undoc == 1'b1) begin
            DO <= ALU_Q;
          end
        end
      end
    end
  end
  //-------------------------------------------------------------------------
  //
  // BC('), DE('), HL('), IX and IY
  //
  //-------------------------------------------------------------------------
  always @(posedge CLK_n) begin
    if(ClkEn == 1'b1) begin
      // Bus A / Write
      RegAddrA_r <= {Alternate,Set_BusA_To[2:1]};
      if(XY_Ind == 1'b0 && XY_State != 2'b00 && Set_BusA_To[2:1] == 2'b10) begin
        RegAddrA_r <= {XY_State[1],2'b11};
      end
      // Bus B
      RegAddrB_r <= {Alternate,Set_BusB_To[2:1]};
      if(XY_Ind == 1'b0 && XY_State != 2'b00 && Set_BusB_To[2:1] == 2'b10) begin
        RegAddrB_r <= {XY_State[1],2'b11};
      end
      // Address from register
      RegAddrC <= {Alternate,Set_Addr_To[1:0]};
      // Jump (HL), LD SP,HL
      if((JumpXY == 1'b1 || LDSPHL == 1'b1)) begin
        RegAddrC <= {Alternate,2'b10};
      end
      if(((JumpXY == 1'b1 || LDSPHL == 1'b1) && XY_State != 2'b00) || (MCycle == 3'b110)) begin
        RegAddrC <= {XY_State[1],2'b11};
      end
      if(I_DJNZ == 1'b1 && Save_ALU_r == 1'b1 && Mode < 2) begin
        IncDecZ <= F_Out[Flag_Z];
      end
      if((TState == 2 || (TState == 3 && MCycle == 3'b001)) && IncDec_16[2:0] == 3'b100) begin
        if(ID16 == 0) begin
          IncDecZ <= 1'b0;
        end
        else begin
          IncDecZ <= 1'b1;
        end
      end
      RegBusA_r <= RegBusA;
    end
  end
  assign RegAddrA = (TState == 2 || (TState == 3 && MCycle == 3'b001 && IncDec_16[2] == 1'b1)) && XY_State == 2'b00 ? {Alternate,IncDec_16[1:0]} : (TState == 2 || (TState == 3 && MCycle == 3'b001 && IncDec_16[2] == 1'b1)) && IncDec_16[1:0] == 2'b10 ? {XY_State[1],2'b11} : ExchangeDH == 1'b1 && TState == 3 ? {Alternate,2'b10} : ExchangeDH == 1'b1 && TState == 4 ? {Alternate,2'b01} : RegAddrA_r;
  assign RegAddrB = ExchangeDH == 1'b1 && TState == 3 ? {Alternate,2'b01} : RegAddrB_r;
  assign ID16 = IncDec_16[3] == 1'b1 ? (RegBusA) - 1 : (RegBusA) + 1;
  always @(Save_ALU_r, Auto_Wait_t1, ALU_OP_r, Read_To_Reg_r, ExchangeDH, IncDec_16, MCycle, TState, Wait_n) begin
    RegWEH <= 1'b0;
    RegWEL <= 1'b0;
    if((TState == 1 && Save_ALU_r == 1'b0 && Auto_Wait_t1 == 1'b0) || (Save_ALU_r == 1'b1 && ALU_OP_r != 4'b0111)) begin
      case(Read_To_Reg_r)
      5'b10000,5'b10001,5'b10010,5'b10011,5'b10100,5'b10101 : begin
        RegWEH <=  ~Read_To_Reg_r[0];
        RegWEL <= Read_To_Reg_r[0];
      end
      default : begin
      end
      endcase
    end
    if(ExchangeDH == 1'b1 && (TState == 3 || TState == 4)) begin
      RegWEH <= 1'b1;
      RegWEL <= 1'b1;
    end
    if(IncDec_16[2] == 1'b1 && ((TState == 2 && Wait_n == 1'b1 && MCycle != 3'b001) || (TState == 3 && MCycle == 3'b001))) begin
      case(IncDec_16[1:0])
      2'b00,2'b01,2'b10 : begin
        RegWEH <= 1'b1;
        RegWEL <= 1'b1;
      end
      default : begin
      end
      endcase
    end
  end
  always @(Save_Mux, RegBusB, RegBusA_r, ID16, ExchangeDH, IncDec_16, MCycle, TState, Wait_n) begin
    RegDIH <= Save_Mux;
    RegDIL <= Save_Mux;
    if(ExchangeDH == 1'b1 && TState == 3) begin
      RegDIH <= RegBusB[15:8];
      RegDIL <= RegBusB[7:0];
    end
    if(ExchangeDH == 1'b1 && TState == 4) begin
      RegDIH <= RegBusA_r[15:8];
      RegDIL <= RegBusA_r[7:0];
    end
    if(IncDec_16[2] == 1'b1 && ((TState == 2 && MCycle != 3'b001) || (TState == 3 && MCycle == 3'b001))) begin
      RegDIH <= ID16[15:8];
      RegDIL <= ID16[7:0];
    end
  end
  T80_Reg Regs(
      .Clk(CLK_n),
    .CEN(ClkEn),
    .WEH(RegWEH),
    .WEL(RegWEL),
    .AddrA(RegAddrA),
    .AddrB(RegAddrB),
    .AddrC(RegAddrC),
    .DIH(RegDIH),
    .DIL(RegDIL),
    .DOAH(RegBusA[15:8]),
    .DOAL(RegBusA[7:0]),
    .DOBH(RegBusB[15:8]),
    .DOBL(RegBusB[7:0]),
    .DOCH(RegBusC[15:8]),
    .DOCL(RegBusC[7:0]),
    .DOR(DOR),
    .DIRSet(DIRSet),
    .DIR(DIR[207:80]));
  //-------------------------------------------------------------------------
  //
  // Buses
  //
  //-------------------------------------------------------------------------
  always @(posedge CLK_n) begin
    if(ClkEn == 1'b1) begin
      case(Set_BusB_To)
      4'b0111 : begin
        BusB <= ACC;
      end
      4'b0000,4'b0001,4'b0010,4'b0011,4'b0100,4'b0101 : begin
        if(Set_BusB_To[0] == 1'b1) begin
          BusB <= RegBusB[7:0];
        end
        else begin
          BusB <= RegBusB[15:8];
        end
      end
      4'b0110 : begin
        BusB <= DI_Reg;
      end
      4'b1000 : begin
        BusB <= SP[7:0];
      end
      4'b1001 : begin
        BusB <= SP[15:8];
      end
      4'b1010 : begin
        BusB <= 8'b00000001;
      end
      4'b1011 : begin
        BusB <= F;
      end
      4'b1100 : begin
        BusB <= PC[7:0];
      end
      4'b1101 : begin
        BusB <= PC[15:8];
      end
      4'b1110 : begin
        if(IR == 8'h71 && out0 == 1'b1) begin
          BusB <= 8'b11111111;
        end
        else begin
          BusB <= 8'b00000000;
        end
      end
      default : begin
        BusB <= 8'b--------;
      end
      endcase
      case(Set_BusA_To)
      4'b0111 : begin
        BusA <= ACC;
      end
      4'b0000,4'b0001,4'b0010,4'b0011,4'b0100,4'b0101 : begin
        if(Set_BusA_To[0] == 1'b1) begin
          BusA <= RegBusA[7:0];
        end
        else begin
          BusA <= RegBusA[15:8];
        end
      end
      4'b0110 : begin
        BusA <= DI_Reg;
      end
      4'b1000 : begin
        BusA <= SP[7:0];
      end
      4'b1001 : begin
        BusA <= SP[15:8];
      end
      4'b1010 : begin
        BusA <= 8'b00000000;
      end
      default : begin
        BusA <= 8'b--------;
      end
      endcase
      if(XYbit_undoc == 1'b1) begin
        BusA <= DI_Reg;
        BusB <= DI_Reg;
      end
    end
  end
  //-------------------------------------------------------------------------
  //
  // Generate external control signals
  //
  //-------------------------------------------------------------------------
  always @(posedge RESET_n, posedge CLK_n) begin
    if(RESET_n == 1'b0) begin
      RFSH_n <= 1'b1;
    end else begin
      if(DIRSet == 1'b0 && CEN == 1'b1) begin
        if(MCycle == 3'b001 && ((TState == 2 && Wait_n == 1'b1) || TState == 3)) begin
          RFSH_n <= 1'b0;
        end
        else begin
          RFSH_n <= 1'b1;
        end
      end
    end
  end
  assign MC = MCycle;
  assign TS = TState;
  assign DI_Reg = DI;
  assign HALT_n =  ~Halt_FF;
  assign BUSAK_n =  ~BusAck;
  assign IntCycle_n =  ~IntCycle;
  assign NMICycle_n =  ~NMICycle;
  assign IntE = IntE_FF1;
  assign IORQ = IORQ_i;
  assign Stop = I_DJNZ;
  //-----------------------------------------------------------------------
  //
  // Main state machine
  //
  //-----------------------------------------------------------------------
  always @(posedge RESET_n, posedge CLK_n) begin : P1
    reg OldNMI_n;
    if(RESET_n == 1'b0) begin
      MCycle <= 3'b001;
      TState <= 3'b000;
      Pre_XY_F_M <= 3'b000;
      Halt_FF <= 1'b0;
      BusAck <= 1'b0;
      NMICycle <= 1'b0;
      IntCycle <= 1'b0;
      IntE_FF1 <= 1'b0;
      IntE_FF2 <= 1'b0;
      No_BTR <= 1'b0;
      Auto_Wait_t1 <= 1'b0;
      Auto_Wait_t2 <= 1'b0;
      M1_n <= 1'b1;
      BusReq_s <= 1'b0;
      NMI_s <= 1'b0;
    end else begin
      if(DIRSet == 1'b1) begin
        IntE_FF2 <= DIR[211];
        IntE_FF1 <= DIR[210];
      end
      else begin
        if(NMI_n == 1'b0 && OldNMI_n == 1'b1) begin
          NMI_s <= 1'b1;
        end
        OldNMI_n = NMI_n;
        if(CEN == 1'b1) begin
          BusReq_s <=  ~BUSRQ_n;
          Auto_Wait_t2 <= Auto_Wait_t1;
          if(T_Res == 1'b1) begin
            Auto_Wait_t1 <= 1'b0;
            Auto_Wait_t2 <= 1'b0;
          end
          else begin
            Auto_Wait_t1 <= Auto_Wait | IORQ_i;
          end
          No_BTR <= (I_BT & ( ~IR[4] |  ~F[Flag_P])) | (I_BC & ( ~IR[4] | F[Flag_Z] |  ~F[Flag_P])) | (I_BTR & ( ~IR[4] | F[Flag_Z]));
          if(TState == 2) begin
            if(SetEI == 1'b1) begin
              IntE_FF1 <= 1'b1;
              IntE_FF2 <= 1'b1;
            end
            if(I_RETN == 1'b1) begin
              IntE_FF1 <= IntE_FF2;
            end
          end
          if(TState == 3) begin
            if(SetDI == 1'b1) begin
              IntE_FF1 <= 1'b0;
              IntE_FF2 <= 1'b0;
            end
          end
          if(IntCycle == 1'b1 || NMICycle == 1'b1) begin
            Halt_FF <= 1'b0;
          end
          if(MCycle == 3'b001 && TState == 2 && Wait_n == 1'b1) begin
            M1_n <= 1'b1;
          end
          if(BusReq_s == 1'b1 && BusAck == 1'b1) begin
          end
          else begin
            BusAck <= 1'b0;
            if(TState == 2 && Wait_n == 1'b0) begin
            end
            else if(T_Res == 1'b1) begin
              if(Halt == 1'b1) begin
                Halt_FF <= 1'b1;
              end
              if(BusReq_s == 1'b1) begin
                BusAck <= 1'b1;
              end
              else begin
                TState <= 3'b001;
                if(NextIs_XY_Fetch == 1'b1) begin
                  MCycle <= 3'b110;
                  Pre_XY_F_M <= MCycle;
                  if(IR == 8'b00110110 && Mode == 0) begin
                    Pre_XY_F_M <= 3'b010;
                  end
                end
                else if((MCycle == 3'b111) || (MCycle == 3'b110 && Mode == 1 && ISet != 2'b01)) begin
                  MCycle <= (Pre_XY_F_M) + 1;
                end
                else if((MCycle == MCycles) || No_BTR == 1'b1 || (MCycle == 3'b010 && I_DJNZ == 1'b1 && IncDecZ == 1'b1)) begin
                  M1_n <= 1'b0;
                  MCycle <= 3'b001;
                  IntCycle <= 1'b0;
                  NMICycle <= 1'b0;
                  if(NMI_s == 1'b1 && Prefix == 2'b00) begin
                    NMI_s <= 1'b0;
                    NMICycle <= 1'b1;
                    IntE_FF1 <= 1'b0;
                  end
                  else if(IntE_FF1 == 1'b1 && INT_n == 1'b0 && Prefix == 2'b00 && SetEI == 1'b0) begin
                    IntCycle <= 1'b1;
                    IntE_FF1 <= 1'b0;
                    IntE_FF2 <= 1'b0;
                  end
                end
                else begin
                  MCycle <= (MCycle) + 1;
                end
              end
            end
            else begin
              if(!((Auto_Wait == 1'b1 && Auto_Wait_t2 == 1'b0) || (IOWait == 1 && IORQ_i == 1'b1 && Auto_Wait_t1 == 1'b0))) begin
                TState <= TState + 1;
              end
            end
          end
          if(TState == 0) begin
            M1_n <= 1'b0;
          end
        end
      end
    end
  end
  assign Auto_Wait = IntCycle == 1'b1 && MCycle == 3'b001 ? 1'b1 : 1'b0;
endmodule

module rs232_receiver(
input wire clock_50MHz,
input wire input,
output reg [7:0] receive_data,
output reg ack
);
// connected to comport input pin
// a pulse notification
parameter [1:0]
  STATE_IDLE = 0,
  STATE_RECEIVING = 1,
  STATE_END_BIT = 2,
  STATE_ACKING = 3;
reg [1:0] state;
reg power_on = 1'b0;
reg [31:0] bit_count;
reg [31:0] cycle_count;
reg [31:0] ack_count;
  always @(posedge clock_50MHz, posedge input) begin
    if((power_on == 1'b0)) begin
      // init
      power_on <= 1'b1;
      ack <= 1'b0;
      state <= STATE_IDLE;
      receive_data <= 8'b00000000;
      ack_count <= 0;
    end
    else begin
      // non-init
      case(state)
      STATE_IDLE : begin
        ack <= 1'b0;
        ack_count <= 0;
        if((input == 1'b0)) begin
          state <= STATE_RECEIVING;
          bit_count <= 0;
          cycle_count <= 0;
        end
      end
      STATE_RECEIVING : begin
        cycle_count <= cycle_count + 1;
        ack <= 1'b0;
        if((cycle_count == 651 || cycle_count == 1085 || cycle_count == 1519 || cycle_count == 1953 || cycle_count == 2387 || cycle_count == 2821 || cycle_count == 3255 || cycle_count == 3689)) begin
          receive_data[bit_count] <= input;
          bit_count <= bit_count + 1;
        end
        else if((cycle_count > 3689)) begin
          state <= STATE_END_BIT;
        end
      end
      STATE_END_BIT : begin
        cycle_count <= cycle_count + 1;
        if((cycle_count > 4123 && input == 1'b1)) begin
          state <= STATE_ACKING;
        end
      end
      STATE_ACKING : begin
        ack <= 1'b1;
        ack_count <= ack_count + 1;
        if((ack_count > 500)) begin
          state <= STATE_IDLE;
        end
      end
      endcase
    end
    // init / non-init
  end
endmodule

module fx2_interface(
input wire clk_in,
input wire reset_in,
output reg reset_out,
output reg fx2FifoSel_out,
inout wire [7:0] fx2Data_io,
output wire fx2Read_out,
input wire fx2GotData_in,
output wire fx2Write_out,
input wire fx2GotRoom_in,
output reg fx2PktEnd_out,
output wire [6:0] chanAddr_out,
output wire [7:0] h2fData_out,
output reg h2fValid_out,
input wire h2fReady_in,
input wire [7:0] f2hData_in,
input wire f2hValid_in,
output reg f2hReady_out
);
// 48MHz clock from FX2LP
// synchronous active-high reset input
// synchronous active-high reset output
// FX2LP interface ---------------------------------------------------------------------------
// select FIFO: '0' for EP2OUT, '1' for EP6IN
// 8-bit data to/from FX2LP
// When EP2OUT selected:
// asserted (active-low) when reading from FX2LP
// asserted (active-high) when FX2LP has data for us
// When EP6IN selected:
// asserted (active-low) when writing to FX2LP
// asserted (active-high) when FX2LP has room for more data from us
// asserted (active-low) when a host read needs to be committed early
// Channel read/write interface --------------------------------------------------------------
// the selected channel (0-127)
// Host >> FPGA pipe:
// data lines used when the host writes to a channel
// '1' means "on the next clock rising edge, please accept the data on h2fData_out"
// channel logic can drive this low to say "I'm not ready for more data yet"
// Host << FPGA pipe:
// data lines used when the host reads from a channel
// channel logic can drive this low to say "I don't have data ready for you"
// '1' means "on the next clock rising edge, put your next byte of data on f2hData_in"
// The read/write nomenclature here refers to the FPGA reading and writing the FX2LP FIFOs, and is therefore
// of the opposite sense to the host's read and write. So host reads are fulfilled in the S_WRITE state, and
// vice-versa. Apologies for the confusion.
parameter [3:0]
  S_RESET = 0,
  S_IDLE = 1,
  S_GET_COUNT0 = 2,
  S_GET_COUNT1 = 3,
  S_BEGIN_WRITE = 4,
  S_WRITE = 5,
  S_END_WRITE_ALIGNED = 6,
  S_END_WRITE_NONALIGNED = 7,
  S_READ = 8;
parameter FIFO_READ = 2'b10;  // assert fx2Read_out (active-low)
parameter FIFO_WRITE = 2'b01;  // assert fx2Write_out (active-low)
parameter FIFO_NOP = 2'b11;  // assert nothing
parameter OUT_FIFO = 1'b0;  // EP2OUT
parameter IN_FIFO = 1'b1;  // EP6IN
reg [3:0] state = S_RESET; reg [3:0] state_next = S_RESET;
reg [1:0] fifoOp = 2'bZZ;
reg [16:0] count = 1'b0; reg [16:0] count_next = 1'b0;  // read/write count
reg [6:0] chanAddr = 1'b0; reg [6:0] chanAddr_next = 1'b0;  // channel being accessed (0-127)
reg isWrite = 1'b0; reg isWrite_next = 1'b0;  // is this FX2LP FIFO access a write or a read?
reg isAligned = 1'b0; reg isAligned_next = 1'b0;  // is this FX2LP FIFO write block-aligned?
reg [7:0] dataOut;  // data to be driven on fx2Data_io
reg driveBus = 1'b0;  // whether or not to drive fx2Data_io
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      state <= S_RESET;
      count <= {17{1'b0}};
      chanAddr <= {7{1'b0}};
      isWrite <= 1'b0;
      isAligned <= 1'b0;
    end
    else begin
      state <= state_next;
      count <= count_next;
      chanAddr <= chanAddr_next;
      isWrite <= isWrite_next;
      isAligned <= isAligned_next;
    end
  end
  // Next state logic
  always @(state, fx2Data_io, fx2GotData_in, fx2GotRoom_in, count, isAligned, isWrite, chanAddr, f2hData_in, f2hValid_in, h2fReady_in) begin
    state_next <= state;
    count_next <= count;
    chanAddr_next <= chanAddr;
    isWrite_next <= isWrite;
    // is the FPGA writing to the FX2LP?
    isAligned_next <= isAligned;
    // does this FIFO write end on a block (512-byte) boundary?
    dataOut <= {8{1'b0}};
    driveBus <= 1'b0;
    // don't drive fx2Data_io by default
    fifoOp <= FIFO_READ;
    // read the FX2LP FIFO by default
    fx2PktEnd_out <= 1'b1;
    // inactive: FPGA does not commit a short packet.
    f2hReady_out <= 1'b0;
    h2fValid_out <= 1'b0;
    reset_out <= 1'b0;
    case(state)
    S_GET_COUNT0 : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1)) begin
        // The count high word high byte will be available on the next clock edge.
        count_next[15:8] <= fx2Data_io;
        state_next <= S_GET_COUNT1;
      end
    end
    S_GET_COUNT1 : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1)) begin
        // The count high word low byte will be available on the next clock edge.
        count_next[7:0] <= fx2Data_io;
        if((count[15:8] == 8'h00 && fx2Data_io == 8'h00)) begin
          count_next[16] <= 1'b1;
        end
        else begin
          count_next[16] <= 1'b0;
        end
        if((isWrite == 1'b1)) begin
          state_next <= S_BEGIN_WRITE;
        end
        else begin
          state_next <= S_READ;
        end
      end
    end
    S_BEGIN_WRITE : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      fifoOp <= FIFO_NOP;
      if((count[8:0] == 9'b000000000)) begin
        isAligned_next <= 1'b1;
      end
      else begin
        isAligned_next <= 1'b0;
      end
      state_next <= S_WRITE;
    end
    S_WRITE : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      if((fx2GotRoom_in == 1'b1)) begin
        f2hReady_out <= 1'b1;
      end
      if((fx2GotRoom_in == 1'b1 && f2hValid_in == 1'b1)) begin
        fifoOp <= FIFO_WRITE;
        dataOut <= f2hData_in;
        driveBus <= 1'b1;
        count_next <= count - 1;
        if((count == 1)) begin
          if((isAligned == 1'b1)) begin
            state_next <= S_END_WRITE_ALIGNED;
            // don't assert fx2PktEnd
          end
          else begin
            state_next <= S_END_WRITE_NONALIGNED;
            // assert fx2PktEnd to commit small packet
          end
        end
      end
      else begin
        fifoOp <= FIFO_NOP;
      end
    end
    S_END_WRITE_ALIGNED : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      fifoOp <= FIFO_NOP;
      state_next <= S_IDLE;
    end
    S_END_WRITE_NONALIGNED : begin
      fx2FifoSel_out <= IN_FIFO;
      // Writing to FX2LP
      fifoOp <= FIFO_NOP;
      fx2PktEnd_out <= 1'b0;
      // Active: FPGA commits the packet early.
      state_next <= S_IDLE;
    end
    S_READ : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1 && h2fReady_in == 1'b1)) begin
        // A data byte will be available on the next clock edge
        h2fValid_out <= 1'b1;
        count_next <= count - 1;
        if((count == 1)) begin
          state_next <= S_IDLE;
        end
      end
      else begin
        fifoOp <= FIFO_NOP;
      end
      // S_RESET - tri-state everything
    end
    S_RESET : begin
      reset_out <= 1'b1;
      driveBus <= 1'b0;
      fifoOp <= 2'bZZ;
      fx2FifoSel_out <= 1'bZ;
      fx2PktEnd_out <= 1'bZ;
      if((fx2GotData_in == 1'b0)) begin
        state_next <= S_IDLE;
      end
      // S_IDLE and others
    end
    default : begin
      fx2FifoSel_out <= OUT_FIFO;
      // Reading from FX2LP
      if((fx2GotData_in == 1'b1)) begin
        // The read/write flag and a seven-bit channel address will be available on the
        // next clock edge.
        chanAddr_next <= fx2Data_io[6:0];
        isWrite_next <= fx2Data_io[7];
        state_next <= S_GET_COUNT0;
      end
    end
    endcase
  end
  // Drive stateless signals
  assign fx2Read_out = fifoOp[0];
  assign fx2Write_out = fifoOp[1];
  assign chanAddr_out = chanAddr;
  assign h2fData_out = fx2Data_io;
  assign fx2Data_io = driveBus == 1'b1 ? dataOut : {8{1'bZ}};
endmodule

module arbiter(
input wire [0:C_NR_SLOTS - 1] i_ready,
input wire [0:C_NR_SLOTS - 1] i_req_0,
input wire [0:C_NR_SLOTS - 1] i_req_1,
input wire [0:C_NR_SLOTS - 1] i_req_2,
output wire [0:C_NR_SLOTS - 1] o_grant_0,
output wire [0:C_NR_SLOTS - 1] o_grant_1,
output wire [0:C_NR_SLOTS - 1] o_grant_2,
input wire clk,
input wire reset
);
parameter [31:0] C_NR_SLOTS=3;
// it is not a "real" generic, e.g., we still have to adapt the number of ports and the number of signals manually
//every thread can tell whether it is ready to accept data
//requests vector of thread Nr 0 (0 to 0 is allowed, loops are explicitly allowed)
//requests vector of thread Nr. 1. (element 0 = 1 => want to talk with thread 0)
//requests vector of thread Nr. 2.
//grant vector to thread NR 0. (element 0 = 1 => allowed to talk to thread 0)
//grant vector to thread NR 1. (element 0 = 1 => allowed to talk to thread 0)
//grant vector to thread Nr 2. (element 0 = 1 => allowed to talk to thread 0)
wire [0:C_NR_SLOTS - 1] req_for_thread_0;  // request signals for talking with thread 0
wire [0:C_NR_SLOTS - 1] req_for_thread_1;  // element 0 = 1 => thread 0 wants to talk to thread 1
wire [0:C_NR_SLOTS - 1] req_for_thread_2;
reg [0:C_NR_SLOTS - 1] grant_for_thread_0;  // grant signals for talking with thread 0
reg [0:C_NR_SLOTS - 1] grant_for_thread_1;  // element 0 = 1 => thread 0 is allowed to talk to thread 1
reg [0:C_NR_SLOTS - 1] grant_for_thread_2;
parameter [2:0]
  STATE_INIT = 0,
  STATE_WAIT = 1,
  STATE_GRANT_0 = 2,
  STATE_GRANT_1 = 3,
  STATE_GRANT_2 = 4;
reg [2:0] b0_state = STATE_INIT;
reg [2:0] b0_state_next = STATE_INIT;
reg [2:0] b1_state = STATE_INIT;
reg [2:0] b1_state_next = STATE_INIT;
reg [2:0] b2_state = STATE_INIT;
reg [2:0] b2_state_next = STATE_INIT;
  // how could this be done less ugly?...
  assign req_for_thread_0[0] = i_req_0[0];
  assign req_for_thread_0[1] = i_req_1[0];
  assign req_for_thread_0[2] = i_req_2[0];
  assign req_for_thread_1[0] = i_req_0[1];
  //	'1'
  assign req_for_thread_1[1] = i_req_1[1];
  //	'0'
  assign req_for_thread_1[2] = i_req_2[1];
  // 	'0'	
  assign req_for_thread_2[0] = i_req_0[2];
  assign req_for_thread_2[1] = i_req_1[2];
  assign req_for_thread_2[2] = i_req_2[2];
  assign o_grant_0[0] = grant_for_thread_0[0];
  assign o_grant_0[1] = grant_for_thread_1[0];
  assign o_grant_0[2] = grant_for_thread_2[0];
  assign o_grant_1[0] = grant_for_thread_0[1];
  assign o_grant_1[1] = grant_for_thread_1[1];
  assign o_grant_1[2] = grant_for_thread_2[1];
  assign o_grant_2[0] = grant_for_thread_0[2];
  //0
  assign o_grant_2[1] = grant_for_thread_1[2];
  //1
  assign o_grant_2[2] = grant_for_thread_2[2];
  //0
  //computes the grant signal for bus_0 (e.g. determines who is allowed to send to the hwthread in slot 0.
  always @(req_for_thread_0, b0_state) begin
    b0_state_next <= b0_state;
    case(b0_state)
    STATE_INIT : begin
      b0_state_next <= STATE_WAIT;
      grant_for_thread_0 <= {((C_NR_SLOTS - 1)-(0)+1){1'b0}};
    end
    STATE_WAIT : begin
      //highes priority has slot 0 the rest can starve.
      if(req_for_thread_0[0] == 1'b1) begin
        b0_state_next <= STATE_GRANT_0;
        grant_for_thread_0 <= 3'b100;
      end
      else if(req_for_thread_0[1] == 1'b1) begin
        b0_state_next <= STATE_GRANT_1;
        grant_for_thread_0 <= 3'b010;
      end
      else if(req_for_thread_0[2] == 1'b1) begin
        b0_state_next <= STATE_GRANT_2;
        grant_for_thread_0 <= 3'b001;
      end
      else begin
        b0_state_next <= STATE_WAIT;
        grant_for_thread_0 <= 3'b000;
      end
    end
    STATE_GRANT_0 : begin
      //he can send as long as he likes...
      if(req_for_thread_0[0] == 1'b0) begin
        grant_for_thread_0 <= 3'b000;
        b0_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_0 <= 3'b100;
        b0_state_next <= STATE_GRANT_0;
      end
    end
    STATE_GRANT_1 : begin
      //he can send as long as he likes...
      if(req_for_thread_0[1] == 1'b0) begin
        grant_for_thread_0 <= 3'b000;
        b0_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_0 <= 3'b010;
        b0_state_next <= STATE_GRANT_1;
      end
    end
    STATE_GRANT_2 : begin
      //he can send as long as he likes...
      if(req_for_thread_0[2] == 1'b0) begin
        grant_for_thread_0 <= 3'b000;
        b0_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_0 <= 3'b001;
        b0_state_next <= STATE_GRANT_2;
      end
    end
    default : begin
      b0_state_next <= STATE_INIT;
    end
    endcase
  end
  //	grant_for_thread_1 <= "100";
  //computes the grant signal for bus_0 (e.g. determines who is allowed to send to the hwthread in slot 0.
  always @(req_for_thread_1, b1_state) begin
    b1_state_next <= b1_state;
    grant_for_thread_1 <= 3'b000;
    case(b1_state)
    STATE_INIT : begin
      b1_state_next <= STATE_WAIT;
      grant_for_thread_1 <= 3'b000;
    end
    STATE_WAIT : begin
      //highes priority has slot 0 the rest can starve.
      if(req_for_thread_1[0] == 1'b1) begin
        b1_state_next <= STATE_GRANT_0;
        grant_for_thread_1 <= 3'b100;
      end
      else if(req_for_thread_1[1] == 1'b1) begin
        b1_state_next <= STATE_GRANT_1;
        grant_for_thread_1 <= 3'b010;
      end
      else if(req_for_thread_1[2] == 1'b1) begin
        b1_state_next <= STATE_GRANT_2;
        grant_for_thread_1 <= 3'b001;
      end
      else begin
        b1_state_next <= STATE_WAIT;
        grant_for_thread_1 <= 3'b000;
      end
    end
    STATE_GRANT_0 : begin
      //he can send as long as he likes...
      if(req_for_thread_1[0] == 1'b0) begin
        grant_for_thread_1 <= 3'b000;
        b1_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_1 <= 3'b100;
        b1_state_next <= STATE_GRANT_0;
      end
    end
    STATE_GRANT_1 : begin
      //he can send as long as he likes...
      if(req_for_thread_1[1] == 1'b0) begin
        grant_for_thread_1 <= 3'b000;
        b1_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_1 <= 3'b010;
        b1_state_next <= STATE_GRANT_1;
      end
    end
    STATE_GRANT_2 : begin
      //he can send as long as he likes...
      if(req_for_thread_1[2] == 1'b0) begin
        grant_for_thread_1 <= 3'b000;
        b1_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_1 <= 3'b001;
        b1_state_next <= STATE_GRANT_2;
      end
    end
    default : begin
      b1_state_next <= STATE_INIT;
    end
    endcase
  end
  always @(req_for_thread_2, b2_state) begin
    b2_state_next <= b2_state;
    case(b2_state)
    STATE_INIT : begin
      b2_state_next <= STATE_WAIT;
      grant_for_thread_2 <= {((C_NR_SLOTS - 1)-(0)+1){1'b0}};
    end
    STATE_WAIT : begin
      //highes priority has slot 0 the rest can starve.
      if(req_for_thread_2[0] == 1'b1) begin
        b2_state_next <= STATE_GRANT_0;
        grant_for_thread_2 <= 3'b100;
      end
      else if(req_for_thread_2[1] == 1'b1) begin
        b2_state_next <= STATE_GRANT_1;
        grant_for_thread_2 <= 3'b010;
      end
      else if(req_for_thread_2[2] == 1'b1) begin
        b2_state_next <= STATE_GRANT_2;
        grant_for_thread_2 <= 3'b001;
      end
      else begin
        b2_state_next <= STATE_WAIT;
        grant_for_thread_2 <= 3'b000;
      end
    end
    STATE_GRANT_0 : begin
      //he can send as long as he likes...
      if(req_for_thread_2[0] == 1'b0) begin
        grant_for_thread_2 <= 3'b000;
        b2_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_2 <= 3'b100;
        b2_state_next <= STATE_GRANT_0;
      end
    end
    STATE_GRANT_1 : begin
      //he can send as long as he likes...
      if(req_for_thread_2[1] == 1'b0) begin
        grant_for_thread_2 <= 3'b000;
        b2_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_2 <= 3'b010;
        b2_state_next <= STATE_GRANT_1;
      end
    end
    STATE_GRANT_2 : begin
      //he can send as long as he likes...
      if(req_for_thread_2[2] == 1'b0) begin
        grant_for_thread_2 <= 3'b000;
        b2_state_next <= STATE_WAIT;
      end
      else begin
        grant_for_thread_2 <= 3'b001;
        b2_state_next <= STATE_GRANT_2;
      end
    end
    default : begin
      b2_state_next <= STATE_INIT;
    end
    endcase
  end
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      b0_state <= STATE_INIT;
      b1_state <= STATE_INIT;
      b2_state <= STATE_INIT;
    end else begin
      b0_state <= b0_state_next;
      b1_state <= b1_state_next;
      b2_state <= b2_state_next;
    end
  end
endmodule

module g23_YMD_counter(
input wire clock,
input wire reset,
input wire day_count_en,
input wire load_enable,
input wire [11:0] Y_set,
input wire [3:0] M_set,
input wire [4:0] D_set,
output wire [11:0] years,
output wire [3:0] months,
output wire [4:0] days
);
// ASYNC, Should be connected to the master 50MHz clock.
// ASYNC, When high the counts are all set to zero.
// SYNC, A pulse with a width of 1 master clock cycle.
// SYNC, if high sets count values to Y_Set, M_Set, and D_Set inputs
reg [31:0] y;
reg [31:0] m;
reg [31:0] d;
wire last_year;
wire last_month;
reg last_day;
wire leap_year;
wire mth_31d;
wire mth_30d;
wire mth_29d;
wire mth_28d;
  assign years = y;
  assign months = m;
  assign days = d;
  assign last_year = y == 4000 ? 1'b1 : 1'b0;
  assign last_month = m == 12 ? 1'b1 : 1'b0;
  assign leap_year = ((y % 4) == 0 && (y % 100) != 0 && (y % 400) == 0) ? 1'b1 : 1'b0;
  assign mth_31d = (m == 1) || (m == 3) || (m == 5) || (m == 7) || (m == 8) || (m == 10) || (m == 12) ? 1'b1 : 1'b0;
  assign mth_30d = (m == 4) || (m == 6) || (m == 9) || (m == 11) ? 1'b1 : 1'b0;
  assign mth_29d = (m == 2) && leap_year == 1'b1 ? 1'b1 : 1'b0;
  assign mth_28d = (m == 2) && leap_year == 1'b0 ? 1'b1 : 1'b0;
  // The counters are copycats from slide 43 in the VHDL 3 pdf
  // counts from 1 to 31
  always @(posedge reset, posedge clock) begin
    if(reset == 1'b1) begin
      d <= 1;
    end else begin
      last_day <= 1'b0;
      if(load_enable == 1'b1) begin
        d <= D_set;
      end
      if(day_count_en == 1'b1) begin
        if(mth_31d == 1'b1 && d < 31) begin
          d <= d + 1;
        end
        else if(mth_30d == 1'b1 && d < 30) begin
          d <= d + 1;
        end
        else if(mth_29d == 1'b1 && d < 29) begin
          d <= d + 1;
        end
        else if(mth_28d == 1'b1 && d < 28) begin
          d <= d + 1;
        end
        else begin
          // RESET EVERYTHING
          d <= 1;
          last_day <= 1'b1;
        end
      end
      //if enable
    end
  end
  // counts from 1 to 12
  always @(posedge reset, posedge clock, posedge last_day) begin
    if(reset == 1'b1) begin
      m <= 1;
    end else begin
      if(load_enable == 1'b1) begin
        m <= M_set;
      end
      if(last_day == 1'b1) begin
        if(last_month == 1'b0) begin
          m <= m + 1;
        end
        else begin
          m <= 1;
        end
        //if load
      end
      //if enable
    end
  end
  // counts from 0 to 4000
  always @(posedge reset, posedge clock, posedge last_month, posedge last_day) begin
    if(reset == 1'b1) begin
      y <= 0;
    end else begin
      if(load_enable == 1'b1) begin
        y <= Y_set;
      end
      if(last_day == 1'b1 && last_month == 1'b1) begin
        if(last_year == 1'b1) begin
          y <= 0;
        end
        else begin
          y <= y + 1;
        end
        //if load
      end
      //if enable
    end
  end
endmodule

module dp_neg(
input wire sysclk,
input wire reset,
input wire enable,
input wire signin,
input wire [11:1] exponentin,
input wire [52:1] mantissain,
output wire signout,
output wire [11:1] exponentout,
output wire [52:1] mantissaout,
output wire satout,
output wire zeroout,
output wire nanout
);
reg signff;
reg [11:1] exponentff;
reg [52:1] mantissaff;
wire [11:1] expnode;
wire [11:1] expzerochk; wire [11:1] expmaxchk;
wire expzero; wire expmax;
wire [52:1] manzerochk;
wire manzero; wire mannonzero;
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      signff <= 1'b0;
      for (k=1; k <= 11; k = k + 1) begin
        exponentff[k] <= 1'b0;
      end
      for (k=1; k <= 52; k = k + 1) begin
        mantissaff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        signff <=  ~(signin);
        exponentff <= exponentin;
        mantissaff <= mantissain;
      end
    end
  end
  assign expzerochk[1] = exponentff[1];
  assign expmaxchk[1] = exponentff[1];
  genvar k;
  generate for (k=2; k <= 11; k = k + 1) begin: gxa
      assign expzerochk[k] = expzerochk[k - 1] | exponentff[k];
    assign expmaxchk[k] = expmaxchk[k - 1] & exponentff[k];
  end
  endgenerate
  assign expzero =  ~(expzerochk[11]);
  assign expmax = expmaxchk[11];
  assign manzerochk[1] = mantissaff[1];
  genvar k;
  generate for (k=2; k <= 52; k = k + 1) begin: gma
      assign manzerochk[k] = manzerochk[k - 1] | mantissaff[k];
  end
  endgenerate
  assign manzero =  ~(manzerochk[52]);
  assign mannonzero = manzerochk[52];
  assign signout = signff;
  assign exponentout = exponentff;
  assign mantissaout = mantissaff;
  assign satout = expmax & manzero;
  assign zeroout = expzero;
  assign nanout = expmax & mannonzero;
endmodule

