module Prueba(
input wire [3:0] a,
input wire [3:0] b,
input wire op,
output wire [3:0] s,
output wire cout
);
wire [3:0] eb;
wire [4:0] c;
  assign c[0] = op;
  genvar i;
  generate for (i=0; i <= 3; i = i + 1) begin: sumador
      assign EB[i] = B[i] ^ OP;
    assign S[i] = A[i] ^ EB[i] ^ C[i];
    assign C[i + 1] = (EB[i] & C[i]) | (A[i] & C[i]) | (A[i] & EB[i]);
  end
  endgenerate
  assign cout = c[4];
endmodule

module cla(
input wire [n - 1:0] x,
input wire [n - 1:0] y,
output wire [n - 1:0] sum,
output wire cout
);
parameter [31:0] n=32;
// input size (default is 32 bits)
// first binary number to sum
// second binary number to sum
// result of the sum
// carry out
wire [n - 1:0] G;  // generate signal:  G_i = x_i * y_i
wire [n - 1:0] P;  // propagate signal: P_i = x_i + y_i
wire [n - 1:0] S;  // sum signal
wire [n:0] C;  // carry signal
  genvar i;
  generate for (i=0; i <= n - 1; i = i + 1) begin: FA_gen
      full_adder FA_instance(
          .x(x[i]),
      .y(y[i]),
      .cin(C[i]),
      .sum(S[i]),
      .cout(/* open */));
  end
  endgenerate
  assign C[0] = 1'b0;
  // there is no initial carry
  genvar j;
  generate for (j=0; j <= n - 1; j = j + 1) begin: PGC_gen
      assign G[j] = x[j] & y[j];
    assign P[j] = x[j] | y[j];
    assign C[j + 1] = G[j] | (P[j] & C[j]);
  end
  endgenerate
  assign sum = S;
  assign cout = C[n];
endmodule

module uart_transmitter(
input wire CLK,
input wire RST,
input wire TXCLK,
input wire TXSTART,
input wire CLEAR,
input wire [1:0] WLS,
input wire STB,
input wire PEN,
input wire EPS,
input wire SP,
input wire BC,
input wire [7:0] DIN,
output wire TXFINISHED,
output wire SOUT
);
// Clock
// Reset
// Transmitter clock (2x baudrate)
// Start transmitter
// Clear transmitter state
// Word length select
// Number of stop bits
// Parity enable
// Even parity select
// Stick parity
// Break control
// Input data
// Transmitter operation finished
// Transmitter output
// FSM
parameter [3:0]
  IDLE = 0,
  START = 1,
  BIT0 = 2,
  BIT1 = 3,
  BIT2 = 4,
  BIT3 = 5,
  BIT4 = 6,
  BIT5 = 7,
  BIT6 = 8,
  BIT7 = 9,
  PAR = 10,
  STOP = 11,
  STOP2 = 12;
reg [3:0] CState; reg [3:0] NState;  // Signals
reg iTx2;  // Next TX step
reg iSout;  // Transmitter output
reg iParity;  // Parity
reg iFinished;  // TX finished
  // Transmitter FSM update process
  always @(posedge RST, posedge CLK) begin
    if((RST == 1'b1)) begin
      CState <= IDLE;
      iTx2 <= 1'b0;
    end else begin
      if((TXCLK == 1'b1)) begin
        // TX clock
        if((iTx2 == 1'b0)) begin
          // Two TX clocks per step
          CState <= NState;
          // Next step
          iTx2 <= 1'b1;
        end
        else begin
          if(((WLS == 2'b00) && (STB == 1'b1) && CState == STOP2)) begin
            CState <= NState;
            // 1.5 stop bits for 5 bit word mode
            iTx2 <= 1'b1;
          end
          else begin
            CState <= CState;
            // First TX clock, wait
            iTx2 <= 1'b0;
          end
        end
      end
    end
  end
  // Transmitter FSM
  always @(CState, TXSTART, DIN, WLS, PEN, SP, EPS, STB, iParity) begin
    // Defaults
    NState <= IDLE;
    iSout <= 1'b1;
    case(CState)
    IDLE : begin
      if((TXSTART == 1'b1)) begin
        NState <= START;
      end
    end
    START : begin
      iSout <= 1'b0;
      NState <= BIT0;
    end
    BIT0 : begin
      iSout <= DIN[0];
      NState <= BIT1;
    end
    BIT1 : begin
      iSout <= DIN[1];
      NState <= BIT2;
    end
    BIT2 : begin
      iSout <= DIN[2];
      NState <= BIT3;
    end
    BIT3 : begin
      iSout <= DIN[3];
      NState <= BIT4;
    end
    BIT4 : begin
      iSout <= DIN[4];
      if((WLS == 2'b00)) begin
        // 5 bits
        if((PEN == 1'b1)) begin
          NState <= PAR;
          // Parity enabled
        end
        else begin
          NState <= STOP;
          // No parity
        end
      end
      else begin
        NState <= BIT5;
      end
    end
    BIT5 : begin
      iSout <= DIN[5];
      if((WLS == 2'b01)) begin
        // 6 bits
        if((PEN == 1'b1)) begin
          NState <= PAR;
          // Parity enabled
        end
        else begin
          NState <= STOP;
          // No parity
        end
      end
      else begin
        NState <= BIT6;
      end
    end
    BIT6 : begin
      iSout <= DIN[6];
      if((WLS == 2'b10)) begin
        // 7 bits
        if((PEN == 1'b1)) begin
          NState <= PAR;
          // Parity enabled
        end
        else begin
          NState <= STOP;
          // No parity
        end
      end
      else begin
        NState <= BIT7;
      end
    end
    BIT7 : begin
      iSout <= DIN[7];
      if((PEN == 1'b1)) begin
        NState <= PAR;
        // Parity enabled
      end
      else begin
        NState <= STOP;
        // No parity
      end
    end
    PAR : begin
      if((SP == 1'b1)) begin
        // Sticky parity
        if((EPS == 1'b1)) begin
          iSout <= 1'b0;
          // Even parity -> cleared
        end
        else begin
          iSout <= 1'b1;
          // Odd parity  -> set
        end
      end
      else begin
        if((EPS == 1'b1)) begin
          iSout <= iParity;
          // Even parity
        end
        else begin
          iSout <=  ~iParity;
          // Odd parity
        end
      end
      NState <= STOP;
    end
    STOP : begin
      if((STB == 1'b1)) begin
        // 2 stop bits
        NState <= STOP2;
      end
      else begin
        if((TXSTART == 1'b1)) begin
          // Next transmission
          NState <= START;
        end
      end
    end
    STOP2 : begin
      if((TXSTART == 1'b1)) begin
        // Next transmission
        NState <= START;
      end
    end
    default : begin
    end
    endcase
  end
  // Parity generation
  always @(DIN, WLS) begin : P2
    reg iP40, iP50, iP60, iP70;
    iP40 = DIN[4] ^ DIN[3] ^ DIN[2] ^ DIN[1] ^ DIN[0];
    iP50 = DIN[5] ^ iP40;
    iP60 = DIN[6] ^ iP50;
    iP70 = DIN[7] ^ iP60;
    case(WLS)
    2'b00 : begin
      iParity <= iP40;
    end
    2'b01 : begin
      iParity <= iP50;
    end
    2'b10 : begin
      iParity <= iP60;
    end
    default : begin
      iParity <= iP70;
    end
    endcase
  end
  // Signal TX finished on STOP bit transmission
  always @(posedge CLK, posedge RST) begin : P1
    reg iLast;
    if((RST == 1'b1)) begin
      iFinished <= 1'b0;
      iLast = 1'b0;
    end else begin
      iFinished <= 1'b0;
      if((iLast == 1'b0 && CState == STOP)) begin
        iFinished <= 1'b1;
      end
      if((CState == STOP)) begin
        iLast = 1'b1;
      end
      else begin
        iLast = 1'b0;
      end
    end
  end
  // Output signals
  assign SOUT = BC == 1'b0 ? iSout : 1'b0;
  assign TXFINISHED = iFinished;
endmodule

