reg [15:0] Part1_0; reg [15:0] Part1_1; reg [15:0] Part1_2; reg [15:0] Part1_3;
reg [15:0] Part2_0; reg [15:0] Part2_1; reg [15:0] Part2_2; reg [15:0] Part2_3;
reg [15:0] Part3_0; reg [15:0] Part3_1; reg [15:0] Part3_2; reg [15:0] Part3_3;
reg [15:0] Part4_0; reg [15:0] Part4_1; reg [15:0] Part4_2; reg [15:0] Part4_3;
  //--------------------------------
  //---- Combinatorial logic  ------
  //--------------------------------
  always @(Part0_0, Part0_1, Part0_2, Part0_3, Part1_0, Part1_1, Part1_2, Part1_3, Part2_0, Part2_1, Part2_2, Part2_3, Part3_0, Part3_1, Part3_2, Part3_3, Part4_0, Part4_1, Part4_2, Part4_3, Sel) begin
    load0out <= {Part0_0,Part0_1,Part0_2,Part0_3};
    load1out <= {Part1_0,Part1_1,Part1_2,Part1_3};
    load2out <= {Part2_0,Part2_1,Part2_2,Part2_3};
    load3out <= {Part3_0,Part3_1,Part3_2,Part3_3};
    load4out <= {Part4_0,Part4_1,Part4_2,Part4_3};
    if(Sel == 2'b00) begin
      Shift0Out <= Part0_0;
      Shift1Out <= Part1_0;
      Shift2Out <= Part2_0;
      Shift3Out <= Part3_0;
      Shift4Out <= Part4_0;
    end
    else if(Sel == 2'b01) begin
      Shift0Out <= Part0_1;
      Shift1Out <= Part1_1;
      Shift2Out <= Part2_1;
      Shift3Out <= Part3_1;
      Shift4Out <= Part4_1;
    end
    else if(Sel == 2'b10) begin
      Shift0Out <= Part0_2;
      Shift1Out <= Part1_2;
      Shift2Out <= Part2_2;
      Shift3Out <= Part3_2;
      Shift4Out <= Part4_2;
    end
    else begin
      Shift0Out <= Part0_3;
      Shift1Out <= Part1_3;
      Shift2Out <= Part2_3;
      Shift3Out <= Part3_3;
      Shift4Out <= Part4_3;
    end
  end
  //-------------------------------------------
  //---- The registers in the datapath --------
  //-------------------------------------------
  always @(posedge Clk) begin
    if(ShiftEnable == 1'b1) begin
      if(Sel == 2'b00) begin
        Part0_0 <= Shift0In;
        Part1_0 <= Shift1In;
        Part2_0 <= Shift2In;
        Part3_0 <= Shift3In;
        Part4_0 <= Shift4In;
      end
      else if(Sel == 2'b01) begin
        Part0_1 <= Shift0In;
        Part1_1 <= Shift1In;
        Part2_1 <= Shift2In;
        Part3_1 <= Shift3In;
        Part4_1 <= Shift4In;
      end
      else if(Sel == 2'b10) begin
        Part0_2 <= Shift0In;
        Part1_2 <= Shift1In;
        Part2_2 <= Shift2In;
        Part3_2 <= Shift3In;
        Part4_2 <= Shift4In;
      end
      else if(Sel == 2'b11) begin
        Part0_3 <= Shift0In;
        Part1_3 <= Shift1In;
        Part2_3 <= Shift2In;
        Part3_3 <= Shift3In;
        Part4_3 <= Shift4In;
      end
    end
    else begin
      if(Reg0En == 1'b1) begin
        Part0_0 <= load0in[63:48];
        Part0_1 <= load0in[47:32];
        Part0_2 <= load0in[31:16];
        Part0_3 <= load0in[15:0];
      end
      if(Reg1En == 1'b1) begin
        Part1_0 <= load1in[63:48];
        Part1_1 <= load1in[47:32];
        Part1_2 <= load1in[31:16];
        Part1_3 <= load1in[15:0];
      end
      if(Reg2En == 1'b1) begin
        Part2_0 <= load2in[63:48];
        Part2_1 <= load2in[47:32];
        Part2_2 <= load2in[31:16];
        Part2_3 <= load2in[15:0];
      end
      if(Reg3En == 1'b1) begin
        Part3_0 <= load3in[63:48];
        Part3_1 <= load3in[47:32];
        Part3_2 <= load3in[31:16];
        Part3_3 <= load3in[15:0];
      end
      if(Reg4En == 1'b1) begin
        Part4_0 <= load4in[63:48];
        Part4_1 <= load4in[47:32];
        Part4_2 <= load4in[31:16];
        Part4_3 <= load4in[15:0];
      end
    end
  end
endmodule

