);
parameter [3:0]
  recv = 0,
  bsend1 = 1,
  send1 = 2,
  bsend2 = 3,
  send2 = 4,
  bsend3 = 5,
  send3 = 6,
  bsend4 = 7,
  send4 = 8,
  s1 = 9,
  s2 = 10,
  s3 = 11,
  s4 = 12,
  s5 = 13,
  s6 = 14;
reg [3:0] present_state = s3;
reg [3:0] next_state = s3;
wire [15:0] player_color;
wire [7:0] input;  // sender ports
reg [7:0] snd_data = 8'b00000000;
reg snd_start = 1'b0;
wire snd_busy;
  // set senders port
  async_transmitter snd(
      clk,
    snd_start,
    snd_data,
    txd,
    snd_busy);
  always @(posedge clk) begin
    present_state <= next_state;
  end
  always @(present_state, snd_busy) begin
    case(present_state)
    s1 : begin
      // nothing
          end
    recv : begin
      // nothing
          end
    s2 : begin
      // nothing
          end
    s3 : begin
      // start send @
      snd_data <= 8'b01000000;
      next_state <= bsend1;
    end
    bsend1 : begin
      snd_start <= 1'b1;
      next_state <= send1;
    end
    send1 : begin
      snd_start <= 1'b0;
      if((snd_busy == 1'b0)) begin
        next_state <= s4;
      end
    end
    s4 : begin
      // start send 0
      snd_data <= 8'b00110000;
      next_state <= bsend2;
    end
    bsend2 : begin
      snd_start <= 1'b1;
      next_state <= send2;
    end
    send2 : begin
      snd_start <= 1'b0;
      if((snd_busy == 1'b0)) begin
        next_state <= s5;
      end
    end
    s5 : begin
      // start send /
      snd_data <= 8'b00101111;
      next_state <= bsend3;
    end
    bsend3 : begin
      snd_start <= 1'b1;
      next_state <= send3;
    end
    send3 : begin
      snd_start <= 1'b0;
      if((snd_busy == 1'b0)) begin
        next_state <= s6;
      end
    end
    s6 : begin
      // start send \n
      snd_data <= 8'b00001010;
      next_state <= bsend4;
    end
    bsend4 : begin
      snd_start <= 1'b1;
      next_state <= send4;
    end
    send4 : begin
      snd_start <= 1'b0;
      if((snd_busy == 1'b0)) begin
        next_state <= s3;
      end
    end
    endcase
  end
endmodule

