        argumentff <= argumentbus;
        topargumentff <= argumentff[36:28];
        middleargumentff <= argumentff[27:20];
        tanhighmantissaff <= tanhighmantissa;
        tanhighexponentff <= tanhighexponent;
        tanmiddleff <= tanmiddle;
        tanlowsumff <= tanlowsumnode;
      end
    end
  end
  assign shiftin = 127 - exponentinff;
  assign shiftinbus = {1'b1,mantissainff,zerovec[12:1]};
  fp_rsft36 csftin(
      .inbus(shiftinbus),
    .shift(shiftin[6:1]),
    .outbus(argumentbus));
  fp_tanlut1 chtt(
      .add(topargumentff),
    .mantissa(tanhighmantissa),
    .exponent(tanhighexponent));
  fp_tanlut2 cltt(
      .add(middleargumentff),
    .tanfraction(tanmiddle));
  // in level 2, out level 4        
  fp_del #(
      .width(19),
    .pipes(2))
  dtail(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(argumentff[19:1]),
    .cc(deltwo_tailnode));
  assign tantailnode = {zerovec[8:1],deltwo_tailnode,zerovec[9:1]};
  assign tanlowsumnode = ({1'b0,tanmiddleff[36:1]}) + ({1'b0,tantailnode});
  assign tanlowmantissabus = {tanlowsumff,zerovec[19:1]};
  //*********************************************
  //*** Align two tangent values for addition ***
  //*********************************************
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 56; k = k + 1) begin
        tanlowff[k] <= 1'b0;
      end
      for (k=1; k <= 57; k = k + 1) begin
        numeratorsumff[k] <= 1'b0;
      end
      for (k=1; k <= 36; k = k + 1) begin
        numeratormantissaff[k] <= 1'b0;
      end
      for (k=1; k <= 5; k = k + 1) begin
        numeratorexponentff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        tanlowff <= tanlowbus;
        numeratorsumff <= numeratorsum;
        numeratormantissaff <= numeratormantissa;
        numeratorexponentff <= numeratorexponent;
      end
    end
  end
  // in level 4, out level 5        
  fp_del #(
      .width(5),
    .pipes(1))
  dhxa(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(tanhighexponentff),
    .cc(delone_tanhighexponent));
  // in level 5, out level 7        
  fp_del #(
      .width(5),
    .pipes(2))
  dhxb(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(delone_tanhighexponent),
    .cc(delthr_tanhighexponent));
  // in level 4, out level 6        
  fp_del #(
      .width(36),
    .pipes(2))
  dhm(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(tanhighmantissaff),
    .cc(deltwo_tanhighmantissa));
  // tan high mantissa format 1.XXX, tan low mantissa format 0.XXXXX 
  // tan high exponent base is 119 (top of middle range)
  assign tanlowshift = delone_tanhighexponent;
  fp_rsft56x20 crsadd(
      .inbus(tanlowmantissabus),
    .shift(tanlowshift),
    .outbus(tanlowbus));
  assign numeratorsum = ({1'b0,deltwo_tanhighmantissa,zerovec[20:1]}) + ({1'b0,tanlowff});
  // level 8
  // no pipe between clz and shift as only 6 bit shift 
  // middle exponent is 119, and 2 overflow bits in numerator sum, so this will
  // cover downto (119+2-6) = 115 exponent
  // below 115 exponent, output mantissa = input mantissa
  fp_clz36x6 clznuma(
      .mantissa(numeratorsumff[57:22]),
    .leading(numeratorlead));
  assign numeratorleadnode = {3'b000,numeratorlead[3:1]};
  // force [6:4] to 0 to optimize away logic in LSFT
  fp_lsft36 clsnuma(
      .inbus(numeratorsumff[57:22]),
    .shift(numeratorleadnode),
    .outbus(numeratormantissa));
  assign numeratorexponent = delthr_tanhighexponent - numeratorlead[5:1] + 1;
  //gnnadd: FOR k IN 1 TO 36 GENERATE
  //  numeratormantissa(k) <= (numeratorsumff(k+20) AND NOT(numeratorsumff(57))) OR 
  //                          (numeratorsumff(k+21) AND numeratorsumff(57));
  //END GENERATE;
  //numeratorexponent <= delthr_tanhighexponent + ("0000" & numeratorsumff(57));
  //***************************************************
  //*** Align two tangent values for multiplication ***
  //***************************************************  
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 6; k = k + 1) begin
        lowleadff[k] <= 1'b0;
        denominatorleadff[k] <= 1'b0;
        inverseexponentff[k] <= 1'b0;
      end
      for (k=1; k <= 6; k = k + 1) begin
        multshiftff[k] <= 1'b0;
      end
      for (k=1; k <= 36; k = k + 1) begin
        denominatorproductff[k] <= 1'b0;
        denominatorff[k] <= 1'b0;
        denominatormantissaff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        lowleadff <= lowleadnode;
        multshiftff <= multshiftnode;
        denominatorproductff <= denominatorproductbus;
        denominatorff <= denominator;
        denominatorleadff <= denominatorlead;
        denominatormantissaff <= denominatormantissa;
        inverseexponentff <= inverseexponent;
      end
    end
  end
  fp_clz36 clzmula(
      .mantissa(tanlowsumff[37:2]),
    .leading(lowleadnode));
  // in level 5, out level 6       
  fp_del #(
      .width(36),
    .pipes(1))
  dlm(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(tanlowsumff[37:2]),
    .cc(delone_tanlowsum));
  fp_lsft36 clsmula(
      .inbus(delone_tanlowsum),
    .shift(lowleadff),
    .outbus(lowmantissabus));
  fp_fxmul #(
      .widthaa(36),
    .widthbb(36),
    .widthcc(72),
    .pipes(3),
    .synthesize(0))
  cma(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    .dataaa(deltwo_tanhighmantissa),
    .databb(lowmantissabus),
    .result(multipliernode));
  // in level 5, out level 8        
  fp_del #(
      .width(5),
    .pipes(3))
  dhxc(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(delone_tanhighexponent),
    .cc(delfor_tanhighexponent));
  // in level 6, out level 8        
  fp_del #(
      .width(6),
    .pipes(2))
  dlla(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(lowleadff),
    .cc(deltwo_lowlead));
  // msb of lowmantissa(37) is at exponent 0 for highmantissa
  assign multexponent = {1'b0,delfor_tanhighexponent};
  //multshiftnode <= "001000" - multexponent + 8 - 1 + lowlead;
  assign multshiftnode = 6'b001111 - multexponent + deltwo_lowlead;
  // '1.0' is at exponent 8 compared to highmantissa 
  fp_rsft36 crsmul(
      .inbus(multipliernode[72:37]),
    .shift(multshiftff),
    .outbus(denominatorproductbus));
  assign denominator = ({1'b1,zerovec[35:1]}) - denominatorproductff;
  // in level 11, out level 12        
  fp_del #(
      .width(36),
    .pipes(1))
  dda(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    // use reset to force to ffs here
    .aa(denominatorff),
    .cc(delone_denominator));
  fp_clz36 clzmulb(
      .mantissa(denominatorff),
    .leading(denominatorlead));
  // denominatormantissa level 12, (denominatormantissaff level 13)
  fp_lsft36 clsmulb(
      .inbus(delone_denominator),
    .shift(denominatorleadff),
    .outbus(denominatormantissa));
  assign denominatorexponent = denominatorleadff;
  // actually inverse of exponent i.e. 4 => -4, so sign does not have to change after inverting
  // inverseexponentff level 13
  assign inverseexponent = denominatorexponent - 1;
  //****************************   
  //*** main divider section ***
  //****************************
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 8; k = k + 1) begin
        tanexponentff[k] <= 1'b0;
        tanexponentnormff[k] <= 1'b0;
        exponentoutff[k] <= 1'b0;
      end
      for (k=1; k <= 24; k = k + 1) begin
        tanmantissanormff[k] <= 1'b0;
      end
      roundbitff <= 1'b0;
      for (k=1; k <= 23; k = k + 1) begin
        mantissaoutff[k] <= 1'b0;
      end
      overff <= 1'b0;
    end else begin
      if((enable == 1'b1)) begin
        tanexponentff <= tanexponent;
        tanmantissanormff <= tanmantissanorm;
        // level 29
        tanexponentnormff <= tanexponentnorm;
        // level 29
        overff <= overcheck[24];
        // round up if 0.4999
        roundbitff <= tanmantissanorm[1] | (tanmantissatail[9] & tanmantissatail[8] & tanmantissatail[7] & tanmantissatail[6] & tanmantissatail[5] & tanmantissatail[4] & tanmantissatail[3] & tanmantissatail[2] & tanmantissatail[1]);
        mantissaoutff <= mantissaoutnode;
        // level 30
        exponentoutff <= exponentoutnode;
        // level 30
      end
    end
  end
  // latency 12
  // will give output between 0.5 and 0.99999...
  // will always need to be normalized
  // level 13 in, level 25 out
  fp_inv_core #(
      .synthesize(0))
  cinv(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    .divisor(denominatormantissaff),
    .quotient(denominatorinverse));
  // level 8 in, level 25 out         
  fp_del #(
      .width(36),
    .pipes(17))
  dnuma(
      .sysclk(sysclk),
    .reset(1'b0),
    .enable(enable),
    // no resets for memory
    .aa(numeratormantissaff),
    .cc(del_numeratormantissa));
  // level 25 in, level 28 out
  fp_fxmul #(
      .widthaa(36),
    .widthbb(36),
    .widthcc(72),
    .pipes(3),
    .synthesize(0))
  cmt(
      .sysclk(sysclk),
    .reset(reset),
    .enable(enable),
    .dataaa(del_numeratormantissa),
    .databb(denominatorinverse),
    .result(multiplier_tan));
  assign tanmantissa = multiplier_tan[72:37];
  genvar k;
  generate for (k=1; k <= 24; k = k + 1) begin: gmna
      assign tanmantissanorm[k] = (tanmantissa[k + 9] &  ~(tanmantissa[35])) | (tanmantissa[k + 10] & tanmantissa[35]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 9; k = k + 1) begin: gmnb
      assign tanmantissatail[k] = (tanmantissa[k] &  ~(tanmantissa[35])) | (tanmantissa[k + 1] & tanmantissa[35]);
  end
  endgenerate
  assign overcheck[1] = tanmantissanorm[1];
  genvar k;
  generate for (k=2; k <= 24; k = k + 1) begin: gova
      assign overcheck[k] = overcheck[k - 1] & tanmantissanorm[k];
  end
  endgenerate
  // level 13 in, level 27 out
  fp_del #(
      .width(6),
    .pipes(14))
  ddena(
      .sysclk(sysclk),
    .reset(1'b0),
    .enable(enable),
    // no resets for memory
    .aa(inverseexponentff),
    .cc(del_inverseexponent));
  // level 8 in, level 27 out         
  fp_del #(
      .width(5),
    .pipes(19))
  dnumb(
      .sysclk(sysclk),
    .reset(1'b0),
    .enable(enable),
    // no resets for memory
    .aa(numeratorexponentff),
    .cc(del_numeratorexponent));
  assign tanexponent = 8'b01110111 + ({del_numeratorexponent[5],del_numeratorexponent[5],del_numeratorexponent[5],del_numeratorexponent}) + ({del_inverseexponent[6],del_inverseexponent[6],del_inverseexponent});
  // 119 + exponent
  assign tanexponentnorm = tanexponentff + tanmantissa[35];
  //*** handle small inputs ****
  fp_del #(
      .width(23),
    .pipes(29))
  dsma(
      .sysclk(sysclk),
    .reset(1'b0),
    .enable(enable),
    // no resets for memory
    .aa(mantissain),
    .cc(small_mantissa));
  fp_del #(
      .width(8),
    .pipes(29))
  dsxa(
      .sysclk(sysclk),
    .reset(1'b0),
    .enable(enable),
    // no resets for memory
    .aa(exponentin),
    .cc(small_exponent));
  assign exponentcheck = exponentinff - 115;
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      for (k=1; k <= 30; k = k + 1) begin
        signff[k] <= 1'b0;
      end
      for (k=1; k <= 28; k = k + 1) begin
        small_inputff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        signff[1] <= signin;
        for (k=2; k <= 30; k = k + 1) begin
          signff[k] <= signff[k - 1];
        end
        small_inputff[1] <= exponentcheck[8];
        for (k=2; k <= 28; k = k + 1) begin
          small_inputff[k] <= small_inputff[k - 1];
        end
      end
    end
  end
  //mantissabase(1) <= (tanmantissanormff(1) AND NOT(small_inputff(28)));
  assign mantissabase[1] = roundbitff &  ~(small_inputff[28]);
  genvar k;
  generate for (k=2; k <= 24; k = k + 1) begin: gmba
      assign mantissabase[k] = (small_mantissa[k - 1] & small_inputff[28]) | (tanmantissanormff[k] &  ~(small_inputff[28]));
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 8; k = k + 1) begin: gxba
      assign exponentbase[k] = (small_exponent[k] & small_inputff[28]) | (tanexponentnormff[k] &  ~(small_inputff[28]));
  end
  endgenerate
  assign mantissaoutnode = mantissabase[24:2] + mantissabase[1];
  assign exponentoutnode = exponentbase + (overff &  ~(small_inputff[28]));
  //***************
  //*** OUTPUTS ***
  //***************
  assign signout = signff[30];
  assign mantissaout = mantissaoutff;
  assign exponentout = exponentoutff;
endmodule

