module divisorfrec(
input wire clk,
input wire reset,
output wire salida
);
reg temporal;
reg [31:0] contador = 0;  //De 50Mhz a 83Hz
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      temporal <= 1'b0;
      contador <= 0;
    end else begin
      if((contador == 299999)) begin
        temporal <=  ~(temporal);
        contador <= 0;
      end
      else begin
        contador <= contador + 1;
      end
    end
  end
  assign salida = temporal;
endmodule

module UARTReciever(
input wire clk,
input wire rst,
input wire tick,
input wire rx,
output wire [7:0] d_out,
output reg rx_done
);
parameter [1:0]
  idle = 0,
  start = 1,
  data = 2,
  stop = 3;
reg [1:0] next_state; reg [1:0] current_state;
reg [3:0] tick_counter; reg [3:0] tick_counter_next;
reg [2:0] bit_counter; reg [2:0] bit_counter_next;
reg [7:0] reg; reg [7:0] reg_next;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b0)) begin
      current_state <= idle;
      tick_counter <= 4'b0000;
      bit_counter <= 3'b000;
      reg <= {8{1'b0}};
    end else begin
      current_state <= next_state;
      tick_counter <= tick_counter_next;
      bit_counter <= bit_counter_next;
      reg <= reg_next;
    end
  end
  always @(current_state, tick_counter, bit_counter, reg, tick, rx) begin
    next_state <= current_state;
    tick_counter_next <= tick_counter;
    bit_counter_next <= bit_counter;
    reg_next <= reg;
    rx_done <= 1'b0;
    case(current_state)
    idle : begin
      if((rx == 1'b0)) begin
        next_state <= start;
        tick_counter_next <= 4'b0000;
        reg_next <= 8'b00000000;
      end
    end
    start : begin
      if((tick == 1'b1)) begin
        if((tick_counter < 7)) begin
          tick_counter_next <= tick_counter + 1;
        end
        else begin
          tick_counter_next <= 4'b0000;
          bit_counter_next <= 3'b000;
          next_state <= data;
        end
      end
    end
    data : begin
      if((tick == 1'b1)) begin
        if((tick_counter < 15)) begin
          tick_counter_next <= tick_counter + 1;
        end
        else begin
          tick_counter_next <= 4'b0000;
          reg_next <= {rx,reg[7:1]};
          if((bit_counter == 7)) begin
            next_state <= stop;
          end
          else begin
            bit_counter_next <= bit_counter + 1;
          end
        end
      end
    end
    stop : begin
      if((tick == 1'b1)) begin
        if((tick_counter < 15)) begin
          tick_counter_next <= tick_counter + 1;
        end
        else begin
          next_state <= idle;
          rx_done <= 1'b1;
        end
      end
    end
    endcase
  end
  assign d_out = reg;
endmodule

`timescale 1 ns / 1 ns
module weights_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
reg [0:0] WEA_R = 1'b0;
wire [4:0] ADDRA = 1'b0;
reg [4:0] ADDRA_R = 1'b0;
wire [23:0] DINA = 1'b0;
reg [23:0] DINA_R = 1'b0;
wire [23:0] DOUTA;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(24),
    .READ_WIDTH(24))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {1{1'b0}};
      DINA_R <= # 50 {24{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {5{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  weights_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

