module i2c_arbiter_hotone_dec(
input wire clk_i,
input wire rst_n_i,
input wire enable_i,
input wire [g_num_inputs - 1:0] start_state_i,
output reg input_enabled_o,
output reg [31:0] input_idx_enabled_o
);
parameter [31:0] g_num_inputs=2;
// Clock & Reset
  always @(posedge clk_i) begin : P1
    reg [31:0] idx =  -1;
    if(rst_n_i == 1'b0) begin
      input_enabled_o <= 1'b0;
      input_idx_enabled_o <= 0;
    end
    else begin
      if(enable_i == 1'b1) begin
        idx =  -1;
        for (I=g_num_inputs - 1; I >= 0; I = I - 1) begin
          if(start_state_i[I] == 1'b1) begin
            idx = I;
          end
        end
        if(idx == ( -1)) begin
          input_enabled_o <= 1'b0;
          input_idx_enabled_o <= 0;
        end
        else begin
          input_enabled_o <= 1'b1;
          input_idx_enabled_o <= idx;
        end
      end
    end
  end
endmodule

module DE1_disp(
input wire [6:0] HEX0,
input wire [6:0] HEX1,
input wire [6:0] HEX2,
input wire [6:0] HEX3,
input wire clk,
output wire [6:0] HEX,
output wire [3:0] DISPn
);
wire [2:0] M;
  // Behavior
  sweep S0(
      clk,
    M);
  assign HEX = M == 3'b000 ? HEX0 : M == 3'b010 ? HEX1 : M == 3'b100 ? HEX2 : M == 3'b110 ? HEX3 : 7'b1111111;
  assign DISPn = M == 3'b000 ? 4'b1110 : M == 3'b010 ? 4'b1101 : M == 3'b100 ? 4'b1011 : M == 3'b110 ? 4'b0111 : 4'b1111;
endmodule

module mul_540(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [15:0] in_b
);
wire [47:0] tmp_res;
  // The actual multiplication
  assign tmp_res = (in_a) * (in_b);
  // Set the output
  assign result = tmp_res[31:0];
endmodule

module add_184(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

module Reg(
input wire CLK,
input wire RST,
input wire [regSize:0] D,
output reg [regSize:0] Q
);
parameter [31:0] regSize=BITREG_16;
  always @(negedge CLK, negedge RST) begin
    if((RST == 1'b1)) begin
      Q <= {((regSize)-(0)+1){1'b0}};
    end else begin
      // trigger on falling edge
      Q <= D;
    end
  end
endmodule

module Mux4to1(
input wire [3:0] DecHor,
input wire [3:0] UniHor,
input wire [3:0] DecMin,
input wire [3:0] UniMin,
input wire [1:0] Sel,
output reg [3:0] Tiempo
);
  // Definicion del multiplexor
  always @(*) begin
    case(Sel)
      2'b00 : Tiempo <= DecHor;
      2'b01 : Tiempo <= UniHor;
      2'b10 : Tiempo <= DecMin;
      default : Tiempo <= UniMin;
    endcase
  end
endmodule

module dma_tx(
input wire Clk,
input wire Reset,
input wire [7:0] Databus,
output reg [7:0] Address,
output reg ChipSelect,
output wire WriteEnable,
output reg OutputEnable,
input wire Start_TX,
output reg Ready_TX,
output reg End_TX,
output reg [7:0] DataOut,
output reg Valid_DO,
input wire Ack_DO
);
// Señales procedentes del bus del uP.
// Señales procedentes de la FSM del Controlador de Bus.
// Bus de datos y señales de handshake orientadas al transmisor del
// RS232.
// Definición de los posibles estados de la FSM del Transmisor:
parameter [2:0]
  idle = 0,
  CPY_REG0 = 1,
  CPY_REG1 = 2,
  SND_REG0 = 3,
  SND_REG1 = 4;
reg [2:0] TX_now; reg [2:0] TX_next;  // Señales usadas para inferir los biestables necesarios para cada uno de
// los registros de copia de los datos a envíar.
reg [7:0] REG0; reg [7:0] REG1;  // Señal de enable de cada uno de los registros anteriores.
reg R0_enable; reg R1_enable;  // Tabla de direcciones:
// El valor contenido en cada uno de los registros anteriores será recibido 
// desde su respectiva dirección de memoria.
parameter R0_address = 8'h04;
parameter R1_address = 8'h05;
  // El Transmisor nunca modificará un valor de memoria. Únicamente lee los 
  // datos necesarios de ella.
  assign WriteEnable = 1'b0;
  // Proceso secuencial de la máquina de estados del Transmisor. 
  // Dispone de una señal de Reset asíncrono activa a nivel bajo. Mientras que
  // esta señal se mantenga activa, la FSM se mantiene en el estado de 'Idle',
  // y los registros se inicializan a 0.
  always @(posedge Clk, posedge Reset) begin
    if((Reset == 1'b0)) begin
      TX_now <= idle;
      REG0 <= 8'h00;
      REG1 <= 8'h00;
    end else begin
      TX_now <= TX_next;
      if(R0_enable == 1'b1) begin
        REG0 <= Databus;
      end
      if(R1_enable == 1'b1) begin
        REG1 <= Databus;
      end
    end
  end
  // Proceso combinacional de la máquina de estados.
  always @(TX_now, Start_TX, REG0, REG1, Ack_DO) begin
    // Valores preasignados por defecto.
    Address <= 8'h00;
    ChipSelect <= 1'b0;
    OutputEnable <= 1'b0;
    Ready_TX <= 1'b0;
    End_TX <= 1'b0;
    DataOut <= 8'h00;
    Valid_DO <= 1'b1;
    R0_enable <= 1'b0;
    R1_enable <= 1'b0;
    case(TX_now)
    idle : begin
      Ready_TX <= 1'b1;
      // Si el Controlador de Bus da permiso para iniciar una nueva
      // transmisión...
      if(Start_TX == 1'b1) begin
        TX_next <= CPY_REG0;
      end
      else begin
        TX_next <= idle;
      end
    end
    CPY_REG0 : begin
      Address <= R0_address;
      ChipSelect <= 1'b1;
      OutputEnable <= 1'b1;
      R0_enable <= 1'b1;
      // Las lecturas desde memoria se realizan en un único ciclo de
      // reloj. Por tanto en el siguiente flanco de reloj, R0 habrá 
      // almacenado su dato, y se debe pedir a la memoria el siguiente 
      // valor.
      TX_next <= CPY_REG1;
    end
    CPY_REG1 : begin
      Address <= R1_address;
      ChipSelect <= 1'b1;
      OutputEnable <= 1'b1;
      R1_enable <= 1'b1;
      // Las lecturas desde memoria se realizan en un único ciclo de
      // reloj. Por tanto en el siguiente flanco de reloj, R1 habrá 
      // almacenado su dato, terminando así el uso de los buses del uP, 
      // pudiendo devolver su control e iniciando la tranferencia con el 
      // RS232.
      End_TX <= 1'b1;
      TX_next <= SND_REG0;
    end
    SND_REG0 : begin
      DataOut <= REG0;
      Valid_DO <= 1'b0;
      // Si el RS232 ha aceptado el dato...
      if(Ack_DO == 1'b0) begin
        Valid_DO <= 1'b1;
        TX_next <= SND_REG1;
      end
      else begin
        TX_next <= SND_REG0;
      end
    end
    SND_REG1 : begin
      DataOut <= REG1;
      Valid_DO <= 1'b0;
      // Si el RS232 ha aceptado el dato...				
      if(Ack_DO == 1'b0) begin
        Valid_DO <= 1'b1;
        TX_next <= idle;
      end
      else begin
        TX_next <= SND_REG1;
      end
    end
    endcase
  end
endmodule

