module filter(
input wire [31:0] la_input,
input wire [31:0] la_input180,
input wire clock,
output wire [31:0] output
);
reg [31:0] la_input360; reg [31:0] la_input180Delay; reg [31:0] result;
  always @(posedge clock) begin
    // determine next result
    for (i=31; i >= 0; i = i - 1) begin
      result[i] <= (result[i] | la_input360[i] | la_input[i]) & la_input180Delay[i];
    end
    // shift in la_input data
    la_input360 <= la_input;
    la_input180Delay <= la_input180;
  end
  assign output = result;
endmodule

module indices_if_ap_fifo(
input wire clk,
input wire reset,
output wire if_empty_n,
input wire if_read_ce,
input wire if_read,
output wire [DATA_WIDTH - 1:0] if_dout,
output wire if_full_n,
input wire if_write_ce,
input wire if_write,
input wire [DATA_WIDTH - 1:0] if_din
);
parameter [31:0] DATA_WIDTH=32;
parameter [31:0] ADDR_WIDTH=16;
parameter [31:0] DEPTH=1;
reg [DATA_WIDTH - 1:0] mStorage[0:DEPTH - 1] = 1'b0;
reg [ADDR_WIDTH - 1:0] mInPtr = 1'b0;
reg [ADDR_WIDTH - 1:0] mOutPtr = 1'b0;
wire internal_empty_n; wire internal_full_n;
reg mFlag_nEF_hint = 1'b0;  // 0: empty hint, 1: full hint
  assign if_dout = mStorage[mOutPtr];
  assign if_empty_n = internal_empty_n;
  assign if_full_n = internal_full_n;
  assign internal_empty_n = mInPtr == mOutPtr && mFlag_nEF_hint == 1'b0 ? 1'b0 : 1'b1;
  assign internal_full_n = mInptr == mOutPtr && mFlag_nEF_hint == 1'b1 ? 1'b0 : 1'b1;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      mInPtr <= {((ADDR_WIDTH - 1)-(0)+1){1'b0}};
      mOutPtr <= {((ADDR_WIDTH - 1)-(0)+1){1'b0}};
      mFlag_nEF_hint <= 1'b0;
      // empty hint
    end else begin
      if(if_read_ce == 1'b1 && if_read == 1'b1 && internal_empty_n == 1'b1) begin
        if((mOutPtr == (DEPTH - 1))) begin
          mOutPtr <= {((ADDR_WIDTH - 1)-(0)+1){1'b0}};
          mFlag_nEF_hint <=  ~mFlag_nEF_hint;
        end
        else begin
          mOutPtr <= mOutPtr + 1;
        end
      end
      if(if_write_ce == 1'b1 && if_write == 1'b1 && internal_full_n == 1'b1) begin
        mStorage[mInPtr] <= if_din;
        if((mInPtr == (DEPTH - 1))) begin
          mInPtr <= {((ADDR_WIDTH - 1)-(0)+1){1'b0}};
          mFlag_nEF_hint <=  ~mFlag_nEF_hint;
        end
        else begin
          mInPtr <= mInPtr + 1;
        end
      end
    end
  end
endmodule

module piso_r_2(
input wire Clock,
input wire ALOAD,
input wire [N - 1:0] D,
output wire [N - 1:0] SO
);
parameter [31:0] N=8;
reg [N - 1:0] tmp;
  always @(posedge Clock) begin
    if((ALOAD == 1'b1)) begin
      tmp <= D;
    end
    else begin
      tmp <= {tmp[N - 3:0],2'b00};
    end
  end
  assign SO = tmp;
endmodule

module video_generator(
input wire clk,
input wire [11:0] h_visible_len,
input wire [11:0] h_blank_len,
input wire [11:0] h_front_len,
input wire [11:0] h_sync_len,
input wire [11:0] v_visible_len,
input wire [11:0] v_blank_len,
input wire [11:0] v_front_len,
input wire [11:0] v_sync_len,
output reg vid_blank,
output reg vid_hsync,
output reg vid_vsync
);
reg [11:0] h_counter = 1'b0;
reg [11:0] v_counter = 1'b0;
  always @(posedge clk) begin
    // Generate the sync and blanking signals
    if(h_counter >= (h_front_len) && h_counter < ((h_front_len) + (h_sync_len))) begin
      vid_hsync <= 1'b1;
    end
    else begin
      vid_hsync <= 1'b0;
    end
    if(v_counter >= (v_front_len) && v_counter < ((v_front_len) + (v_sync_len))) begin
      vid_vsync <= 1'b1;
    end
    else begin
      vid_vsync <= 1'b0;
    end
    if(h_counter < (h_blank_len) || v_counter < (v_blank_len)) begin
      vid_blank <= 1'b1;
    end
    else begin
      vid_blank <= 1'b0;
    end
    // Manage the counters
    if(h_counter == ((h_visible_len) + (h_blank_len) - 1)) begin
      h_counter <= {12{1'b0}};
      if(v_counter == ((v_visible_len) + (v_blank_len) - 1)) begin
        v_counter <= {12{1'b0}};
      end
      else begin
        v_counter <= v_counter + 1;
      end
    end
    else begin
      h_counter <= h_counter + 1;
    end
  end
endmodule

module gfmapinv(
input wire [3:0] ah,
input wire [3:0] al,
output wire [7:0] a
);
// ah -> High Data Input (4 std_logic)
// al -> Low Data Input (4 std_logic)
// a -> Data Output (remapped back) (8 std_logic)
// Architecture of the Component
  // Inverse Mapping Process
  assign a[0] = al[0] ^ ah[0];
  assign a[1] = ah[0] ^ ah[1] ^ ah[3];
  assign a[2] = al[1] ^ ah[3] ^ ah[0] ^ ah[1];
  assign a[3] = ah[0] ^ ah[1] ^ al[1] ^ ah[2];
  assign a[4] = al[1] ^ ah[3] ^ ah[0] ^ ah[1] ^ al[3];
  assign a[5] = ah[0] ^ ah[1] ^ al[2];
  assign a[6] = al[1] ^ ah[3] ^ al[2] ^ al[3] ^ ah[0];
  assign a[7] = ah[0] ^ ah[1] ^ al[2] ^ ah[3];
endmodule

